import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
  private static final String BASE_URL = Optional
      .ofNullable(System.getenv("BASE_URL"))
      .filter(s -> !s.isBlank())
      .orElse("http://127.0.0.1:8000");

  public ModelSimulation() {
    HttpProtocolBuilder httpProtocol = http
        .baseUrl(BASE_URL)
        .acceptHeader("*/*")
        .disableFollowRedirect();

    ChainBuilder catalogPage = exec(
        http("GET catalog page")
            .get(session -> session.getString("nextPage"))
            .check(status().is(200), bodyString().saveAs("catalogBody")))
        .exec(ModelSimulation::appendCatalogPage);

    ChainBuilder cartGet = exec(
        http("GET cart")
            .get(session -> "/v2/carts/" + session.getString("cartId"))
            .check(status().is(200), header("ETag").saveAs("cartEtag")));

    ChainBuilder pollReservation = exec(
        http("Poll reservation")
            .get(session -> session.getString("statusUrl"))
            .check(status().is(200), bodyString().saveAs("reservationPollBody")))
        .exec(ModelSimulation::captureReservationPoll);

    ChainBuilder workRequest = exec(session -> session.remove("workRetryAfter"))
        .exec(
            http("POST work")
                .post("/v2/work")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(
                    status().in(200, 429),
                    status().saveAs("workStatus"),
                    header("Retry-After").optional().saveAs("workRetryAfter"),
                    bodyString().saveAs("workBody")))
        .exec(ModelSimulation::validateWorkResponse);

    ChainBuilder workRetries = asLongAs(session ->
        session.getInt("workStatus") == 429 && session.getInt("workRetries") < 4
    ).on(
        exec(session -> session.set("workRetries", session.getInt("workRetries") + 1))
            .exec(pause(Duration.ofSeconds(1)))
            .exec(workRequest)
    );

    ChainBuilder journey =
        exec(ModelSimulation::resetJourney)
            .exec(
                http("GET login form")
                    .get("/v2/login-form")
                    .check(
                        status().is(200),
                        css("form input[name='csrf'][type='hidden']", "value")
                            .saveAs("formCsrf")))
            .exec(
                http("POST login")
                    .post("/v2/login")
                    .header("Content-Type", "application/json")
                    .body(StringBody(session ->
                        "{\"username\":" + quote(session.getString("username")) +
                            ",\"password\":\"bench\",\"csrf\":" +
                            quote(session.getString("formCsrf")) + "}"))
                    .check(
                        status().in(200, 302),
                        jsonPath("$.csrf").optional().saveAs("loginCsrf"),
                        header("Location").optional().saveAs("loginLocation")))
            .exec(ModelSimulation::applyLoginToken)
            .doIf(ModelSimulation::hasLoginLocation).then(
                exec(
                    http("GET login redirect")
                        .get(session -> session.getString("loginLocation"))
                        .check(
                            status().in(200, 302),
                            jsonPath("$.csrf").optional().saveAs("redirectCsrf")))
                    .exec(ModelSimulation::applyRedirectToken))
            .exec(
                http("GET catalog")
                    .get("/v2/catalog")
                    .check(status().is(200), bodyString().saveAs("catalogBody")))
            .exec(ModelSimulation::appendCatalogPage)
            .doIf(session -> hasValue(session, "nextPage")).then(catalogPage)
            .doIf(session -> hasValue(session, "nextPage")).then(catalogPage)
            .exec(ModelSimulation::selectProductAndVariant)
            .exec(
                http("GET challenge form")
                    .get("/v2/challenge-form")
                    .check(
                        status().is(200),
                        css("form[action]", "action").saveAs("challengeAction"),
                        css("form input[name='challenge']", "value")
                            .saveAs("challengeValue")))
            .exec(
                http("POST challenge")
                    .post(session -> session.getString("challengeAction"))
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody(session ->
                        "{\"challenge\":" + quote(session.getString("challengeValue")) + "}"))
                    .check(
                        status().is(302),
                        header("Location").saveAs("challengeLocation")))
            .exec(
                http("GET challenge grant")
                    .get(session -> session.getString("challengeLocation"))
                    .check(
                        status().is(200),
                        jsonPath("$.grant_id").exists(),
                        jsonPath("$.csrf").exists(),
                        bodyString().saveAs("grantBody")))
            .exec(ModelSimulation::captureGrant)
            .exec(
                http("POST cart")
                    .post("/v2/carts")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody(session ->
                        "{\"product_id\":" + jsonValue(session.get("productId")) +
                            ",\"variant_id\":" + jsonValue(session.get("variantId")) +
                            ",\"grant_id\":" + quote(session.getString("grantId")) + "}"))
                    .check(
                        status().is(201),
                        jsonPath("$.id").exists(),
                        jsonPath("$.csrf").exists(),
                        header("ETag").saveAs("cartEtag"),
                        bodyString().saveAs("cartCreateBody")))
            .exec(ModelSimulation::captureCart)
            .exec(cartGet)
            .exec(
                http("PATCH cart quantity")
                    .patch(session -> "/v2/carts/" + session.getString("cartId"))
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .header("If-Match", "#{cartEtag}")
                    .body(StringBody("{\"quantity\":1}"))
                    .check(
                        status().in(200, 412),
                        status().saveAs("patchStatus"),
                        bodyString().saveAs("patchBody")))
            .exec(session -> updateCsrfFromBody(session, "patchBody"))
            .doIf(session -> session.getInt("patchStatus") == 412).then(
                exec(cartGet)
                    .exec(
                        http("Retry PATCH cart quantity")
                            .patch(session -> "/v2/carts/" + session.getString("cartId"))
                            .header("Content-Type", "application/json")
                            .header("X-CSRF-Token", "#{csrf}")
                            .header("If-Match", "#{cartEtag}")
                            .body(StringBody("{\"quantity\":1}"))
                            .check(
                                status().is(200),
                                bodyString().saveAs("patchRetryBody")))
                    .exec(session -> updateCsrfFromBody(session, "patchRetryBody")))
            .exec(cartGet)
            .exec(
                http("POST reservation")
                    .post("/v2/reservations")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody(session ->
                        "{\"cart_id\":" + jsonValue(session.get("cartId")) + "}"))
                    .check(
                        status().is(202),
                        jsonPath("$.status_url").exists(),
                        bodyString().saveAs("reservationCreateBody")))
            .exec(ModelSimulation::captureReservation)
            .exec(pollReservation)
            .exec(
                asLongAs(session ->
                    "pending".equals(session.getString("reservationStatus")) &&
                        session.getInt("reservationPollCount") < 5
                ).on(
                    exec(pause(Duration.ofMillis(50)))
                        .exec(pollReservation)))
            .exec(ModelSimulation::assertReservationReady)
            .exec(
                http("POST order")
                    .post("/v2/orders")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .header("Idempotency-Key", "order-#{cartId}")
                    .header("If-Match", "#{cartEtag}")
                    .body(StringBody(session ->
                        "{\"cart_id\":" + jsonValue(session.get("cartId")) +
                            ",\"reservation_id\":" +
                            jsonValue(session.get("reservationId")) + "}"))
                    .check(
                        status().is(201),
                        jsonPath("$.accepted").ofBoolean().is(true),
                        bodyString().saveAs("orderBody")))
            .exec(session -> updateCsrfFromBody(session, "orderBody"))
            .exec(session -> session.set("workRetries", 0).set("workStatus", 0))
            .exec(workRequest)
            .exec(workRetries);

    ScenarioBuilder user1 = scenario("bench-1")
        .exec(session -> session.set("username", "bench-1"))
        .repeat(2).on(journey);

    ScenarioBuilder user2 = scenario("bench-2")
        .exec(session -> session.set("username", "bench-2"))
        .repeat(2).on(journey);

    setUp(
        user1.injectOpen(atOnceUsers(1)),
        user2.injectOpen(atOnceUsers(1))
    ).protocols(httpProtocol);
  }

  private static Session resetJourney(Session session) {
    Session s = session;
    for (String key : new String[] {
        "csrf", "formCsrf", "loginCsrf", "loginLocation", "redirectCsrf",
        "catalogBody", "catalogProducts", "nextPage", "productId", "variantId",
        "challengeAction", "challengeValue", "challengeLocation", "grantBody",
        "grantId", "cartId", "cartEtag", "cartCreateBody", "patchStatus",
        "patchBody", "patchRetryBody", "reservationCreateBody", "statusUrl",
        "reservationStatus", "reservationId", "reservationPollBody",
        "reservationPollCount", "orderBody", "workRetries", "workStatus",
        "workRetryAfter", "workBody"
    }) {
      s = s.remove(key);
    }
    return s;
  }

  private static Session applyLoginToken(Session session) {
    String token = optionalString(session, "loginCsrf");
    if (token == null) {
      token = optionalString(session, "formCsrf");
    }
    if (token == null) {
      throw new IllegalStateException("No CSRF token after login");
    }
    return session.set("csrf", token);
  }

  private static boolean hasLoginLocation(Session session) {
    return hasValue(session, "loginLocation");
  }

  private static Session applyRedirectToken(Session session) {
    String token = optionalString(session, "redirectCsrf");
    return token == null ? session : session.set("csrf", token);
  }

  private static Session appendCatalogPage(Session session) {
    Map<String, Object> root = asMap(parseJson(session.getString("catalogBody")));
    Map<String, Object> data = asMap(root.get("data"));
    Object pageProducts = data.get("products");
    if (!(pageProducts instanceof List<?>)) {
      throw new IllegalStateException("Catalog response has no products list");
    }

    List<Object> products = new ArrayList<>();
    if (session.contains("catalogProducts")) {
      products.addAll((List<?>) session.get("catalogProducts"));
    }
    products.addAll((List<?>) pageProducts);

    Object next = root.get("next");
    String nextPage = next == null ? null : String.valueOf(next);
    return session.set("catalogProducts", products)
        .set("nextPage", nextPage == null ? "" : nextPage);
  }

  private static Session selectProductAndVariant(Session session) {
    List<?> products = (List<?>) session.get("catalogProducts");
    for (Object productValue : products) {
      Map<String, Object> product = asMap(productValue);
      Object productId = product.get("id");
      Object variantsValue = product.get("variants");
      if (productId == null || !(variantsValue instanceof List<?>)) {
        continue;
      }
      for (Object variantValue : (List<?>) variantsValue) {
        Map<String, Object> variant = asMap(variantValue);
        Object inStock = variant.get("in_stock");
        Object variantId = variant.get("id");
        if (variantId != null &&
            (Boolean.TRUE.equals(inStock) || "true".equalsIgnoreCase(String.valueOf(inStock)))) {
          return session.set("productId", productId).set("variantId", variantId);
        }
      }
    }
    throw new IllegalStateException("Catalog contains no in-stock variant");
  }

  private static Session captureGrant(Session session) {
    Map<String, Object> body = asMap(parseJson(session.getString("grantBody")));
    Object grantId = body.get("grant_id");
    Object csrf = body.get("csrf");
    if (grantId == null || csrf == null) {
      throw new IllegalStateException("Challenge grant response is incomplete");
    }
    return session.set("grantId", String.valueOf(grantId))
        .set("csrf", String.valueOf(csrf));
  }

  private static Session captureCart(Session session) {
    Map<String, Object> body = asMap(parseJson(session.getString("cartCreateBody")));
    Object id = body.get("id");
    Object csrf = body.get("csrf");
    if (id == null || csrf == null) {
      throw new IllegalStateException("Cart response is incomplete");
    }
    return session.set("cartId", String.valueOf(id))
        .set("csrf", String.valueOf(csrf));
  }

  private static Session captureReservation(Session session) {
    Map<String, Object> body = asMap(parseJson(session.getString("reservationCreateBody")));
    Object statusUrl = body.get("status_url");
    if (statusUrl == null) {
      throw new IllegalStateException("Reservation response has no status URL");
    }
    Session s = session.set("statusUrl", String.valueOf(statusUrl))
        .set("reservationStatus", "pending")
        .set("reservationPollCount", 0);
    return updateCsrf(body, s);
  }

  private static Session captureReservationPoll(Session session) {
    Map<String, Object> body = asMap(parseJson(session.getString("reservationPollBody")));
    Object status = body.get("status");
    if (status == null) {
      throw new IllegalStateException("Reservation poll response has no status");
    }
    int count = session.getInt("reservationPollCount") + 1;
    Session s = session.set("reservationStatus", String.valueOf(status))
        .set("reservationPollCount", count);
    if ("ready".equals(String.valueOf(status))) {
      Object reservationId = body.get("reservation_id");
      if (reservationId == null) {
        throw new IllegalStateException("Ready reservation has no reservation_id");
      }
      s = s.set("reservationId", reservationId);
    }
    return updateCsrf(body, s);
  }

  private static Session assertReservationReady(Session session) {
    if (!"ready".equals(session.getString("reservationStatus"))) {
      throw new IllegalStateException("Reservation did not become ready within five polls");
    }
    return session;
  }

  private static Session validateWorkResponse(Session session) {
    int status = session.getInt("workStatus");
    if (status == 200) {
      Map<String, Object> body = asMap(parseJson(session.getString("workBody")));
      if (!Boolean.TRUE.equals(body.get("ok"))) {
        throw new IllegalStateException("/v2/work did not return ok:true");
      }
      return updateCsrf(body, session);
    }
    if (status == 429) {
      String retryAfter = optionalString(session, "workRetryAfter");
      if (retryAfter == null || !retryAfter.trim().startsWith("1")) {
        throw new IllegalStateException("429 response did not provide Retry-After: 1");
      }
    }
    return session;
  }

  private static Session updateCsrfFromBody(Session session, String bodyKey) {
    String body = optionalString(session, bodyKey);
    if (body == null || body.isBlank()) {
      return session;
    }
    Object parsed = parseJson(body);
    if (parsed instanceof Map<?, ?>) {
      return updateCsrf(asMap(parsed), session);
    }
    return session;
  }

  private static Session updateCsrf(Map<String, Object> body, Session session) {
    Object csrf = body.get("csrf");
    return csrf == null ? session : session.set("csrf", String.valueOf(csrf));
  }

  private static boolean hasValue(Session session, String key) {
    String value = optionalString(session, key);
    return value != null && !value.isBlank();
  }

  private static String optionalString(Session session, String key) {
    if (!session.contains(key)) {
      return null;
    }
    Object value = session.get(key);
    return value == null ? null : String.valueOf(value);
  }

  private static String quote(String value) {
    StringBuilder out = new StringBuilder("\"");
    for (int i = 0; i < value.length(); i++) {
      char c = value.charAt(i);
      switch (c) {
        case '"': out.append("\\\""); break;
        case '\\': out.append("\\\\"); break;
        case '\b': out.append("\\b"); break;
        case '\f': out.append("\\f"); break;
        case '\n': out.append("\\n"); break;
        case '\r': out.append("\\r"); break;
        case '\t': out.append("\\t"); break;
        default:
          if (c < 0x20) {
            out.append(String.format("\\u%04x", (int) c));
          } else {
            out.append(c);
          }
      }
    }
    return out.append('"').toString();
  }

  private static String jsonValue(Object value) {
    if (value == null) {
      throw new IllegalStateException("Cannot serialize a missing JSON value");
    }
    if (value instanceof String || value instanceof Character) {
      return quote(String.valueOf(value));
    }
    if (value instanceof Number || value instanceof Boolean) {
      return String.valueOf(value);
    }
    throw new IllegalArgumentException("Unsupported JSON value: " + value.getClass());
  }

  @SuppressWarnings("unchecked")
  private static Map<String, Object> asMap(Object value) {
    if (!(value instanceof Map<?, ?>)) {
      throw new IllegalStateException("Expected a JSON object");
    }
    return (Map<String, Object>) value;
  }

  private static Object parseJson(String input) {
    return new JsonParser(input).parse();
  }

  private static final class JsonParser {
    private final String text;
    private int position;

    JsonParser(String text) {
      this.text = Objects.requireNonNull(text);
    }

    Object parse() {
      skipWhitespace();
      Object result = readValue();
      skipWhitespace();
      if (position != text.length()) {
        throw new IllegalArgumentException("Unexpected trailing JSON content");
      }
      return result;
    }

    private Object readValue() {
      skipWhitespace();
      if (position >= text.length()) {
        throw new IllegalArgumentException("Unexpected end of JSON");
      }
      char c = text.charAt(position);
      if (c == '{') return readObject();
      if (c == '[') return readArray();
      if (c == '"') return readString();
      if (c == 't') return readLiteral("true", Boolean.TRUE);
      if (c == 'f') return readLiteral("false", Boolean.FALSE);
      if (c == 'n') return readLiteral("null", null);
      return readNumber();
    }

    private Map<String, Object> readObject() {
      position++;
      Map<String, Object> result = new LinkedHashMap<>();
      skipWhitespace();
      if (take('}')) return result;
      while (true) {
        skipWhitespace();
        String key = readString();
        skipWhitespace();
        require(':');
        result.put(key, readValue());
        skipWhitespace();
        if (take('}')) return result;
        require(',');
      }
    }

    private List<Object> readArray() {
      position++;
      List<Object> result = new ArrayList<>();
      skipWhitespace();
      if (take(']')) return result;
      while (true) {
        result.add(readValue());
        skipWhitespace();
        if (take(']')) return result;
        require(',');
      }
    }

    private String readString() {
      require('"');
      StringBuilder result = new StringBuilder();
      while (position < text.length()) {
        char c = text.charAt(position++);
        if (c == '"') return result.toString();
        if (c != '\\') {
          result.append(c);
          continue;
        }
        if (position >= text.length()) {
          throw new IllegalArgumentException("Incomplete JSON escape");
        }
        char escaped = text.charAt(position++);
        switch (escaped) {
          case '"': result.append('"'); break;
          case '\\': result.append('\\'); break;
          case '/': result.append('/'); break;
          case 'b': result.append('\b'); break;
          case 'f': result.append('\f'); break;
          case 'n': result.append('\n'); break;
          case 'r': result.append('\r'); break;
          case 't': result.append('\t'); break;
          case 'u':
            if (position + 4 > text.length()) {
              throw new IllegalArgumentException("Incomplete unicode escape");
            }
            result.append((char) Integer.parseInt(text.substring(position, position + 4), 16));
            position += 4;
            break;
          default:
            throw new IllegalArgumentException("Invalid JSON escape");
        }
      }
      throw new IllegalArgumentException("Unterminated JSON string");
    }

    private Object readNumber() {
      int start = position;
      while (position < text.length()) {
        char c = text.charAt(position);
        if ((c >= '0' && c <= '9') || c == '-' || c == '+' ||
            c == '.' || c == 'e' || c == 'E') {
          position++;
        } else {
          break;
        }
      }
      if (start == position) {
        throw new IllegalArgumentException("Invalid JSON value");
      }
      String number = text.substring(start, position);
      if (number.indexOf('.') >= 0 || number.indexOf('e') >= 0 || number.indexOf('E') >= 0) {
        return Double.parseDouble(number);
      }
      return Long.parseLong(number);
    }

    private Object readLiteral(String literal, Object value) {
      if (!text.startsWith(literal, position)) {
        throw new IllegalArgumentException("Invalid JSON literal");
      }
      position += literal.length();
      return value;
    }

    private void skipWhitespace() {
      while (position < text.length() && Character.isWhitespace(text.charAt(position))) {
        position++;
      }
    }

    private boolean take(char expected) {
      if (position < text.length() && text.charAt(position) == expected) {
        position++;
        return true;
      }
      return false;
    }

    private void require(char expected) {
      if (!take(expected)) {
        throw new IllegalArgumentException("Expected '" + expected + "' in JSON");
      }
    }
  }
}

import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const ORIGIN_MATCH = BASE_URL.match(/^(https?:\/\/[^/]+)/i);
if (!ORIGIN_MATCH) {
  throw new Error('BASE_URL must be an HTTP URL');
}
const BASE_ORIGIN = ORIGIN_MATCH[1];
const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    shop_flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '10m',
    },
  },
};

function resolveUrl(path) {
  const value = String(path || '');
  const absolute = value.match(/^(https?:\/\/[^/]+)/i);
  if (absolute) {
    if (absolute[1].toLowerCase() !== BASE_ORIGIN.toLowerCase()) {
      throw new Error('Refusing to request a URL outside BASE_URL');
    }
    return value;
  }
  if (value.charAt(0) === '/') {
    return BASE_URL + value;
  }
  return BASE_URL + '/' + value;
}

function parseJson(response) {
  try {
    return JSON.parse(response && response.body ? response.body : '{}');
  } catch (_) {
    return {};
  }
}

function responseData(response) {
  const obj = parseJson(response);
  return obj && obj.data && typeof obj.data === 'object' ? obj.data : obj;
}

function getHeader(response, name) {
  if (!response || !response.headers) {
    return '';
  }
  const wanted = name.toLowerCase();
  for (const key in response.headers) {
    if (key.toLowerCase() === wanted) {
      return String(response.headers[key]);
    }
  }
  return '';
}

function decodeEntities(value) {
  return String(value)
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&apos;/gi, "'")
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#x([0-9a-f]+);/gi, function (_, hex) {
      return String.fromCharCode(parseInt(hex, 16));
    })
    .replace(/&#([0-9]+);/g, function (_, dec) {
      return String.fromCharCode(parseInt(dec, 10));
    });
}

function parseAttributes(text) {
  const attrs = {};
  const re = /([^\s=/>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/g;
  let match;
  while ((match = re.exec(text)) !== null) {
    const key = match[1].toLowerCase();
    let value = '';
    if (match[2] !== undefined) {
      value = match[2];
    } else if (match[3] !== undefined) {
      value = match[3];
    } else if (match[4] !== undefined) {
      value = match[4].replace(/\/$/, '');
    }
    attrs[key] = decodeEntities(value);
  }
  return attrs;
}

function inputValue(html, fieldName, hiddenOnly) {
  const re = /<input\b[^>]*>/gi;
  let match;
  let fallback = null;
  while ((match = re.exec(html || '')) !== null) {
    const raw = match[0]
      .replace(/^<\s*input\b/i, '')
      .replace(/\/?>\s*$/, '');
    const attrs = parseAttributes(raw);
    if (attrs.name !== fieldName || attrs.value === undefined) {
      continue;
    }
    const isHidden = String(attrs.type || '').toLowerCase() === 'hidden';
    if (hiddenOnly && !isHidden) {
      continue;
    }
    if (isHidden) {
      return attrs.value;
    }
    if (fallback === null) {
      fallback = attrs.value;
    }
  }
  return fallback;
}

function challengeForm(html) {
  const forms = /<form\b([^>]*)>([\s\S]*?)<\/form\s*>/gi;
  let match;
  while ((match = forms.exec(html || '')) !== null) {
    const attrs = parseAttributes(match[1]);
    const action = attrs.action || '';
    if (!/^\/v2\/challenges\/[^/?#]+(?:[?#].*)?$/.test(action)) {
      continue;
    }
    const challenge = inputValue(match[2], 'challenge', false);
    if (challenge !== null && challenge !== undefined) {
      return { action: action, challenge: challenge };
    }
  }
  return null;
}

function extractCsrf(response) {
  const obj = parseJson(response);
  const data = obj && obj.data && typeof obj.data === 'object' ? obj.data : obj;
  if (data && typeof data.csrf === 'string' && data.csrf.length > 0) {
    return data.csrf;
  }
  if (obj && typeof obj.csrf === 'string' && obj.csrf.length > 0) {
    return obj.csrf;
  }
  return '';
}

function send(state, method, path, payload, extraHeaders, countWork) {
  const headers = { Accept: 'application/json' };
  if (payload !== undefined && method !== 'GET') {
    headers['Content-Type'] = 'application/json';
  }
  if (state && method !== 'GET' && state.csrf) {
    headers['X-CSRF-Token'] = state.csrf;
  }
  if (extraHeaders) {
    for (const key in extraHeaders) {
      headers[key] = extraHeaders[key];
    }
  }

  const body = method === 'GET' || payload === undefined ? null : JSON.stringify(payload);
  const response = http.request(method, resolveUrl(path), body, {
    headers: headers,
    redirects: 0,
  });

  if (countWork) {
    const obj = parseJson(response);
    const expectedExpiry = response.status === 401 && obj.error === 'expired';
    const scheduled429 = response.status === 429;
    const successful = response.status === 200 && obj.ok === true;
    businessFailure.add(!(expectedExpiry || scheduled429 || successful));
  }

  return response;
}

function captureMutationCsrf(state, response) {
  if (!state || !response) {
    return;
  }
  const status = response.status;
  if (!((status >= 200 && status < 300) || status === 302)) {
    return;
  }
  const token = extractCsrf(response);
  if (token) {
    state.csrf = token;
  }
}

function responseError(response) {
  return parseJson(response).error || '';
}

function performLogin(state) {
  const formResponse = send(null, 'GET', '/v2/login-form', undefined, {
    Accept: 'text/html,application/json',
  }, false);
  const formOk = check(formResponse, {
    'login form returned 200': (r) => r.status === 200,
  });
  if (!formOk) {
    return false;
  }

  const formToken = inputValue(formResponse.body || '', 'csrf', true);
  check({ token: formToken }, {
    'login form hidden csrf input selected': (v) => typeof v.token === 'string' && v.token.length > 0,
  });
  if (!formToken) {
    return false;
  }

  const loginResponse = send(null, 'POST', '/v2/login', {
    username: state.username,
    password: 'bench',
    csrf: formToken,
  }, {}, false);

  let finalResponse = loginResponse;
  if (loginResponse.status === 302) {
    const location = getHeader(loginResponse, 'Location');
    check({ location: location }, {
      'login redirect has dynamic Location': (v) => v.location.length > 0,
    });
    if (!location) {
      return false;
    }
    finalResponse = send(null, 'GET', location, undefined, {
      Accept: 'application/json',
    }, false);
  }

  const finalData = responseData(finalResponse);
  const loginData = responseData(loginResponse);
  const token = extractCsrf(finalResponse) || extractCsrf(loginResponse);
  const user = finalData.user || loginData.user;
  const userName = typeof user === 'string' ? user : (user && user.username);
  const loginOk = check({
    status: finalResponse.status,
    token: token,
    user: user,
    userName: userName,
  }, {
    'login succeeded with a fresh csrf token': (v) =>
      v.status === 200 && !!v.token && !!v.user &&
      (!v.userName || v.userName === state.username),
  });

  if (!loginOk) {
    return false;
  }
  state.csrf = token;
  return true;
}

function recoverExistingCart(state) {
  if (state.cartId === null || state.cartId === undefined) {
    return true;
  }
  const path = '/v2/carts/' + encodeURIComponent(String(state.cartId)) + '/recover';
  const response = send(state, 'POST', path, {}, {}, false);
  captureMutationCsrf(state, response);
  return check(response, {
    'existing cart recovered': (r) => r.status >= 200 && r.status < 300,
  });
}

function authenticatedRequest(state, method, path, payload, extraHeaders, countWork) {
  let response = send(state, method, path, payload, extraHeaders, countWork);
  captureMutationCsrf(state, response);

  if (response.status !== 401) {
    return response;
  }

  const error = responseError(response);
  check({ error: error }, {
    'authorization was not denied': (v) => v.error !== 'denied',
  });

  if (error !== 'expired' && error !== 'session') {
    return response;
  }

  let sessionReady = false;
  if (error === 'expired') {
    const renewResponse = send(state, 'POST', '/v2/session/renew', {}, {}, false);
    const renewToken = extractCsrf(renewResponse);
    const renewed = check({
      status: renewResponse.status,
      token: renewToken,
    }, {
      'expired session renewed with csrf': (v) =>
        v.status >= 200 && v.status < 300 && !!v.token,
    });
    if (renewed) {
      state.csrf = renewToken;
      sessionReady = true;
    } else if (responseError(renewResponse) === 'session') {
      sessionReady = performLogin(state);
    }
  } else {
    sessionReady = performLogin(state);
  }

  if (!sessionReady) {
    return response;
  }
  if (!recoverExistingCart(state)) {
    return response;
  }

  // Retry only the interrupted operation, once.
  response = send(state, method, path, payload, extraHeaders, countWork);
  captureMutationCsrf(state, response);
  if (response.status === 401) {
    check({ status: response.status }, {
      'interrupted operation retry was authorized': (v) => v.status !== 401,
    });
  }
  return response;
}

function findAvailableVariant(products) {
  for (let i = 0; i < products.length; i++) {
    const product = products[i];
    if (!product || product.id === undefined || !Array.isArray(product.variants)) {
      continue;
    }
    for (let j = 0; j < product.variants.length; j++) {
      const variant = product.variants[j];
      if (variant && variant.id !== undefined && variant.in_stock === true) {
        return { product_id: product.id, variant_id: variant.id };
      }
    }
  }
  return null;
}

function productsFrom(obj) {
  const data = obj && obj.data && typeof obj.data === 'object' ? obj.data : obj;
  if (data && Array.isArray(data.products)) {
    return data.products;
  }
  if (data && data.product) {
    return [data.product];
  }
  if (obj && obj.product) {
    return [obj.product];
  }
  return [];
}

function nextFrom(obj) {
  const data = obj && obj.data && typeof obj.data === 'object' ? obj.data : obj;
  if (obj && obj.next !== undefined) {
    return obj.next;
  }
  return data ? data.next : null;
}

function discoverProduct() {
  let path = '/v2/catalog';
  for (let page = 0; page < 3; page++) {
    const response = send(null, 'GET', path, undefined, {}, false);
    const ok = check(response, {
      'catalog page returned 200': (r) => r.status === 200,
    });
    if (!ok) {
      return null;
    }

    const obj = parseJson(response);
    const product = findAvailableVariant(productsFrom(obj));
    if (product) {
      return product;
    }

    const next = nextFrom(obj);
    if (!next || page === 2) {
      return null;
    }
    path = String(next);
  }
  return null;
}

function getCart(state) {
  const path = '/v2/carts/' + encodeURIComponent(String(state.cartId));
  const response = authenticatedRequest(state, 'GET', path, undefined, {}, false);
  const ok = check(response, {
    'cart read returned 200': (r) => r.status === 200,
  });
  if (!ok) {
    return false;
  }
  const etag = getHeader(response, 'ETag');
  const hasEtag = check({ etag: etag }, {
    'cart read returned ETag': (v) => v.etag.length > 0,
  });
  if (hasEtag) {
    state.etag = etag;
  }
  return hasEtag;
}

function obtainGrant(state) {
  const formResponse = send(state, 'GET', '/v2/challenge-form', undefined, {
    Accept: 'text/html,application/json',
  }, false);
  const formOk = check(formResponse, {
    'challenge form returned 200': (r) => r.status === 200,
  });
  if (!formOk) {
    return null;
  }

  const parsed = challengeForm(formResponse.body || '');
  check({ form: parsed }, {
    'challenge form action and input selected': (v) =>
      !!v.form && !!v.form.action && !!v.form.challenge,
  });
  if (!parsed) {
    return null;
  }

  const claimResponse = authenticatedRequest(
    state,
    'POST',
    parsed.action,
    { challenge: parsed.challenge },
    {},
    false
  );
  const claimOk = check(claimResponse, {
    'challenge claim redirected': (r) => r.status === 302,
  });
  if (!claimOk) {
    return null;
  }

  const location = getHeader(claimResponse, 'Location');
  check({ location: location }, {
    'challenge claim has dynamic Location': (v) => v.location.length > 0,
  });
  if (!location) {
    return null;
  }

  // Fetch the dynamic grant Location exactly once.
  const grantResponse = send(state, 'GET', location, undefined, {}, false);
  const grantData = responseData(grantResponse);
  const grantOk = check({
    status: grantResponse.status,
    grantId: grantData.grant_id,
  }, {
    'challenge grant returned': (v) => v.status === 200 && !!v.grantId,
  });
  if (!grantOk) {
    return null;
  }
  const csrf = extractCsrf(grantResponse);
  if (csrf) {
    state.csrf = csrf;
  }
  return grantData.grant_id;
}

function reserveCart(state) {
  const response = authenticatedRequest(state, 'POST', '/v2/reservations', {
    cart_id: state.cartId,
  }, {}, false);

  const data = responseData(response);
  const started = check({
    status: response.status,
    statusUrl: data.status_url,
  }, {
    'reservation accepted': (v) => v.status === 202 && !!v.statusUrl,
  });
  if (!started) {
    return null;
  }

  const statusUrl = data.status_url;
  for (let poll = 0; poll < 5; poll++) {
    sleep(0.05);
    const pollResponse = authenticatedRequest(state, 'GET', statusUrl, undefined, {}, false);
    const pollOk = check(pollResponse, {
      'reservation status poll returned 200': (r) => r.status === 200,
    });
    if (!pollOk) {
      return null;
    }

    const statusData = responseData(pollResponse);
    if (statusData.status === 'ready' && statusData.reservation_id) {
      return statusData.reservation_id;
    }
    if (statusData.status === 'failed') {
      break;
    }
  }

  check({ ready: false }, {
    'reservation became ready before checkout': (v) => v.ready,
  });
  return null;
}

function doWork(state) {
  let response = authenticatedRequest(state, 'POST', '/v2/work', {}, {}, true);
  let retries = 0;

  while (response.status === 429 && retries < 4) {
    const retryAfter = getHeader(response, 'Retry-After');
    const seconds = parseFloat(retryAfter);
    check({ retryAfter: retryAfter, seconds: seconds }, {
      'scheduled 429 requested a one-second delay': (v) =>
        !!v.retryAfter && !isNaN(v.seconds) && v.seconds >= 1,
    });
    sleep(!isNaN(seconds) && seconds >= 1 ? seconds : 1);
    retries++;
    response = authenticatedRequest(state, 'POST', '/v2/work', {}, {}, true);
  }

  const data = parseJson(response);
  check({
    status: response.status,
    ok: data.ok,
  }, {
    'work completed': (v) => v.status === 200 && v.ok === true,
  });
}

export default function () {
  const state = {
    username: 'bench-' + __VU,
    csrf: '',
    cartId: null,
    etag: '',
  };

  if (!performLogin(state)) {
    return;
  }

  doWork(state);

  const product = discoverProduct();
  check({ product: product }, {
    'in-stock catalog variant selected dynamically': (v) =>
      !!v.product && v.product.product_id !== undefined && v.product.variant_id !== undefined,
  });
  if (!product) {
    return;
  }

  const grantId = obtainGrant(state);
  if (!grantId) {
    return;
  }

  const cartResponse = authenticatedRequest(state, 'POST', '/v2/carts', {
    product_id: product.product_id,
    variant_id: product.variant_id,
    grant_id: grantId,
  }, {}, false);

  const cartData = responseData(cartResponse);
  const cartCreated = check({
    status: cartResponse.status,
    id: cartData.id,
  }, {
    'exactly one cart created for the journey': (v) => v.status === 201 && v.id !== undefined,
  });
  if (!cartCreated) {
    return;
  }
  state.cartId = cartData.id;

  if (!getCart(state)) {
    return;
  }

  const patchPayload = { quantity: 1 };
  let patchResponse = authenticatedRequest(
    state,
    'PATCH',
    '/v2/carts/' + encodeURIComponent(String(state.cartId)),
    patchPayload,
    { 'If-Match': state.etag },
    false
  );

  if (patchResponse.status === 412) {
    if (!getCart(state)) {
      return;
    }
    patchResponse = authenticatedRequest(
      state,
      'PATCH',
      '/v2/carts/' + encodeURIComponent(String(state.cartId)),
      patchPayload,
      { 'If-Match': state.etag },
      false
    );
  }

  const patchOk = check(patchResponse, {
    'cart quantity updated': (r) => r.status >= 200 && r.status < 300,
  });
  if (!patchOk) {
    return;
  }
  const patchEtag = getHeader(patchResponse, 'ETag');
  if (patchEtag) {
    state.etag = patchEtag;
  }

  const reservationId = reserveCart(state);
  if (!reservationId) {
    return;
  }

  if (!getCart(state)) {
    return;
  }

  const orderHeaders = { 'Idempotency-Key': 'order-' + String(state.cartId) };
  if (state.etag) {
    orderHeaders['If-Match'] = state.etag;
  }

  const orderResponse = authenticatedRequest(state, 'POST', '/v2/orders', {
    cart_id: state.cartId,
    reservation_id: reservationId,
  }, orderHeaders, false);

  const orderData = responseData(orderResponse);
  check({
    status: orderResponse.status,
    accepted: orderData.accepted,
    id: orderData.id,
  }, {
    'one order committed for the journey': (v) =>
      v.status === 201 && v.accepted === true && v.id !== undefined,
  });
}

import json
import os
from itertools import count
from urllib.parse import quote, urlsplit

import gevent
from html.parser import HTMLParser
from locust import HttpUser, LoadTestShape, StopUser, constant, task


_USER_SEQUENCE = count()
_STARTED_USERS = 0
_DONE_USERS = 0
ITERATIONS_PER_USER = 2


class JourneyAbort(Exception):
    """The current journey has failed an assertion recorded on a response."""


class FormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self.outside_inputs = []
        self.current_form = None

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        attrs = {key.lower(): value for key, value in attrs if key}
        if tag == "form":
            form = {"attrs": attrs, "inputs": []}
            self.forms.append(form)
            self.current_form = form
        elif tag == "input":
            if self.current_form is not None:
                self.current_form["inputs"].append(attrs)
            else:
                self.outside_inputs.append(attrs)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        if tag.lower() == "form":
            self.handle_endtag(tag)

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self.current_form = None


def json_body(response):
    try:
        value = response.json()
    except (ValueError, TypeError):
        return None
    return value if isinstance(value, dict) else None


def csrf_from_response(response):
    body = json_body(response)
    if body:
        value = body.get("csrf")
        if isinstance(value, str) and value:
            return value
    value = response.headers.get("X-CSRF-Token")
    return value if isinstance(value, str) and value else None


def form_csrf(html):
    parser = FormParser()
    parser.feed(html)

    candidates = []
    for form_index, form in enumerate(parser.forms):
        attrs = form["attrs"]
        action = (attrs.get("action") or "").lower()
        identity = " ".join(
            str(attrs.get(key) or "") for key in ("id", "name", "class")
        ).lower()
        field_names = {
            (field.get("name") or "").lower() for field in form["inputs"]
        }
        score = 0
        if "login" in action:
            score += 8
        if "login" in identity:
            score += 4
        if "username" in field_names or "password" in field_names:
            score += 2

        for field in form["inputs"]:
            if (
                (field.get("name") or "").lower() == "csrf"
                and (field.get("type") or "").lower() == "hidden"
                and isinstance(field.get("value"), str)
                and field.get("value")
            ):
                candidates.append((score, -form_index, field["value"]))

    for field_index, field in enumerate(parser.outside_inputs):
        if (
            (field.get("name") or "").lower() == "csrf"
            and (field.get("type") or "").lower() == "hidden"
            and isinstance(field.get("value"), str)
            and field.get("value")
        ):
            candidates.append((0, -field_index, field["value"]))

    if not candidates:
        return None
    return max(candidates)[2]


def challenge_fields(html):
    parser = FormParser()
    parser.feed(html)

    for form in parser.forms:
        action = form["attrs"].get("action")
        for field in form["inputs"]:
            if (
                (field.get("name") or "").lower() == "challenge"
                and isinstance(field.get("value"), str)
                and field.get("value")
                and isinstance(action, str)
                and action
            ):
                return action, field["value"]
    return None, None


class ShopUser(HttpUser):
    host = os.environ["BASE_URL"]
    wait_time = constant(0)

    def on_start(self):
        global _STARTED_USERS
        _STARTED_USERS += 1
        self.username = f"bench-{next(_USER_SEQUENCE) % 16 + 1}"
        self.csrf = None
        self.cart_id = None
        self.journey_index = 0
        self._counted_done = False

    def _request(self, method, url, expected, name, check=None, **kwargs):
        error = None
        with self.client.request(
            method,
            url,
            name=name,
            catch_response=True,
            allow_redirects=False,
            **kwargs,
        ) as response:
            if response.status_code not in expected:
                error = (
                    f"{method} {name}: unexpected HTTP "
                    f"{response.status_code}"
                )
            elif check is not None:
                try:
                    error = check(response)
                except Exception as exc:
                    error = f"{method} {name}: response assertion raised {exc!r}"

            if error:
                response.failure(error)

        if error:
            raise JourneyAbort(error)
        return response

    def _target_is_local(self, target):
        if not isinstance(target, str) or not target:
            return False
        parsed = urlsplit(target)
        if not parsed.scheme and not parsed.netloc:
            return True

        base = urlsplit(self.host)
        if parsed.netloc:
            return parsed.netloc.lower() == base.netloc.lower()
        return parsed.scheme.lower() == base.scheme.lower()

    def _remember_csrf(self, response):
        value = csrf_from_response(response)
        if value:
            self.csrf = value

    def _login(self, clear_cookies):
        if clear_cookies:
            self.client.cookies.clear()
        self.csrf = None

        form_state = {}

        def check_login_form(response):
            token = form_csrf(response.text)
            if not token:
                return "login form has no hidden input[name=csrf]"
            form_state["csrf"] = token
            return None

        self._request(
            "GET",
            "/v2/login-form",
            {200},
            "GET /v2/login-form",
            check=check_login_form,
        )

        login_state = {}

        def check_login(response):
            token = csrf_from_response(response)
            if token:
                login_state["csrf"] = token

            if response.status_code == 200:
                if not token:
                    return "login response has no CSRF token"
            elif response.status_code == 302:
                location = response.headers.get("Location")
                if not location or not self._target_is_local(location):
                    return "login redirect has no safe dynamic Location"
            return None

        response = self._request(
            "POST",
            "/v2/login",
            {200, 302},
            "POST /v2/login",
            check=check_login,
            json={
                "username": self.username,
                "password": "bench",
                "csrf": form_state["csrf"],
            },
        )
        if login_state.get("csrf"):
            self.csrf = login_state["csrf"]

        if response.status_code == 302:
            location = response.headers["Location"]

            def check_login_redirect(result):
                token = csrf_from_response(result)
                if token:
                    login_state["csrf"] = token
                if not login_state.get("csrf"):
                    return "login redirect response has no CSRF token"
                return None

            self._request(
                "GET",
                location,
                {200},
                "GET login redirect",
                check=check_login_redirect,
            )
            self.csrf = login_state["csrf"]

        if not self.csrf:
            raise JourneyAbort("login did not establish a CSRF token")

    def _renew(self):
        if not self.csrf:
            return False

        def check_renew(response):
            if response.status_code == 401:
                body = json_body(response) or {}
                if body.get("error") in ("expired", "session"):
                    return None
                return f"session renew denied: {body.get('error')!r}"
            if not csrf_from_response(response):
                return "session renew response has no fresh CSRF token"
            return None

        response = self._request(
            "POST",
            "/v2/session/renew",
            {200, 401},
            "POST /v2/session/renew",
            check=check_renew,
            headers={"X-CSRF-Token": self.csrf},
            json={},
        )
        if response.status_code != 200:
            return False

        self._remember_csrf(response)
        return True

    def _recover_cart(self, cart_id):
        def check_recover(response):
            if response.status_code == 200:
                body = json_body(response)
                if body is not None and body.get("ok") is False:
                    return "cart recovery was rejected"
            return None

        response = self._request(
            "POST",
            f"/v2/carts/{quote(str(cart_id), safe='')}/recover",
            {200, 204},
            "POST cart recover",
            check=check_recover,
            headers={"X-CSRF-Token": self.csrf},
            json={},
        )
        self._remember_csrf(response)

    def _recover_session(self, cart_id):
        if not self._renew():
            self._login(clear_cookies=True)
        if cart_id is not None:
            self._recover_cart(cart_id)

    def _auth_request(
        self,
        method,
        url,
        expected,
        name,
        check=None,
        recovery_cart_id=None,
        **kwargs,
    ):
        cart_id = (
            self.cart_id if recovery_cart_id is None else recovery_cart_id
        )

        def send(allow_recovery):
            statuses = set(expected)
            statuses.add(401)

            def validate(response):
                if response.status_code == 401:
                    if not allow_recovery:
                        return "unauthorized after bounded recovery"
                    body = json_body(response) or {}
                    if body.get("error") in ("expired", "session"):
                        return None
                    return f"authenticated request denied: {body.get('error')!r}"
                if check is not None:
                    return check(response)
                return None

            headers = dict(kwargs.pop("headers", {}) or {})
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf

            response = self._request(
                method,
                url,
                statuses,
                name,
                check=validate,
                headers=headers,
                **kwargs,
            )
            if method.upper() != "GET" and response.status_code < 400:
                self._remember_csrf(response)
            return response

        response = send(True)
        if response.status_code == 401:
            body = json_body(response) or {}
            self._recover_session(cart_id)
            response = send(False)
        return response

    def _catalog_choice(self):
        choice = {}

        def check_catalog(response):
            body = json_body(response)
            data = body.get("data") if body else None
            products = data.get("products") if isinstance(data, dict) else None
            if not isinstance(products, list):
                return "catalog response has no data.products list"

            for product in products:
                if not isinstance(product, dict) or product.get("id") is None:
                    continue
                variants = product.get("variants")
                if not isinstance(variants, list):
                    continue
                for variant in variants:
                    if not isinstance(variant, dict) or variant.get("id") is None:
                        continue
                    stock = variant.get("in_stock")
                    available = (
                        stock is True
                        or stock == 1
                        or (isinstance(stock, str) and stock.lower() == "true")
                    )
                    if available:
                        choice["product_id"] = product["id"]
                        choice["variant_id"] = variant["id"]
                        return None
            return "catalog has no in-stock product variant"

        self._request(
            "GET",
            "/v2/catalog",
            {200},
            "GET /v2/catalog",
            check=check_catalog,
        )
        return choice["product_id"], choice["variant_id"]

    def _get_challenge_grant(self):
        form_state = {}

        def check_form(response):
            action, challenge = challenge_fields(response.text)
            if not action or not challenge or not self._target_is_local(action):
                return "challenge form has no usable action and input[name=challenge]"
            form_state["action"] = action
            form_state["challenge"] = challenge
            return None

        self._request(
            "GET",
            "/v2/challenge-form",
            {200},
            "GET /v2/challenge-form",
            check=check_form,
        )

        def check_claim(response):
            location = response.headers.get("Location")
            if response.status_code != 302:
                return "challenge claim did not redirect"
            if not location or not self._target_is_local(location):
                return "challenge claim has no safe dynamic Location"
            return None

        self._auth_request(
            "POST",
            form_state["action"],
            {302},
            "POST challenge claim",
            check=check_claim,
            json={"challenge": form_state["challenge"]},
        )

        grant_state = {}

        def check_grant(response):
            body = json_body(response)
            if not body or body.get("grant_id") is None:
                return "challenge redirect has no grant_id"
            token = body.get("csrf")
            if not isinstance(token, str) or not token:
                return "challenge redirect has no CSRF token"
            grant_state["grant_id"] = body["grant_id"]
            grant_state["csrf"] = token
            return None

        location = response.headers["Location"]
        self._request(
            "GET",
            location,
            {200},
            "GET challenge redirect",
            check=check_grant,
        )
        self.csrf = grant_state["csrf"]
        return grant_state["grant_id"]

    def _cart_etag(self, cart_path):
        def check_cart(response):
            if not response.headers.get("ETag"):
                return "cart response has no ETag"
            return None

        response = self._auth_request(
            "GET",
            cart_path,
            {200},
            "GET cart",
            check=check_cart,
        )
        return response.headers["ETag"]

    def _set_quantity(self, cart_path):
        payload = {"quantity": 1}

        for attempt in range(2):
            etag = self._cart_etag(cart_path)

            def check_patch(response, final_attempt=attempt == 1):
                if response.status_code == 412 and final_attempt:
                    return "cart PATCH still returned 412 after one retry"
                return None

            response = self._auth_request(
                "PATCH",
                cart_path,
                {200, 204, 412},
                "PATCH cart quantity",
                check=check_patch,
                headers={"If-Match": etag},
                json=payload,
            )
            if response.status_code != 412:
                return

        raise JourneyAbort("cart quantity could not be updated")

    def _reserve(self, cart_id):
        state = {}

        def check_reservation(response):
            body = json_body(response)
            if not body or not isinstance(body.get("status_url"), str):
                return "reservation response has no status_url"
            status_url = body["status_url"]
            if not status_url or not self._target_is_local(status_url):
                return "reservation response has an unsafe status_url"
            state["status_url"] = status_url
            return None

        self._auth_request(
            "POST",
            "/v2/reservations",
            {202},
            "POST reservation",
            check=check_reservation,
            json={"cart_id": cart_id},
        )

        for poll_index in range(5):
            if poll_index:
                gevent.sleep(0.05)

            poll_state = {}

            def check_status(response, final_poll=poll_index == 4):
                body = json_body(response)
                if not body:
                    return "reservation status response is not JSON"
                status = body.get("status")
                if status == "failed":
                    return "reservation failed"
                if status == "pending":
                    if final_poll:
                        return "reservation remained pending after five polls"
                    return None
                if status == "ready":
                    if body.get("reservation_id") is None:
                        return "ready reservation has no reservation_id"
                    poll_state["reservation_id"] = body["reservation_id"]
                    return None
                return f"unknown reservation status: {status!r}"

            self._auth_request(
                "GET",
                state["status_url"],
                {200},
                "GET reservation status",
                check=check_status,
                recovery_cart_id=cart_id,
            )
            if "reservation_id" in poll_state:
                return poll_state["reservation_id"]

        raise JourneyAbort("reservation did not become ready")

    def _place_order(self, cart_id, reservation_id, etag):
        key = f"order-{self.username}-{self.journey_index}-{cart_id}"

        def check_order(response):
            body = json_body(response)
            if not body:
                return "order response is not JSON"
            if body.get("accepted") is not True:
                return "order was not accepted"
            if body.get("id") is None:
                return "accepted order has no id"
            return None

        self._auth_request(
            "POST",
            "/v2/orders",
            {200, 201},
            "POST order",
            check=check_order,
            headers={
                "Idempotency-Key": key,
                "If-Match": etag,
            },
            json={
                "cart_id": cart_id,
                "reservation_id": reservation_id,
            },
            recovery_cart_id=cart_id,
        )

    def _do_work(self):
        for attempt in range(5):
            retry_delay = {}

            def check_work(response):
                if response.status_code == 200:
                    body = json_body(response)
                    if not body or body.get("ok") is not True:
                        return "work response did not assert ok=true"
                    return None

                value = response.headers.get("Retry-After")
                try:
                    delay = float(value)
                except (TypeError, ValueError):
                    return "scheduled 429 has no valid Retry-After"
                if delay < 1:
                    return "scheduled 429 Retry-After is less than one second"
                retry_delay["seconds"] = delay
                return None

            response = self._auth_request(
                "POST",
                "/v2/work",
                {200, 429},
                "POST /v2/work",
                check=check_work,
                json={},
            )
            if response.status_code == 200:
                return
            if attempt < 4:
                gevent.sleep(retry_delay["seconds"])

    def _journey(self):
        self.client.cookies.clear()
        self.csrf = None
        self.cart_id = None

        self._login(clear_cookies=False)
        product_id, variant_id = self._catalog_choice()
        grant_id = self._get_challenge_grant()

        def check_cart_created(response):
            body = json_body(response)
            if not body or body.get("id") is None:
                return "cart creation response has no id"
            return None

        response = self._auth_request(
            "POST",
            "/v2/carts",
            {201},
            "POST cart",
            check=check_cart_created,
            json={
                "product_id": product_id,
                "variant_id": variant_id,
                "grant_id": grant_id,
            },
        )
        self.cart_id = json_body(response)["id"]
        cart_path = f"/v2/carts/{quote(str(self.cart_id), safe='')}"

        self._set_quantity(cart_path)
        reservation_id = self._reserve(self.cart_id)

        etag = self._cart_etag(cart_path)
        self._place_order(self.cart_id, reservation_id, etag)
        self._do_work()

    @task
    def run_journeys(self):
        global _DONE_USERS
        try:
            for index in range(ITERATIONS_PER_USER):
                self.journey_index = index
                try:
                    self._journey()
                except JourneyAbort:
                    # The failing response has already been marked; do not
                    # restart or duplicate this journey's cart/checkout.
                    continue
        finally:
            if not self._counted_done:
                self._counted_done = True
                _DONE_USERS += 1
        raise StopUser()


class FlowShape(LoadTestShape):
    def tick(self):
        if _DONE_USERS >= 2:
            return None
        if _STARTED_USERS < 2:
            return (2, 100)
        return (2 - _DONE_USERS, 100)

