                    return "login redirect response has no CSRF token"
                return None

            self._request(
                "GET",
                location,
                {200},
                "GET login redirect",
                check=check_login_redirect,
            )
            self.csrf = login_state["csrf"]

        if not self.csrf:
            raise JourneyAbort("login did not establish a CSRF token")

    def _renew(self):
        if not self.csrf:
            return False

        def check_renew(response):
            if response.status_code == 401:
                body = json_body(response) or {}
                if body.get("error") in ("expired", "session"):
                    return None
                return f"session renew denied: {body.get('error')!r}"
            if not csrf_from_response(response):
                return "session renew response has no fresh CSRF token"
            return None

        response = self._request(
            "POST",
            "/v2/session/renew",
            {200, 401},
            "POST /v2/session/renew",
            check=check_renew,
            headers={"X-CSRF-Token": self.csrf},
            json={},
        )
        if response.status_code != 200:
            return False

        self._remember_csrf(response)
        return True

    def _recover_cart(self, cart_id):
        def check_recover(response):
            if response.status_code == 200:
                body = json_body(response)
                if body is not None and body.get("ok") is False:
                    return "cart recovery was rejected"
            return None

        response = self._request(
            "POST",
            f"/v2/carts/{quote(str(cart_id), safe='')}/recover",
            {200, 204},
            "POST cart recover",
            check=check_recover,
            headers={"X-CSRF-Token": self.csrf},
            json={},
        )
        self._remember_csrf(response)

    def _recover_session(self, cart_id):
        if not self._renew():
            self._login(clear_cookies=True)
        if cart_id is not None:
            self._recover_cart(cart_id)

    def _auth_request(
        self,
        method,
        url,
        expected,
        name,
        check=None,
        recovery_cart_id=None,
        **kwargs,
    ):
        cart_id = (
            self.cart_id if recovery_cart_id is None else recovery_cart_id
        )
        base_kwargs = dict(kwargs)
        base_headers = dict(base_kwargs.pop("headers", {}) or {})

        def send(allow_recovery):
            statuses = set(expected)
            statuses.add(401)

            def validate(response):
                if response.status_code == 401:
                    if not allow_recovery:
                        return "unauthorized after bounded recovery"
                    body = json_body(response) or {}
                    if body.get("error") in ("expired", "session"):
                        return None
                    return f"authenticated request denied: {body.get('error')!r}"
                if check is not None:
                    return check(response)
                return None

            headers = dict(base_headers)
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf

            request_kwargs = dict(base_kwargs)
            response = self._request(
                method,
                url,
                statuses,
                name,
                check=validate,
                headers=headers,
                **request_kwargs,
            )
            if method.upper() != "GET" and response.status_code < 400:
                self._remember_csrf(response)
            return response

        response = send(True)
        if response.status_code == 401:
            self._recover_session(cart_id)
            response = send(False)
        return response

    def _catalog_choice(self):
        choice = {}

        def check_catalog(response):
            body = json_body(response)
            data = body.get("data") if body else None
            products = data.get("products") if isinstance(data, dict) else None
            if not isinstance(products, list):
                return "catalog response has no data.products list"

            for product in products:
                if not isinstance(product, dict) or product.get("id") is None:
                    continue
                variants = product.get("variants")
                if not isinstance(variants, list):
                    continue
                for variant in variants:
                    if (
                        not isinstance(variant, dict)
                        or variant.get("id") is None
                    ):
                        continue
                    stock = variant.get("in_stock")
                    available = (
                        stock is True
                        or stock == 1
                        or (
                            isinstance(stock, str)
                            and stock.lower() == "true"
                        )
                    )
                    if available:
                        choice["product_id"] = product["id"]
                        choice["variant_id"] = variant["id"]
                        return None
            return "catalog has no in-stock product variant"

        self._request(
            "GET",
            "/v2/catalog",
            {200},
            "GET /v2/catalog",
            check=check_catalog,
        )
        return choice["product_id"], choice["variant_id"]

    def _get_challenge_grant(self):
        form_state = {}

        def check_form(response):
            action, challenge = challenge_fields(response.text)
            if not action or not challenge or not self._target_is_local(action):
                return (
                    "challenge form has no usable action and "
                    "input[name=challenge]"
                )
            form_state["action"] = action
            form_state["challenge"] = challenge
            return None

        self._request(
            "GET",
            "/v2/challenge-form",
            {200},
            "GET /v2/challenge-form",
            check=check_form,
        )

        def check_claim(response):
            location = response.headers.get("Location")
            if response.status_code != 302:
                return "challenge claim did not redirect"
            if not location or not self._target_is_local(location):
                return "challenge claim has no safe dynamic Location"
            return None

        self._auth_request(
            "POST",
            form_state["action"],
            {302},
            "POST challenge claim",
            check=check_claim,
            json={"challenge": form_state["challenge"]},
        )

        grant_state = {}

        def check_grant(response):
            body = json_body(response)
            if not body or body.get("grant_id") is None:
                return "challenge redirect has no grant_id"
            token = body.get("csrf")
            if not isinstance(token, str) or not token:
                return "challenge redirect has no CSRF token"
            grant_state["grant_id"] = body["grant_id"]
            grant_state["csrf"] = token
            return None

        self._request(
            "GET",
            response.headers["Location"],
            {200},
            "GET challenge redirect",
            check=check_grant,
        )
        self.csrf = grant_state["csrf"]
        return grant_state["grant_id"]

    def _cart_etag(self, cart_path):
        def check_cart(response):
            if not response.headers.get("ETag"):
                return "cart response has no ETag"
            return None

        response = self._auth_request(
            "GET",
            cart_path,
            {200},
            "GET cart",
            check=check_cart,
        )
        return response.headers["ETag"]

    def _set_quantity(self, cart_path):
        payload = {"quantity": 1}

        for attempt in range(2):
            etag = self._cart_etag(cart_path)

            def check_patch(response, final_attempt=attempt == 1):
                if response.status_code == 412 and final_attempt:
                    return "cart PATCH still returned 412 after one retry"
                return None

            response = self._auth_request(
                "PATCH",
                cart_path,
                {200, 204, 412},
                "PATCH cart quantity",
                check=check_patch,
                headers={"If-Match": etag},
                json=payload,
            )
            if response.status_code != 412:
                return

        raise JourneyAbort("cart quantity could not be updated")

    def _reserve(self, cart_id):
        state = {}

        def check_reservation(response):
            body = json_body(response)
            if not body or not isinstance(body.get("status_url"), str):
                return "reservation response has no status_url"
            status_url = body["status_url"]
            if not status_url or not self._target_is_local(status_url):
                return "reservation response has an unsafe status_url"
            state["status_url"] = status_url
            return None

        self._auth_request(
            "POST",
            "/v2/reservations",
            {202},
            "POST reservation",
            check=check_reservation,
            json={"cart_id": cart_id},
        )

        for poll_index in range(5):
            if poll_index:
                gevent.sleep(0.05)

            poll_state = {}

            def check_status(response, final_poll=poll_index == 4):
                body = json_body(response)
                if not body:
                    return "reservation status response is not JSON"
                status = body.get("status")
                if status == "failed":
                    return "reservation failed"
                if status == "pending":
                    if final_poll:
                        return "reservation remained pending after five polls"
                    return None
                if status == "ready":
                    if body.get("reservation_id") is None:
                        return "ready reservation has no reservation_id"
                    poll_state["reservation_id"] = body["reservation_id"]
                    return None
                return f"unknown reservation status: {status!r}"

            self._auth_request(
                "GET",
                state["status_url"],
                {200},
                "GET reservation status",
                check=check_status,
                recovery_cart_id=cart_id,
            )
            if "reservation_id" in poll_state:
                return poll_state["reservation_id"]

        raise JourneyAbort("reservation did not become ready")

    def _place_order(self, cart_id, reservation_id, etag):
        key = f"order-{self.username}-{self.journey_index}-{cart_id}"

        def check_order(response):
            body = json_body(response)
            if not body:
                return "order response is not JSON"
            if body.get("accepted") is not True:
                return "order was not accepted"
            if body.get("id") is None:
                return "accepted order has no id"
            return None

        self._auth_request(
            "POST",
            "/v2/orders",
            {200, 201},
            "POST order",
            check=check_order,
            headers={
                "Idempotency-Key": key,
                "If-Match": etag,
            },
            json={
                "cart_id": cart_id,
                "reservation_id": reservation_id,
            },
            recovery_cart_id=cart_id,
        )

    def _do_work(self):
        for attempt in range(5):
            retry_delay = {}

            def check_work(response):
                if response.status_code == 200:
                    body = json_body(response)
                    if not body or body.get("ok") is not True:
                        return "work response did not assert ok=true"
                    return None

                value = response.headers.get("Retry-After")
                try:
                    delay = float(value)
                except (TypeError, ValueError):
                    return "scheduled 429 has no valid Retry-After"
                if delay < 1:
                    return "scheduled 429 Retry-After is less than one second"
                retry_delay["seconds"] = delay
                return None

            response = self._auth_request(
                "POST",
                "/v2/work",
                {200, 429},
                "POST /v2/work",
                check=check_work,
                json={},
            )
            if response.status_code == 200:
                return
            if attempt < 4:
                gevent.sleep(retry_delay["seconds"])

    def _journey(self):
        self.client.cookies.clear()
        self.csrf = None
        self.cart_id = None

        self._login(clear_cookies=False)
        product_id, variant_id = self._catalog_choice()
        grant_id = self._get_challenge_grant()

        def check_cart_created(response):
            body = json_body(response)
            if not body or body.get("id") is None:
                return "cart creation response has no id"
            return None

        response = self._auth_request(
            "POST",
            "/v2/carts",
            {201},
            "POST cart",
            check=check_cart_created,
            json={
                "product_id": product_id,
                "variant_id": variant_id,
                "grant_id": grant_id,
            },
        )
        self.cart_id = json_body(response)["id"]
        cart_path = f"/v2/carts/{quote(str(self.cart_id), safe='')}"

        self._set_quantity(cart_path)
        reservation_id = self._reserve(self.cart_id)

        etag = self._cart_etag(cart_path)
        self._place_order(self.cart_id, reservation_id, etag)
        self._do_work()

    @task
    def run_journeys(self):
        global _DONE_USERS
        try:
            for index in range(ITERATIONS_PER_USER):
                self.journey_index = index
                try:
                    self._journey()
                except JourneyAbort:
                    continue
        finally:
            if not self._counted_done:
                self._counted_done = True
                _DONE_USERS += 1
        raise StopUser()


class FlowShape(LoadTestShape):
    def tick(self):
        if _DONE_USERS >= 2:
            return None
        if _STARTED_USERS < 2:
            return (2, 100)
        return (2 - _DONE_USERS, 100)

import http from 'k6/http';
import { check, fail, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const ORIGIN_MATCH = BASE.match(/^https?:\/\/[^/]+/i);
if (!ORIGIN_MATCH) {
  throw new Error('BASE_URL must be an HTTP(S) URL');
}
const ORIGIN = ORIGIN_MATCH[0];

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '10m',
    },
  },
};

const businessFailure = new Rate('business_failure');

function assert(condition, message) {
  const passed = check(Boolean(condition), { [message]: (value) => value === true });
  if (!passed) {
    fail(message);
  }
}

function responseJson(response) {
  if (!response || !response.body) {
    return null;
  }
  try {
    return JSON.parse(response.body);
  } catch (_) {
    return null;
  }
}

function responseHeader(response, name) {
  if (!response || !response.headers) {
    return null;
  }
  const wanted = name.toLowerCase();
  for (const key in response.headers) {
    if (key.toLowerCase() === wanted) {
      const value = response.headers[key];
      return Array.isArray(value) ? value[0] : String(value);
    }
  }
  return null;
}

function updateCsrf(state, response) {
  const body = responseJson(response);
  if (body && typeof body.csrf === 'string' && body.csrf.length > 0) {
    state.csrf = body.csrf;
  }
}

function resolveLocal(reference, currentUrl) {
  assert(typeof reference === 'string' && reference.length > 0, 'Expected a non-empty URL reference');

  if (/^https?:\/\//i.test(reference)) {
    const refOrigin = (reference.match(/^https?:\/\/[^/]+/i) || [])[0];
    assert(refOrigin === ORIGIN, 'Refusing a URL outside the configured target');
    return reference;
  }
  assert(!reference.startsWith('//'), 'Refusing a protocol-relative URL');

  if (reference.startsWith('/')) {
    return ORIGIN + reference;
  }

  const current = currentUrl || BASE;
  const currentPath = current.replace(ORIGIN, '').split('#')[0];
  if (reference.startsWith('?')) {
    return ORIGIN + currentPath.split('?')[0] + reference;
  }

  const pathWithoutQuery = currentPath.split('?')[0];
  const slash = pathWithoutQuery.lastIndexOf('/');
  const joined = pathWithoutQuery.slice(0, slash + 1) + reference;
  const queryIndex = joined.indexOf('?');
  const rawPath = queryIndex >= 0 ? joined.slice(0, queryIndex) : joined;
  const query = queryIndex >= 0 ? joined.slice(queryIndex) : '';
  const segments = [];
  for (const segment of rawPath.split('/')) {
    if (!segment || segment === '.') {
      continue;
    }
    if (segment === '..') {
      segments.pop();
    } else {
      segments.push(segment);
    }
  }
  return ORIGIN + '/' + segments.join('/') + query;
}

function requestParams(headers, tags) {
  return {
    redirects: 0,
    headers: headers || {},
    tags: tags || {},
  };
}

function parseAttributes(tag) {
  const attrs = {};
  const start = tag.indexOf(' ');
  const content = start >= 0 ? tag.slice(start + 1) : '';
  const pattern = /([^\s=\/>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/g;
  let match;
  while ((match = pattern.exec(content)) !== null) {
    const key = match[1].toLowerCase();
    let value = match[2];
    if (value === undefined) value = match[3];
    if (value === undefined) value = match[4];
    if (value === undefined) value = '';
    value = value.replace(/\/$/, '');
    attrs[key] = value;
  }
  return attrs;
}

function findInputValue(html, inputName) {
  const tags = html.match(/<input\b[^>]*>/gi) || [];
  for (const tag of tags) {
    const attrs = parseAttributes(tag);
    if ((attrs.name || '').toLowerCase() === inputName.toLowerCase() &&
        Object.prototype.hasOwnProperty.call(attrs, 'value')) {
      return attrs.value;
    }
  }
  return null;
}

function getFreshLoginCsrf(state, username) {
  const formResponse = http.get(resolveLocal('/v2/login-form'), requestParams({}, { name: 'login-form' }));
  assert(formResponse.status === 200, 'Login form must load successfully');

  const formCsrf = findInputValue(formResponse.body || '', 'csrf');
  assert(formCsrf, 'Login form must contain input[name=csrf]');

  const loginResponse = http.post(
    resolveLocal('/v2/login'),
    JSON.stringify({ username: username, password: 'bench', csrf: formCsrf }),
    requestParams({ 'Content-Type': 'application/json' }, { name: 'login' })
  );

  updateCsrf(state, loginResponse);
  if (loginResponse.status === 302) {
    const location = responseHeader(loginResponse, 'Location');
    assert(location, 'Login redirect must include Location');
    const landingResponse = http.get(
      resolveLocal(location, resolveLocal('/v2/login')),
      requestParams({}, { name: 'login-redirect' })
    );
    assert(landingResponse.status >= 200 && landingResponse.status < 300, 'Login redirect target must succeed');
    updateCsrf(state, landingResponse);
  } else {
    assert(loginResponse.status >= 200 && loginResponse.status < 300, 'Login must succeed');
  }

  assert(state.csrf, 'Login must provide a CSRF token');
}

function directAuthenticatedPost(state, path, payload, tags) {
  assert(state.csrf, 'Authenticated mutation requires a CSRF token');
  const response = http.post(
    resolveLocal(path),
    JSON.stringify(payload),
    requestParams(
      {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      tags
    )
  );
  updateCsrf(state, response);
  return response;
}

function recoverCart(state, cartId) {
  const response = directAuthenticatedPost(
    state,
    '/v2/carts/' + encodeURIComponent(String(cartId)) + '/recover',
    {},
    { name: 'cart-recover' }
  );
  assert(response.status >= 200 && response.status < 300, 'Cart recovery must succeed');
}

function renewSession(state, cartId) {
  const response = directAuthenticatedPost(state, '/v2/session/renew', {}, { name: 'session-renew' });
  assert(response.status >= 200 && response.status < 300, 'Expired session renewal must succeed');
  assert(state.csrf, 'Session renewal must provide a fresh CSRF token');
  if (cartId !== null && cartId !== undefined) {
    recoverCart(state, cartId);
  }
}

function handleAuthenticationFailure(state, response, cartId, username) {
  const body = responseJson(response);
  const error = body && body.error;
  if (error === 'expired') {
    renewSession(state, cartId);
    return true;
  }
  if (error === 'session') {
    getFreshLoginCsrf(state, username);
    if (cartId !== null && cartId !== undefined) {
      recoverCart(state, cartId);
    }
    return true;
  }
  return false;
}

function authenticatedRequest(state, method, path, payload, extraHeaders, cartId, username, observer, tags) {
  function send() {
    assert(state.csrf, 'Authenticated mutation requires a CSRF token');
    const headers = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    };
    if (extraHeaders) {
      for (const key in extraHeaders) {
        headers[key] = extraHeaders[key];
      }
    }
    const response = http.request(
      method,
      resolveLocal(path),
      JSON.stringify(payload),
      requestParams(headers, tags)
    );
    updateCsrf(state, response);
    if (observer) {
      observer(response);
    }
    return response;
  }

  let response = send();
  if (response.status === 401 && handleAuthenticationFailure(state, response, cartId, username)) {
    response = send();
  }
  return response;
}

function authenticatedCartGet(state, cartId, username) {
  const path = '/v2/carts/' + encodeURIComponent(String(cartId));

  function send() {
    return http.get(resolveLocal(path), requestParams({}, { name: 'cart-get' }));
  }

  let response = send();
  if (response.status === 401 && handleAuthenticationFailure(state, response, cartId, username)) {
    response = send();
  }
  assert(response.status === 200, 'Cart must be readable');
  return response;
}

function productsFrom(body) {
  if (!body || typeof body !== 'object') {
    return [];
  }
  if (body.data && Array.isArray(body.data.products)) {
    return body.data.products;
  }
  if (Array.isArray(body.products)) {
    return body.products;
  }
  if (body.data && body.data.product && typeof body.data.product === 'object') {
    return [body.data.product];
  }
  if (body.product && typeof body.product === 'object') {
    return [body.product];
  }
  if (body.data && body.data.id !== undefined && Array.isArray(body.data.variants)) {
    return [body.data];
  }
  if (body.id !== undefined && Array.isArray(body.variants)) {
    return [body];
  }
  return [];
}

function nextPageFrom(body) {
  if (!body || typeof body !== 'object') {
    return null;
  }
  if (Object.prototype.hasOwnProperty.call(body, 'next')) {
    return body.next;
  }
  if (body.data && Object.prototype.hasOwnProperty.call(body.data, 'next')) {
    return body.data.next;
  }
  return null;
}

function eligibleProduct(products) {
  for (const product of products) {
    if (!product || product.id === undefined || product.id === null || !Array.isArray(product.variants)) {
      continue;
    }
    for (const variant of product.variants) {
      if (variant && variant.id !== undefined && variant.id !== null && variant.in_stock === true) {
        return { productId: product.id, variantId: variant.id };
      }
    }
  }
  return null;
}

function selectProduct() {
  const catalogResponse = http.get(resolveLocal('/v2/catalog'), requestParams({}, { name: 'catalog' }));
  assert(catalogResponse.status === 200, 'Catalog must load successfully');

  const catalogBody = responseJson(catalogResponse);
  let selected = eligibleProduct(productsFrom(catalogBody));
  if (selected) {
    return selected;
  }

  let next = nextPageFrom(catalogBody);
  let currentUrl = resolveLocal('/v2/catalog');

  if (!next) {
    next = '/v2/catalog/page';
  }

  for (let page = 0; page < 3 && next; page += 1) {
    currentUrl = resolveLocal(String(next), currentUrl);
    const pageResponse = http.get(currentUrl, requestParams({}, { name: 'catalog-page' }));
    assert(pageResponse.status === 200, 'Catalog page must load successfully');
    const pageBody = responseJson(pageResponse);
    selected = eligibleProduct(productsFrom(pageBody));
    if (selected) {
      return selected;
    }
    next = nextPageFrom(pageBody);
  }

  fail('No in-stock product with a parent-specific variant was found');
}

function challengeDetails(html) {
  const formTags = html.match(/<form\b[^>]*>/gi) || [];
  let action = null;
  for (const tag of formTags) {
    const attrs = parseAttributes(tag);
    if (attrs.action && /\/v2\/challenges\//.test(attrs.action)) {
      action = attrs.action;
      break;
    }
  }
  const challenge = findInputValue(html, 'challenge');
  return { action: action, challenge: challenge };
}

function obtainGrant(state, username) {
  const formResponse = http.get(
    resolveLocal('/v2/challenge-form'),
    requestParams({}, { name: 'challenge-form' })
  );
  assert(formResponse.status === 200, 'Challenge form must load successfully');

  const details = challengeDetails(formResponse.body || '');
  assert(details.action, 'Challenge form must contain a challenge action');
  assert(details.challenge, 'Challenge form must contain input[name=challenge]');

  const challengeResponse = authenticatedRequest(
    state,
    'POST',
    resolveLocal(details.action, resolveLocal('/v2/challenge-form')),
    { challenge: details.challenge },
    {},
    null,
    username,
    null,
    { name: 'challenge-submit' }
  );

  assert(challengeResponse.status === 302, 'Challenge submission must return a redirect');
  const location = responseHeader(challengeResponse, 'Location');
  assert(location, 'Challenge redirect must include Location');

  const grantResponse = http.get(
    resolveLocal(location, resolveLocal(details.action, resolveLocal('/v2/challenge-form'))),
    requestParams({}, { name: 'challenge-redirect' })
  );
  assert(grantResponse.status >= 200 && grantResponse.status < 300, 'Challenge redirect target must succeed');

  const grantBody = responseJson(grantResponse);
  if (grantBody && typeof grantBody.csrf === 'string' && grantBody.csrf.length > 0) {
    state.csrf = grantBody.csrf;
  }
  assert(grantBody && grantBody.grant_id !== undefined && grantBody.grant_id !== null, 'Challenge must provide a grant_id');
  return grantBody.grant_id;
}

function retryAfterSeconds(response) {
  const value = responseHeader(response, 'Retry-After');
  if (value === null) {
    return null;
  }
  const trimmed = String(value).trim();
  const seconds = Number(trimmed);
  return seconds === 1 ? 1 : null;
}

function noteWorkResponse(response) {
  const body = responseJson(response);
  const expired = response.status === 401 && body && body.error === 'expired';
  const scheduled429 = response.status === 429 && retryAfterSeconds(response) === 1;
  const successful = response.status === 200 && body && body.ok === true;
  businessFailure.add(!(expired || scheduled429 || successful));
}

function runWork(state, cartId, username) {
  let response = null;

  for (let attempt = 0; attempt <= 4; attempt += 1) {
    response = authenticatedRequest(
      state,
      'POST',
      '/v2/work',
      {},
      {},
      cartId,
      username,
      noteWorkResponse,
      { name: 'work' }
    );

    if (response.status === 429 && retryAfterSeconds(response) === 1 && attempt < 4) {
      sleep(1);
      continue;
    }
    break;
  }

  const body = responseJson(response);
  assert(response.status === 200 && body && body.ok === true, 'Work request must succeed');
}

function runJourney() {
  const username = 'bench-' + String(__VU);
  const state = { csrf: null };

  getFreshLoginCsrf(state, username);

  const product = selectProduct();
  assert(product && product.productId !== undefined && product.variantId !== undefined, 'An eligible product and its own variant must be selected');

  const grantId = obtainGrant(state, username);
  const cartResponse = authenticatedRequest(
    state,
    'POST',
    '/v2/carts',
    {
      product_id: product.productId,
      variant_id: product.variantId,
      grant_id: grantId,
    },
    {},
    null,
    username,
    null,
    { name: 'cart-create' }
  );
  assert(cartResponse.status === 201, 'Exactly one cart must be created successfully');

  const cartBody = responseJson(cartResponse);
  assert(cartBody && cartBody.id !== undefined && cartBody.id !== null, 'Cart creation must provide an ID');
  if (typeof cartBody.csrf === 'string' && cartBody.csrf.length > 0) {
    state.csrf = cartBody.csrf;
  }
  const cartId = cartBody.id;
  let etag = responseHeader(cartResponse, 'ETag');

  const initialCart = authenticatedCartGet(state, cartId, username);
  etag = responseHeader(initialCart, 'ETag') || etag;
  assert(etag, 'Cart must provide an ETag for conditional updates');

  const quantityPayload = { quantity: 1 };
  let patchResponse = authenticatedRequest(
    state,
    'PATCH',
    '/v2/carts/' + encodeURIComponent(String(cartId)),
    quantityPayload,
    { 'If-Match': etag },
    cartId,
    username,
    null,
    { name: 'cart-patch' }
  );

  if (patchResponse.status === 412) {
    const reread = authenticatedCartGet(state, cartId, username);
    etag = responseHeader(reread, 'ETag');
    assert(etag, 'Cart re-read after 412 must provide an ETag');
    patchResponse = authenticatedRequest(
      state,
      'PATCH',
      '/v2/carts/' + encodeURIComponent(String(cartId)),
      quantityPayload,
      { 'If-Match': etag },
      cartId,
      username,
      null,
      { name: 'cart-patch-retry' }
    );
  }
  assert(patchResponse.status >= 200 && patchResponse.status < 300, 'Cart quantity update must succeed');
  etag = responseHeader(patchResponse, 'ETag') || etag;

  const reservationResponse = authenticatedRequest(
    state,
    'POST',
    '/v2/reservations',
    { cart_id: cartId },
    {},
    cartId,
    username,
    null,
    { name: 'reservation-create' }
  );
  assert(reservationResponse.status === 202, 'Reservation request must be accepted');

  const reservationBody = responseJson(reservationResponse);
  assert(reservationBody && reservationBody.status_url, 'Reservation response must provide a status URL');

  const statusUrl = resolveLocal(String(reservationBody.status_url), resolveLocal('/v2/reservations'));
  let reservationId = null;
  for (let poll = 0; poll < 5; poll += 1) {
    sleep(0.05);
    const statusResponse = http.get(statusUrl, requestParams({}, { name: 'reservation-poll' }));
    assert(statusResponse.status === 200, 'Reservation status poll must succeed');
    const statusBody = responseJson(statusResponse);
    assert(statusBody && typeof statusBody.status === 'string', 'Reservation poll must provide a status');

    if (statusBody.status === 'ready') {
      assert(statusBody.reservation_id !== undefined && statusBody.reservation_id !== null, 'Ready reservation must provide an ID');
      reservationId = statusBody.reservation_id;
      break;
    }
    if (statusBody.status === 'failed') {
      fail('Reservation failed and must not proceed to checkout');
    }
    assert(statusBody.status === 'pending', 'Reservation must be pending or ready');
  }
  assert(reservationId !== null, 'Reservation did not become ready within five polls');

  const idempotencyKey = 'order-' + encodeURIComponent(String(cartId));
  const orderResponse = authenticatedRequest(
    state,
    'POST',
    '/v2/orders',
    { cart_id: cartId, reservation_id: reservationId },
    {
      'Idempotency-Key': idempotencyKey,
      'If-Match': etag,
    },
    cartId,
    username,
    null,
    { name: 'order-create' }
  );
  const orderBody = responseJson(orderResponse);
  assert(
    orderResponse.status === 201 && orderBody && orderBody.accepted === true && orderBody.id !== undefined,
    'Exactly one order must be committed successfully'
  );

  runWork(state, cartId, username);
}

export default function () {
  runJourney();
}

import itertools
import os
import time
import uuid
from html.parser import HTMLParser
from urllib.parse import urlsplit

from locust import HttpUser, LoadTestShape, StopUser, constant, task


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
ITERATIONS_PER_USER = 2
VIRTUAL_USERS = 2


class FormParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.forms = []
        self.current_form = None

    def handle_starttag(self, tag, attrs):
        attrs = {key.lower(): value for key, value in attrs if key}
        if tag.lower() == "form":
            self.current_form = {"attrs": attrs, "inputs": []}
            self.forms.append(self.current_form)
        elif tag.lower() == "input" and self.current_form is not None:
            self.current_form["inputs"].append(attrs)

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self.current_form = None


def _json_body(response):
    try:
        value = response.json()
        return value if isinstance(value, dict) else None
    except (ValueError, TypeError):
        return None


def _form_field(html, field_name):
    parser = FormParser()
    parser.feed(html)
    for form in parser.forms:
        for field in form["inputs"]:
            if field.get("name") == field_name and field.get("value"):
                return field["value"]
    raise AssertionError(f"Form input[name={field_name!r}] was not found")


def _challenge_form(html):
    parser = FormParser()
    parser.feed(html)
    for form in parser.forms:
        for field in form["inputs"]:
            if field.get("name") == "challenge" and field.get("value"):
                action = form["attrs"].get("action")
                if action:
                    return action, field["value"]
    raise AssertionError("Challenge form action or input[name='challenge'] was not found")


class ShopFlowUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    _account_counter = itertools.count(1)
    completed_users = 0

    def on_start(self):
        account_number = (next(type(self)._account_counter) - 1) % 16 + 1
        self.username = f"bench-{account_number}"
        self.password = "bench"
        self.csrf = None

    def _safe_local_url(self, url):
        if not isinstance(url, str) or not url:
            raise AssertionError("Expected a non-empty URL")

        parsed = urlsplit(url)
        if parsed.scheme or parsed.netloc:
            base = urlsplit(self.host)
            if (
                parsed.scheme.lower() != base.scheme.lower()
                or parsed.netloc.lower() != base.netloc.lower()
            ):
                raise AssertionError("Refusing to request a URL outside BASE_URL")
            return url

        if url.startswith("//"):
            raise AssertionError("Refusing a protocol-relative URL")
        return url

    def _capture_csrf(self, response):
        body = _json_body(response)
        if body and body.get("csrf"):
            self.csrf = str(body["csrf"])

    def _login(self):
        form_response = self.client.get(
            "/v2/login-form", allow_redirects=False
        )
        if form_response.status_code != 200:
            raise AssertionError(
                f"Login form returned HTTP {form_response.status_code}"
            )
        login_csrf = _form_field(form_response.text, "csrf")

        with self.client.post(
            "/v2/login",
            json={
                "username": self.username,
                "password": self.password,
                "csrf": login_csrf,
            },
            allow_redirects=False,
            catch_response=True,
        ) as response:
            if response.status_code == 200:
                body = _json_body(response)
                valid = bool(body and body.get("csrf"))
            elif response.status_code in (302, 303):
                valid = bool(response.headers.get("Location"))
            else:
                valid = False

            if valid:
                response.success()
            else:
                response.failure("Login failed or returned no CSRF/Location")

        if response.status_code in (302, 303):
            location = self._safe_local_url(response.headers["Location"])
            with self.client.get(
                location, allow_redirects=False, catch_response=True
            ) as landing:
                body = _json_body(landing)
                valid = landing.status_code == 200 and bool(
                    body and body.get("csrf")
                )
                if valid:
                    landing.success()
                else:
                    landing.failure("Login redirect did not return login data")
            self._capture_csrf(landing)
        else:
            self._capture_csrf(response)

        if not self.csrf:
            raise AssertionError("Login did not provide a CSRF token")

    def _control_request(
        self,
        method,
        path,
        json_body=None,
        expected_statuses=(200,),
        validator=None,
    ):
        headers = {}
        if method.upper() != "GET":
            if not self.csrf:
                raise AssertionError("No CSRF token for authenticated mutation")
            headers["X-CSRF-Token"] = self.csrf

        with self.client.request(
            method,
            path,
            json=json_body,
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        ) as response:
            valid = response.status_code in expected_statuses
            if valid and validator is not None:
                try:
                    valid = bool(validator(response))
                except Exception:
                    valid = False

            if valid:
                response.success()
            else:
                response.failure(
                    f"Unexpected {method} {path} response: "
                    f"HTTP {response.status_code}"
                )

        if response.status_code < 400 and method.upper() != "GET":
            self._capture_csrf(response)
        return response

    def _recover_session(self, original_error, cart_id=None):
        if original_error not in ("expired", "session"):
            raise AssertionError(f"Authentication denied: {original_error!r}")

        renew = self._control_request(
            "POST",
            "/v2/session/renew",
            json_body={},
            expected_statuses=(200, 401),
            validator=lambda response: (
                response.status_code == 200
                or (
                    (_json_body(response) or {}).get("error")
                    in ("expired", "session")
                )
            ),
        )

        relogged = renew.status_code != 200
        if relogged:
            self._login()

        if cart_id is not None:
            self._control_request(
                "POST",
                f"/v2/carts/{cart_id}/recover",
                json_body={},
                expected_statuses=(200, 201, 204),
            )

        return relogged

    def _authorized_request(
        self,
        method,
        path,
        json_body=None,
        extra_headers=None,
        expected_statuses=None,
        validator=None,
        allow_412=False,
        cart_id=None,
        rebuild_on_login=None,
        capture_csrf_on_get=False,
        retry_delay=0,
    ):
        method = method.upper()
        current_path = path
        current_body = json_body
        current_extra_headers = dict(extra_headers or {})

        for attempt in range(2):
            headers = dict(current_extra_headers)
            if method != "GET":
                if not self.csrf:
                    raise AssertionError("No CSRF token for authenticated mutation")
                headers["X-CSRF-Token"] = self.csrf

            needs_recovery = False
            valid = False

            with self.client.request(
                method,
                current_path,
                json=current_body,
                headers=headers,
                allow_redirects=False,
                catch_response=True,
            ) as response:
                body = _json_body(response)
                error = body.get("error") if body else None

                if (
                    response.status_code == 401
                    and error in ("expired", "session")
                    and attempt == 0
                ):
                    response.success()
                    needs_recovery = True
                elif response.status_code == 412 and allow_412:
                    response.success()
                    valid = True
                else:
                    if expected_statuses is None:
                        valid = 200 <= response.status_code < 400
                    else:
                        valid = response.status_code in expected_statuses

                    if valid and validator is not None:
                        try:
                            valid = bool(validator(response))
                        except Exception:
                            valid = False

                    if valid:
                        response.success()
                    else:
                        response.failure(
                            f"Unexpected {method} {current_path} response: "
                            f"HTTP {response.status_code}"
                        )

            if needs_recovery:
                relogged = self._recover_session(error, cart_id=cart_id)
                if relogged and rebuild_on_login is not None:
                    current_path, current_body, current_extra_headers = (
                        rebuild_on_login()
                    )
                if retry_delay:
                    time.sleep(retry_delay)
                continue

            if not valid:
                raise AssertionError(
                    f"Request failed: {method} {current_path}, "
                    f"HTTP {response.status_code}"
                )

            if response.status_code < 400 and (
                method != "GET" or capture_csrf_on_get
            ):
                self._capture_csrf(response)
            return response

        raise AssertionError(f"Recovery exhausted for {method} {current_path}")

    def _get_challenge_material(self):
        response = self.client.get(
            "/v2/challenge-form", allow_redirects=False
        )
        if response.status_code != 200:
            raise AssertionError(
                f"Challenge form returned HTTP {response.status_code}"
            )
        action, challenge = _challenge_form(response.text)
        return self._safe_local_url(action), challenge

    def _obtain_grant(self):
        action, challenge = self._get_challenge_material()

        def rebuild_after_login():
            new_action, new_challenge = self._get_challenge_material()
            return new_action, {"challenge": new_challenge}, {}

        response = self._authorized_request(
            "POST",
            action,
            json_body={"challenge": challenge},
            expected_statuses=(302, 303),
            validator=lambda result: bool(result.headers.get("Location")),
            rebuild_on_login=rebuild_after_login,
        )

        location = self._safe_local_url(response.headers["Location"])
        landing = self._authorized_request(
            "GET",
            location,
            expected_statuses=(200,),
            validator=lambda result: bool(
                (_json_body(result) or {}).get("grant_id")
                and (_json_body(result) or {}).get("csrf")
            ),
            capture_csrf_on_get=True,
            retry_delay=0.05,
        )
        body = _json_body(landing)
        return str(body["grant_id"])

    def _select_in_stock_product(self):
        path = "/v2/catalog"

        for page_number in range(3):
            response = self.client.get(path, allow_redirects=False)
            if response.status_code != 200:
                raise AssertionError(
                    f"Catalog returned HTTP {response.status_code}"
                )

            payload = _json_body(response)
            data = payload.get("data") if payload else None
            products = data.get("products") if isinstance(data, dict) else None
            if not isinstance(products, list):
                raise AssertionError("Catalog response has no data.products list")

            for product in products:
                if not isinstance(product, dict) or product.get("id") is None:
                    continue
                variants = product.get("variants")
                if not isinstance(variants, list):
                    continue
                for variant in variants:
                    if (
                        isinstance(variant, dict)
                        and variant.get("id") is not None
                        and variant.get("in_stock") is True
                    ):
                        return product["id"], variant["id"]

            next_url = payload.get("next")
            if not next_url or page_number == 2:
                break
            path = self._safe_local_url(next_url)

        raise AssertionError("No in-stock product variant found in catalog pages")

    def _read_cart_etag(self, cart_id):
        response = self._authorized_request(
            "GET",
            f"/v2/carts/{cart_id}",
            expected_statuses=(200,),
            validator=lambda result: bool(result.headers.get("ETag")),
        )
        return response.headers["ETag"]

    def _reserve(self, cart_id):
        response = self._authorized_request(
            "POST",
            "/v2/reservations",
            json_body={"cart_id": cart_id},
            expected_statuses=(202,),
            validator=lambda result: bool(
                (_json_body(result) or {}).get("status_url")
            ),
            cart_id=cart_id,
        )
        status_url = self._safe_local_url(
            _json_body(response)["status_url"]
        )

        last_poll = None
        for poll_number in range(5):
            if last_poll is not None:
                remaining = 0.05 - (time.monotonic() - last_poll)
                if remaining > 0:
                    time.sleep(remaining)

            last_poll = time.monotonic()

            def valid_status(result):
                body = _json_body(result) or {}
                status = body.get("status")
                if status == "ready":
                    return bool(body.get("reservation_id"))
                if status == "pending":
                    return poll_number < 4
                return False

            poll = self._authorized_request(
                "GET",
                status_url,
                expected_statuses=(200,),
                validator=valid_status,
                cart_id=cart_id,
                capture_csrf_on_get=True,
                retry_delay=0.05,
            )
            body = _json_body(poll) or {}
            if body.get("status") == "ready":
                return str(body["reservation_id"])

        raise AssertionError("Reservation did not become ready within five polls")

    def _run_work(self, cart_id):
        auth_retries = 0
        scheduled_retries = 0

        while True:
            headers = {"X-CSRF-Token": self.csrf}
            recover_error = None
            retry_after = None
            should_retry_429 = False

            with self.client.post(
                "/v2/work",
                json={},
                headers=headers,
                name="POST /v2/work",
                allow_redirects=False,
                catch_response=True,
            ) as response:
                body = _json_body(response) or {}

                if response.status_code == 200 and body.get("ok") is True:
                    response.success()
                    self._capture_csrf(response)
                elif (
                    response.status_code == 401
                    and body.get("error") in ("expired", "session")
                    and auth_retries == 0
                ):
                    response.success()
                    recover_error = body["error"]
                elif response.status_code == 429:
                    try:
                        retry_after = float(response.headers.get("Retry-After", ""))
                    except (TypeError, ValueError):
                        retry_after = None

                    if retry_after is not None and retry_after >= 1.0:
                        response.success()
                        should_retry_429 = scheduled_retries < 4
                    else:
                        response.failure("429 response lacked Retry-After of at least 1s")
                else:
                    response.failure(
                        f"Unexpected /v2/work response: HTTP {response.status_code}"
                    )

            if recover_error is not None:
                try:
                    self._recover_session(recover_error, cart_id=cart_id)
                except Exception:
                    return
                auth_retries += 1
                continue

            if response.status_code == 429:
                if should_retry_429:
                    scheduled_retries += 1
                    time.sleep(max(1.0, retry_after))
                    continue
                return

            return

    def _journey(self):
        self._login()
        product_id, variant_id = self._select_in_stock_product()

        grant_id = self._obtain_grant()

        def rebuild_cart_after_login():
            fresh_grant = self._obtain_grant()
            return (
                "/v2/carts",
                {
                    "product_id": product_id,
                    "variant_id": variant_id,
                    "grant_id": fresh_grant,
                },
                {},
            )

        cart_response = self._authorized_request(
            "POST",
            "/v2/carts",
            json_body={
                "product_id": product_id,
                "variant_id": variant_id,
                "grant_id": grant_id,
            },
            expected_statuses=(201,),
            validator=lambda result: bool((_json_body(result) or {}).get("id")),
            rebuild_on_login=rebuild_cart_after_login,
        )
        cart_id = str(_json_body(cart_response)["id"])

        etag = cart_response.headers.get("ETag")
        if not etag:
            etag = self._read_cart_etag(cart_id)

        patch_payload = {"quantity": 1}

        def patch_cart(current_etag, allow_precondition_retry):
            return self._authorized_request(
                "PATCH",
                f"/v2/carts/{cart_id}",
                json_body=patch_payload,
                extra_headers={"If-Match": current_etag},
                expected_statuses=(200, 204),
                allow_412=allow_precondition_retry,
                cart_id=cart_id,
            )

        patch_response = patch_cart(etag, True)
        if patch_response.status_code == 412:
            etag = self._read_cart_etag(cart_id)
            patch_response = patch_cart(etag, False)

        reservation_id = self._reserve(cart_id)
        etag = self._read_cart_etag(cart_id)

        idempotency_key = f"bench-order-{cart_id}-{uuid.uuid4().hex}"
        self._authorized_request(
            "POST",
            "/v2/orders",
            json_body={
                "cart_id": cart_id,
                "reservation_id": reservation_id,
            },
            extra_headers={
                "If-Match": etag,
                "Idempotency-Key": idempotency_key,
            },
            expected_statuses=(201,),
            validator=lambda result: (
                (_json_body(result) or {}).get("accepted") is True
            ),
            cart_id=cart_id,
        )

        self._run_work(cart_id)

    @task
    def execute_flow(self):
        try:
            for _ in range(ITERATIONS_PER_USER):
                self._journey()
        finally:
            type(self).completed_users += 1
        raise StopUser()


class FlowShape(LoadTestShape):
    def tick(self):
        completed = ShopFlowUser.completed_users
        current = self.runner.user_count

        if completed >= VIRTUAL_USERS:
            if current == 0:
                return None
            return current, 1

        target = max(VIRTUAL_USERS - completed, current)
        return target, max(1, target)

