import itertools
import os
import time
import uuid
from html.parser import HTMLParser
from urllib.parse import urlsplit

from locust import HttpUser, LoadTestShape, StopUser, constant, task


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
ITERATIONS_PER_USER = 2
VIRTUAL_USERS = 2


class FormParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.forms = []
        self.current_form = None

    def handle_starttag(self, tag, attrs):
        attrs = {key.lower(): value for key, value in attrs if key}
        if tag.lower() == "form":
            self.current_form = {"attrs": attrs, "inputs": []}
            self.forms.append(self.current_form)
        elif tag.lower() == "input" and self.current_form is not None:
            self.current_form["inputs"].append(attrs)

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self.current_form = None


def _json_body(response):
    try:
        value = response.json()
        return value if isinstance(value, dict) else None
    except (ValueError, TypeError):
