    parser.feed(html)
    for form in parser.forms:
        for field in form["inputs"]:
            if field.get("name") == field_name and field.get("value"):
                return field["value"]
    raise AssertionError(f"Form input[name={field_name!r}] was not found")


def _challenge_form(html):
    parser = FormParser()
    parser.feed(html)
    for form in parser.forms:
        for field in form["inputs"]:
            if field.get("name") == "challenge" and field.get("value"):
                action = form["attrs"].get("action")
                if action:
                    return action, field["value"]
    raise AssertionError("Challenge form action or input[name='challenge'] was not found")


class ShopFlowUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    _account_counter = itertools.count(1)
    completed_users = 0

    def on_start(self):
        account_number = (next(type(self)._account_counter) - 1) % 16 + 1
        self.username = f"bench-{account_number}"
        self.password = "bench"
        self.csrf = None

    def _safe_local_url(self, url):
        if not isinstance(url, str) or not url:
            raise AssertionError("Expected a non-empty URL")

        parsed = urlsplit(url)
        if parsed.scheme or parsed.netloc:
            base = urlsplit(self.host)
            if (
                parsed.scheme.lower() != base.scheme.lower()
                or parsed.netloc.lower() != base.netloc.lower()
            ):
                raise AssertionError("Refusing to request a URL outside BASE_URL")
            return url

        if url.startswith("//"):
            raise AssertionError("Refusing a protocol-relative URL")
        return url

    def _capture_csrf(self, response):
        body = _json_body(response)
        if body and body.get("csrf"):
            self.csrf = str(body["csrf"])

    def _login(self):
        form_response = self.client.get(
            "/v2/login-form", allow_redirects=False
        )
        if form_response.status_code != 200:
            raise AssertionError(
                f"Login form returned HTTP {form_response.status_code}"
            )
        login_csrf = _form_field(form_response.text, "csrf")

        with self.client.post(
            "/v2/login",
            json={
                "username": self.username,
                "password": self.password,
                "csrf": login_csrf,
            },
            allow_redirects=False,
            catch_response=True,
        ) as response:
            if response.status_code == 200:
                body = _json_body(response)
                valid = bool(body and body.get("csrf"))
            elif response.status_code in (302, 303):
                valid = bool(response.headers.get("Location"))
            else:
                valid = False

            if valid:
                response.success()
            else:
                response.failure("Login failed or returned no CSRF/Location")

        if response.status_code in (302, 303):
            location = self._safe_local_url(response.headers["Location"])
            with self.client.get(
                location, allow_redirects=False, catch_response=True
            ) as landing:
                body = _json_body(landing)
                valid = landing.status_code == 200 and bool(
                    body and body.get("csrf")
                )
                if valid:
                    landing.success()
                else:
                    landing.failure("Login redirect did not return login data")
            self._capture_csrf(landing)
        else:
            self._capture_csrf(response)

        if not self.csrf:
            raise AssertionError("Login did not provide a CSRF token")

    def _control_request(
        self,
        method,
        path,
        json_body=None,
        expected_statuses=(200,),
        validator=None,
    ):
        headers = {}
        if method.upper() != "GET":
            if not self.csrf:
                raise AssertionError("No CSRF token for authenticated mutation")
            headers["X-CSRF-Token"] = self.csrf

        with self.client.request(
            method,
            path,
            json=json_body,
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        ) as response:
            valid = response.status_code in expected_statuses
            if valid and validator is not None:
                try:
                    valid = bool(validator(response))
                except Exception:
                    valid = False

            if valid:
                response.success()
            else:
                response.failure(
                    f"Unexpected {method} {path} response: "
                    f"HTTP {response.status_code}"
                )

        if response.status_code < 400 and method.upper() != "GET":
            self._capture_csrf(response)
        return response

    def _recover_session(self, original_error, cart_id=None):
        if original_error not in ("expired", "session"):
            raise AssertionError(f"Authentication denied: {original_error!r}")

        renew = self._control_request(
            "POST",
            "/v2/session/renew",
            json_body={},
            expected_statuses=(200, 401),
            validator=lambda response: (
                response.status_code == 200
                or (
                    (_json_body(response) or {}).get("error")
                    in ("expired", "session")
                )
            ),
        )

        relogged = renew.status_code != 200
        if relogged:
            self._login()

        if cart_id is not None:
            self._control_request(
                "POST",
                f"/v2/carts/{cart_id}/recover",
                json_body={},
                expected_statuses=(200, 201, 204),
            )

        return relogged

    def _authorized_request(
        self,
        method,
        path,
        json_body=None,
        extra_headers=None,
        expected_statuses=None,
        validator=None,
        allow_412=False,
        cart_id=None,
        rebuild_on_login=None,
        capture_csrf_on_get=False,
        retry_delay=0,
    ):
        method = method.upper()
        current_path = path
        current_body = json_body
        current_extra_headers = dict(extra_headers or {})

        for attempt in range(2):
            headers = dict(current_extra_headers)
            if method != "GET":
                if not self.csrf:
                    raise AssertionError("No CSRF token for authenticated mutation")
                headers["X-CSRF-Token"] = self.csrf

            needs_recovery = False
            valid = False

            with self.client.request(
                method,
                current_path,
                json=current_body,
                headers=headers,
                allow_redirects=False,
                catch_response=True,
            ) as response:
                body = _json_body(response)
                error = body.get("error") if body else None

                if (
                    response.status_code == 401
                    and error in ("expired", "session")
                    and attempt == 0
                ):
                    response.success()
                    needs_recovery = True
                elif response.status_code == 412 and allow_412:
                    response.success()
                    valid = True
                else:
                    if expected_statuses is None:
                        valid = 200 <= response.status_code < 400
                    else:
                        valid = response.status_code in expected_statuses

                    if valid and validator is not None:
                        try:
                            valid = bool(validator(response))
                        except Exception:
                            valid = False

                    if valid:
                        response.success()
                    else:
                        response.failure(
                            f"Unexpected {method} {current_path} response: "
                            f"HTTP {response.status_code}"
                        )

            if needs_recovery:
                relogged = self._recover_session(error, cart_id=cart_id)
                if relogged and rebuild_on_login is not None:
                    current_path, current_body, current_extra_headers = (
                        rebuild_on_login()
                    )
                if retry_delay:
                    time.sleep(retry_delay)
                continue

            if not valid:
                raise AssertionError(
                    f"Request failed: {method} {current_path}, "
                    f"HTTP {response.status_code}"
                )

            if response.status_code < 400 and (
                method != "GET" or capture_csrf_on_get
            ):
                self._capture_csrf(response)
            return response

        raise AssertionError(f"Recovery exhausted for {method} {current_path}")

    def _get_challenge_material(self):
        response = self.client.get(
            "/v2/challenge-form", allow_redirects=False
        )
        if response.status_code != 200:
            raise AssertionError(
                f"Challenge form returned HTTP {response.status_code}"
            )
        action, challenge = _challenge_form(response.text)
        return self._safe_local_url(action), challenge

    def _obtain_grant(self):
        action, challenge = self._get_challenge_material()

        def rebuild_after_login():
            new_action, new_challenge = self._get_challenge_material()
            return new_action, {"challenge": new_challenge}, {}

        response = self._authorized_request(
            "POST",
            action,
            json_body={"challenge": challenge},
            expected_statuses=(302, 303),
            validator=lambda result: bool(result.headers.get("Location")),
            rebuild_on_login=rebuild_after_login,
        )

        location = self._safe_local_url(response.headers["Location"])
        landing = self._authorized_request(
            "GET",
            location,
            expected_statuses=(200,),
            validator=lambda result: bool(
                (_json_body(result) or {}).get("grant_id")
                and (_json_body(result) or {}).get("csrf")
            ),
            capture_csrf_on_get=True,
            retry_delay=0.05,
        )
        body = _json_body(landing)
        return str(body["grant_id"])

    def _select_in_stock_product(self):
        path = "/v2/catalog"

        for page_number in range(3):
            response = self.client.get(path, allow_redirects=False)
            if response.status_code != 200:
                raise AssertionError(
                    f"Catalog returned HTTP {response.status_code}"
                )

            payload = _json_body(response)
            data = payload.get("data") if payload else None
            products = data.get("products") if isinstance(data, dict) else None
            if not isinstance(products, list):
                raise AssertionError("Catalog response has no data.products list")

            for product in products:
                if not isinstance(product, dict) or product.get("id") is None:
                    continue
                variants = product.get("variants")
                if not isinstance(variants, list):
                    continue
                for variant in variants:
                    if (
                        isinstance(variant, dict)
                        and variant.get("id") is not None
                        and variant.get("in_stock") is True
                    ):
                        return product["id"], variant["id"]

            next_url = payload.get("next")
            if not next_url or page_number == 2:
                break
            path = self._safe_local_url(next_url)

        raise AssertionError("No in-stock product variant found in catalog pages")

    def _read_cart_etag(self, cart_id):
        response = self._authorized_request(
            "GET",
            f"/v2/carts/{cart_id}",
            expected_statuses=(200,),
            validator=lambda result: bool(result.headers.get("ETag")),
        )
        return response.headers["ETag"]

    def _reserve(self, cart_id):
        response = self._authorized_request(
            "POST",
            "/v2/reservations",
            json_body={"cart_id": cart_id},
            expected_statuses=(202,),
            validator=lambda result: bool(
                (_json_body(result) or {}).get("status_url")
            ),
            cart_id=cart_id,
        )
        status_url = self._safe_local_url(
            _json_body(response)["status_url"]
        )

        last_poll = None
        for poll_number in range(5):
            if last_poll is not None:
                remaining = 0.05 - (time.monotonic() - last_poll)
                if remaining > 0:
                    time.sleep(remaining)

            last_poll = time.monotonic()

            def valid_status(result):
                body = _json_body(result) or {}
                status = body.get("status")
                if status == "ready":
                    return bool(body.get("reservation_id"))
                if status == "pending":
                    return poll_number < 4
                return False

            poll = self._authorized_request(
                "GET",
                status_url,
                expected_statuses=(200,),
                validator=valid_status,
                cart_id=cart_id,
                capture_csrf_on_get=True,
                retry_delay=0.05,
            )
            body = _json_body(poll) or {}
            if body.get("status") == "ready":
                return str(body["reservation_id"])

        raise AssertionError("Reservation did not become ready within five polls")

    def _run_work(self, cart_id):
        auth_retries = 0
        scheduled_retries = 0

        while True:
            headers = {"X-CSRF-Token": self.csrf}
            recover_error = None
            retry_after = None
            should_retry_429 = False

            with self.client.post(
                "/v2/work",
                json={},
                headers=headers,
                name="POST /v2/work",
                allow_redirects=False,
                catch_response=True,
            ) as response:
                body = _json_body(response) or {}

                if response.status_code == 200 and body.get("ok") is True:
                    response.success()
                    self._capture_csrf(response)
                elif (
                    response.status_code == 401
                    and body.get("error") in ("expired", "session")
                    and auth_retries == 0
                ):
                    response.success()
                    recover_error = body["error"]
                elif response.status_code == 429:
                    try:
                        retry_after = float(response.headers.get("Retry-After", ""))
                    except (TypeError, ValueError):
                        retry_after = None

                    if retry_after is not None and retry_after >= 1.0:
                        response.success()
                        should_retry_429 = scheduled_retries < 4
                    else:
                        response.failure("429 response lacked Retry-After of at least 1s")
                else:
                    response.failure(
                        f"Unexpected /v2/work response: HTTP {response.status_code}"
                    )

            if recover_error is not None:
                try:
                    self._recover_session(recover_error, cart_id=cart_id)
                except Exception:
                    return
                auth_retries += 1
                continue

            if response.status_code == 429:
                if should_retry_429:
                    scheduled_retries += 1
                    time.sleep(max(1.0, retry_after))
                    continue
                return

            return

    def _journey(self):
        self._login()
        product_id, variant_id = self._select_in_stock_product()

        grant_id = self._obtain_grant()

        def rebuild_cart_after_login():
            fresh_grant = self._obtain_grant()
            return (
                "/v2/carts",
                {
                    "product_id": product_id,
                    "variant_id": variant_id,
                    "grant_id": fresh_grant,
                },
                {},
            )

        cart_response = self._authorized_request(
            "POST",
            "/v2/carts",
            json_body={
                "product_id": product_id,
                "variant_id": variant_id,
                "grant_id": grant_id,
            },
            expected_statuses=(201,),
            validator=lambda result: bool((_json_body(result) or {}).get("id")),
            rebuild_on_login=rebuild_cart_after_login,
        )
        cart_id = str(_json_body(cart_response)["id"])

        etag = cart_response.headers.get("ETag")
        if not etag:
            etag = self._read_cart_etag(cart_id)

        patch_payload = {"quantity": 1}

        def patch_cart(current_etag, allow_precondition_retry):
            return self._authorized_request(
                "PATCH",
                f"/v2/carts/{cart_id}",
                json_body=patch_payload,
                extra_headers={"If-Match": current_etag},
                expected_statuses=(200, 204),
                allow_412=allow_precondition_retry,
                cart_id=cart_id,
            )

        patch_response = patch_cart(etag, True)
        if patch_response.status_code == 412:
            etag = self._read_cart_etag(cart_id)
            patch_response = patch_cart(etag, False)

        reservation_id = self._reserve(cart_id)
        etag = self._read_cart_etag(cart_id)

        idempotency_key = f"bench-order-{cart_id}-{uuid.uuid4().hex}"
        self._authorized_request(
            "POST",
            "/v2/orders",
            json_body={
                "cart_id": cart_id,
                "reservation_id": reservation_id,
            },
            extra_headers={
                "If-Match": etag,
                "Idempotency-Key": idempotency_key,
            },
            expected_statuses=(201,),
            validator=lambda result: (
                (_json_body(result) or {}).get("accepted") is True
            ),
            cart_id=cart_id,
        )

        self._run_work(cart_id)

    @task
    def execute_flow(self):
        try:
            for _ in range(ITERATIONS_PER_USER):
                self._journey()
        finally:
            type(self).completed_users += 1
        raise StopUser()


class FlowShape(LoadTestShape):
    def tick(self):
        completed = ShopFlowUser.completed_users
        current = self.runner.user_count

        if completed >= VIRTUAL_USERS:
            if current == 0:
                return None
            return current, 1

        target = max(VIRTUAL_USERS - completed, current)
        return target, max(1, target)

