import uuid
from html.parser import HTMLParser
from urllib.parse import urlsplit

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
ITERATIONS_PER_USER = 2
VIRTUAL_USERS = 2


class FormParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.forms = []
        self.current_form = None

    def handle_starttag(self, tag, attrs):
        attrs = {key.lower(): value for key, value in attrs if key}
        if tag.lower() == "form":
            self.current_form = {"attrs": attrs, "inputs": []}
            self.forms.append(self.current_form)
        elif tag.lower() == "input" and self.current_form is not None:
            self.current_form["inputs"].append(attrs)

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self.current_form = None


def _json_body(response):
    try:
        value = response.json()
        return value if isinstance(value, dict) else None
    except (ValueError, TypeError):
        return None


def _form_field(html, field_name):
    parser = FormParser()
    parser.feed(html)
    for form in parser.forms:
        for field in form["inputs"]:
            if field.get("name") == field_name and field.get("value"):
                return field["value"]
    raise AssertionError(f"Form input[name={field_name!r}] was not found")


def _challenge_form(html):
    parser = FormParser()
    parser.feed(html)
    for form in parser.forms:
        for field in form["inputs"]:
            if field.get("name") == "challenge" and field.get("value"):
                action = form["attrs"].get("action")
                if action:
                    return action, field["value"]
    raise AssertionError("Challenge form action or input[name='challenge'] was not found")


