                    f"HTTP {response.status_code}"
                )

            if response.status_code < 400 and (
                method != "GET" or capture_csrf_on_get
            ):
                self._capture_csrf(response)
            return response

        raise AssertionError(f"Recovery exhausted for {method} {current_path}")

    def _get_challenge_material(self):
        for attempt in range(2):
            recover_error = None
            with self.client.get(
                "/v2/challenge-form",
                allow_redirects=False,
                catch_response=True,
            ) as response:
                body = _json_body(response)
                error = body.get("error") if body else None

                if (
                    response.status_code == 401
                    and error in ("expired", "session")
                    and attempt == 0
                ):
                    response.success()
                    recover_error = error
                elif response.status_code == 200:
                    response.success()
                else:
                    response.failure(
                        f"Challenge form returned HTTP {response.status_code}"
                    )

            if recover_error is not None:
                self._recover_session(recover_error)
                continue
            if response.status_code != 200:
                raise AssertionError(
                    f"Challenge form returned HTTP {response.status_code}"
                )
            return self._challenge_material_from_html(response.text)

        raise AssertionError("Challenge form recovery exhausted")

    def _challenge_material_from_html(self, html):
        action, challenge = _challenge_form(html)
        return self._safe_local_url(action), challenge

    def _obtain_grant(self):
        action, challenge = self._get_challenge_material()

        def rebuild_after_recovery():
            new_action, new_challenge = self._get_challenge_material()
            return new_action, {"challenge": new_challenge}, {}

        response = self._authorized_request(
            "POST",
            action,
            json_body={"challenge": challenge},
            expected_statuses=(302, 303),
            validator=lambda result: bool(result.headers.get("Location")),
            rebuild_on_recovery=rebuild_after_recovery,
        )

        location = self._safe_local_url(response.headers["Location"])
        landing = self._authorized_request(
            "GET",
            location,
            expected_statuses=(200,),
            validator=lambda result: bool(
                (_json_body(result) or {}).get("grant_id")
                and (_json_body(result) or {}).get("csrf")
            ),
            capture_csrf_on_get=True,
            retry_delay=0.05,
        )
        return _json_body(landing)["grant_id"]

    def _select_in_stock_product(self):
        path = "/v2/catalog"

        for page_number in range(3):
            response = self.client.get(path, allow_redirects=False)
            if response.status_code != 200:
                raise AssertionError(
                    f"Catalog returned HTTP {response.status_code}"
                )

            payload = _json_body(response)
            data = payload.get("data") if payload else None
            products = data.get("products") if isinstance(data, dict) else None
            if not isinstance(products, list):
                raise AssertionError("Catalog response has no data.products list")

            for product in products:
                if not isinstance(product, dict) or product.get("id") is None:
                    continue
                variants = product.get("variants")
                if not isinstance(variants, list):
                    continue
                for variant in variants:
                    if (
                        isinstance(variant, dict)
                        and variant.get("id") is not None
                        and variant.get("in_stock") is True
                    ):
                        return product["id"], variant["id"]

            next_url = payload.get("next")
            if not next_url or page_number == 2:
                break
            path = self._safe_local_url(next_url)

        raise AssertionError("No in-stock product variant found in catalog pages")

    def _read_cart_etag(self, cart_id):
        response = self._authorized_request(
            "GET",
            f"/v2/carts/{cart_id}",
            expected_statuses=(200,),
            validator=lambda result: bool(result.headers.get("ETag")),
            cart_id=cart_id,
        )
        return response.headers["ETag"]

    def _reserve(self, cart_id):
        response = self._authorized_request(
            "POST",
            "/v2/reservations",
            json_body={"cart_id": cart_id},
            expected_statuses=(202,),
            validator=lambda result: bool(
                (_json_body(result) or {}).get("status_url")
            ),
            cart_id=cart_id,
        )
        status_url = self._safe_local_url(_json_body(response)["status_url"])

        last_poll = None
        for poll_number in range(5):
            if last_poll is not None:
                remaining = 0.05 - (time.monotonic() - last_poll)
                if remaining > 0:
                    time.sleep(remaining)

            last_poll = time.monotonic()

            def valid_status(result):
                body = _json_body(result) or {}
                status = body.get("status")
                if status == "ready":
                    return bool(body.get("reservation_id"))
                if status == "pending":
                    return poll_number < 4
                return False

            poll = self._authorized_request(
                "GET",
                status_url,
                expected_statuses=(200,),
                validator=valid_status,
                cart_id=cart_id,
                capture_csrf_on_get=True,
                retry_delay=0.05,
            )
            body = _json_body(poll) or {}
            if body.get("status") == "ready":
                return body["reservation_id"]

        raise AssertionError("Reservation did not become ready within five polls")

    def _run_work(self, cart_id):
        auth_retries = 0
        scheduled_retries = 0

        while True:
            headers = {"X-CSRF-Token": self.csrf}
            recover_error = None
            retry_after = None
            should_retry_429 = False

            with self.client.post(
                "/v2/work",
                json={},
                headers=headers,
                name="POST /v2/work",
                allow_redirects=False,
                catch_response=True,
            ) as response:
                body = _json_body(response) or {}

                if response.status_code == 200 and body.get("ok") is True:
                    response.success()
                    self._capture_csrf(response)
                elif (
                    response.status_code == 401
                    and body.get("error") in ("expired", "session")
                    and auth_retries == 0
                ):
                    response.success()
                    recover_error = body["error"]
                elif response.status_code == 429:
                    try:
                        retry_after = float(response.headers.get("Retry-After", ""))
                    except (TypeError, ValueError):
                        retry_after = None

                    if retry_after is not None and retry_after >= 1.0:
                        response.success()
                        should_retry_429 = scheduled_retries < 4
                    else:
                        response.failure(
                            "429 response lacked Retry-After of at least 1s"
                        )
                else:
                    response.failure(
                        f"Unexpected /v2/work response: HTTP {response.status_code}"
                    )

            if recover_error is not None:
                self._recover_session(recover_error, cart_id=cart_id)
                auth_retries += 1
                continue

            if response.status_code == 429:
                if should_retry_429:
                    scheduled_retries += 1
                    time.sleep(max(1.0, retry_after))
                    continue
                return

            return

    def _journey(self):
        self._login()
        product_id, variant_id = self._select_in_stock_product()
        grant_id = self._obtain_grant()

        def rebuild_cart_after_recovery():
            fresh_grant = self._obtain_grant()
            return (
                "/v2/carts",
                {
                    "product_id": product_id,
                    "variant_id": variant_id,
                    "grant_id": fresh_grant,
                },
                {},
            )

        cart_response = self._authorized_request(
            "POST",
            "/v2/carts",
            json_body={
                "product_id": product_id,
                "variant_id": variant_id,
                "grant_id": grant_id,
            },
            expected_statuses=(201,),
            validator=lambda result: bool((_json_body(result) or {}).get("id")),
            rebuild_on_recovery=rebuild_cart_after_recovery,
        )
        cart_id = _json_body(cart_response)["id"]

        etag = cart_response.headers.get("ETag")
        if not etag:
            etag = self._read_cart_etag(cart_id)

        patch_payload = {"quantity": 1}

        def patch_cart(current_etag, allow_precondition_retry):
            return self._authorized_request(
                "PATCH",
                f"/v2/carts/{cart_id}",
                json_body=patch_payload,
                extra_headers={"If-Match": current_etag},
                expected_statuses=(200, 204),
                allow_412=allow_precondition_retry,
                cart_id=cart_id,
            )

        patch_response = patch_cart(etag, True)
        if patch_response.status_code == 412:
            etag = self._read_cart_etag(cart_id)
            patch_cart(etag, False)

        reservation_id = self._reserve(cart_id)
        etag = self._read_cart_etag(cart_id)

        idempotency_key = f"bench-order-{cart_id}-{uuid.uuid4().hex}"
        self._authorized_request(
            "POST",
            "/v2/orders",
            json_body={
                "cart_id": cart_id,
                "reservation_id": reservation_id,
            },
            extra_headers={
                "If-Match": etag,
                "Idempotency-Key": idempotency_key,
            },
            expected_statuses=(201,),
            validator=lambda result: (
                (_json_body(result) or {}).get("accepted") is True
            ),
            cart_id=cart_id,
        )

        self._run_work(cart_id)

    @task
    def execute_flow(self):
        try:
            for _ in range(ITERATIONS_PER_USER):
                self._journey()
        finally:
            type(self).completed_users += 1
            raise StopUser()


class FlowShape(LoadTestShape):
    def tick(self):
        completed = ShopFlowUser.completed_users
        current = self.runner.user_count

        if completed >= VIRTUAL_USERS:
            if current == 0:
                return None
            return current, 1

        target = max(VIRTUAL_USERS - completed, current)
        return target, max(1, target)

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.time.Duration;
import java.util.List;
import java.util.Map;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  private static final HttpProtocolBuilder HTTP_PROTOCOL =
      http.baseUrl(baseUrl()).disableFollowRedirect();

  private static String baseUrl() {
    String value = System.getenv("BASE_URL");
    return value == null || value.isBlank() ? "http://127.0.0.1:8000" : value;
  }

  private static boolean nonEmpty(Session session, String key) {
    Object value = session.get(key);
    return value != null && !value.toString().isBlank();
  }

  private static int statusCode(Session session, String key) {
    Object value = session.get(key);
    return value instanceof Number ? ((Number) value).intValue() : -1;
  }

  private static boolean isTrue(Object value) {
    return Boolean.TRUE.equals(value) || "true".equalsIgnoreCase(String.valueOf(value));
  }

  private static Session chooseEligibleProduct(Session session) {
    session = session.set("selectedProduct", "").set("selectedVariant", "");
    Object rawProducts = session.get("products");
    if (!(rawProducts instanceof List<?>)) {
      return session;
    }

    for (Object rawProduct : (List<?>) rawProducts) {
      if (!(rawProduct instanceof Map<?, ?>)) {
        continue;
      }
      Map<?, ?> product = (Map<?, ?>) rawProduct;
      Object rawVariants = product.get("variants");
      if (!(rawVariants instanceof List<?>)) {
        continue;
      }

      for (Object rawVariant : (List<?>) rawVariants) {
        if (!(rawVariant instanceof Map<?, ?>)) {
          continue;
        }
        Map<?, ?> variant = (Map<?, ?>) rawVariant;
        if (isTrue(variant.get("in_stock"))
            && product.get("id") != null
            && variant.get("id") != null) {
          return session
              .set("selectedProduct", String.valueOf(product.get("id")))
              .set("selectedVariant", String.valueOf(variant.get("id")));
        }
      }
    }
    return session;
  }

  private static ChainBuilder login() {
    return exec(session ->
            session
                .set("username", "bench")
                .set("csrf", "")
                .set("loginLocation", ""))
        .exec(
            http("login form")
                .get("/v2/login-form")
                .check(
                    status().is(200),
                    css("input[name='csrf']", "value").saveAs("loginFormCsrf")))
        .exec(
            session ->
                session
                    .set("csrf", session.getString("loginFormCsrf"))
                    .set("loginLocation", ""))
        .exec(
            http("login")
                .post("/v2/login")
                .body(
                    StringBody(
                        "{\"username\":\"#{username}\","
                            + "\"password\":\"bench\","
                            + "\"csrf\":\"#{csrf}\"}"))
                .asJson()
                .check(
                    status().in(200, 302),
                    status().saveAs("loginStatus"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.user").optional().saveAs("loginUser"),
                    header("Location").optional().saveAs("loginLocation")))
        .exec(
            doIf(session -> statusCode(session, "loginStatus") == 302)
                .then(
                    exec(
                        http("login redirect")
                            .get("#{loginLocation}")
                            .check(
                                status().is(200),
                                jsonPath("$.csrf").optional().saveAs("csrf"),
                                jsonPath("$.user").optional().saveAs("loginUser")))))
        .exec(
            session -> {
              if (!nonEmpty(session, "csrf")) {
                throw new IllegalStateException("Login did not provide a CSRF token");
              }
              return session;
            });
  }

  private static ChainBuilder workAttempt(int attempt) {
    return exec(session -> session.set("workOk", "").set("retryAfter", ""))
        .exec(
            http("work " + attempt)
                .post("/v2/work")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .asJson()
                .check(
                    status().in(200, 429),
                    status().saveAs("workStatus"),
                    jsonPath("$.ok").optional().saveAs("workOk"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    header("Retry-After").optional().saveAs("retryAfter")))
        .exec(
            session -> {
              int code = statusCode(session, "workStatus");
              if (code == 200 && !isTrue(session.get("workOk"))) {
                throw new IllegalStateException("Unexpected /v2/work response");
              }
              if (code == 429 && !"1".equals(String.valueOf(session.get("retryAfter")))) {
                throw new IllegalStateException("429 response lacked Retry-After: 1");
              }
              return session;
            });
  }

  private static ChainBuilder workRetryIfNeeded(int attempt) {
    return exec(
        doIf(session -> statusCode(session, "workStatus") == 429)
            .then(
                exec(pause(Duration.ofSeconds(1)))
                    .exec(workAttempt(attempt))));
  }

  private static ChainBuilder catalogPage(int pageNumber) {
    return exec(
        doIf(
                session ->
                    !nonEmpty(session, "selectedProduct") && nonEmpty(session, "nextUrl"))
            .then(
                exec(
                        session ->
                            session
                                .set("pageUrl", session.getString("nextUrl"))
                                .set("nextUrl", ""))
                    .exec(
                        http("catalog page " + pageNumber)
                            .get("#{pageUrl}")
                            .check(
                                status().is(200),
                                jsonPath("$.data.products").ofList().saveAs("products"),
                                jsonPath("$.next").optional().saveAs("nextUrl")))
                    .exec(ModelSimulation::chooseEligibleProduct)));
  }

  private static ChainBuilder reservationPoll(int pollNumber) {
    return exec(
        doIf(
                session ->
                    !"ready".equalsIgnoreCase(String.valueOf(session.get("reservationStatus")))
                        && !"failed".equalsIgnoreCase(
                            String.valueOf(session.get("reservationStatus"))))
            .then(
                exec(pause(Duration.ofMillis(50)))
                    .exec(
                        http("reservation poll " + pollNumber)
                            .get("#{statusUrl}")
                            .check(
                                status().is(200),
                                jsonPath("$.status").saveAs("reservationStatus"),
                                jsonPath("$.reservation_id")
                                    .optional()
                                    .saveAs("reservationId")))));
  }

  private static ChainBuilder initialOrder() {
    return exec(session -> session.set("orderId", "").set("orderAccepted", "").set("orderError", ""))
        .exec(
            http("create order")
                .post("/v2/orders")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "order-#{cartId}")
                .header("If-Match", "#{cartEtag}")
                .body(
                    StringBody(
                        "{\"cart_id\":\"#{cartId}\","
                            + "\"reservation_id\":\"#{reservationId}\"}"))
                .asJson()
                .check(
                    status().in(201, 401),
                    status().saveAs("orderStatus"),
                    jsonPath("$.accepted").optional().saveAs("orderAccepted"),
                    jsonPath("$.id").optional().saveAs("orderId"),
                    jsonPath("$.error").optional().saveAs("orderError"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
        .exec(
            session -> {
              int code = statusCode(session, "orderStatus");
              if (code == 201 && !isTrue(session.get("orderAccepted"))) {
                throw new IllegalStateException("Order was not accepted");
              }
              if (code == 401
                  && !("expired".equals(session.getString("orderError"))
                      || "session".equals(session.getString("orderError")))) {
                throw new IllegalStateException("Order was denied");
              }
              return session;
            })
        .exec(
            doIf(session -> statusCode(session, "orderStatus") == 401)
                .then(
                    exec(
                            http("renew session")
                                .post("/v2/session/renew")
                                .header("X-CSRF-Token", "#{csrf}")
                                .body(StringBody("{}"))
                                .asJson()
                                .check(
                                    status().in(200, 401),
                                    status().saveAs("renewStatus"),
                                    jsonPath("$.csrf").optional().saveAs("csrf")))
                        .exec(
                            doIf(session -> statusCode(session, "renewStatus") == 401)
                                .then(login()))
                        .exec(
                            http("recover cart")
                                .post("/v2/carts/#{cartId}/recover")
                                .header("X-CSRF-Token", "#{csrf}")
                                .body(StringBody("{}"))
                                .asJson()
                                .check(
                                    status().is(200),
                                    jsonPath("$.csrf").optional().saveAs("csrf")))
                        .exec(
                            http("read recovered cart")
                                .get("/v2/carts/#{cartId}")
                                .check(status().is(200), header("ETag").saveAs("cartEtag")))
                        .exec(
                            http("retry order")
                                .post("/v2/orders")
                                .header("X-CSRF-Token", "#{csrf}")
                                .header("Idempotency-Key", "order-#{cartId}")
                                .header("If-Match", "#{cartEtag}")
                                .body(
                                    StringBody(
                                        "{\"cart_id\":\"#{cartId}\","
                                            + "\"reservation_id\":\"#{reservationId}\"}"))
                                .asJson()
                                .check(
                                    status().is(201),
                                    jsonPath("$.accepted").is("true"),
                                    jsonPath("$.id").saveAs("orderId"),
                                    jsonPath("$.csrf").optional().saveAs("csrf")))));
  }

  private static final ChainBuilder JOURNEY =
      login()
          .exec(workAttempt(1))
          .exec(workRetryIfNeeded(2))
          .exec(workRetryIfNeeded(3))
          .exec(workRetryIfNeeded(4))
          .exec(workRetryIfNeeded(5))
          .exec(
              session -> {
                if (statusCode(session, "workStatus") == 429) {
                  throw new IllegalStateException("/v2/work exhausted its retry limit");
                }
                return session;
              })
          .exec(session -> session.set("nextUrl", "").set("selectedProduct", "").set("selectedVariant", ""))
          .exec(
              http("catalog")
                  .get("/v2/catalog")
                  .check(
                      status().is(200),
                      jsonPath("$.data.products").ofList().saveAs("products"),
                      jsonPath("$.next").optional().saveAs("nextUrl")))
          .exec(ModelSimulation::chooseEligibleProduct)
          .exec(catalogPage(1))
          .exec(catalogPage(2))
          .exec(catalogPage(3))
          .exec(
              session -> {
                if (!nonEmpty(session, "selectedProduct")
                    || !nonEmpty(session, "selectedVariant")) {
                  throw new IllegalStateException(
                      "No in-stock catalog variant found within the traversal bound");
                }
                return session;
              })
          .exec(
              http("challenge form")
                  .get("/v2/challenge-form")
                  .check(
                      status().is(200),
                      css("form", "action").saveAs("challengeAction"),
                      css("input[name='challenge']", "value").saveAs("challengeAnswer")))
          .exec(
              http("submit challenge")
                  .post("#{challengeAction}")
                  .header("X-CSRF-Token", "#{csrf}")
                  .body(StringBody("{\"challenge\":\"#{challengeAnswer}\"}"))
                  .asJson()
                  .check(status().is(302), header("Location").saveAs("grantLocation")))
          .exec(
              http("challenge redirect")
                  .get("#{grantLocation}")
                  .check(
                      status().is(200),
                      jsonPath("$.grant_id").saveAs("grantId"),
                      jsonPath("$.csrf").optional().saveAs("csrf")))
          .exec(
              http("create cart")
                  .post("/v2/carts")
                  .header("X-CSRF-Token", "#{csrf}")
                  .body(
                      StringBody(
                          "{\"product_id\":\"#{selectedProduct}\","
                              + "\"variant_id\":\"#{selectedVariant}\","
                              + "\"grant_id\":\"#{grantId}\"}"))
                  .asJson()
                  .check(
                      status().is(201),
                      jsonPath("$.id").saveAs("cartId"),
                      jsonPath("$.csrf").optional().saveAs("csrf"),
                      header("ETag").saveAs("cartEtag")))
          .exec(
              http("read cart before update")
                  .get("/v2/carts/#{cartId}")
                  .check(status().is(200), header("ETag").saveAs("cartEtag")))
          .exec(session -> session.set("patchStatus", -1))
          .exec(
              http("update cart")
                  .patch("/v2/carts/#{cartId}")
                  .header("X-CSRF-Token", "#{csrf}")
                  .header("If-Match", "#{cartEtag}")
                  .body(StringBody("{\"quantity\":1}"))
                  .asJson()
                  .check(
                      status().in(200, 412),
                      status().saveAs("patchStatus"),
                      header("ETag").optional().saveAs("cartEtag"),
                      jsonPath("$.csrf").optional().saveAs("csrf")))
          .exec(
              doIf(session -> statusCode(session, "patchStatus") == 412)
                  .then(
                      exec(
                              http("read cart after conflict")
                                  .get("/v2/carts/#{cartId}")
                                  .check(status().is(200), header("ETag").saveAs("cartEtag")))
                          .exec(
                              http("retry cart update")
                                  .patch("/v2/carts/#{cartId}")
                                  .header("X-CSRF-Token", "#{csrf}")
                                  .header("If-Match", "#{cartEtag}")
                                  .body(StringBody("{\"quantity\":1}"))
                                  .asJson()
                                  .check(
                                      status().is(200),
                                      header("ETag").optional().saveAs("cartEtag"),
                                      jsonPath("$.csrf").optional().saveAs("csrf")))))
          .exec(
              http("reserve cart")
                  .post("/v2/reservations")
                  .header("X-CSRF-Token", "#{csrf}")
                  .body(StringBody("{\"cart_id\":\"#{cartId}\"}"))
                  .asJson()
                  .check(
                      status().is(202),
                      jsonPath("$.status_url").saveAs("statusUrl"),
                      jsonPath("$.csrf").optional().saveAs("csrf")))
          .exec(
              session ->
                  session
                      .set("reservationStatus", "pending")
                      .set("reservationId", ""))
          .exec(reservationPoll(1))
          .exec(reservationPoll(2))
          .exec(reservationPoll(3))
          .exec(reservationPoll(4))
          .exec(reservationPoll(5))
          .exec(
              session -> {
                if (!"ready".equalsIgnoreCase(
                        String.valueOf(session.get("reservationStatus")))
                    || !nonEmpty(session, "reservationId")) {
                  throw new IllegalStateException("Reservation did not become ready");
                }
                return session;
              })
          .exec(
              http("read cart before checkout")
                  .get("/v2/carts/#{cartId}")
                  .check(status().is(200), header("ETag").saveAs("cartEtag")))
          .exec(initialOrder());

  public ModelSimulation() {
    ScenarioBuilder scenario =
        scenario("Paginated eligible-item cart and order")
            .exec(repeat(2).on(JOURNEY));

    setUp(scenario.injectOpen(atOnceUsers(2))).protocols(HTTP_PROTOCOL);
  }
}

