import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.time.Duration;
import java.util.List;
import java.util.Map;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  private static final HttpProtocolBuilder HTTP_PROTOCOL =
      http.baseUrl(baseUrl()).disableFollowRedirect();

  private static String baseUrl() {
    String value = System.getenv("BASE_URL");
    return value == null || value.isBlank() ? "http://127.0.0.1:8000" : value;
  }

  private static boolean nonEmpty(Session session, String key) {
    Object value = session.get(key);
    return value != null && !value.toString().isBlank();
  }

  private static int statusCode(Session session, String key) {
    Object value = session.get(key);
    return value instanceof Number ? ((Number) value).intValue() : -1;
  }

  private static boolean isTrue(Object value) {
    return Boolean.TRUE.equals(value) || "true".equalsIgnoreCase(String.valueOf(value));
  }

  private static Session chooseEligibleProduct(Session session) {
    session = session.set("selectedProduct", "").set("selectedVariant", "");
    Object rawProducts = session.get("products");
    if (!(rawProducts instanceof List<?>)) {
      return session;
    }

    for (Object rawProduct : (List<?>) rawProducts) {
      if (!(rawProduct instanceof Map<?, ?>)) {
        continue;
      }
      Map<?, ?> product = (Map<?, ?>) rawProduct;
      Object rawVariants = product.get("variants");
      if (!(rawVariants instanceof List<?>)) {
        continue;
      }

      for (Object rawVariant : (List<?>) rawVariants) {
        if (!(rawVariant instanceof Map<?, ?>)) {
          continue;
        }
        Map<?, ?> variant = (Map<?, ?>) rawVariant;
        if (isTrue(variant.get("in_stock"))
            && product.get("id") != null
            && variant.get("id") != null) {
          return session
              .set("selectedProduct", String.valueOf(product.get("id")))
              .set("selectedVariant", String.valueOf(variant.get("id")));
        }
      }
    }
    return session;
  }

  private static ChainBuilder login() {
    return exec(session ->
            session
                .set("username", "bench")
                .set("csrf", "")
                .set("loginLocation", ""))
        .exec(
            http("login form")
                .get("/v2/login-form")
                .check(
                    status().is(200),
                    css("input[name='csrf']", "value").saveAs("loginFormCsrf")))
        .exec(
            session ->
                session
                    .set("csrf", session.getString("loginFormCsrf"))
                    .set("loginLocation", ""))
        .exec(
            http("login")
                .post("/v2/login")
                .body(
                    StringBody(
                        "{\"username\":\"#{username}\","
                            + "\"password\":\"bench\","
                            + "\"csrf\":\"#{csrf}\"}"))
                .asJson()
                .check(
                    status().in(200, 302),
                    status().saveAs("loginStatus"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.user").optional().saveAs("loginUser"),
                    header("Location").optional().saveAs("loginLocation")))
        .exec(
            doIf(session -> statusCode(session, "loginStatus") == 302)
                .then(
                    exec(
                        http("login redirect")
                            .get("#{loginLocation}")
                            .check(
                                status().is(200),
                                jsonPath("$.csrf").optional().saveAs("csrf"),
                                jsonPath("$.user").optional().saveAs("loginUser")))))
        .exec(
            session -> {
              if (!nonEmpty(session, "csrf")) {
                throw new IllegalStateException("Login did not provide a CSRF token");
              }
              return session;
            });
  }

  private static ChainBuilder workAttempt(int attempt) {
    return exec(session -> session.set("workOk", "").set("retryAfter", ""))
        .exec(
            http("work " + attempt)
                .post("/v2/work")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .asJson()
                .check(
                    status().in(200, 429),
                    status().saveAs("workStatus"),
                    jsonPath("$.ok").optional().saveAs("workOk"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    header("Retry-After").optional().saveAs("retryAfter")))
        .exec(
