  private static ChainBuilder workRetryIfNeeded(int attempt) {
    return exec(
        doIf(session -> statusCode(session, "workStatus") == 429)
            .then(
                exec(pause(Duration.ofSeconds(1)))
                    .exec(workAttempt(attempt))));
  }

  private static ChainBuilder catalogPage(int pageNumber) {
    return exec(
