  private static ChainBuilder initialOrder() {
    return exec(session -> session.set("orderId", "").set("orderAccepted", "").set("orderError", ""))
        .exec(
            http("create order")
                .post("/v2/orders")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "order-#{cartId}")
                .header("If-Match", "#{cartEtag}")
                .body(
                    StringBody(
                        "{\"cart_id\":\"#{cartId}\","
                            + "\"reservation_id\":\"#{reservationId}\"}"))
                .asJson()
                .check(
                    status().in(201, 401),
                    status().saveAs("orderStatus"),
                    jsonPath("$.accepted").optional().saveAs("orderAccepted"),
                    jsonPath("$.id").optional().saveAs("orderId"),
                    jsonPath("$.error").optional().saveAs("orderError"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
        .exec(
            session -> {
              int code = statusCode(session, "orderStatus");
              if (code == 201 && !isTrue(session.get("orderAccepted"))) {
