            doIf(session -> statusCode(session, "orderStatus") == 401)
                .then(
                    exec(
                            http("renew session")
                                .post("/v2/session/renew")
                                .header("X-CSRF-Token", "#{csrf}")
                                .body(StringBody("{}"))
                                .asJson()
                                .check(
                                    status().in(200, 401),
                                    status().saveAs("renewStatus"),
                                    jsonPath("$.csrf").optional().saveAs("csrf")))
                        .exec(
                            doIf(session -> statusCode(session, "renewStatus") == 401)
                                .then(login()))
                        .exec(
                            http("recover cart")
                                .post("/v2/carts/#{cartId}/recover")
                                .header("X-CSRF-Token", "#{csrf}")
                                .body(StringBody("{}"))
                                .asJson()
                                .check(
                                    status().is(200),
                                    jsonPath("$.csrf").optional().saveAs("csrf")))
                        .exec(
