                  .get("/v2/challenge-form")
                  .check(
                      status().is(200),
                      css("form:has(input[name='challenge'])", "action")
                          .saveAs("challengeAction"),
                      css(
                              "form:has(input[name='challenge']) input[name='challenge']",
                              "value")
                          .saveAs("challengeAnswer")))
          .exec(
              http("submit challenge")
                  .post("#{challengeAction}")
                  .header("X-CSRF-Token", "#{csrf}")
                  .body(StringBody("{\"challenge\":\"#{challengeAnswer}\"}"))
                  .asJson()
                  .check(status().is(302), header("Location").saveAs("grantLocation")))
          .exec(
              http("challenge redirect")
                  .get("#{grantLocation}")
                  .check(
                      status().is(200),
                      jsonPath("$.grant_id").saveAs("grantId"),
                      jsonPath("$.csrf").optional().saveAs("csrf")))
          .exec(
              http("create cart")
                  .post("/v2/carts")
                  .header("X-CSRF-Token", "#{csrf}")
                  .body(
                      StringBody(
                          "{\"product_id\":\"#{selectedProduct}\","
                              + "\"variant_id\":\"#{selectedVariant}\","
                              + "\"grant_id\":\"#{grantId}\"}"))
                  .asJson()
                  .check(
                      status().is(201),
                      jsonPath("$.id").saveAs("cartId"),
                      jsonPath("$.csrf").optional().saveAs("csrf"),
                      header("ETag").saveAs("cartEtag")))
          .exec(
              http("read cart before update")
                  .get("/v2/carts/#{cartId}")
                  .check(status().is(200), header("ETag").saveAs("cartEtag")))
          .exec(session -> session.set("patchStatus", -1))
          .exec(
              http("update cart")
                  .patch("/v2/carts/#{cartId}")
                  .header("X-CSRF-Token", "#{csrf}")
                  .header("If-Match", "#{cartEtag}")
                  .body(StringBody("{\"quantity\":1}"))
                  .asJson()
                  .check(
                      status().in(200, 412),
                      status().saveAs("patchStatus"),
                      header("ETag").optional().saveAs("cartEtag"),
                      jsonPath("$.csrf").optional().saveAs("csrf")))
          .exec(
              doIf(session -> statusCode(session, "patchStatus") == 412)
                  .then(
                      exec(
                              http("read cart after conflict")
                                  .get("/v2/carts/#{cartId}")
                                  .check(status().is(200), header("ETag").saveAs("cartEtag")))
                          .exec(
                              http("retry cart update")
                                  .patch("/v2/carts/#{cartId}")
                                  .header("X-CSRF-Token", "#{csrf}")
                                  .header("If-Match", "#{cartEtag}")
                                  .body(StringBody("{\"quantity\":1}"))
                                  .asJson()
                                  .check(
                                      status().is(200),
                                      header("ETag").optional().saveAs("cartEtag"),
                                      jsonPath("$.csrf").optional().saveAs("csrf")))))
          .exec(
              http("reserve cart")
                  .post("/v2/reservations")
                  .header("X-CSRF-Token", "#{csrf}")
                  .body(StringBody("{\"cart_id\":\"#{cartId}\"}"))
                  .asJson()
                  .check(
                      status().is(202),
                      jsonPath("$.status_url").saveAs("statusUrl"),
                      jsonPath("$.csrf").optional().saveAs("csrf")))
          .exec(
              session ->
                  session
                      .set("reservationStatus", "pending")
                      .set("reservationId", ""))
          .exec(reservationPoll(1))
          .exec(reservationPoll(2))
          .exec(reservationPoll(3))
          .exec(reservationPoll(4))
          .exec(reservationPoll(5))
          .exec(
              session -> {
                if (!"ready".equalsIgnoreCase(
                        String.valueOf(session.get("reservationStatus")))
                    || !nonEmpty(session, "reservationId")) {
                  throw new IllegalStateException("Reservation did not become ready");
                }
                return session;
              })
          .exec(
              http("read cart before checkout")
                  .get("/v2/carts/#{cartId}")
                  .check(status().is(200), header("ETag").saveAs("cartEtag")))
          .exec(initialOrder());

  public ModelSimulation() {
    ScenarioBuilder scenario =
        scenario("Paginated eligible-item cart and order")
            .exec(repeat(2).on(JOURNEY));

    setUp(scenario.injectOpen(atOnceUsers(2))).protocols(HTTP_PROTOCOL);
  }
}

import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    shop_journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '10m',
    },
  },
};

function verify(response, name, condition) {
  const passed = check(response || {}, { [name]: () => Boolean(condition) });
  if (!passed) {
    throw new Error(`${name} failed${response ? ` (HTTP ${response.status})` : ''}`);
  }
}

function jsonBody(response) {
  if (!response || !response.body) return null;
  try {
    return JSON.parse(response.body);
  } catch (_) {
    return null;
  }
}

function errorName(response) {
  const body = jsonBody(response);
  return body && typeof body.error === 'string' ? body.error : '';
}

function urlFor(path) {
  if (typeof path !== 'string' || !path) {
    throw new Error('Cannot resolve an empty URL');
  }
  if (/^https?:\/\//i.test(path)) {
    if (path === BASE_URL || path.indexOf(`${BASE_URL}/`) === 0) return path;
    throw new Error(`Refusing to request outside BASE_URL: ${path}`);
  }
  if (path.indexOf('//') === 0) {
    throw new Error(`Refusing protocol-relative URL: ${path}`);
  }
  return path.indexOf('/') === 0 ? `${BASE_URL}${path}` : `${BASE_URL}/${path}`;
}

function resolveLink(link, currentUrl) {
  if (typeof link !== 'string' || !link) {
    throw new Error('Server supplied an empty dynamic link');
  }
  if (/^https?:\/\//i.test(link)) return urlFor(link);
  if (link.indexOf('//') === 0) {
    throw new Error(`Refusing protocol-relative dynamic link: ${link}`);
  }
  if (link.indexOf('/') === 0) return `${BASE_URL}${link}`;

  const current = currentUrl || `${BASE_URL}/`;
  const currentPath = current.indexOf(BASE_URL) === 0
    ? current.slice(BASE_URL.length).split(/[?#]/)[0]
    : '/';
  let pathPart = link;
  let suffix = '';
  const suffixIndex = link.search(/[?#]/);
  if (suffixIndex >= 0) {
    pathPart = link.slice(0, suffixIndex);
    suffix = link.slice(suffixIndex);
  }

  let candidate;
  if (link.indexOf('?') === 0 || link.indexOf('#') === 0) {
    candidate = `${currentPath}${link}`;
  } else {
    const directory = currentPath.slice(0, currentPath.lastIndexOf('/') + 1);
    candidate = `${directory}${pathPart}${suffix}`;
  }

  const candidateSuffixIndex = candidate.search(/[?#]/);
  const candidatePath = candidateSuffixIndex >= 0
    ? candidate.slice(0, candidateSuffixIndex)
    : candidate;
  const candidateSuffix = candidateSuffixIndex >= 0
    ? candidate.slice(candidateSuffixIndex)
    : '';
  const segments = [];
  candidatePath.split('/').forEach((segment) => {
    if (!segment || segment === '.') return;
    if (segment === '..') {
      if (segments.length) segments.pop();
      return;
    }
    segments.push(segment);
  });
  return `${BASE_URL}/${segments.join('/')}${candidateSuffix}`;
}

function rawRequest(method, url, body, headers, name) {
  const requestHeaders = Object.assign({}, headers || {});
  if (method !== 'GET') requestHeaders['Content-Type'] = 'application/json';

  return http.request(
    method,
    urlFor(url),
    body === null || body === undefined ? null : JSON.stringify(body),
    {
      headers: requestHeaders,
      redirects: 0,
      tags: { name: name || method },
    },
  );
}

function updateCsrf(state, response) {
  if (!response || response.status < 200 || response.status >= 400) return;
  const body = jsonBody(response);
  if (body && typeof body.csrf === 'string' && body.csrf) {
    state.csrf = body.csrf;
  }
}

function htmlEntities(value) {
  return String(value || '')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'");
}

function tagAttributes(tag) {
  const attributes = {};
  const contents = tag
    .replace(/^<\s*[a-zA-Z][^\s/>]*/, '')
    .replace(/\/?>\s*$/, '');
  const matcher = /([^\s=/>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/g;
  let match;
  while ((match = matcher.exec(contents)) !== null) {
    const key = match[1].toLowerCase();
    const value = match[2] !== undefined
      ? match[2]
      : (match[3] !== undefined ? match[3] : match[4]);
    attributes[key] = value === undefined ? '' : htmlEntities(value);
  }
  return attributes;
}

function inputValue(html, inputName) {
  const matcher = /<input\b[^>]*>/gi;
  let match;
  while ((match = matcher.exec(html || '')) !== null) {
    const attributes = tagAttributes(match[0]);
    if ((attributes.name || '').toLowerCase() === inputName &&
        Object.prototype.hasOwnProperty.call(attributes, 'value')) {
      return attributes.value;
    }
  }
  return null;
}

function csrfFromLoginForm(html) {
  return inputValue(html, 'csrf');
}

function parseChallengeForm(html) {
  let action = null;
  const forms = /<form\b[^>]*>/gi;
  let match;
  while ((match = forms.exec(html || '')) !== null) {
    const attributes = tagAttributes(match[0]);
    if (attributes.action &&
        /^\/v2\/challenges\/[^/?#]+(?:[?#].*)?$/.test(attributes.action)) {
      action = attributes.action;
      break;
    }
  }
  return { action, challenge: inputValue(html, 'challenge') };
}

function login(state, username) {
  const formUrl = urlFor('/v2/login-form');
  const formResponse = rawRequest('GET', formUrl, null, {}, 'login_form');
  verify(formResponse, 'login_form_loaded', formResponse.status === 200);

  const formCsrf = csrfFromLoginForm(formResponse.body);
  verify(formResponse, 'login_form_csrf_found', Boolean(formCsrf));

  const loginUrl = urlFor('/v2/login');
  const response = rawRequest(
    'POST',
    loginUrl,
    { username, password: 'bench', csrf: formCsrf },
    {},
    'login',
  );
  verify(response, 'login_accepted_or_redirected',
    response.status === 200 || response.status === 302);

  state.csrf = formCsrf;
  updateCsrf(state, response);

  if (response.status === 302) {
    const location = response.headers.Location || response.headers.location;
    verify(response, 'login_redirect_location_present', Boolean(location));
    const redirectResponse = rawRequest(
      'GET',
      resolveLink(location, loginUrl),
      null,
      {},
      'login_redirect',
    );
    verify(redirectResponse, 'login_redirect_loaded',
      redirectResponse.status >= 200 && redirectResponse.status < 300);
    updateCsrf(state, redirectResponse);
  }

  verify(response, 'login_csrf_available', Boolean(state.csrf));
}

function refreshCredentials(state, authError, username) {
  if (authError === 'denied') {
    verify(null, '401_not_denied', false);
  }

  if (authError === 'session') {
    login(state, username);
    return;
  }

  if (authError !== 'expired') {
    verify(null, '401_has_recognized_error', false);
  }

  const renewal = rawRequest(
    'POST',
    '/v2/session/renew',
    {},
    { 'X-CSRF-Token': state.csrf },
    'session_renew',
  );
  updateCsrf(state, renewal);

  if (renewal.status >= 200 && renewal.status < 300) return;

  if (renewal.status === 401 && errorName(renewal) === 'session') {
    login(state, username);
    return;
  }

  verify(renewal, 'session_renewed_or_relogin_required',
    renewal.status >= 200 && renewal.status < 300);
}

function recoverCart(state, username) {
  if (!state.cartId) return;

  const path = `/v2/carts/${encodeURIComponent(state.cartId)}/recover`;
  let response = rawRequest(
    'POST',
    path,
    {},
    { 'X-CSRF-Token': state.csrf },
    'cart_recover',
  );
  updateCsrf(state, response);

  if (response.status === 401) {
    const authError = errorName(response);
    refreshCredentials(state, authError, username);
    response = rawRequest(
      'POST',
      path,
      {},
      { 'X-CSRF-Token': state.csrf },
      'cart_recover',
    );
    updateCsrf(state, response);
  }

  verify(response, 'cart_recovered',
    response.status >= 200 && response.status < 300);
}

function authenticatedRequest(method, path, body, state, username, extraHeaders, optionsForRequest) {
  const options = optionsForRequest || {};
  const requestUrl = urlFor(path);

  function attempt() {
    const headers = Object.assign({}, extraHeaders || {});
    if (method !== 'GET') headers['X-CSRF-Token'] = state.csrf;

    const response = rawRequest(
      method,
      requestUrl,
      body,
      headers,
      options.name || `${method.toLowerCase()}_authenticated`,
    );
    if (options.onResponse) options.onResponse(response);
    updateCsrf(state, response);
    return response;
  }

  let response = attempt();
  if (response.status !== 401) return response;

  refreshCredentials(state, errorName(response), username);
  recoverCart(state, username);
  if (options.retryDelaySeconds) sleep(options.retryDelaySeconds);

  response = attempt();
  if (response.status === 401) {
    const authError = errorName(response);
    if (authError === 'denied') verify(response, '401_not_denied', false);
    verify(response, 'authenticated_operation_retry_succeeded',
      response.status !== 401);
  }
  return response;
}

function responseHeader(response, wantedName) {
  const wanted = wantedName.toLowerCase();
  const headers = response && response.headers ? response.headers : {};
  const keys = Object.keys(headers);
  for (let i = 0; i < keys.length; i += 1) {
    if (keys[i].toLowerCase() === wanted) return headers[keys[i]];
  }
  return null;
}

function cartEtag(response, name) {
  const etag = responseHeader(response, 'etag');
  verify(response, `${name}_etag_present`, Boolean(etag));
  return etag;
}

function catalogProduct(body) {
  if (!body) return null;
  const data = body.data || body;
  if (data.product && typeof data.product === 'object') return data.product;
  if (Array.isArray(data.products) && data.products.length) return data.products[0];
  if (body.product && typeof body.product === 'object') return body.product;
  if (Array.isArray(body.products) && body.products.length) return body.products[0];
  if (data.id && Array.isArray(data.variants)) return data;
  return null;
}

function catalogNext(body) {
  if (!body) return null;
  if (Object.prototype.hasOwnProperty.call(body, 'next')) return body.next;
  if (body.data && Object.prototype.hasOwnProperty.call(body.data, 'next')) {
    return body.data.next;
  }
  return null;
}

function eligibleVariant(product) {
  if (!product || !Array.isArray(product.variants)) return null;
  for (let i = 0; i < product.variants.length; i += 1) {
    const variant = product.variants[i];
    if (variant && variant.in_stock === true && variant.id !== undefined &&
        variant.id !== null) {
      return variant;
    }
  }
  return null;
}

function findEligibleProduct() {
  let next = '/v2/catalog/page';
  const visited = {};
  for (let page = 1; page <= 3; page += 1) {
    const pageUrl = resolveLink(next, `${BASE_URL}/v2/catalog/page`);
    verify(null, `catalog_cursor_not_repeated_page_${page}`, !visited[pageUrl]);
    visited[pageUrl] = true;

    const response = rawRequest('GET', pageUrl, null, {}, 'catalog_page');
    verify(response, `catalog_page_${page}_loaded`, response.status === 200);

    const body = jsonBody(response);
    const product = catalogProduct(body);
    const variant = eligibleVariant(product);
    if (product && variant) {
      verify(response, 'eligible_product_id_present',
        product.id !== undefined && product.id !== null);
      return { product, variant };
    }

    const cursor = catalogNext(body);
    if (cursor === null || cursor === undefined) break;
    verify(response, `catalog_next_${page}_is_link`, typeof cursor === 'string' && cursor.length > 0);
    next = cursor;
  }

  verify(null, 'eligible_product_found_within_three_pages', false);
  return null;
}

function createChallengeGrant(state, username) {
  const formResponse = authenticatedRequest(
    'GET',
    '/v2/challenge-form',
    null,
    state,
    username,
    {},
    { name: 'challenge_form' },
  );
  verify(formResponse, 'challenge_form_loaded', formResponse.status === 200);

  const form = parseChallengeForm(formResponse.body);
  verify(formResponse, 'challenge_action_and_value_found',
    Boolean(form.action) && Boolean(form.challenge));

  const actionUrl = resolveLink(form.action, `${BASE_URL}/v2/challenge-form`);
  const challengeResponse = authenticatedRequest(
    'POST',
    actionUrl,
    { challenge: form.challenge },
    state,
    username,
    {},
    { name: 'challenge_submit' },
  );
  verify(challengeResponse, 'challenge_redirected',
    challengeResponse.status === 302);

  const location = responseHeader(challengeResponse, 'location');
  verify(challengeResponse, 'challenge_redirect_location_present', Boolean(location));

  const grantResponse = authenticatedRequest(
    'GET',
    resolveLink(location, actionUrl),
    null,
    state,
    username,
    {},
    { name: 'challenge_grant' },
  );
  verify(grantResponse, 'challenge_grant_loaded', grantResponse.status === 200);

  const grantBody = jsonBody(grantResponse);
  verify(grantResponse, 'challenge_grant_id_present',
    grantBody && typeof grantBody.grant_id === 'string' && grantBody.grant_id.length > 0);
  return grantBody.grant_id;
}

function findCartEtag(state, username, name) {
  const response = authenticatedRequest(
    'GET',
    `/v2/carts/${encodeURIComponent(state.cartId)}`,
    null,
    state,
    username,
    {},
    { name },
  );
  verify(response, `${name}_loaded`, response.status === 200);
  return cartEtag(response, name);
}

function patchCart(state, username) {
  let etag = findCartEtag(state, username, 'cart_before_patch');
  const payload = { quantity: 1 };

  let response = authenticatedRequest(
    'PATCH',
    `/v2/carts/${encodeURIComponent(state.cartId)}`,
    payload,
    state,
    username,
    { 'If-Match': etag },
    { name: 'cart_patch' },
  );

  if (response.status === 412) {
    etag = findCartEtag(state, username, 'cart_after_precondition_failure');
    response = authenticatedRequest(
      'PATCH',
      `/v2/carts/${encodeURIComponent(state.cartId)}`,
      payload,
      state,
      username,
      { 'If-Match': etag },
      { name: 'cart_patch_retry' },
    );
  }

  verify(response, 'cart_quantity_patched',
    response.status === 200 || response.status === 204);
}

function createCart(state, username, product, variant, grantId) {
  const response = authenticatedRequest(
    'POST',
    '/v2/carts',
    {
      product_id: product.id,
      variant_id: variant.id,
      grant_id: grantId,
    },
    state,
    username,
    {},
    { name: 'cart_create' },
  );

  verify(response, 'cart_created', response.status === 201);
  const body = jsonBody(response);
  verify(response, 'cart_id_extracted',
    body && body.id !== undefined && body.id !== null && String(body.id).length > 0);

  state.cartId = String(body.id);
  return state.cartId;
}

function createReadyReservation(state, username) {
  const response = authenticatedRequest(
    'POST',
    '/v2/reservations',
    { cart_id: state.cartId },
    state,
    username,
    {},
    { name: 'reservation_create' },
  );
  verify(response, 'reservation_accepted', response.status === 202);

  const body = jsonBody(response);
  verify(response, 'reservation_status_url_present',
    body && typeof body.status_url === 'string' && body.status_url.length > 0);

  const statusUrl = resolveLink(body.status_url, `${BASE_URL}/v2/reservations`);
  for (let poll = 1; poll <= 5; poll += 1) {
    sleep(0.05);
    const statusResponse = authenticatedRequest(
      'GET',
      statusUrl,
      null,
      state,
      username,
      {},
      { name: 'reservation_poll', retryDelaySeconds: 0.05 },
    );
    verify(statusResponse, `reservation_poll_${poll}_loaded`,
      statusResponse.status === 200);

    const statusBody = jsonBody(statusResponse);
    if (statusBody && statusBody.status === 'ready') {
      verify(statusResponse, 'reservation_id_extracted',
        typeof statusBody.reservation_id === 'string' &&
        statusBody.reservation_id.length > 0);
      return statusBody.reservation_id;
    }
    if (statusBody && statusBody.status === 'failed') {
      verify(statusResponse, 'reservation_not_failed', false);
    }
    verify(statusResponse, `reservation_poll_${poll}_pending`,
      statusBody && statusBody.status === 'pending');
  }

  verify(null, 'reservation_ready_within_five_polls', false);
  return null;
}

function placeOrder(state, username, reservationId) {
  const etag = findCartEtag(state, username, 'cart_before_order');
  const idempotencyKey = `order-${state.cartId}`;

  const response = authenticatedRequest(
    'POST',
    '/v2/orders',
    { cart_id: state.cartId, reservation_id: reservationId },
    state,
    username,
    {
      'Idempotency-Key': idempotencyKey,
      'If-Match': etag,
    },
    { name: 'order_create' },
  );

  const body = jsonBody(response);
  verify(response, 'order_committed',
    response.status === 201 && body && body.accepted === true);
  verify(response, 'order_id_extracted',
    body && body.id !== undefined && body.id !== null && String(body.id).length > 0);
  return String(body.id);
}

function doBusinessWork(state, username) {
  const retryLimit = 4;

  for (let retry = 0; retry <= retryLimit; retry += 1) {
    const response = authenticatedRequest(
      'POST',
      '/v2/work',
      {},
      state,
      username,
      {},
      {
        name: 'business_work',
        onResponse: (rawResponse) => {
          const body = jsonBody(rawResponse);
          const expectedExpiry = rawResponse.status === 401 &&
            errorName(rawResponse) === 'expired';
          const scheduled429 = rawResponse.status === 429;
          const successfulWork = rawResponse.status === 200 &&
            body && body.ok === true;
          businessFailure.add(!(expectedExpiry || scheduled429 || successfulWork));
        },
      },
    );

    if (response.status === 429) {
      verify(response, 'scheduled_429_retry_limit_not_exceeded', retry < retryLimit);
      const retryAfter = Number(responseHeader(response, 'retry-after'));
      verify(response, 'scheduled_429_retry_after_at_least_one_second',
        Number.isFinite(retryAfter) && retryAfter >= 1);
      sleep(retryAfter);
      continue;
    }

    const body = jsonBody(response);
    verify(response, 'business_work_succeeded',
      response.status === 200 && body && body.ok === true);
    return;
  }
}

export default function () {
  const username = `bench-${((__VU - 1) % 16) + 1}`;
  const state = { csrf: '', cartId: null };

  login(state, username);

  const eligible = findEligibleProduct();
  const grantId = createChallengeGrant(state, username);
  const cartId = createCart(
    state,
    username,
    eligible.product,
    eligible.variant,
    grantId,
  );

  patchCart(state, username);
  const reservationId = createReadyReservation(state, username);
  const orderId = placeOrder(state, username, reservationId);

  doBusinessWork(state, username);

  verify(null, 'journey_cart_id_retained', cartId === state.cartId);
  verify(null, 'journey_order_id_retained', Boolean(orderId));

  console.log(JSON.stringify({
    user: username,
    cart_id: cartId,
    order_id: orderId,
  }));
}

import itertools
import logging
import os
from html.parser import HTMLParser
from urllib.parse import urljoin, urlparse, urlunparse

from locust import HttpUser, LoadTestShape, StopUser, task


USERS = 2
ITERATIONS_PER_USER = 2
EXPECTED_JOURNEYS = USERS * ITERATIONS_PER_USER

_completed_journeys = 0
_account_sequence = itertools.count(1)
logger = logging.getLogger(__name__)


def _configured_base_url():
    value = os.environ.get("BASE_URL", "http://127.0.0.1:8000").strip()
    if "://" not in value:
        value = "http://" + value
    return value.rstrip("/")


BASE_URL = _configured_base_url()
_BASE_PARSED = urlparse(BASE_URL)
_BASE_ORIGIN = f"{_BASE_PARSED.scheme}://{_BASE_PARSED.netloc}"


def _valid_id(value):
    return (
        value is not None
        and not isinstance(value, bool)
        and (not isinstance(value, str) or bool(value.strip()))
    )


class _FormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.csrf_inputs = []
        self.forms = []
        self._current_form = None

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        attributes = {str(key).lower(): value for key, value in attrs if key}

        if tag == "form":
            form = {"action": attributes.get("action"), "inputs": []}
            self.forms.append(form)
            self._current_form = form
        elif tag == "input":
            name = attributes.get("name")
            value = attributes.get("value")
            input_type = (attributes.get("type") or "").lower()
            if name and name.lower() == "csrf":
                self.csrf_inputs.append((input_type, value))
            if self._current_form is not None and name:
                self._current_form["inputs"].append(
                    (name.lower(), value, input_type)
                )

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self._current_form = None

    def csrf_value(self):
        hidden = [
            value
            for input_type, value in self.csrf_inputs
            if input_type == "hidden" and value
        ]
        if hidden:
            return hidden[0]
        for _, value in self.csrf_inputs:
            if value:
                return value
        return None

    def challenge_form(self):
        for form in self.forms:
            if not form.get("action"):
                continue
            for name, value, _ in form["inputs"]:
                if name == "challenge" and value:
                    return form["action"], value
        return None


def _json_object(response):
    try:
        payload = response.json()
    except Exception:
        return None
    return payload if isinstance(payload, dict) else None


def _response_csrf(response):
    header_token = response.headers.get("X-CSRF-Token")
    if header_token:
        return header_token
    payload = _json_object(response)
    if payload and isinstance(payload.get("csrf"), str) and payload["csrf"]:
        return payload["csrf"]
    return None


def _product_and_next(payload):
    if not isinstance(payload, dict):
        return None, None

    data = payload.get("data")
    product = payload.get("product")
    if product is None and isinstance(data, dict):
        product = data.get("product")
        if product is None and _valid_id(data.get("id")):
            product = data
        if product is None:
            products = data.get("products")
            if isinstance(products, list) and products:
                product = products[0]

    if product is None:
        products = payload.get("products")
        if isinstance(products, list) and products:
            product = products[0]

    next_link = payload.get("next")
    if next_link is None and isinstance(data, dict):
        next_link = data.get("next")

    if not isinstance(product, dict):
        product = None
    return product, next_link


def _eligible_ids(product):
    if not isinstance(product, dict) or not _valid_id(product.get("id")):
        return None

    variants = product.get("variants")
    if not isinstance(variants, list):
        return None

    for variant in variants:
        if (
            isinstance(variant, dict)
            and variant.get("in_stock") is True
            and _valid_id(variant.get("id"))
        ):
            return product["id"], variant["id"]
    return None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = lambda self: 0

    def on_start(self):
        account_number = (next(_account_sequence) - 1) % 16 + 1
        self.username = f"bench-{account_number}"
        self.password = "bench"
        self.csrf = None
        self.iteration = 0
        self.cart_id = None
        self.order_id = None
        self.reservation_id = None
        self.etag = None
        self.orders_by_cart = {}

    def _resolve_link(self, current_url, link):
        if not isinstance(link, str) or not link.strip():
            raise ValueError("Expected a non-empty dynamic URL")

        if current_url.startswith(("http://", "https://")):
            current = current_url
        else:
            current = urljoin(BASE_URL + "/", current_url)

        absolute = urljoin(current, link)
        parsed = urlparse(absolute)
        origin = f"{parsed.scheme}://{parsed.netloc}"
        if origin != _BASE_ORIGIN:
            raise ValueError("Dynamic URL points outside the configured host")

        # Fragments are client-side only and must not be sent in the request.
        return urlunparse(
            (parsed.scheme, parsed.netloc, parsed.path, parsed.params, parsed.query, "")
        )

    def _capture_csrf(self, response):
        if response.status_code == 401:
            return
        token = _response_csrf(response)
        if token:
            self.csrf = token

    def _single_request(
        self,
        method,
        path,
        *,
        expected_status,
        json_body=None,
        headers=None,
        name=None,
        validator=None,
    ):
        request_headers = dict(headers or {})
        kwargs = {
            "headers": request_headers,
            "catch_response": True,
            "allow_redirects": False,
        }
        if name:
            kwargs["name"] = name
        if json_body is not None:
            kwargs["json"] = json_body

        expected_status = tuple(expected_status)
        with self.client.request(method, path, **kwargs) as response:
            if response.status_code not in expected_status:
                response.failure(
                    f"Unexpected HTTP {response.status_code} for {method} {name or path}"
                )
            elif validator is not None:
                try:
                    validator(response)
                except Exception as exc:
                    response.failure(f"Response validation failed: {exc}")

        self._capture_csrf(response)
        return response

    def _error_name(self, response):
        payload = _json_object(response)
        if not payload:
            return None
        error = payload.get("error")
        return error.lower() if isinstance(error, str) else None

    def _auth_request(
        self,
        method,
        path,
        *,
        expected_status,
        json_body=None,
        headers=None,
        name=None,
        validator=None,
    ):
        method = method.upper()
        base_headers = dict(headers or {})
        if method != "GET":
            base_headers["X-CSRF-Token"] = self.csrf or ""

        expected = tuple(expected_status)
        for attempt in range(2):
            auth_error = {"value": None}

            def check_response(response):
                if response.status_code == 401:
                    error = self._error_name(response)
                    auth_error["value"] = error
                    if attempt == 0 and error in ("expired", "session"):
                        return
                    response.failure(
                        f"Authentication assertion failed: {error or 'unknown'}"
                    )
                    return
                if validator is not None:
                    validator(response)

            response = self._single_request(
                method,
                path,
                expected_status=expected + (401,),
                json_body=json_body,
                headers=base_headers,
                name=name,
                validator=check_response,
            )

            if response.status_code != 401:
                return response

            error = auth_error["value"]
            if attempt == 0 and error in ("expired", "session"):
                if self._reauthenticate_and_recover():
                    # Reuse the same operation payload and headers, with the
                    # fresh CSRF token. This is the only operation retry.
                    if method != "GET":
                        base_headers["X-CSRF-Token"] = self.csrf or ""
                    continue
            return response

        return response

    def _login(self):
        form_data = {}

        def check_login_form(response):
            parser = _FormParser()
            parser.feed(response.text or "")
            form_data["csrf"] = parser.csrf_value()
            if not form_data["csrf"]:
                response.failure("Login form did not contain input[name=csrf]")

        form_response = self._single_request(
            "GET",
            "/v2/login-form",
            expected_status=(200,),
            name="/v2/login-form",
            validator=check_login_form,
        )
        if form_response.status_code != 200 or not form_data.get("csrf"):
            return False

        self.csrf = form_data["csrf"]
        login_data = {}

        def check_login_response(response):
            if response.status_code == 302:
                location = response.headers.get("Location")
                if not location:
                    response.failure("Login redirect did not include Location")
                    return
                try:
                    login_data["location"] = self._resolve_link(
                        "/v2/login", location
                    )
                except Exception as exc:
                    response.failure(f"Invalid login redirect: {exc}")
                return

            payload = _json_object(response)
            if (
                not payload
                or not payload.get("csrf")
                or "user" not in payload
            ):
                response.failure("Login response did not contain csrf and user")

        login_response = self._single_request(
            "POST",
            "/v2/login",
            expected_status=(200, 302),
            json_body={
                "username": self.username,
                "password": self.password,
                "csrf": self.csrf,
            },
            name="/v2/login",
            validator=check_login_response,
        )

        if login_response.status_code == 200:
            payload = _json_object(login_response)
            return bool(payload and payload.get("csrf"))

        if login_response.status_code != 302 or not login_data.get("location"):
            return False

        landing_data = {}

        def check_login_landing(response):
            payload = _json_object(response)
            if not payload or not payload.get("csrf"):
                response.failure("Login redirect target did not return a fresh csrf")
                return
            landing_data["payload"] = payload

        landing = self._single_request(
            "GET",
            login_data["location"],
            expected_status=(200,),
            name="/v2/login/[redirect]",
            validator=check_login_landing,
        )
        return landing.status_code == 200 and bool(landing_data.get("payload"))

    def _reauthenticate_and_recover(self):
        renewed = {"ok": False}

        def check_renew(response):
            if response.status_code == 401:
                # A revoked session may not be renewable; perform a fresh login.
                return
            if not _response_csrf(response):
                response.failure("Session renewal did not provide a fresh csrf")
                return
            renewed["ok"] = True

        renew = self._single_request(
            "POST",
            "/v2/session/renew",
            expected_status=(200, 204, 401),
            json_body={},
            headers={"X-CSRF-Token": self.csrf or ""},
            name="/v2/session/renew",
            validator=check_renew,
        )

        if renew.status_code not in (200, 204) or not renewed["ok"]:
            if not self._login():
                return False

        if self.cart_id is not None:
            cart_path = f"/v2/carts/{self._path_id(self.cart_id)}/recover"

            def check_recovery(response):
                return

            recovered = self._single_request(
                "POST",
                cart_path,
                expected_status=(200, 204),
                json_body={},
                headers={"X-CSRF-Token": self.csrf or ""},
                name="/v2/carts/[id]/recover",
                validator=check_recovery,
            )
            if recovered.status_code not in (200, 204):
                return False

        return True

    @staticmethod
    def _path_id(value):
        from urllib.parse import quote

        return quote(str(value), safe="")

    def _do_work(self):
        for retry_number in range(5):
            retry_delay = {"seconds": None}

            def check_work(response):
                if response.status_code == 200:
                    payload = _json_object(response)
                    if not payload or payload.get("ok") is not True:
                        response.failure("/v2/work did not return {ok:true}")
                    return

                if response.status_code == 429:
                    retry_after = response.headers.get("Retry-After")
                    try:
                        delay = float(retry_after)
                        if delay <= 0:
                            raise ValueError("Retry-After must be positive")
                        retry_delay["seconds"] = max(1.0, delay)
                    except (TypeError, ValueError):
                        response.failure("Scheduled 429 lacked a valid Retry-After")

            response = self._auth_request(
                "POST",
                "/v2/work",
                expected_status=(200, 429),
                json_body={},
                name="/v2/work",
                validator=check_work,
            )
            if response.status_code != 429:
                return

            if retry_number >= 4 or retry_delay["seconds"] is None:
                return
            self.wait(retry_delay["seconds"])

    def _find_product(self):
        selected = {}
        current_url = self._resolve_link(BASE_URL + "/", "/v2/catalog/page")

        for page_number in range(3):
            page_info = {}

            def check_page(response):
                payload = _json_object(response)
                if not payload:
                    response.failure("Catalog page did not return a JSON object")
                    return

                product, next_link = _product_and_next(payload)
                page_info["next"] = next_link
                candidate = _eligible_ids(product) if product else None
                if candidate:
                    selected["ids"] = candidate
                    return

                if next_link is not None and not isinstance(next_link, str):
                    response.failure("Catalog next cursor was not a relative URL")
                    return

                if page_number == 2 or next_link is None:
                    response.failure(
                        "No in-stock product variant found within three catalog pages"
                    )
                    return

                try:
                    page_info["resolved_next"] = self._resolve_link(
                        current_url, next_link
                    )
                except Exception as exc:
                    response.failure(f"Invalid catalog next link: {exc}")

            response = self._single_request(
                "GET",
                current_url,
                expected_status=(200,),
                name="/v2/catalog/page",
                validator=check_page,
            )

            if response.status_code != 200:
                return None
            if selected.get("ids"):
                return selected["ids"]

            next_url = page_info.get("resolved_next")
            if not next_url:
                return None
            current_url = next_url

        return None

    def _get_challenge_grant(self):
        form_info = {}

        def check_challenge_form(response):
            parser = _FormParser()
            parser.feed(response.text or "")
            parsed = parser.challenge_form()
            if not parsed:
                response.failure(
                    "Challenge form lacked a form action and input[name=challenge]"
                )
                return
            action, challenge = parsed
            try:
                form_info["action"] = self._resolve_link(
                    "/v2/challenge-form", action
                )
                form_info["challenge"] = challenge
            except Exception as exc:
                response.failure(f"Invalid challenge form action: {exc}")

        form_response = self._auth_request(
            "GET",
            "/v2/challenge-form",
            expected_status=(200,),
            name="/v2/challenge-form",
            validator=check_challenge_form,
        )
        if form_response.status_code != 200 or not form_info.get("action"):
            return None

        claim_info = {}

        def check_claim(response):
            location = response.headers.get("Location")
            if not location:
                response.failure("Challenge claim did not return a redirect Location")
                return
            try:
                claim_info["location"] = self._resolve_link(
                    form_info["action"], location
                )
            except Exception as exc:
                response.failure(f"Invalid challenge redirect: {exc}")

        claim_response = self._auth_request(
            "POST",
            form_info["action"],
            expected_status=(302,),
            json_body={"challenge": form_info["challenge"]},
            name="/v2/challenges/[id]",
            validator=check_claim,
        )
        if claim_response.status_code != 302 or not claim_info.get("location"):
            return None

        grant_info = {}

        def check_grant(response):
            payload = _json_object(response)
            if not payload or not _valid_id(payload.get("grant_id")):
                response.failure("Challenge redirect target lacked grant_id")
                return
            if not payload.get("csrf"):
                response.failure("Challenge redirect target lacked csrf")
                return
            grant_info["grant_id"] = payload["grant_id"]

        grant_response = self._auth_request(
            "GET",
            claim_info["location"],
            expected_status=(200,),
            name="/v2/challenges/[redirect]",
            validator=check_grant,
        )
        if grant_response.status_code != 200:
            return None
        return grant_info.get("grant_id")

    def _create_cart(self, product_id, variant_id, grant_id):
        cart_info = {}

        def check_cart(response):
            payload = _json_object(response)
            if not payload or not _valid_id(payload.get("id")):
                response.failure("Cart creation did not return a cart id")
                return
            cart_info["id"] = payload["id"]

        response = self._auth_request(
            "POST",
            "/v2/carts",
            expected_status=(201,),
            json_body={
                "product_id": product_id,
                "variant_id": variant_id,
                "grant_id": grant_id,
            },
            name="/v2/carts",
            validator=check_cart,
        )
        if response.status_code != 201 or not _valid_id(cart_info.get("id")):
            return False

        self.cart_id = cart_info["id"]
        self.etag = response.headers.get("ETag")
        return True

    def _read_cart_etag(self):
        cart_path = f"/v2/carts/{self._path_id(self.cart_id)}"
        etag_info = {}

        def check_cart(response):
            etag = response.headers.get("ETag")
            if not etag:
                response.failure("Cart response did not include ETag")
                return
            etag_info["etag"] = etag

        response = self._auth_request(
            "GET",
            cart_path,
            expected_status=(200,),
            name="/v2/carts/[id]",
            validator=check_cart,
        )
        if response.status_code != 200 or not etag_info.get("etag"):
            return None
        self.etag = etag_info["etag"]
        return self.etag

    def _patch_cart(self):
        cart_path = f"/v2/carts/{self._path_id(self.cart_id)}"
        payload = {"quantity": 1}

        etag = self._read_cart_etag()
        if not etag:
            return False

        for patch_number in range(2):
            patch_info = {}

            def check_patch(response):
                if response.status_code == 412:
                    if patch_number == 1:
                        response.failure("Cart PATCH still failed after one 412 retry")
                    return
                patch_info["etag"] = response.headers.get("ETag")

            response = self._auth_request(
                "PATCH",
                cart_path,
                expected_status=(200, 204, 412),
                json_body=payload,
                headers={"If-Match": etag},
                name="/v2/carts/[id]",
                validator=check_patch,
            )

            if response.status_code == 412:
                if patch_number == 1:
                    return False
                etag = self._read_cart_etag()
                if not etag:
                    return False
                continue

            if response.status_code not in (200, 204):
                return False
            if patch_info.get("etag"):
                self.etag = patch_info["etag"]
            else:
                self.etag = etag
            return True

        return False

    def _reserve(self):
        reservation_info = {}

        def check_reservation(response):
            payload = _json_object(response)
            if not payload or not isinstance(payload.get("status_url"), str):
                response.failure("Reservation response lacked status_url")
                return
            try:
                reservation_info["status_url"] = self._resolve_link(
                    "/v2/reservations", payload["status_url"]
                )
            except Exception as exc:
                response.failure(f"Invalid reservation status URL: {exc}")

        response = self._auth_request(
            "POST",
            "/v2/reservations",
            expected_status=(202,),
            json_body={"cart_id": self.cart_id},
            name="/v2/reservations",
            validator=check_reservation,
        )
        if response.status_code != 202 or not reservation_info.get("status_url"):
            return None

        status_url = reservation_info["status_url"]
        for poll_number in range(5):
            # The first poll and every later poll are separated from the prior
            # reservation operation by at least 50 ms.
            self.wait(0.05)
            poll_info = {}

            def check_status(poll_response):
                payload = _json_object(poll_response)
                if not payload:
                    poll_response.failure("Reservation poll was not a JSON object")
                    return

                status = payload.get("status")
                if status == "ready":
                    if not _valid_id(payload.get("reservation_id")):
                        poll_response.failure(
                            "Ready reservation lacked reservation_id"
                        )
                        return
                    poll_info["reservation_id"] = payload["reservation_id"]
                elif status == "pending":
                    if poll_number == 4:
                        poll_response.failure(
                            "Reservation was still pending after five polls"
                        )
                elif status == "failed":
                    poll_response.failure("Reservation failed")
                else:
                    poll_response.failure("Reservation returned an unknown status")

            poll_response = self._auth_request(
                "GET",
                status_url,
                expected_status=(200,),
                name="/v2/reservations/[status]",
                validator=check_status,
            )
            if poll_response.status_code != 200:
                return None

            if _valid_id(poll_info.get("reservation_id")):
                self.reservation_id = poll_info["reservation_id"]
                return self.reservation_id

            payload = _json_object(poll_response)
            if payload and payload.get("status") != "pending":
                return None
            if poll_number == 4:
                return None

        return None

    def _place_order(self):
        order_info = {}
        headers = {
            "Idempotency-Key": f"order:{self.username}:{self.cart_id}",
        }
        if self.etag:
            headers["If-Match"] = self.etag

        def check_order(response):
            payload = _json_object(response)
            if response.status_code == 200:
                response.failure("Order was not committed (HTTP 200)")
                return
            if (
                not payload
                or payload.get("accepted") is not True
                or not _valid_id(payload.get("id"))
            ):
                response.failure("Order response did not confirm an accepted order")
                return
            order_info["id"] = payload["id"]

        response = self._auth_request(
            "POST",
            "/v2/orders",
            expected_status=(201, 200),
            json_body={
                "cart_id": self.cart_id,
                "reservation_id": self.reservation_id,
            },
            headers=headers,
            name="/v2/orders",
            validator=check_order,
        )

        if response.status_code != 201 or not _valid_id(order_info.get("id")):
            return False

        self.order_id = order_info["id"]
        self.orders_by_cart[self.cart_id] = self.order_id
        return True

    def _journey(self):
        self.cart_id = None
        self.order_id = None
        self.reservation_id = None
        self.etag = None

        if not self._login():
            return

        self._do_work()

        eligible = self._find_product()
        if not eligible:
            return
        product_id, variant_id = eligible

        grant_id = self._get_challenge_grant()
        if not _valid_id(grant_id):
            return

        if not self._create_cart(product_id, variant_id, grant_id):
            return
        if not self._patch_cart():
            return

        reservation_id = self._reserve()
        if not _valid_id(reservation_id):
            return

        self._place_order()

    @task
    def run_journey(self):
        global _completed_journeys

        self.iteration += 1
        try:
            self._journey()
        except StopUser:
            raise
        except Exception:
            logger.exception(
                "Journey failed unexpectedly for %s, iteration %s",
                self.username,
                self.iteration,
            )
        finally:
            _completed_journeys += 1

        if self.iteration >= ITERATIONS_PER_USER:
            raise StopUser()


class FixedJourneyShape(LoadTestShape):
    def tick(self):
        if _completed_journeys >= EXPECTED_JOURNEYS:
            return None
        return USERS, USERS

