import itertools
import logging
import os
from html.parser import HTMLParser
from urllib.parse import quote, urljoin, urlparse, urlunparse

from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


USERS = 2
ITERATIONS_PER_USER = 2
EXPECTED_JOURNEYS = USERS * ITERATIONS_PER_USER

_completed_journeys = 0
_account_sequence = itertools.count(1)
logger = logging.getLogger(__name__)


def _configured_base_url():
    value = os.environ.get("BASE_URL", "http://127.0.0.1:8000").strip()
    if "://" not in value:
        value = "http://" + value
    return value.rstrip("/")


BASE_URL = _configured_base_url()
_BASE_PARSED = urlparse(BASE_URL)
_BASE_ORIGIN = f"{_BASE_PARSED.scheme}://{_BASE_PARSED.netloc}"


def _valid_id(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, str):
        return bool(value.strip())
    return isinstance(value, int)


class _FormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.csrf_inputs = []
        self.forms = []
        self._current_form = None

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        attributes = {str(key).lower(): value for key, value in attrs if key}

        if tag == "form":
            form = {"action": attributes.get("action"), "inputs": []}
            self.forms.append(form)
            self._current_form = form
        elif tag == "input":
            name = attributes.get("name")
            value = attributes.get("value")
            input_type = (attributes.get("type") or "").lower()
            if name and name.lower() == "csrf":
                self.csrf_inputs.append((input_type, value))
            if self._current_form is not None and name:
                self._current_form["inputs"].append(
                    (name.lower(), value, input_type)
                )

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self._current_form = None

    def csrf_value(self):
        hidden = [
            value
            for input_type, value in self.csrf_inputs
            if input_type == "hidden" and value
        ]
        if hidden:
            return hidden[0]
        for _, value in self.csrf_inputs:
            if value:
                return value
        return None

    def challenge_form(self):
        for form in self.forms:
            if not form.get("action"):
                continue
            for name, value, _ in form["inputs"]:
                if name == "challenge" and value:
                    return form["action"], value
        return None


def _json_object(response):
    try:
        payload = response.json()
    except Exception:
        return None
    return payload if isinstance(payload, dict) else None


def _response_csrf(response):
    header_token = response.headers.get("X-CSRF-Token")
    if header_token:
        return header_token
    payload = _json_object(response)
    if payload and isinstance(payload.get("csrf"), str) and payload["csrf"]:
        return payload["csrf"]
    return None


def _product_and_next(payload):
    if not isinstance(payload, dict):
        return None, None

    data = payload.get("data")
    product = payload.get("product")
    if product is None and isinstance(data, dict):
        product = data.get("product")
        if product is None and _valid_id(data.get("id")):
            product = data
        if product is None:
            products = data.get("products")
            if isinstance(products, list) and products:
                product = products[0]

    if product is None:
        products = payload.get("products")
        if isinstance(products, list) and products:
            product = products[0]

    next_link = payload.get("next")
    if next_link is None and isinstance(data, dict):
        next_link = data.get("next")

    if not isinstance(product, dict):
        product = None
    return product, next_link


def _eligible_ids(product):
    if not isinstance(product, dict) or not _valid_id(product.get("id")):
        return None

    variants = product.get("variants")
    if not isinstance(variants, list):
        return None

    for variant in variants:
        if (
            isinstance(variant, dict)
            and variant.get("in_stock") is True
            and _valid_id(variant.get("id"))
        ):
            return product["id"], variant["id"]
    return None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = lambda self: 0

    def on_start(self):
        account_number = (next(_account_sequence) - 1) % 16 + 1
        self.username = f"bench-{account_number}"
        self.password = "bench"
        self.csrf = None
        self.iteration = 0
        self.cart_id = None
        self.order_id = None
        self.reservation_id = None
        self.etag = None
        self.orders_by_cart = {}

    def _resolve_link(self, current_url, link):
        if not isinstance(link, str) or not link.strip():
            raise ValueError("Expected a non-empty dynamic URL")

        if current_url.startswith(("http://", "https://")):
            current = current_url
        else:
            current = urljoin(BASE_URL + "/", current_url)

        absolute = urljoin(current, link)
        parsed = urlparse(absolute)
        origin = f"{parsed.scheme}://{parsed.netloc}"
        if origin != _BASE_ORIGIN:
            raise ValueError("Dynamic URL points outside the configured host")

        return urlunparse(
            (parsed.scheme, parsed.netloc, parsed.path, parsed.params, parsed.query, "")
        )

    @staticmethod
    def _path_id(value):
        return quote(str(value), safe="")

    def _capture_csrf(self, response):
        if response.status_code == 401:
            return
        token = _response_csrf(response)
        if token:
            self.csrf = token

    def _single_request(
        self,
        method,
        path,
        *,
        expected_status,
        json_body=None,
        headers=None,
        name=None,
        validator=None,
    ):
        request_headers = dict(headers or {})
        kwargs = {
            "headers": request_headers,
            "catch_response": True,
            "allow_redirects": False,
        }
        if name:
            kwargs["name"] = name
        if json_body is not None:
            kwargs["json"] = json_body

        expected_status = tuple(expected_status)
        with self.client.request(method, path, **kwargs) as response:
            if response.status_code not in expected_status:
                response.failure(
                    f"Unexpected HTTP {response.status_code} for {method} {name or path}"
                )
            elif validator is not None:
                try:
                    validator(response)
                except Exception as exc:
                    response.failure(f"Response validation failed: {exc}")

        self._capture_csrf(response)
        return response

    def _error_name(self, response):
        payload = _json_object(response)
        if not payload:
            return None
        error = payload.get("error")
        return error.lower() if isinstance(error, str) else None

    def _auth_request(
        self,
        method,
        path,
        *,
        expected_status,
        json_body=None,
        headers=None,
        name=None,
        validator=None,
    ):
        method = method.upper()
        base_headers = dict(headers or {})
        if method != "GET":
            base_headers["X-CSRF-Token"] = self.csrf or ""

        expected = tuple(expected_status)
        for attempt in range(2):
            auth_error = {"value": None}

            def check_response(response):
                if response.status_code == 401:
                    error = self._error_name(response)
                    auth_error["value"] = error
                    if attempt == 0 and error in ("expired", "session"):
                        return
                    response.failure(
                        f"Authentication assertion failed: {error or 'unknown'}"
                    )
                    return
                if validator is not None:
                    validator(response)

            response = self._single_request(
                method,
                path,
                expected_status=expected + (401,),
                json_body=json_body,
                headers=base_headers,
                name=name,
                validator=check_response,
            )

            if response.status_code != 401:
                return response

            error = auth_error["value"]
            if attempt == 0 and error in ("expired", "session"):
                if self._reauthenticate_and_recover():
                    if method != "GET":
                        base_headers["X-CSRF-Token"] = self.csrf or ""
                    continue
            return response

        return response

    def _login(self):
        form_data = {}

        def check_login_form(response):
            parser = _FormParser()
            parser.feed(response.text or "")
            form_data["csrf"] = parser.csrf_value()
            if not form_data["csrf"]:
                response.failure("Login form did not contain input[name=csrf]")

        form_response = self._single_request(
            "GET",
            "/v2/login-form",
            expected_status=(200,),
            name="/v2/login-form",
            validator=check_login_form,
        )
        if form_response.status_code != 200 or not form_data.get("csrf"):
            return False

        self.csrf = form_data["csrf"]
        login_data = {}

        def check_login_response(response):
            if response.status_code == 302:
                location = response.headers.get("Location")
                if not location:
                    response.failure("Login redirect did not include Location")
                    return
                try:
                    login_data["location"] = self._resolve_link("/v2/login", location)
                except Exception as exc:
                    response.failure(f"Invalid login redirect: {exc}")
                return

            payload = _json_object(response)
            if not payload or not payload.get("csrf") or "user" not in payload:
                response.failure("Login response did not contain csrf and user")

        login_response = self._single_request(
            "POST",
            "/v2/login",
            expected_status=(200, 302),
            json_body={
                "username": self.username,
                "password": self.password,
                "csrf": self.csrf,
            },
            name="/v2/login",
            validator=check_login_response,
        )

        if login_response.status_code == 200:
            payload = _json_object(login_response)
            return bool(payload and payload.get("csrf"))

        if login_response.status_code != 302 or not login_data.get("location"):
            return False

        landing_data = {}

        def check_login_landing(response):
            payload = _json_object(response)
            if not payload or not payload.get("csrf"):
                response.failure("Login redirect target did not return a fresh csrf")
                return
            landing_data["payload"] = payload

        landing = self._single_request(
            "GET",
            login_data["location"],
            expected_status=(200,),
            name="/v2/login/[redirect]",
            validator=check_login_landing,
        )
        return landing.status_code == 200 and bool(landing_data.get("payload"))

    def _reauthenticate_and_recover(self):
        renew_info = {"ok": False, "error": None}

        def check_renew(response):
            if response.status_code == 401:
                error = self._error_name(response)
                renew_info["error"] = error
                if error != "session":
                    response.failure(
                        f"Session renewal failed unexpectedly: {error or 'unknown'}"
                    )
                return
            if not _response_csrf(response):
                response.failure("Session renewal did not provide a fresh csrf")
                return
            renew_info["ok"] = True

        renew = self._single_request(
            "POST",
            "/v2/session/renew",
            expected_status=(200, 204, 401),
            json_body={},
            headers={"X-CSRF-Token": self.csrf or ""},
            name="/v2/session/renew",
            validator=check_renew,
        )

        if renew.status_code in (200, 204):
            if not renew_info["ok"]:
                return False
        elif renew.status_code == 401 and renew_info["error"] == "session":
            if not self._login():
                return False
        else:
            return False

        if self.cart_id is not None:
            cart_path = f"/v2/carts/{self._path_id(self.cart_id)}/recover"
            recovered = self._single_request(
                "POST",
                cart_path,
                expected_status=(200, 204),
                json_body={},
                headers={"X-CSRF-Token": self.csrf or ""},
                name="/v2/carts/[id]/recover",
            )
            if recovered.status_code not in (200, 204):
                return False

        return True

    def _do_work(self):
        for retry_number in range(5):
            retry_delay = {"seconds": None}

            def check_work(response):
                if response.status_code == 200:
                    payload = _json_object(response)
                    if not payload or payload.get("ok") is not True:
                        response.failure("/v2/work did not return {ok:true}")
                    return

                if response.status_code == 429:
                    retry_after = response.headers.get("Retry-After")
                    try:
                        delay = float(retry_after)
                        if delay <= 0:
                            raise ValueError("Retry-After must be positive")
                        retry_delay["seconds"] = max(1.0, delay)
                    except (TypeError, ValueError):
                        response.failure("Scheduled 429 lacked a valid Retry-After")

            response = self._auth_request(
                "POST",
                "/v2/work",
                expected_status=(200, 429),
                json_body={},
                name="/v2/work",
                validator=check_work,
            )
            if response.status_code != 429:
                return
            if retry_number >= 4 or retry_delay["seconds"] is None:
                return
            self.wait(retry_delay["seconds"])

    def _find_product(self):
        selected = {}
        current_url = self._resolve_link(BASE_URL + "/", "/v2/catalog/page")

        for page_number in range(3):
            page_info = {}

            def check_page(response):
                payload = _json_object(response)
                if not payload:
                    response.failure("Catalog page did not return a JSON object")
                    return

                product, next_link = _product_and_next(payload)
                page_info["next"] = next_link
                candidate = _eligible_ids(product) if product else None
                if candidate:
                    selected["ids"] = candidate
                    return

                if next_link is not None and not isinstance(next_link, str):
                    response.failure("Catalog next cursor was not a relative URL")
                    return

                if page_number == 2 or next_link is None:
                    response.failure(
                        "No in-stock product variant found within three catalog pages"
                    )
                    return

                try:
                    page_info["resolved_next"] = self._resolve_link(
                        current_url, next_link
                    )
                except Exception as exc:
                    response.failure(f"Invalid catalog next link: {exc}")

            response = self._single_request(
                "GET",
                current_url,
                expected_status=(200,),
                name="/v2/catalog/page",
                validator=check_page,
            )

            if response.status_code != 200:
                return None
            if selected.get("ids"):
                return selected["ids"]

            next_url = page_info.get("resolved_next")
            if not next_url:
                return None
            current_url = next_url

        return None

    def _get_challenge_grant(self):
        form_info = {}

        def check_challenge_form(response):
            parser = _FormParser()
            parser.feed(response.text or "")
            parsed = parser.challenge_form()
            if not parsed:
                response.failure(
                    "Challenge form lacked a form action and input[name=challenge]"
                )
                return
            action, challenge = parsed
            try:
                form_info["action"] = self._resolve_link(
                    "/v2/challenge-form", action
                )
                form_info["challenge"] = challenge
            except Exception as exc:
                response.failure(f"Invalid challenge form action: {exc}")

        form_response = self._auth_request(
            "GET",
            "/v2/challenge-form",
            expected_status=(200,),
            name="/v2/challenge-form",
            validator=check_challenge_form,
        )
        if form_response.status_code != 200 or not form_info.get("action"):
            return None

        claim_info = {}

        def check_claim(response):
            location = response.headers.get("Location")
            if not location:
                response.failure("Challenge claim did not return a redirect Location")
                return
            try:
                claim_info["location"] = self._resolve_link(
                    form_info["action"], location
                )
            except Exception as exc:
                response.failure(f"Invalid challenge redirect: {exc}")

        claim_response = self._auth_request(
            "POST",
            form_info["action"],
            expected_status=(302,),
            json_body={"challenge": form_info["challenge"]},
            name="/v2/challenges/[id]",
            validator=check_claim,
        )
        if claim_response.status_code != 302 or not claim_info.get("location"):
            return None

        grant_info = {}

        def check_grant(response):
            payload = _json_object(response)
            if not payload or not _valid_id(payload.get("grant_id")):
                response.failure("Challenge redirect target lacked grant_id")
                return
            if not payload.get("csrf"):
                response.failure("Challenge redirect target lacked csrf")
                return
            grant_info["grant_id"] = payload["grant_id"]

        grant_response = self._auth_request(
            "GET",
            claim_info["location"],
            expected_status=(200,),
            name="/v2/challenges/[redirect]",
            validator=check_grant,
        )
        if grant_response.status_code != 200:
            return None
        return grant_info.get("grant_id")

    def _create_cart(self, product_id, variant_id, grant_id):
        cart_info = {}

        def check_cart(response):
            payload = _json_object(response)
            if not payload or not _valid_id(payload.get("id")):
                response.failure("Cart creation did not return a cart id")
                return
            cart_info["id"] = payload["id"]

        response = self._auth_request(
            "POST",
            "/v2/carts",
            expected_status=(201,),
            json_body={
                "product_id": product_id,
                "variant_id": variant_id,
                "grant_id": grant_id,
            },
            name="/v2/carts",
            validator=check_cart,
        )
        if response.status_code != 201 or not _valid_id(cart_info.get("id")):
            return False

        self.cart_id = cart_info["id"]
        self.etag = response.headers.get("ETag")
        return True

    def _read_cart_etag(self):
        cart_path = f"/v2/carts/{self._path_id(self.cart_id)}"
        etag_info = {}

        def check_cart(response):
            etag = response.headers.get("ETag")
            if not etag:
                response.failure("Cart response did not include ETag")
                return
            etag_info["etag"] = etag

        response = self._auth_request(
            "GET",
            cart_path,
            expected_status=(200,),
            name="/v2/carts/[id]",
            validator=check_cart,
        )
        if response.status_code != 200 or not etag_info.get("etag"):
            return None
        self.etag = etag_info["etag"]
        return self.etag

    def _patch_cart(self):
        cart_path = f"/v2/carts/{self._path_id(self.cart_id)}"
        payload = {"quantity": 1}

        etag = self._read_cart_etag()
        if not etag:
            return False

        for patch_number in range(2):
            patch_info = {}

            def check_patch(response):
                if response.status_code == 412:
                    if patch_number == 1:
                        response.failure("Cart PATCH still failed after one 412 retry")
                    return
                patch_info["etag"] = response.headers.get("ETag")

            response = self._auth_request(
                "PATCH",
                cart_path,
                expected_status=(200, 204, 412),
                json_body=payload,
                headers={"If-Match": etag},
                name="/v2/carts/[id]",
                validator=check_patch,
            )

            if response.status_code == 412:
                if patch_number == 1:
                    return False
                etag = self._read_cart_etag()
                if not etag:
                    return False
                continue

            if response.status_code not in (200, 204):
                return False

            if patch_info.get("etag"):
                self.etag = patch_info["etag"]
            else:
                self.etag = etag

            # Read the current entity tag after mutation for any later
            # conditional order operation.
            return self._read_cart_etag() is not None

        return False

    def _reserve(self):
        reservation_info = {}

        def check_reservation(response):
            payload = _json_object(response)
            if not payload or not isinstance(payload.get("status_url"), str):
                response.failure("Reservation response lacked status_url")
                return
            try:
                reservation_info["status_url"] = self._resolve_link(
                    "/v2/reservations", payload["status_url"]
                )
            except Exception as exc:
                response.failure(f"Invalid reservation status URL: {exc}")

        response = self._auth_request(
            "POST",
            "/v2/reservations",
            expected_status=(202,),
            json_body={"cart_id": self.cart_id},
            name="/v2/reservations",
            validator=check_reservation,
        )
        if response.status_code != 202 or not reservation_info.get("status_url"):
            return None

        status_url = reservation_info["status_url"]
        for poll_number in range(5):
            self.wait(0.05)
            poll_info = {}

            def check_status(poll_response):
                payload = _json_object(poll_response)
                if not payload:
                    poll_response.failure("Reservation poll was not a JSON object")
                    return

                status = payload.get("status")
                if status == "ready":
                    if not _valid_id(payload.get("reservation_id")):
                        poll_response.failure("Ready reservation lacked reservation_id")
                        return
                    poll_info["reservation_id"] = payload["reservation_id"]
                elif status == "pending":
                    if poll_number == 4:
                        poll_response.failure(
                            "Reservation was still pending after five polls"
                        )
                elif status == "failed":
                    poll_response.failure("Reservation failed")
                else:
                    poll_response.failure("Reservation returned an unknown status")

            poll_response = self._auth_request(
                "GET",
                status_url,
                expected_status=(200,),
                name="/v2/reservations/[status]",
                validator=check_status,
            )
            if poll_response.status_code != 200:
                return None

            if _valid_id(poll_info.get("reservation_id")):
                self.reservation_id = poll_info["reservation_id"]
                return self.reservation_id

            payload = _json_object(poll_response)
            if payload and payload.get("status") != "pending":
                return None
            if poll_number == 4:
                return None

        return None

    def _place_order(self):
        order_info = {}
        headers = {"Idempotency-Key": f"order:{self.username}:{self.cart_id}"}
        if self.etag:
            headers["If-Match"] = self.etag

        def check_order(response):
            payload = _json_object(response)
            if response.status_code == 200:
                response.failure("Order was not committed (HTTP 200)")
                return
            if (
                not payload
                or payload.get("accepted") is not True
                or not _valid_id(payload.get("id"))
            ):
                response.failure("Order response did not confirm an accepted order")
                return
            order_info["id"] = payload["id"]

        response = self._auth_request(
            "POST",
            "/v2/orders",
            expected_status=(201, 200),
            json_body={
                "cart_id": self.cart_id,
                "reservation_id": self.reservation_id,
            },
            headers=headers,
            name="/v2/orders",
            validator=check_order,
        )

        if response.status_code != 201 or not _valid_id(order_info.get("id")):
            return False

        self.order_id = order_info["id"]
        self.orders_by_cart[self.cart_id] = self.order_id
        return True

    def _journey(self):
        self.cart_id = None
        self.order_id = None
        self.reservation_id = None
        self.etag = None

        if not self._login():
            return

        self._do_work()

        eligible = self._find_product()
        if not eligible:
            return
        product_id, variant_id = eligible

        grant_id = self._get_challenge_grant()
        if not _valid_id(grant_id):
            return

        if not self._create_cart(product_id, variant_id, grant_id):
            return
        if not self._patch_cart():
            return

        reservation_id = self._reserve()
        if not _valid_id(reservation_id):
            return

        self._place_order()

    @task
    def run_journey(self):
        global _completed_journeys

        self.iteration += 1
        try:
            self._journey()
        except StopUser:
            raise
        except Exception:
            logger.exception(
                "Journey failed unexpectedly for %s, iteration %s",
                self.username,
                self.iteration,
            )
        finally:
            _completed_journeys += 1

        if self.iteration >= ITERATIONS_PER_USER:
            raise StopUser()


class FixedJourneyShape(LoadTestShape):
    def tick(self):
        if _completed_journeys >= EXPECTED_JOURNEYS:
            return None
        return USERS, USERS

import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const ORIGIN = 'http://127.0.0.1:8000';
const BASE_URL = (__ENV.BASE_URL || ORIGIN).replace(/\/+$/, '');
if (BASE_URL !== ORIGIN) {
  throw new Error('BASE_URL must target http://127.0.0.1:8000');
}

const USERS = 2;
const ITERATIONS_PER_USER = 2;
const QUANTITY = 2;
const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: USERS,
      iterations: ITERATIONS_PER_USER,
      maxDuration: '5m',
    },
  },
};

function insist(condition, label) {
  const passed = check({ passed: Boolean(condition) }, {
    [label]: (value) => value.passed,
  });
  if (!passed) {
    throw new Error(label);
  }
}

function is2xx(status) {
  return status >= 200 && status < 300;
}

function resolveLocal(reference, baseUrl) {
  const ref = String(reference);
  if (/^https?:\/\//i.test(ref)) {
    if (
      ref !== ORIGIN &&
      ref.indexOf(ORIGIN + '/') !== 0 &&
      ref.indexOf(ORIGIN + '?') !== 0 &&
      ref.indexOf(ORIGIN + '#') !== 0
    ) {
      throw new Error('Refusing URL outside the target origin');
    }
    return ref;
  }
  if (ref.indexOf('//') === 0) {
    throw new Error('Refusing protocol-relative URL');
  }

  const current = baseUrl || BASE_URL;
  const currentPath = current.indexOf(ORIGIN) === 0
    ? current.substring(ORIGIN.length).split(/[?#]/)[0]
    : '/';

  let path;
  if (ref.charAt(0) === '/') {
    path = ref;
  } else if (ref.charAt(0) === '?') {
    path = currentPath + ref;
  } else {
    const slash = currentPath.lastIndexOf('/');
    path = currentPath.substring(0, slash + 1) + ref;
  }

  const suffixIndex = path.search(/[?#]/);
  const pathname = suffixIndex < 0 ? path : path.substring(0, suffixIndex);
  const suffix = suffixIndex < 0 ? '' : path.substring(suffixIndex);
  const parts = pathname.split('/');
  const normalized = [];
  for (let i = 0; i < parts.length; i += 1) {
    if (!parts[i] || parts[i] === '.') {
      continue;
    }
    if (parts[i] === '..') {
      if (normalized.length) {
        normalized.pop();
      }
    } else {
      normalized.push(parts[i]);
    }
  }
  return ORIGIN + '/' + normalized.join('/') + suffix;
}

function getHeader(response, wantedName) {
  const headers = (response && response.headers) || {};
  const keys = Object.keys(headers);
  for (let i = 0; i < keys.length; i += 1) {
    if (keys[i].toLowerCase() === wantedName.toLowerCase()) {
      return String(headers[keys[i]]);
    }
  }
  return null;
}

function parseJson(response) {
  if (!response || !response.body) {
    return null;
  }
  try {
    return JSON.parse(response.body);
  } catch (e) {
    return null;
  }
}

function recordWorkResponse(response, json) {
  const expected =
    (response.status === 200 && json && json.ok === true) ||
    response.status === 429 ||
    (response.status === 401 && json && json.error === 'expired');
  businessFailure.add(!expected, { endpoint: 'work' });
}

function sendRaw(state, method, url, bodyText, extraHeaders, tag, isWork) {
  const headers = { Accept: 'application/json' };

  if (method !== 'GET' && state && state.csrf) {
    headers['X-CSRF-Token'] = state.csrf;
  }
  if (bodyText !== null && method !== 'GET') {
    headers['Content-Type'] = 'application/json';
  }

  if (extraHeaders) {
    const additions = typeof extraHeaders === 'function'
      ? extraHeaders()
      : extraHeaders;
    const keys = Object.keys(additions || {});
    for (let i = 0; i < keys.length; i += 1) {
      headers[keys[i]] = additions[keys[i]];
    }
  }

  const params = {
    headers: headers,
    redirects: 0,
    tags: { name: tag || method + ' request' },
  };
  const response = http.request(method, url, bodyText, params);
  const json = parseJson(response);

  if (state && json && typeof json.csrf === 'string' && json.csrf.length > 0) {
    state.csrf = json.csrf;
  }
  if (isWork) {
    recordWorkResponse(response, json);
  }

  return { response: response, json: json };
}

function getAttribute(tag, name) {
  const attributes = tag
    .replace(/^<\s*[a-z][^\s/>]*/i, '')
    .replace(/\/?>\s*$/, '');
  const pattern = new RegExp(
    '(?:^|\\s)' + name +
    '\\s*=\\s*(?:"([^"]*)"|\\x27([^\\x27]*)\\x27|([^\\s>]+))',
    'i'
  );
  const match = attributes.match(pattern);
  if (!match) {
    return null;
  }
  return decodeEntities(match[1] !== undefined
    ? match[1]
    : (match[2] !== undefined ? match[2] : match[3]));
}

function decodeEntities(value) {
  return String(value)
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#x([0-9a-f]+);/gi, function (whole, hex) {
      return String.fromCharCode(parseInt(hex, 16));
    })
    .replace(/&#([0-9]+);/g, function (whole, decimal) {
      return String.fromCharCode(parseInt(decimal, 10));
    });
}

function findInputValue(html, wantedName) {
  const tags = String(html || '').match(/<input\b[^>]*>/gi) || [];
  for (let i = 0; i < tags.length; i += 1) {
    const name = getAttribute(tags[i], 'name');
    if (name && name.toLowerCase() === wantedName.toLowerCase()) {
      const value = getAttribute(tags[i], 'value');
      if (value !== null) {
        return value;
      }
    }
  }
  return null;
}

function findChallengeAction(html) {
  const forms = String(html || '').match(/<form\b[^>]*>/gi) || [];
  for (let i = 0; i < forms.length; i += 1) {
    const action = getAttribute(forms[i], 'action');
    if (action && /\/v2\/challenges\//.test(action)) {
      return action;
    }
  }
  return null;
}

function freshLogin(state, clearCookies) {
  if (clearCookies) {
    http.cookieJar().clear(BASE_URL);
  }

  const formUrl = resolveLocal('/v2/login-form');
  const form = sendRaw(null, 'GET', formUrl, null, null, 'login form', false);
  insist(form.response.status === 200, 'login form returned successfully');

  const formCsrf = findInputValue(form.response.body, 'csrf');
  insist(formCsrf !== null && formCsrf.length > 0, 'login form CSRF extracted');

  const loginBody = JSON.stringify({
    username: state.username,
    password: 'bench',
    csrf: formCsrf,
  });
  const login = sendRaw(
    null,
    'POST',
    resolveLocal('/v2/login'),
    loginBody,
    null,
    'login',
    false
  );

  let finalJson = login.json;
  let finalResponse = login.response;

  if (login.response.status === 302) {
    const location = getHeader(login.response, 'Location');
    insist(location !== null && location.length > 0, 'login redirect location present');
    const redirected = sendRaw(
      null,
      'GET',
      resolveLocal(location, resolveLocal('/v2/login')),
      null,
      null,
      'login redirect destination',
      false
    );
    finalResponse = redirected.response;
    finalJson = redirected.json || finalJson;
  } else {
    insist(is2xx(login.response.status), 'login accepted');
  }

  insist(is2xx(finalResponse.status), 'login destination returned successfully');
  if (finalJson && typeof finalJson.csrf === 'string' && finalJson.csrf.length > 0) {
    state.csrf = finalJson.csrf;
  } else if (login.json && typeof login.json.csrf === 'string' && login.json.csrf.length > 0) {
    state.csrf = login.json.csrf;
  }
  insist(typeof state.csrf === 'string' && state.csrf.length > 0, 'login CSRF captured');
}

function recoverCart(state) {
  if (!state.cartId) {
    return;
  }
  const result = sendRaw(
    state,
    'POST',
    resolveLocal('/v2/carts/' + encodeURIComponent(String(state.cartId)) + '/recover'),
    '{}',
    null,
    'recover cart',
    false
  );
  insist(is2xx(result.response.status), 'existing cart recovered');
}

function recoverExpiredSession(state) {
  const renewed = sendRaw(
    state,
    'POST',
    resolveLocal('/v2/session/renew'),
    '{}',
    null,
    'renew session',
    false
  );
  insist(
    is2xx(renewed.response.status) &&
      renewed.json &&
      typeof renewed.json.csrf === 'string' &&
      renewed.json.csrf.length > 0,
    'expired session renewed with fresh CSRF'
  );
  state.csrf = renewed.json.csrf;
  recoverCart(state);
}

function recoverRevokedSession(state) {
  // A revoked session may reject renewal; the required recovery is a fresh login.
  sendRaw(
    state,
    'POST',
    resolveLocal('/v2/session/renew'),
    '{}',
    null,
    'attempt renewal for revoked session',
    false
  );
  freshLogin(state, true);
  recoverCart(state);
}

function apiRequest(state, method, urlOrPath, bodyText, extraHeaders, tag, isWork) {
  let recovered = false;
  const url = resolveLocal(urlOrPath);

  while (true) {
    if (method !== 'GET') {
      insist(
        typeof state.csrf === 'string' && state.csrf.length > 0,
        'CSRF available for authenticated mutation'
      );
    }

    const result = sendRaw(
      state,
      method,
      url,
      bodyText,
      extraHeaders,
      tag,
      Boolean(isWork)
    );

    if (result.response.status !== 401 || recovered) {
      return result;
    }

    const error = result.json && result.json.error;
    if (error === 'expired') {
      recoverExpiredSession(state);
      recovered = true;
    } else if (error === 'session') {
      recoverRevokedSession(state);
      recovered = true;
    } else {
      return result;
    }
  }
}

function catalogProducts(json) {
  if (!json) {
    return [];
  }
  const data = json.data || json;
  if (data && Array.isArray(data.products)) {
    return data.products;
  }
  if (data && data.product) {
    return [data.product];
  }
  if (data && data.id && Array.isArray(data.variants)) {
    return [data];
  }
  if (Array.isArray(json.products)) {
    return json.products;
  }
  return [];
}

function findAvailableProduct(products) {
  for (let i = 0; i < products.length; i += 1) {
    const product = products[i];
    const variants = product && Array.isArray(product.variants)
      ? product.variants
      : [];
    for (let j = 0; j < variants.length; j += 1) {
      if (variants[j] && variants[j].in_stock === true) {
        return { product: product, variant: variants[j] };
      }
    }
  }
  return null;
}

function selectCatalogItem() {
  let currentUrl = resolveLocal('/v2/catalog');
  let selected = null;

  for (let pageNumber = 0; pageNumber < 3; pageNumber += 1) {
    const page = sendRaw(
      null,
      'GET',
      currentUrl,
      null,
      null,
      pageNumber === 0 ? 'catalog' : 'catalog page',
      false
    );
    insist(page.response.status === 200, 'catalog page returned successfully');

    selected = findAvailableProduct(catalogProducts(page.json));
    if (selected) {
      break;
    }

    const next = page.json && (page.json.next ||
      (page.json.data && page.json.data.next));
    if (!next) {
      break;
    }
    currentUrl = resolveLocal(next, currentUrl);
  }

  insist(
    selected && selected.product.id !== undefined &&
      selected.variant.id !== undefined,
    'available catalog product and variant selected'
  );
  return selected;
}

function obtainGrant(state) {
  const form = apiRequest(
    state,
    'GET',
    '/v2/challenge-form',
    null,
    null,
    'challenge form',
    false
  );
  insist(form.response.status === 200, 'challenge form returned successfully');

  const action = findChallengeAction(form.response.body);
  const challenge = findInputValue(form.response.body, 'challenge');
  insist(action !== null, 'dynamic challenge action extracted');
  insist(challenge !== null && challenge.length > 0, 'challenge value extracted');

  const posted = apiRequest(
    state,
    'POST',
    action,
    JSON.stringify({ challenge: challenge }),
    null,
    'submit challenge',
    false
  );
  insist(posted.response.status === 302, 'challenge submission redirected');

  const location = getHeader(posted.response, 'Location');
  insist(location !== null && location.length > 0, 'challenge redirect location present');

  const grant = apiRequest(
    state,
    'GET',
    resolveLocal(location, resolveLocal(action)),
    null,
    null,
    'claim challenge grant',
    false
  );
  insist(grant.response.status === 200, 'challenge grant claimed');
  insist(
    grant.json && typeof grant.json.grant_id === 'string' &&
      grant.json.grant_id.length > 0,
    'challenge grant ID extracted'
  );
  return grant.json.grant_id;
}

function extractEtag(response) {
  const value = getHeader(response, 'ETag');
  return value && value.length > 0 ? value : null;
}

function readCart(state, cartId, tag) {
  return apiRequest(
    state,
    'GET',
    '/v2/carts/' + encodeURIComponent(String(cartId)),
    null,
    null,
    tag || 'read cart',
    false
  );
}

function createReservation(state, cartId) {
  const created = apiRequest(
    state,
    'POST',
    '/v2/reservations',
    JSON.stringify({ cart_id: cartId }),
    null,
    'create reservation',
    false
  );
  insist(created.response.status === 202, 'reservation accepted');
  insist(
    created.json && typeof created.json.status_url === 'string' &&
      created.json.status_url.length > 0,
    'reservation status URL extracted'
  );

  const statusUrl = resolveLocal(
    created.json.status_url,
    resolveLocal('/v2/reservations')
  );

  for (let poll = 0; poll < 5; poll += 1) {
    if (poll > 0) {
      sleep(0.05);
    }
    const status = apiRequest(
      state,
      'GET',
      statusUrl,
      null,
      null,
      'poll reservation',
      false
    );
    insist(status.response.status === 200, 'reservation status returned successfully');

    if (status.json && status.json.status === 'ready') {
      insist(
        typeof status.json.reservation_id === 'string' &&
          status.json.reservation_id.length > 0,
        'ready reservation ID extracted'
      );
      return status.json.reservation_id;
    }
    insist(
      status.json && status.json.status === 'pending',
      'reservation is pending or ready'
    );
  }

  insist(false, 'reservation became ready within five polls');
  return null;
}

function performWork(state) {
  let scheduledRetries = 0;

  while (true) {
    const work = apiRequest(
      state,
      'POST',
      '/v2/work',
      '{}',
      null,
      'business work',
      true
    );

    if (work.response.status === 429) {
      insist(scheduledRetries < 4, 'scheduled work throttling stayed within retry limit');
      const retryAfter = getHeader(work.response, 'Retry-After');
      const delay = retryAfter === null ? NaN : parseFloat(retryAfter);
      insist(delay === 1, 'scheduled work throttle requested one-second delay');
      scheduledRetries += 1;
      sleep(delay);
      continue;
    }

    insist(
      work.response.status === 200 && work.json && work.json.ok === true,
      'business work completed'
    );
    return;
  }
}

function journey() {
  const accountNumber = (((__VU - 1) * ITERATIONS_PER_USER + __ITER) % 16) + 1;
  const state = {
    username: 'bench-' + accountNumber,
    csrf: null,
    cartId: null,
  };

  freshLogin(state, true);

  const item = selectCatalogItem();
  const grantId = obtainGrant(state);

  const cartBody = JSON.stringify({
    product_id: item.product.id,
    variant_id: item.variant.id,
    grant_id: grantId,
  });
  const created = apiRequest(
    state,
    'POST',
    '/v2/carts',
    cartBody,
    null,
    'create cart',
    false
  );
  insist(created.response.status === 201, 'one cart created');
  insist(
    created.json && created.json.id !== undefined && created.json.id !== null,
    'cart ID extracted'
  );
  state.cartId = created.json.id;

  let initialEtag = extractEtag(created.response);
  if (!initialEtag) {
    const initialRead = readCart(state, state.cartId, 'extract initial cart revision');
    insist(initialRead.response.status === 200, 'initial cart revision read');
    initialEtag = extractEtag(initialRead.response);
  }
  insist(initialEtag !== null, 'initial cart ETag extracted');

  const patchBody = JSON.stringify({ quantity: QUANTITY });
  const firstPatch = apiRequest(
    state,
    'PATCH',
    '/v2/carts/' + encodeURIComponent(String(state.cartId)),
    patchBody,
    function () {
      return { 'If-Match': initialEtag };
    },
    'initial conditional cart update',
    false
  );

  insist(firstPatch.response.status === 412, 'scheduled stale cart update detected');

  const reread = readCart(state, state.cartId, 're-read cart after conflict');
  insist(reread.response.status === 200, 'cart re-read after stale update');
  const freshEtag = extractEtag(reread.response);
  insist(freshEtag !== null, 'fresh cart ETag extracted after conflict');

  const retryBody = patchBody;
  insist(retryBody === patchBody, 'conditional retry preserves the original payload');
  const retryEtag = freshEtag;
  insist(retryEtag === freshEtag, 'conditional retry uses the re-read ETag');

  const retriedPatch = apiRequest(
    state,
    'PATCH',
    '/v2/carts/' + encodeURIComponent(String(state.cartId)),
    retryBody,
    function () {
      return { 'If-Match': retryEtag };
    },
    'conditional cart update retry',
    false
  );
  insist(is2xx(retriedPatch.response.status), 'conditional cart retry committed');

  const finalCart = readCart(state, state.cartId, 'read updated cart revision');
  insist(finalCart.response.status === 200, 'updated cart read successfully');
  const orderEtag = extractEtag(finalCart.response);
  insist(orderEtag !== null, 'current cart ETag extracted for checkout');

  const reservationId = createReservation(state, state.cartId);
  const idempotencyKey = 'order-' + String(state.cartId);
  const order = apiRequest(
    state,
    'POST',
    '/v2/orders',
    JSON.stringify({
      cart_id: state.cartId,
      reservation_id: reservationId,
    }),
    function () {
      return {
        'If-Match': orderEtag,
        'Idempotency-Key': idempotencyKey,
      };
    },
    'commit order',
    false
  );
  insist(
    order.response.status === 201 &&
      order.json &&
      order.json.accepted === true,
    'exactly one intended order accepted'
  );

  performWork(state);
}

