import itertools
import json
import os
from html.parser import HTMLParser
from urllib.parse import quote, urljoin, urlsplit

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
ACCOUNT_IDS = itertools.count()


def _json_dict(response):
    try:
        value = response.json()
        return value if isinstance(value, dict) else {}
    except (ValueError, json.JSONDecodeError):
        return {}


def _value(data, key):
    if not isinstance(data, dict):
        return None
    if key in data:
        return data[key]
    nested = data.get("data")
    return nested.get(key) if isinstance(nested, dict) else None


class _InputParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.inputs = []
        self.current_form_action = None
        self.challenge_fields = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag.lower() == "form":
            self.current_form_action = attrs.get("action")
        elif tag.lower() == "input":
            name = attrs.get("name")
            value = attrs.get("value")
            self.inputs.append((name, value))
            if name == "challenge" and self.current_form_action:
                self.challenge_fields.append(
                    (self.current_form_action, value)
                )

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        self.handle_endtag(tag)

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self.current_form_action = None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.username = f"bench-{next(ACCOUNT_IDS) % 16 + 1}"
        self.csrf = None

    def _local_path(self, location):
        if not location:
            raise AssertionError("Expected a dynamic Location or URL")

        base = self.host
        if "://" not in base:
            base = "http://" + base
        resolved = urljoin(base.rstrip("/") + "/", location)
        base_parts = urlsplit(base)
        target_parts = urlsplit(resolved)

        if (
            target_parts.scheme.lower() != base_parts.scheme.lower()
            or target_parts.netloc.lower() != base_parts.netloc.lower()
        ):
            raise AssertionError("Refusing to request a URL outside BASE_URL")

        return target_parts.path or "/" + (
            ("?" + target_parts.query) if target_parts.query else ""
        )

    def _send(
        self,
        method,
        path,
        *,
        payload=None,
        headers=None,
        expected_statuses=(200,),
        validator=None,
        allow_auth_error=False,
        name=None,
    ):
        kwargs = {
            "headers": dict(headers or {}),
            "allow_redirects": False,
            "catch_response": True,
            "name": name,
        }
        if payload is not None:
            kwargs["json"] = payload

        expected_statuses = set(expected_statuses)
        with self.client.request(method, path, **kwargs) as response:
            status = response.status_code
            error = _json_dict(response).get("error")

            if (
                status == 401
                and allow_auth_error
                and error in {"expired", "session"}
            ):
                response.success()
            elif status not in expected_statuses:
                response.failure(
                    f"Unexpected HTTP status {status}; "
                    f"expected {sorted(expected_statuses)}"
                )
            elif validator is not None:
                try:
                    valid = bool(validator(response))
                except Exception:
                    valid = False
                if not valid:
                    response.failure("Response assertion failed")
                else:
                    response.success()
            else:
                response.success()

        return response

    def _absorb_csrf(self, response):
        token = _json_dict(response).get("csrf")
        if isinstance(token, str) and token:
            self.csrf = token

    def _csrf_from_html(self, response):
        parser = _InputParser()
        parser.feed(response.text)
        for name, value in parser.inputs:
            if name == "csrf" and value:
                return value
        return None

    def _login(self):
        self.csrf = None
        form = self._send(
            "GET",
            "/v2/login-form",
            expected_statuses={200},
            validator=lambda r: self._csrf_from_html(r) is not None,
        )
        form_csrf = self._csrf_from_html(form)
        if not form_csrf:
            raise AssertionError("Login form did not contain input[name=csrf]")

        login = self._send(
            "POST",
            "/v2/login",
            payload={
                "username": self.username,
                "password": "bench",
                "csrf": form_csrf,
            },
            expected_statuses={200, 302},
            validator=lambda r: (
                bool(r.headers.get("Location"))
                if r.status_code == 302
                else bool(_json_dict(r).get("csrf"))
            ),
        )

        if login.status_code == 302:
            landing = self._send(
                "GET",
                self._local_path(login.headers.get("Location")),
                expected_statuses={200},
                validator=lambda r: bool(_json_dict(r).get("csrf")),
            )
            token = _json_dict(landing).get("csrf")
        else:
            token = _json_dict(login).get("csrf")

        if not isinstance(token, str) or not token:
            raise AssertionError("Login did not return a CSRF token")
        self.csrf = token

    def _authenticated_request(
        self,
        method,
        path,
        *,
        payload=None,
        headers=None,
        expected_statuses=(200,),
        validator=None,
        cart_id=None,
        name=None,
    ):
        method = method.upper()
        request_headers = dict(headers or {})
        if method != "GET":
            if not self.csrf:
                raise AssertionError("Missing CSRF token")
            request_headers["X-CSRF-Token"] = self.csrf

        response = self._send(
            method,
            path,
            payload=payload,
            headers=request_headers,
            expected_statuses=expected_statuses,
            validator=validator,
            allow_auth_error=True,
            name=name,
        )

        if response.status_code != 401:
            self._absorb_csrf(response)
            return response

        error = _json_dict(response).get("error")
        if error not in {"expired", "session"}:
            raise AssertionError(f"Authentication denied: {error!r}")

        self._recover_auth(error, cart_id)

        retry_headers = dict(headers or {})
        if method != "GET":
            retry_headers["X-CSRF-Token"] = self.csrf

        response = self._send(
            method,
            path,
            payload=payload,
            headers=retry_headers,
            expected_statuses=expected_statuses,
            validator=validator,
            name=name,
        )
