        if response.status_code == 401:
            raise AssertionError("Operation remained unauthorized after recovery")
        return response

    def _recovery_post(self, path, payload, expected_statuses=(200,)):
        if not self.csrf:
            raise AssertionError("Missing CSRF token during recovery")
