        return response

    def _recover_auth(self, original_error, cart_id):
        renew = self._send(
            "POST",
            "/v2/session/renew",
            payload={},
            headers={"X-CSRF-Token": self.csrf or ""},
            expected_statuses={200},
            allow_auth_error=True,
        )

        renew_error = _json_dict(renew).get("error")
        if renew.status_code == 401 and renew_error not in {"expired", "session"}:
            raise AssertionError(f"Session renewal denied: {renew_error!r}")
        if renew.status_code not in {200, 401}:
            raise AssertionError("Session renewal failed unexpectedly")

        if renew.status_code == 200:
            self._absorb_csrf(renew)
            if original_error == "expired" and not self.csrf:
                raise AssertionError("Session renewal did not return a CSRF token")

        if original_error == "session":
            self._login()

        if cart_id is not None:
            self._recovery_post(
                f"/v2/carts/{quote(str(cart_id), safe='')}/recover",
                {},
                expected_statuses={200, 204},
            )

    def _catalog_products(self, payload):
        data = payload.get("data", payload)
        products = []
        if isinstance(data, dict):
            listed = data.get("products")
            if isinstance(listed, list):
                products.extend(listed)
            product = data.get("product")
            if isinstance(product, dict):
                products.append(product)
            if not products and "id" in data and "variants" in data:
                products.append(data)
        elif isinstance(data, list):
            products.extend(data)

        next_url = payload.get("next")
        if next_url is None and isinstance(data, dict):
            next_url = data.get("next")
        return products, next_url

    def _choose_product_variant(self):
        response = self._send(
            "GET",
            "/v2/catalog",
            expected_statuses={200},
            validator=lambda r: isinstance(_json_dict(r), dict),
        )
        payload = _json_dict(response)
        products, next_url = self._catalog_products(payload)

        page_count = 0
        while next_url is not None and page_count < 3:
            page = self._send(
                "GET",
                self._local_path(next_url),
                expected_statuses={200},
                validator=lambda r: isinstance(_json_dict(r), dict),
            )
            page_products, next_url = self._catalog_products(_json_dict(page))
            products.extend(page_products)
            page_count += 1

        for product in products:
            if not isinstance(product, dict):
                continue
            product_id = product.get("id")
            variants = product.get("variants", [])
            if product_id is None or not isinstance(variants, list):
                continue
            for variant in variants:
                if (
                    isinstance(variant, dict)
                    and variant.get("id") is not None
                    and variant.get("in_stock") is True
                ):
                    return product_id, variant["id"]

        raise AssertionError("No in-stock catalog variant was found")

    def _challenge_grant(self):
        form = self._authenticated_request(
            "GET",
            "/v2/challenge-form",
            expected_statuses={200},
            validator=lambda r: bool(
                self._challenge_details(r)[0]
                and self._challenge_details(r)[1]
            ),
        )
        action, challenge = self._challenge_details(form)
        if not action or not challenge:
            raise AssertionError("Challenge form is missing its action or value")

        posted = self._authenticated_request(
            "POST",
            self._local_path(action),
            payload={"challenge": challenge},
            expected_statuses={302},
            validator=lambda r: bool(r.headers.get("Location")),
        )
        self._absorb_csrf(posted)

        grant_response = self._send(
            "GET",
            self._local_path(posted.headers.get("Location")),
            expected_statuses={200},
            validator=lambda r: bool(_value(_json_dict(r), "grant_id")),
        )
        grant_data = _json_dict(grant_response)
        self._absorb_csrf(grant_response)
        grant_id = _value(grant_data, "grant_id")
        if not grant_id:
            raise AssertionError("Challenge redirect did not return grant_id")
        return grant_id

    def _challenge_details(self, response):
        parser = _InputParser()
        parser.feed(response.text)
        for action, challenge in parser.challenge_fields:
            if action and challenge:
                return action, challenge
        return None, None

    def _get_cart_etag(self, cart_id):
        response = self._authenticated_request(
            "GET",
            f"/v2/carts/{quote(str(cart_id), safe='')}",
            expected_statuses={200},
            validator=lambda r: bool(r.headers.get("ETag")),
            cart_id=cart_id,
        )
        self._absorb_csrf(response)
        etag = response.headers.get("ETag")
        if not etag:
            raise AssertionError("Cart response did not contain an ETag")
        return etag

    def _run_work(self, cart_id):
        for attempt in range(5):
            def valid_work(response):
                if response.status_code == 200:
                    return _json_dict(response).get("ok") is True
                if response.status_code == 429:
                    retry_after = response.headers.get("Retry-After")
                    try:
                        valid_delay = float(retry_after) == 1.0
                    except (TypeError, ValueError):
                        valid_delay = False
                    return valid_delay and attempt < 4
                return False

            response = self._authenticated_request(
                "POST",
                "/v2/work",
                payload={},
                expected_statuses={200, 429},
                validator=valid_work,
                cart_id=cart_id,
                name="/v2/work",
            )
            if response.status_code == 200:
                return
            if response.status_code == 429:
                if attempt == 4:
                    raise AssertionError("Work endpoint exhausted its retry limit")
                self.wait(1)

        raise AssertionError("Work endpoint did not succeed")

    def _journey(self):
        self._login()

        product_id, variant_id = self._choose_product_variant()
        grant_id = self._challenge_grant()

        cart_response = self._authenticated_request(
            "POST",
            "/v2/carts",
            payload={
                "product_id": product_id,
                "variant_id": variant_id,
                "grant_id": grant_id,
            },
            expected_statuses={201},
            validator=lambda r: bool(_value(_json_dict(r), "id")),
        )
        cart_data = _json_dict(cart_response)
        cart_id = _value(cart_data, "id")
        if cart_id is None:
            raise AssertionError("Cart creation did not return an id")
        self._absorb_csrf(cart_response)

        etag = cart_response.headers.get("ETag")
        if not etag:
            etag = self._get_cart_etag(cart_id)

        quantity_payload = {"quantity": 2}

        def valid_patch(response):
            if response.status_code == 412:
                return True
            return response.status_code in {200, 204}

        first_patch = self._authenticated_request(
            "PATCH",
            f"/v2/carts/{quote(str(cart_id), safe='')}",
            payload=quantity_payload,
            headers={"If-Match": etag},
            expected_statuses={200, 204, 412},
            validator=valid_patch,
            cart_id=cart_id,
        )

        if first_patch.status_code != 412:
            raise AssertionError("Expected the scheduled stale-cart conflict")

        etag = self._get_cart_etag(cart_id)
        retry_patch = self._authenticated_request(
            "PATCH",
            f"/v2/carts/{quote(str(cart_id), safe='')}",
            payload=quantity_payload,
            headers={"If-Match": etag},
            expected_statuses={200, 204},
            validator=valid_patch,
            cart_id=cart_id,
        )
        self._absorb_csrf(retry_patch)

        etag = retry_patch.headers.get("ETag") or self._get_cart_etag(cart_id)

        self._run_work(cart_id)

        order_key = f"bench-order-{cart_id}"
        order_response = self._authenticated_request(
            "POST",
            "/v2/orders",
            payload={"cart_id": cart_id},
            headers={
                "If-Match": etag,
                "Idempotency-Key": order_key,
            },
            expected_statuses={201},
            validator=lambda r: (
                _value(_json_dict(r), "accepted") is True
                and _value(_json_dict(r), "id") is not None
            ),
            cart_id=cart_id,
        )
        if _value(_json_dict(order_response), "accepted") is not True:
            raise AssertionError("Order was not accepted")
        self._absorb_csrf(order_response)

    @task
    def run_journeys(self):
        for _ in range(2):
            self._journey()
        raise StopUser()


class FixedJourneyShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self._observed_users = False

    def tick(self):
        current_users = self.get_current_user_count()
        if current_users:
            self._observed_users = True
        elif self._observed_users:
            return None

        if self.get_run_time() > 300:
            return None
        return 2, 2
