import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.Supplier;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
  private static final String ERROR_RE = "\"error\"\\s*:\\s*\"([^\"]+)\"";
  private static final String CSRF_RE = "\"csrf\"\\s*:\\s*\"([^\"]+)\"";

  private final HttpProtocolBuilder httpProtocol;
  private final ScenarioBuilder journeyScenario;

  public ModelSimulation() {
    String configuredBaseUrl = System.getenv("BASE_URL");
    String baseUrl = configuredBaseUrl == null || configuredBaseUrl.isBlank()
        ? "http://127.0.0.1:8000"
        : configuredBaseUrl;

    httpProtocol = http.baseUrl(baseUrl)
        .acceptHeader("*/*")
        .contentTypeHeader("application/json")
        .disableFollowRedirect();

    journeyScenario = scenario("Cart checkout with bounded session recovery")
        .exec(session -> {
          long account = Math.floorMod(session.userId(), 16L) + 1L;
          return session
              .set("username", "bench-" + account)
              .set("journeyNumber", 0);
        })
        .repeat(2).on(journey());

    setUp(journeyScenario.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
  }

  private ChainBuilder journey() {
    return exec(this::resetJourney)
        .exec(login())
        .exec(catalog())
        .exec(this::chooseProduct)
        .doIf(session -> hasText(session, "productId") && hasText(session, "variantId"))
        .then(challengeAndCreateCart())
        .doIf(session -> hasText(session, "cartId"))
        .then(workloadAndCheckout())
        .doIf(session -> !hasText(session, "cartId"))
        .then(exec(this::fail));
  }

  private Session resetJourney(Session session) {
    return session
        .set("journeyNumber", session.getInt("journeyNumber") + 1)
        .set("csrf", "")
        .set("reauthOk", false)
        .set("loginFormCsrf", "")
        .set("loginResponseCsrf", "")
        .set("loginLocation", "")
        .set("loginStatus", 0)
        .set("cartId", "")
        .set("cartEtagCandidate", "")
        .set("cartEtag", "")
        .set("etagCandidate", "")
        .set("grantId", "")
        .set("grantCsrf", "")
        .set("challengeAction", "")
        .set("challengeValue", "")
        .set("challengeLocation", "")
        .set("productId", "")
        .set("variantId", "")
        .set("statusUrl", "")
        .set("reservationState", "pending")
        .set("reservationId", "")
        .set("cartPrepared", false)
        .set("reservationQueued", false)
        .set("workStatus", 0)
        .set("workRetries", 0)
        .set("workRetryAfter", "")
        .set("workOk", "")
        .set("challengeRecoveryUsed", false)
        .set("cartCreateRecoveryUsed", false)
        .set("cartReadRecoveryUsed", false)
        .set("patchRecoveryUsed", false)
        .set("reservationRecoveryUsed", false)
        .set("orderRecoveryUsed", false)
        .set("workRecoveryUsed", false)
        .set("pollRecovery1", false)
        .set("pollRecovery2", false)
        .set("pollRecovery3", false)
        .set("pollRecovery4", false)
        .set("pollRecovery5", false);
  }

  private ChainBuilder login() {
    return exec(session -> session
            .set("loginFormCsrf", "")
            .set("loginResponseCsrf", "")
            .set("loginLocation", "")
            .set("loginStatus", 0)
            .set("reauthOk", false))
        .exec(http("login form")
            .get("/v2/login-form")
            .check(
                status().is(200),
                css("form input[name='csrf']", "value").saveAs("loginFormCsrf")))
        .exec(http("login")
            .post("/v2/login")
            .body(StringBody(session ->
                "{\"username\":" + jsonLiteral(session.get("username"))
                    + ",\"password\":\"bench\",\"csrf\":"
                    + jsonLiteral(session.get("loginFormCsrf")) + "}"))
            .check(
                status().in(200, 302).saveAs("loginStatus"),
                header("Location").optional().saveAs("loginLocation"),
                regex(CSRF_RE).optional().saveAs("loginResponseCsrf")))
        .exec(this::applyLoginResponse)
        .doIf(session -> session.getInt("loginStatus") == 302
            && !hasText(session, "loginLocation"))
        .then(exec(this::fail))
        .doIf(session -> session.getInt("loginStatus") == 302
            && hasText(session, "loginLocation"))
        .then(exec(http("login redirect")
            .get("#{loginLocation}")
            .check(
                status().is(200),
                regex(CSRF_RE).saveAs("csrf")))
            .exec(session -> {
              if (hasText(session, "csrf")) {
                return session.set("reauthOk", true);
              }
              return fail(session);
            }));
  }

  private Session applyLoginResponse(Session session) {
    if (session.getInt("loginStatus") == 200) {
      String token = text(session.get("loginResponseCsrf"));
      if (!token.isEmpty()) {
        return session.set("csrf", token).set("reauthOk", true);
      }
      return fail(session);
    }
    return session;
  }

  private ChainBuilder catalog() {
    return exec(session -> session
            .set("productsAccum", new ArrayList<>())
            .set("pageProducts", new ArrayList<>())
            .set("pagesSeen", 0)
            .set("nextCandidate", "")
            .set("nextUrl", ""))
        .exec(http("catalog")
            .get("/v2/catalog")
            .check(
                status().is(200),
                jsonPath("$.data.products").ofList().saveAs("pageProducts"),
                jsonPath("$.next").optional().saveAs("nextCandidate")))
        .exec(this::accumulateCatalogPage)
        .exec(catalogPageIfAvailable())
        .exec(catalogPageIfAvailable());
  }

  private ChainBuilder catalogPageIfAvailable() {
    return doIf(session -> session.getInt("pagesSeen") < 3
        && hasText(session, "nextUrl"))
        .then(exec(session -> session.set("nextCandidate", ""))
            .exec(http("catalog page")
                .get("#{nextUrl}")
                .check(
                    status().is(200),
                    jsonPath("$.data.products").ofList().saveAs("pageProducts"),
                    jsonPath("$.next").optional().saveAs("nextCandidate")))
            .exec(this::accumulateCatalogPage));
  }

  private Session accumulateCatalogPage(Session session) {
    List<Object> products = new ArrayList<>();
    Object accumulated = session.get("productsAccum");
    if (accumulated instanceof List<?>) {
      products.addAll((List<?>) accumulated);
    }
    Object currentPage = session.get("pageProducts");
    if (currentPage instanceof List<?>) {
      products.addAll((List<?>) currentPage);
    }

    String next = text(session.get("nextCandidate"));
    return session
        .set("productsAccum", products)
        .set("nextUrl", next)
        .set("pagesSeen", session.getInt("pagesSeen") + 1);
  }

  private Session chooseProduct(Session session) {
    Object accumulated = session.get("productsAccum");
    if (accumulated instanceof List<?>) {
      for (Object productObject : (List<?>) accumulated) {
        if (!(productObject instanceof Map<?, ?>)) {
          continue;
        }
        Map<?, ?> product = (Map<?, ?>) productObject;
        Object productId = product.get("id");
        Object variantsObject = product.get("variants");
        if (productId == null || !(variantsObject instanceof List<?>)) {
          continue;
        }

        for (Object variantObject : (List<?>) variantsObject) {
          if (!(variantObject instanceof Map<?, ?>)) {
            continue;
          }
          Map<?, ?> variant = (Map<?, ?>) variantObject;
          Object inStock = variant.get("in_stock");
          Object variantId = variant.get("id");
          if (variantId != null && isTrue(inStock)) {
            return session.set("productId", productId).set("variantId", variantId);
          }
        }
      }
    }
    return fail(session.set("productId", "").set("variantId", ""));
  }

  private ChainBuilder challengeAndCreateCart() {
    return exec(session -> session
            .set("challengeAction", "")
            .set("challengeValue", "")
            .set("challengeLocation", "")
            .set("grantId", "")
            .set("grantCsrf", "")
            .set("cartEtagCandidate", ""))
        .exec(http("challenge form")
            .get("/v2/challenge-form")
            .check(
                status().is(200),
                css("form[action^='/v2/challenges/']", "action").saveAs("challengeAction"),
                css("form input[name='challenge']", "value").saveAs("challengeValue")))
        .exec(guarded("challengeRecoveryUsed", this::challengeSubmitRequest, 302, 401))
        .doIf(session -> session.getInt("opStatus") == 302
            && hasText(session, "challengeLocation"))
        .then(exec(http("challenge redirect")
            .get("#{challengeLocation}")
            .check(
                status().is(200),
                jsonPath("$.grant_id").saveAs("grantId"),
                regex(CSRF_RE).saveAs("grantCsrf")))
            .exec(this::applyGrantCsrf)
            .doIf(session -> hasText(session, "grantId") && hasText(session, "csrf"))
            .then(exec(guarded("cartCreateRecoveryUsed", this::createCartRequest, 201, 401))
                .exec(this::applyCartEtag)
                .exec(session -> session.set("grantId", ""))));
  }

  private Supplier<HttpRequestActionBuilder> challengeSubmitRequest() {
    return () -> http("submit challenge")
        .post("#{challengeAction}")
        .header("X-CSRF-Token", "#{csrf}")
        .body(StringBody(session ->
            "{\"challenge\":" + jsonLiteral(session.get("challengeValue")) + "}"))
        .check(header("Location").optional().saveAs("challengeLocation"));
  }

  private Supplier<HttpRequestActionBuilder> createCartRequest() {
    return () -> http("create cart")
        .post("/v2/carts")
        .header("X-CSRF-Token", "#{csrf}")
        .body(StringBody(session -> {
          String body = "{\"product_id\":" + jsonLiteral(session.get("productId"))
              + ",\"variant_id\":" + jsonLiteral(session.get("variantId"));
          if (hasText(session, "grantId")) {
            body += ",\"grant_id\":" + jsonLiteral(session.get("grantId"));
          }
          return body + "}";
        }))
        .check(
            jsonPath("$.id").optional().saveAs("cartId"),
            header("ETag").optional().saveAs("cartEtagCandidate"));
  }

  private Session applyGrantCsrf(Session session) {
    String token = text(session.get("grantCsrf"));
    if (!token.isEmpty()) {
      return session.set("csrf", token);
    }
    return fail(session);
  }

  private Session applyCartEtag(Session session) {
    String etag = text(session.get("cartEtagCandidate"));
    return etag.isEmpty() ? session : session.set("cartEtag", etag);
  }

  private ChainBuilder workloadAndCheckout() {
    return exec(workAttempt())
        .exec(workRetryIfNeeded())
        .exec(workRetryIfNeeded())
        .exec(workRetryIfNeeded())
        .exec(workRetryIfNeeded())
        .exec(session -> {
          if (session.getInt("workStatus") == 429) {
            return fail(session);
          }
          return session;
        })
        .exec(cartReadAndPatch())
        .doIf(session -> Boolean.TRUE.equals(session.get("cartPrepared")))
        .then(reservePollAndOrder());
  }

  private ChainBuilder workAttempt() {
    return exec(session -> session
            .set("workRetryAfter", "")
            .set("workOk", ""))
        .exec(guarded("workRecoveryUsed", this::workRequest, 200, 429, 401))
        .exec(session -> {
          int code = session.getInt("workStatus");
          String retryAfter = text(session.get("workRetryAfter"));
          String ok = text(session.get("workOk"));
          if (code == 429 && !"1".equals(retryAfter)) {
            return fail(session);
          }
          if (code == 200 && !"true".equalsIgnoreCase(ok)) {
            return fail(session);
          }
          return session;
        });
  }

  private Supplier<HttpRequestActionBuilder> workRequest() {
    return () -> http("work")
        .post("/v2/work")
        .header("X-CSRF-Token", "#{csrf}")
        .body(StringBody("{}"))
        .check(
            status().in(200, 429, 401).saveAs("workStatus"),
            jsonPath("$.ok").optional().saveAs("workOk"),
            jsonPath("$.ok").optional().is("true"),
            header("Retry-After").optional().saveAs("workRetryAfter"),
            header("Retry-After").optional().is("1"));
  }

  private ChainBuilder workRetryIfNeeded() {
    return doIf(session -> session.getInt("workStatus") == 429
        && session.getInt("workRetries") < 4)
        .then(exec(pause(Duration.ofSeconds(1)))
            .exec(session -> session.set("workRetries", session.getInt("workRetries") + 1))
            .exec(workAttempt()));
  }

  private ChainBuilder cartReadAndPatch() {
    return exec(session -> session.set("etagCandidate", ""))
        .exec(guarded("cartReadRecoveryUsed", this::readCartRequest, 200, 401))
        .exec(this::applyReadEtag)
        .doIf(session -> hasText(session, "cartEtag"))
        .then(patchCart())
        .doIf(session -> !hasText(session, "cartEtag"))
        .then(exec(this::fail));
  }

  private Supplier<HttpRequestActionBuilder> readCartRequest() {
    return () -> http("read cart")
        .get("/v2/carts/#{cartId}")
        .check(header("ETag").optional().saveAs("etagCandidate"));
  }

  private Session applyReadEtag(Session session) {
    String etag = text(session.get("etagCandidate"));
    if (!etag.isEmpty()) {
      return session.set("cartEtag", etag);
    }
    return session;
  }

  private ChainBuilder patchCart() {
    return exec(guarded("patchRecoveryUsed", this::patchCartRequest, 200, 401, 412))
        .doIf(session -> session.getInt("patchStatus") == 412)
        .then(exec(session -> session.set("etagCandidate", ""))
            .exec(guarded("cartReadRecoveryUsed", this::readCartRequest, 200, 401))
            .exec(this::applyReadEtag)
            .exec(guarded("patchRecoveryUsed", this::patchCartRequest, 200, 401, 412))
            .doIf(session -> session.getInt("patchStatus") == 412)
            .then(exec(this::fail)))
        .exec(session -> session.set("cartPrepared", session.getInt("patchStatus") == 200));
  }

  private Supplier<HttpRequestActionBuilder> patchCartRequest() {
    return () -> http("patch cart quantity")
        .patch("/v2/carts/#{cartId}")
        .header("X-CSRF-Token", "#{csrf}")
        .header("If-Match", "#{cartEtag}")
        .body(StringBody("{\"quantity\":2}"))
        .check(status().in(200, 401, 412).saveAs("patchStatus"));
  }

  private ChainBuilder reservePollAndOrder() {
    return exec(session -> session
            .set("statusUrl", "")
            .set("reservationState", "pending")
            .set("reservationId", ""))
        .exec(guarded("reservationRecoveryUsed", this::reserveRequest, 202, 401))
        .exec(session -> session.set("reservationQueued", session.getInt("opStatus") == 202))
        .doIf(session -> Boolean.TRUE.equals(session.get("reservationQueued")))
        .then(exec(pollAttempt(1))
            .exec(pollAttempt(2))
            .exec(pollAttempt(3))
            .exec(pollAttempt(4))
            .exec(pollAttempt(5))
            .exec(session -> {
              if ("ready".equalsIgnoreCase(text(session.get("reservationState")))
                  && hasText(session, "reservationId")) {
                return session;
              }
              return fail(session);
            })
            .doIf(session -> "ready".equalsIgnoreCase(text(session.get("reservationState")))
                && hasText(session, "reservationId"))
            .then(exec(guarded("orderRecoveryUsed", this::placeOrderRequest, 201, 401))))
        .doIf(session -> !Boolean.TRUE.equals(session.get("reservationQueued")))
        .then(exec(this::fail));
  }

  private Supplier<HttpRequestActionBuilder> reserveRequest() {
    return () -> http("create reservation")
        .post("/v2/reservations")
        .header("X-CSRF-Token", "#{csrf}")
        .body(StringBody(session ->
            "{\"cart_id\":" + jsonLiteral(session.get("cartId")) + "}"))
        .check(jsonPath("$.status_url").optional().saveAs("statusUrl"));
  }

  private ChainBuilder pollAttempt(int number) {
    return doIf(session -> !"ready".equalsIgnoreCase(text(session.get("reservationState"))))
        .then(exec(pause(Duration.ofMillis(50)))
            .exec(session -> session
                .set("reservationState", "pending")
                .set("reservationId", ""))
            .exec(guarded("pollRecovery" + number, this::pollReservationRequest, 200, 401)));
  }

  private Supplier<HttpRequestActionBuilder> pollReservationRequest() {
    return () -> http("poll reservation")
        .get("#{statusUrl}")
        .check(
            jsonPath("$.status").optional().saveAs("reservationState"),
            jsonPath("$.reservation_id").optional().saveAs("reservationId"));
  }

  private Supplier<HttpRequestActionBuilder> placeOrderRequest() {
    return () -> http("place order")
        .post("/v2/orders")
        .header("X-CSRF-Token", "#{csrf}")
        .header("Idempotency-Key", "bench-order-#{cartId}")
        .header("If-Match", "#{cartEtag}")
        .body(StringBody(session ->
            "{\"cart_id\":" + jsonLiteral(session.get("cartId"))
                + ",\"reservation_id\":" + jsonLiteral(session.get("reservationId")) + "}"))
        .check(
            jsonPath("$.accepted").optional().is("true"),
            jsonPath("$.id").optional().saveAs("orderId"));
  }

  private ChainBuilder guarded(
      String recoveryFlag,
      Supplier<HttpRequestActionBuilder> request,
      int... allowedStatuses) {

    Supplier<HttpRequestActionBuilder> checkedRequest = () -> request.get().check(
        status().in(allowedStatuses).saveAs("opStatus"),
        regex(ERROR_RE).optional().in("expired", "session"),
        regex(ERROR_RE).optional().saveAs("opError"),
        regex(CSRF_RE).optional().saveAs("opCsrf"));

    ChainBuilder retry = exec(session -> session
            .set("opStatus", 0)
            .set("opError", "")
            .set("opCsrf", ""))
        .exec(checkedRequest.get())
        .exec(this::applyOperationCsrf)
        .doIf(session -> session.getInt("opStatus") == 401)
        .then(exec(this::fail));

    return exec(session -> session
            .set("opStatus", 0)
            .set("opError", "")
            .set("opCsrf", ""))
        .exec(checkedRequest.get())
        .exec(this::applyOperationCsrf)
        .doIf(session -> session.getInt("opStatus") == 401)
        .then(
            doIf(session -> isRecoverable(session, recoveryFlag))
                .then(exec(session -> session.set(recoveryFlag, true))
                    .exec(recoverSession())
                    .exec(retry))
                .doIf(session -> !isRecoverable(session, recoveryFlag))
                .then(exec(this::fail)));
  }

  private boolean isRecoverable(Session session, String recoveryFlag) {
    String error = text(session.get("opError"));
    return session.getInt("opStatus") == 401
        && ("expired".equals(error) || "session".equals(error))
        && !Boolean.TRUE.equals(session.get(recoveryFlag));
  }

  private Session applyOperationCsrf(Session session) {
    String token = text(session.get("opCsrf"));
    return token.isEmpty() ? session : session.set("csrf", token);
  }

  private ChainBuilder recoverSession() {
    return exec(session -> session
            .set("renewStatus", 0)
            .set("renewError", "")
            .set("renewCsrf", "")
            .set("reauthOk", false))
        .exec(http("renew session")
            .post("/v2/session/renew")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(
                status().in(200, 401).saveAs("renewStatus"),
                regex(ERROR_RE).optional().in("expired", "session"),
                regex(ERROR_RE).optional().saveAs("renewError"),
                regex(CSRF_RE).optional().saveAs("renewCsrf")))
        .exec(this::applyRenewResponse)
        .doIf(session -> session.getInt("renewStatus") == 401
            && ("expired".equals(text(session.get("renewError")))
                || "session".equals(text(session.get("renewError")))))
        .then(login())
        .doIf(session -> session.getInt("renewStatus") == 401
            && !"expired".equals(text(session.get("renewError")))
            && !"session".equals(text(session.get("renewError"))))
        .then(exec(this::fail))
        .doIf(session -> Boolean.TRUE.equals(session.get("reauthOk"))
            && hasText(session, "cartId"))
        .then(recoverCart());
  }

  private Session applyRenewResponse(Session session) {
    if (session.getInt("renewStatus") == 200) {
      String token = text(session.get("renewCsrf"));
      if (!token.isEmpty()) {
        return session.set("csrf", token).set("reauthOk", true);
      }
      return fail(session);
    }
    return session;
  }

  private ChainBuilder recoverCart() {
    return exec(session -> session.set("recoverCsrf", ""))
        .exec(http("recover cart")
            .post("/v2/carts/#{cartId}/recover")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(
                status().is(200),
                regex(CSRF_RE).saveAs("recoverCsrf")))
        .exec(session -> {
          String token = text(session.get("recoverCsrf"));
          if (!token.isEmpty()) {
            return session.set("csrf", token);
          }
          return fail(session);
        });
  }

  private Session fail(Session session) {
    return session.markAsFailed();
  }

  private static boolean hasText(Session session, String key) {
    return !text(session.get(key)).isEmpty();
  }

  private static String text(Object value) {
    return value == null ? "" : String.valueOf(value);
  }

  private static boolean isTrue(Object value) {
    return Boolean.TRUE.equals(value) || "true".equalsIgnoreCase(text(value));
  }

  private static String jsonLiteral(Object value) {
    if (value == null) {
      return "null";
    }
    if (value instanceof Number || value instanceof Boolean) {
      return String.valueOf(value);
    }

    String input = String.valueOf(value);
    StringBuilder output = new StringBuilder("\"");
    for (int i = 0; i < input.length(); i++) {
      char c = input.charAt(i);
      switch (c) {
        case '"':
          output.append("\\\"");
          break;
        case '\\':
          output.append("\\\\");
          break;
        case '\b':
          output.append("\\b");
          break;
        case '\f':
          output.append("\\f");
          break;
        case '\n':
          output.append("\\n");
          break;
        case '\r':
          output.append("\\r");
          break;
        case '\t':
          output.append("\\t");
          break;
        default:
          if (c < 0x20) {
            output.append(String.format("\\u%04x", (int) c));
          } else {
            output.append(c);
          }
      }
    }
    return output.append('"').toString();
  }
}

