import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
  private static final String ERROR_RE = "\"error\"\\s*:\\s*\"([^\"]+)\"";
  private static final String CSRF_RE = "\"csrf\"\\s*:\\s*\"([^\"]+)\"";

  @FunctionalInterface
  private interface RequestFactory {
    HttpRequestActionBuilder build();
  }

  public ModelSimulation() {
    String configuredBaseUrl = System.getenv("BASE_URL");
    String baseUrl = configuredBaseUrl == null || configuredBaseUrl.isBlank()
        ? "http://127.0.0.1:8000"
        : configuredBaseUrl;

    HttpProtocolBuilder httpProtocol = http.baseUrl(baseUrl)
        .acceptHeader("*/*")
        .contentTypeHeader("application/json")
        .disableFollowRedirect();

    ScenarioBuilder journey = scenario("Recover cart checkout after session expiry")
        .exec(session -> {
          long account = Math.floorMod(session.userId(), 16L) + 1L;
          return session
              .set("username", "bench-" + account)
              .set("journeyNumber", 0);
        })
        .repeat(2).on(journey());

    setUp(journey.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
  }

  private ChainBuilder journey() {
    return exec(this::resetJourney)
        .exec(login())
        .exec(catalog())
        .exec(this::chooseProduct)
        .doIf(session -> hasText(session, "productId")
            && hasText(session, "variantId"))
        .then(challengeAndCreateCart())
        .doIf(session -> hasText(session, "cartId"))
        .then(workloadAndCheckout())
        .doIf(session -> !hasText(session, "cartId"))
        .then(exec(this::fail));
  }

  private Session resetJourney(Session session) {
    return session
        .set("journeyNumber", session.getInt("journeyNumber") + 1)
        .set("csrf", "")
        .set("reauthOk", false)
        .set("loginFormCsrf", "")
        .set("loginResponseCsrf", "")
        .set("loginLocation", "")
        .set("loginStatus", 0)
        .set("cartId", "")
        .set("cartEtagCandidate", "")
        .set("cartEtag", "")
        .set("etagCandidate", "")
        .set("grantId", "")
        .set("grantCsrf", "")
        .set("challengeAction", "")
        .set("challengeValue", "")
        .set("challengeLocation", "")
        .set("productId", "")
        .set("variantId", "")
        .set("statusUrl", "")
        .set("reservationState", "pending")
        .set("reservationId", "")
        .set("cartPrepared", false)
        .set("reservationQueued", false)
        .set("workStatus", 0)
        .set("workRetries", 0)
        .set("workRetryAfter", "")
        .set("workOk", "")
        .set("challengeRecoveryUsed", false)
        .set("cartCreateRecoveryUsed", false)
        .set("cartReadRecoveryUsed", false)
        .set("cartRereadRecoveryUsed", false)
        .set("patchRecoveryUsed", false)
        .set("reservationRecoveryUsed", false)
        .set("orderRecoveryUsed", false)
        .set("workRecoveryUsed", false)
        .set("pollRecovery1", false)
        .set("pollRecovery2", false)
        .set("pollRecovery3", false)
        .set("pollRecovery4", false)
        .set("pollRecovery5", false);
  }

  private ChainBuilder login() {
    return exec(session -> session
            .set("loginFormCsrf", "")
            .set("loginResponseCsrf", "")
            .set("loginLocation", "")
            .set("loginStatus", 0)
            .set("reauthOk", false))
        .exec(http("login form")
            .get("/v2/login-form")
            .check(
                status().is(200),
                css("form input[name='csrf']", "value").saveAs("loginFormCsrf")))
        .exec(http("login")
            .post("/v2/login")
            .body(StringBody(session ->
                "{\"username\":" + jsonLiteral(session.get("username"))
                    + ",\"password\":\"bench\",\"csrf\":"
                    + jsonLiteral(session.get("loginFormCsrf")) + "}"))
            .check(
                status().in(200, 302),
                status().saveAs("loginStatus"),
                header("Location").optional().saveAs("loginLocation"),
                regex(CSRF_RE).optional().saveAs("loginResponseCsrf")))
        .exec(this::applyLoginResponse)
        .doIf(session -> session.getInt("loginStatus") == 302
            && !hasText(session, "loginLocation"))
        .then(exec(this::fail))
        .doIf(session -> session.getInt("loginStatus") == 302
            && hasText(session, "loginLocation"))
        .then(exec(http("login redirect")
            .get("#{loginLocation}")
            .check(
                status().is(200),
                regex(CSRF_RE).saveAs("csrf")))
            .exec(session -> hasText(session, "csrf")
                ? session.set("reauthOk", true)
                : fail(session)));
  }

  private Session applyLoginResponse(Session session) {
    if (session.getInt("loginStatus") == 200) {
      String token = text(session.get("loginResponseCsrf"));
      return token.isEmpty()
          ? fail(session)
          : session.set("csrf", token).set("reauthOk", true);
    }
    return session;
  }

  private ChainBuilder catalog() {
    return exec(session -> session
            .set("productsAccum", new ArrayList<>())
            .set("pageProducts", new ArrayList<>())
            .set("pagesSeen", 0)
            .set("nextCandidate", "")
            .set("nextUrl", ""))
        .exec(http("catalog")
            .get("/v2/catalog")
            .check(
                status().is(200),
                jsonPath("$.data.products").ofList().saveAs("pageProducts"),
                jsonPath("$.next").optional().saveAs("nextCandidate")))
        .exec(this::accumulateCatalogPage)
        .exec(catalogPageIfAvailable())
        .exec(catalogPageIfAvailable());
  }

  private ChainBuilder catalogPageIfAvailable() {
    return doIf(session -> session.getInt("pagesSeen") < 3
        && hasText(session, "nextUrl"))
        .then(exec(session -> session.set("nextCandidate", ""))
            .exec(http("catalog page")
                .get("#{nextUrl}")
                .check(
                    status().is(200),
                    jsonPath("$.data.products").ofList().saveAs("pageProducts"),
                    jsonPath("$.next").optional().saveAs("nextCandidate")))
            .exec(this::accumulateCatalogPage));
  }

  private Session accumulateCatalogPage(Session session) {
    List<Object> products = new ArrayList<>();
    Object accumulated = session.get("productsAccum");
    if (accumulated instanceof List<?>) {
      products.addAll((List<?>) accumulated);
    }
    Object currentPage = session.get("pageProducts");
    if (currentPage instanceof List<?>) {
      products.addAll((List<?>) currentPage);
    }

    return session
        .set("productsAccum", products)
        .set("nextUrl", text(session.get("nextCandidate")))
        .set("pagesSeen", session.getInt("pagesSeen") + 1);
  }

  private Session chooseProduct(Session session) {
    Object accumulated = session.get("productsAccum");
    if (accumulated instanceof List<?>) {
      for (Object productObject : (List<?>) accumulated) {
        if (!(productObject instanceof Map<?, ?>)) {
          continue;
        }

        Map<?, ?> product = (Map<?, ?>) productObject;
        Object productId = product.get("id");
        Object variantsObject = product.get("variants");
        if (productId == null || !(variantsObject instanceof List<?>)) {
          continue;
        }

        for (Object variantObject : (List<?>) variantsObject) {
          if (!(variantObject instanceof Map<?, ?>)) {
            continue;
          }

          Map<?, ?> variant = (Map<?, ?>) variantObject;
          Object variantId = variant.get("id");
          if (variantId != null && isTrue(variant.get("in_stock"))) {
            return session.set("productId", productId).set("variantId", variantId);
          }
        }
      }
    }

    return fail(session.set("productId", "").set("variantId", ""));
  }

  private ChainBuilder challengeAndCreateCart() {
    return exec(session -> session
            .set("challengeAction", "")
            .set("challengeValue", "")
            .set("challengeLocation", "")
            .set("grantId", "")
            .set("grantCsrf", "")
            .set("cartEtagCandidate", ""))
        .exec(http("challenge form")
            .get("/v2/challenge-form")
            .check(
                status().is(200),
                css("form[action^='/v2/challenges/']", "action")
                    .saveAs("challengeAction"),
                css("form input[name='challenge']", "value")
                    .saveAs("challengeValue")))
        .exec(guarded("challengeRecoveryUsed", this::challengeSubmitRequest, 302, 401))
        .doIf(session -> session.getInt("opStatus") == 302
            && hasText(session, "challengeLocation"))
        .then(exec(http("challenge redirect")
            .get("#{challengeLocation}")
            .check(
                status().is(200),
                jsonPath("$.grant_id").saveAs("grantId"),
                regex(CSRF_RE).saveAs("grantCsrf")))
            .exec(this::applyGrantCsrf)
            .doIf(session -> hasText(session, "grantId") && hasText(session, "csrf"))
            .then(exec(guarded("cartCreateRecoveryUsed", this::createCartRequest, 201, 401))
                .exec(this::applyCartEtag)
                .exec(session -> session.set("grantId", ""))));
  }

  private HttpRequestActionBuilder challengeSubmitRequest() {
    return http("submit challenge")
        .post("#{challengeAction}")
        .header("X-CSRF-Token", "#{csrf}")
        .body(StringBody(session ->
            "{\"challenge\":" + jsonLiteral(session.get("challengeValue")) + "}"))
        .check(header("Location").optional().saveAs("challengeLocation"));
  }

  private HttpRequestActionBuilder createCartRequest() {
    return http("create cart")
        .post("/v2/carts")
        .header("X-CSRF-Token", "#{csrf}")
        .body(StringBody(session -> {
          String body = "{\"product_id\":" + jsonLiteral(session.get("productId"))
              + ",\"variant_id\":" + jsonLiteral(session.get("variantId"));
          if (hasText(session, "grantId")) {
            body += ",\"grant_id\":" + jsonLiteral(session.get("grantId"));
          }
          return body + "}";
        }))
        .check(
            jsonPath("$.id").optional().saveAs("cartId"),
            header("ETag").optional().saveAs("cartEtagCandidate"));
  }

  private Session applyGrantCsrf(Session session) {
    String token = text(session.get("grantCsrf"));
    return token.isEmpty() ? fail(session) : session.set("csrf", token);
  }

  private Session applyCartEtag(Session session) {
    String etag = text(session.get("cartEtagCandidate"));
    return etag.isEmpty() ? session : session.set("cartEtag", etag);
  }

  private ChainBuilder workloadAndCheckout() {
    return exec(workAttempt())
        .exec(workRetryIfNeeded())
        .exec(workRetryIfNeeded())
        .exec(workRetryIfNeeded())
        .exec(workRetryIfNeeded())
        .doIf(session -> session.getInt("workStatus") == 200
            && isTrue(session.get("workOk")))
        .then(exec(cartReadAndPatch())
            .doIf(session -> Boolean.TRUE.equals(session.get("cartPrepared")))
            .then(reservePollAndOrder()))
        .doIf(session -> session.getInt("workStatus") != 200
            || !isTrue(session.get("workOk")))
        .then(exec(this::fail));
  }

  private ChainBuilder workAttempt() {
    return exec(session -> session
            .set("workRetryAfter", "")
            .set("workOk", ""))
        .exec(guarded("workRecoveryUsed", this::workRequest, 200, 429, 401))
        .exec(session -> {
          int code = session.getInt("workStatus");
          if (code == 429 && !"1".equals(text(session.get("workRetryAfter")))) {
            return fail(session);
          }
          if (code == 200 && !isTrue(session.get("workOk"))) {
            return fail(session);
          }
          return session;
        });
  }

  private HttpRequestActionBuilder workRequest() {
    return http("work")
        .post("/v2/work")
        .header("X-CSRF-Token", "#{csrf}")
        .body(StringBody("{}"))
        .check(
            status().in(200, 429, 401),
            status().saveAs("workStatus"),
            jsonPath("$.ok").optional().saveAs("workOk"),
            header("Retry-After").optional().saveAs("workRetryAfter"));
  }

  private ChainBuilder workRetryIfNeeded() {
    return doIf(session -> session.getInt("workStatus") == 429
        && "1".equals(text(session.get("workRetryAfter")))
        && session.getInt("workRetries") < 4)
        .then(exec(pause(Duration.ofSeconds(1)))
            .exec(session -> session.set("workRetries", session.getInt("workRetries") + 1))
            .exec(workAttempt()));
  }

  private ChainBuilder cartReadAndPatch() {
    return exec(session -> session.set("etagCandidate", ""))
        .exec(guarded("cartReadRecoveryUsed", this::readCartRequest, 200, 401))
        .exec(this::applyReadEtag)
        .doIf(session -> hasText(session, "cartEtag"))
        .then(patchCart())
        .doIf(session -> !hasText(session, "cartEtag"))
        .then(exec(this::fail));
  }

  private HttpRequestActionBuilder readCartRequest() {
    return http("read cart")
        .get("/v2/carts/#{cartId}")
        .check(header("ETag").optional().saveAs("etagCandidate"));
  }

  private Session applyReadEtag(Session session) {
    String etag = text(session.get("etagCandidate"));
    return etag.isEmpty() ? session : session.set("cartEtag", etag);
  }

  private ChainBuilder patchCart() {
    return exec(guarded("patchRecoveryUsed", this::patchCartRequest, 200, 401, 412))
        .doIf(session -> session.getInt("opStatus") == 412)
        .then(exec(session -> session.set("etagCandidate", ""))
            .exec(guarded("cartRereadRecoveryUsed", this::readCartRequest, 200, 401))
            .exec(this::applyReadEtag)
            .exec(guarded("patchRecoveryUsed", this::patchCartRequest, 200, 401, 412))
            .doIf(session -> session.getInt("opStatus") == 412)
            .then(exec(this::fail)))
        .exec(session -> session.set("cartPrepared", session.getInt("opStatus") == 200));
  }

  private HttpRequestActionBuilder patchCartRequest() {
    return http("patch cart quantity")
        .patch("/v2/carts/#{cartId}")
        .header("X-CSRF-Token", "#{csrf}")
        .header("If-Match", "#{cartEtag}")
        .body(StringBody("{\"quantity\":2}"));
  }

  private ChainBuilder reservePollAndOrder() {
    return exec(session -> session
            .set("statusUrl", "")
            .set("reservationState", "pending")
            .set("reservationId", ""))
        .exec(guarded("reservationRecoveryUsed", this::reserveRequest, 202, 401))
        .exec(session -> {
          boolean queued = session.getInt("opStatus") == 202
              && hasText(session, "statusUrl");
          return session.set("reservationQueued", queued);
        })
        .doIf(session -> Boolean.TRUE.equals(session.get("reservationQueued")))
        .then(exec(pollAttempt(1))
            .exec(pollAttempt(2))
            .exec(pollAttempt(3))
            .exec(pollAttempt(4))
            .exec(pollAttempt(5))
            .exec(session -> {
              if ("ready".equalsIgnoreCase(text(session.get("reservationState")))
                  && hasText(session, "reservationId")) {
                return session;
              }
              return fail(session);
            })
            .doIf(session -> "ready".equalsIgnoreCase(text(session.get("reservationState")))
                && hasText(session, "reservationId"))
            .then(exec(guarded("orderRecoveryUsed", this::placeOrderRequest, 201, 401))
                .exec(session -> {
                  if (session.getInt("opStatus") == 201
                      && isTrue(session.get("accepted"))
                      && hasText(session, "orderId")) {
                    return session;
                  }
                  return fail(session);
                })))
        .doIf(session -> !Boolean.TRUE.equals(session.get("reservationQueued")))
        .then(exec(this::fail));
  }

  private HttpRequestActionBuilder reserveRequest() {
    return http("create reservation")
        .post("/v2/reservations")
        .header("X-CSRF-Token", "#{csrf}")
        .body(StringBody(session ->
            "{\"cart_id\":" + jsonLiteral(session.get("cartId")) + "}"))
        .check(jsonPath("$.status_url").optional().saveAs("statusUrl"));
  }

  private ChainBuilder pollAttempt(int number) {
    return doIf(session -> !"ready".equalsIgnoreCase(text(session.get("reservationState"))))
        .then(exec(pause(Duration.ofMillis(50)))
            .exec(session -> session
                .set("reservationState", "pending")
                .set("reservationId", ""))
            .exec(guarded("pollRecovery" + number, this::pollReservationRequest, 200, 401)));
  }

  private HttpRequestActionBuilder pollReservationRequest() {
    return http("poll reservation")
        .get("#{statusUrl}")
        .check(
            jsonPath("$.status").optional().saveAs("reservationState"),
            jsonPath("$.reservation_id").optional().saveAs("reservationId"));
  }

  private HttpRequestActionBuilder placeOrderRequest() {
    return http("place order")
        .post("/v2/orders")
        .header("X-CSRF-Token", "#{csrf}")
        .header("Idempotency-Key", "bench-order-#{cartId}")
        .header("If-Match", "#{cartEtag}")
        .body(StringBody(session ->
            "{\"cart_id\":" + jsonLiteral(session.get("cartId"))
                + ",\"reservation_id\":" + jsonLiteral(session.get("reservationId")) + "}"))
        .check(
            jsonPath("$.accepted").optional().saveAs("accepted"),
            jsonPath("$.id").optional().saveAs("orderId"));
  }

  private ChainBuilder guarded(
      String recoveryFlag,
      RequestFactory requestFactory,
      Integer... allowedStatuses) {

    HttpRequestActionBuilder checkedRequest = requestFactory.build()
        .check(
            status().in(allowedStatuses),
            status().saveAs("opStatus"),
            regex(ERROR_RE).optional().saveAs("opError"),
            regex(CSRF_RE).optional().saveAs("opCsrf"));

    ChainBuilder retry = exec(checkedRequest)
        .exec(this::applyOperationCsrf)
        .doIf(session -> session.getInt("opStatus") == 401)
        .then(exec(this::fail));

    return exec(session -> session
            .set("opStatus", 0)
            .set("opError", "")
            .set("opCsrf", ""))
        .exec(checkedRequest)
        .exec(this::applyOperationCsrf)
        .doIf(session -> isRecoverable(session, recoveryFlag))
        .then(exec(session -> session.set(recoveryFlag, true))
            .exec(recoverSession())
            .exec(retry))
        .doIf(session -> session.getInt("opStatus") == 401
            && !isRecoverable(session, recoveryFlag))
        .then(exec(this::fail))
        .doIf(session -> session.getInt("opStatus") == 0)
        .then(exec(this::fail));
  }

  private boolean isRecoverable(Session session, String recoveryFlag) {
    String error = text(session.get("opError"));
    return session.getInt("opStatus") == 401
        && ("expired".equals(error) || "session".equals(error))
        && !Boolean.TRUE.equals(session.get(recoveryFlag));
  }

  private Session applyOperationCsrf(Session session) {
    String token = text(session.get("opCsrf"));
    return token.isEmpty() ? session : session.set("csrf", token);
  }

  private ChainBuilder recoverSession() {
    return exec(session -> session
            .set("renewStatus", 0)
            .set("renewError", "")
            .set("renewCsrf", "")
            .set("reauthOk", false))
        .exec(http("renew session")
            .post("/v2/session/renew")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(
                status().in(200, 401),
                status().saveAs("renewStatus"),
                regex(ERROR_RE).optional().saveAs("renewError"),
                regex(CSRF_RE).optional().saveAs("renewCsrf")))
        .exec(this::applyRenewResponse)
        .doIf(session -> session.getInt("renewStatus") == 401
            && ("expired".equals(text(session.get("renewError")))
                || "session".equals(text(session.get("renewError")))))
        .then(login())
        .doIf(session -> session.getInt("renewStatus") == 401
            && !"expired".equals(text(session.get("renewError")))
            && !"session".equals(text(session.get("renewError"))))
        .then(exec(this::fail))
        .doIf(session -> Boolean.TRUE.equals(session.get("reauthOk"))
            && hasText(session, "cartId"))
        .then(recoverCart());
  }

  private Session applyRenewResponse(Session session) {
    if (session.getInt("renewStatus") == 200) {
      String token = text(session.get("renewCsrf"));
      return token.isEmpty()
          ? fail(session)
          : session.set("csrf", token).set("reauthOk", true);
    }
    return session;
  }

  private ChainBuilder recoverCart() {
    return exec(session -> session.set("recoverCsrf", ""))
        .exec(http("recover cart")
            .post("/v2/carts/#{cartId}/recover")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(
                status().is(200),
                regex(CSRF_RE).optional().saveAs("recoverCsrf")))
        .exec(session -> {
          String token = text(session.get("recoverCsrf"));
          return token.isEmpty() ? session : session.set("csrf", token);
        });
  }

  private Session fail(Session session) {
    return session.markAsFailed();
  }

  private static boolean hasText(Session session, String key) {
    return !text(session.get(key)).isEmpty();
  }

  private static String text(Object value) {
    return value == null ? "" : String.valueOf(value);
  }

  private static boolean isTrue(Object value) {
    return Boolean.TRUE.equals(value) || "true".equalsIgnoreCase(text(value));
  }

  private static String jsonLiteral(Object value) {
    if (value == null) {
      return "null";
    }
    if (value instanceof Number || value instanceof Boolean) {
      return String.valueOf(value);
    }

    String input = String.valueOf(value);
    StringBuilder output = new StringBuilder("\"");
    for (int i = 0; i < input.length(); i++) {
      char c = input.charAt(i);
      switch (c) {
        case '"':
          output.append("\\\"");
          break;
        case '\\':
          output.append("\\\\");
          break;
        case '\b':
          output.append("\\b");
          break;
        case '\f':
          output.append("\\f");
          break;
        case '\n':
          output.append("\\n");
          break;
        case '\r':
          output.append("\\r");
          break;
        case '\t':
          output.append("\\t");
          break;
        default:
          if (c < 0x20) {
            output.append(String.format("\\u%04x", (int) c));
          } else {
            output.append(c);
          }
      }
    }
    return output.append('"').toString();
  }
}

import http from "k6/http";
import { check, sleep } from "k6";

const BASE = (__ENV.BASE_URL || "http://127.0.0.1:8000").replace(/\/+$/, "");
const ORIGIN = BASE.match(/^https?:\/\/[^/]+/i)?.[0];
const MAX_RECOVERIES = 4;

export const options = {
  scenarios: {
    checkout: {
      executor: "per-vu-iterations",
      vus: 2,
      iterations: 2,
      maxDuration: "5m",
    },
  },
};

function fail(message) {
  throw new Error(message);
}

function assertCheck(value, name, predicate) {
  if (!check(value, { [name]: predicate })) {
    fail(name);
  }
}

function safeJson(response) {
  if (!response || !response.body) return null;
  try {
    return JSON.parse(response.body);
  } catch (_) {
    return null;
  }
}

function header(response, wanted) {
  if (!response || !response.headers) return null;
  const target = wanted.toLowerCase();
  for (const key of Object.keys(response.headers)) {
    if (key.toLowerCase() === target) return response.headers[key];
  }
  return null;
}

function responseError(response) {
  const json = safeJson(response);
  return json && typeof json.error === "string" ? json.error : null;
}

function pathPart(url) {
  if (url.indexOf(ORIGIN) === 0) {
    return url.substring(ORIGIN.length) || "/";
  }
  return url;
}

function normalizePath(path) {
  const parts = path.split("/");
  const result = [];
  for (const part of parts) {
    if (!part || part === ".") continue;
    if (part === "..") {
      if (result.length) result.pop();
    } else {
      result.push(part);
    }
  }
  return "/" + result.join("/");
}

function resolveUrl(reference, context) {
  if (typeof reference !== "string" || !reference) fail("Missing URL");

  if (/^https?:\/\//i.test(reference)) {
    if (!ORIGIN || reference.indexOf(ORIGIN + "/") !== 0) {
      fail("Refusing a URL outside the configured target");
    }
    return reference;
  }
  if (reference.indexOf("//") === 0) fail("Refusing a protocol-relative URL");

  const hashAt = reference.indexOf("#");
  const hash = hashAt >= 0 ? reference.substring(hashAt) : "";
  const withoutHash = hashAt >= 0 ? reference.substring(0, hashAt) : reference;
  const queryAt = withoutHash.indexOf("?");
  const query = queryAt >= 0 ? withoutHash.substring(queryAt) : "";
  const refPath = queryAt >= 0 ? withoutHash.substring(0, queryAt) : withoutHash;

  let combined;
  if (refPath.indexOf("/") === 0) {
    combined = refPath;
  } else if (!refPath && context) {
    const current = pathPart(context).split("?")[0];
    combined = current;
  } else if (context) {
    const current = pathPart(context).split("?")[0];
    const slash = current.lastIndexOf("/");
    combined = current.substring(0, slash + 1) + refPath;
  } else {
    combined = "/" + refPath;
  }

  return ORIGIN + normalizePath(combined) + query + hash;
}

function decodeHtml(value) {
  return value
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&amp;/gi, "&");
}

function attribute(tag, name) {
  const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const expression = new RegExp(
    "(?:^|\\s)" + escaped + "\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))",
    "i"
  );
  const match = tag.match(expression);
  if (!match) return null;
  return decodeHtml(match[1] !== undefined ? match[1] :
    match[2] !== undefined ? match[2] : match[3]);
}

function inputValue(html, wantedName) {
  const inputs = html.match(/<input\b[^>]*>/gi) || [];
  for (const tag of inputs) {
    if ((attribute(tag, "name") || "").toLowerCase() === wantedName.toLowerCase()) {
      return attribute(tag, "value");
    }
  }
  return null;
}

function challengeForm(html) {
  const forms = html.match(/<form\b[\s\S]*?<\/form\s*>/gi) || [];
  for (const form of forms) {
    const actionMatch = form.match(/<form\b[^>]*>/i);
    const action = actionMatch ? attribute(actionMatch[0], "action") : null;
    const challenge = inputValue(form, "challenge");
    if (action && challenge) return { action, challenge };
  }

  const formTag = html.match(/<form\b[^>]*>/i);
  const action = formTag ? attribute(formTag[0], "action") : null;
  const challenge = inputValue(html, "challenge");
  return action && challenge ? { action, challenge } : null;
}

function updateCsrf(state, response) {
  const json = safeJson(response);
  if (json && typeof json.csrf === "string" && json.csrf.length) {
    state.csrf = json.csrf;
  }
}

function rawRequest(state, method, path, body, extraHeaders, name, authenticated, context) {
  const headers = { Accept: "application/json" };
  if (body !== undefined && body !== null) headers["Content-Type"] = "application/json";

  if (authenticated && method.toUpperCase() !== "GET") {
    if (!state.csrf) fail("Missing CSRF token for " + name);
    headers["X-CSRF-Token"] = state.csrf;
  }
  if (extraHeaders) {
    for (const key of Object.keys(extraHeaders)) headers[key] = extraHeaders[key];
  }

  const response = http.request(
    method,
    resolveUrl(path, context),
    body === undefined || body === null ? null : JSON.stringify(body),
    {
      headers,
      redirects: 0,
      tags: { name },
    }
  );

  if (response.status >= 200 && response.status < 300) updateCsrf(state, response);
  return response;
}

function classify401(state, response, operation) {
  const error = responseError(response);
  if (error === "expired") {
    state.expiryRecognized += 1;
    return error;
  }
  if (error === "session") {
    state.revocationRecognized += 1;
    return error;
  }

  assertCheck(response, operation + ": reject non-expiry 401", () => false);
  fail(operation + ": unexpected 401 error=" + error);
}

function login(state) {
  const formResponse = rawRequest(
    state, "GET", "/v2/login-form", null, null, "login-form", false
  );
  assertCheck(formResponse, "login form loaded", (r) => r.status === 200);

  const loginCsrf = inputValue(formResponse.body || "", "csrf");
  assertCheck(loginCsrf, "login form CSRF parsed", (value) =>
    typeof value === "string" && value.length > 0
  );

  const loginResponse = rawRequest(
    state,
    "POST",
    "/v2/login",
    { username: state.username, password: "bench", csrf: loginCsrf },
    null,
    "login",
    false
  );

  let resultResponse = loginResponse;
  if (loginResponse.status === 302) {
    const location = header(loginResponse, "Location");
    assertCheck(location, "login redirect has Location", (value) =>
      typeof value === "string" && value.length > 0
    );
    resultResponse = rawRequest(
      state,
      "GET",
      location,
      null,
      null,
      "login-redirect",
      false,
      resolveUrl("/v2/login")
    );
  } else {
    assertCheck(loginResponse, "login accepted", (r) => r.status === 200);
  }

  assertCheck(resultResponse, "login result loaded", (r) => r.status === 200);
  const resultJson = safeJson(resultResponse);
  let csrf = resultJson && resultJson.csrf;
  if (typeof csrf !== "string" || !csrf.length) {
    csrf = inputValue(resultResponse.body || "", "csrf");
  }
  assertCheck(csrf, "authenticated CSRF received", (value) =>
    typeof value === "string" && value.length > 0
  );
  state.csrf = csrf;
  state.loginCount += 1;
}

function recoverSession(state, cartId, reason) {
  state.recoveryCount += 1;
  if (state.recoveryCount > MAX_RECOVERIES) {
    fail("Session recovery limit exceeded");
  }

  const renewal = rawRequest(
    state, "POST", "/v2/session/renew", {}, null, "session-renew", true
  );

  let renewed = renewal.status >= 200 && renewal.status < 300;
  if (!renewed && renewal.status === 401) {
    const renewError = classify401(state, renewal, "session renewal");
    if (renewError !== "expired" && renewError !== "session") {
      fail("Session renewal failed");
    }
  } else if (!renewed) {
    fail("Unexpected session renewal status " + renewal.status);
  }

  if (!renewed) login(state);

  if (cartId) {
    const recovered = rawRequest(
      state,
      "POST",
      "/v2/carts/" + encodeURIComponent(String(cartId)) + "/recover",
      {},
      null,
      "cart-recover",
      true
    );
    assertCheck(recovered, "cart recovery accepted", (r) =>
      r.status >= 200 && r.status < 300
    );
  }
}

function recoverableRequest(state, method, path, body, extraHeaders, name, context) {
  let response = rawRequest(
    state, method, path, body, extraHeaders, name, true, context
  );
  if (response.status !== 401) return response;

  const error = classify401(state, response, name);
  recoverSession(state, state.cartId, error);

  response = rawRequest(
    state, method, path, body, extraHeaders, name + "-retry", true, context
  );
  if (response.status === 401) {
    classify401(state, response, name + " retry");
    fail(name + ": authentication retry failed");
  }
  return response;
}

function selectProduct() {
  let url = resolveUrl("/v2/catalog");
  let productChoice = null;

  for (let page = 0; page < 3; page += 1) {
    const response = rawRequest(
      null, "GET", url, null, null, "catalog", false
    );
    assertCheck(response, "catalog page loaded", (r) => r.status === 200);

    const json = safeJson(response);
    assertCheck(json, "catalog JSON parsed", (value) => !!value);

    const root = json.data || json;
    let products = root.products || json.products || [];
    if (!Array.isArray(products)) products = [];
    if (!products.length) {
      const single = root.product || json.product ||
        (root.id !== undefined && Array.isArray(root.variants) ? root : null);
      if (single) products = [single];
    }

    for (const product of products) {
      if (!product || product.id === undefined || !Array.isArray(product.variants)) continue;
      for (const variant of product.variants) {
        if (variant && variant.id !== undefined && variant.in_stock === true) {
          productChoice = { product_id: product.id, variant_id: variant.id };
          break;
        }
      }
      if (productChoice) break;
    }
    if (productChoice) break;

    const next = json.next !== undefined ? json.next : root.next;
    if (!next || page === 2) break;
    url = resolveUrl(next, url);
  }

  assertCheck(productChoice, "in-stock catalog variant found", (value) => !!value);
  return productChoice;
}

function acquireGrant(state) {
  for (let attempt = 0; attempt < 2; attempt += 1) {
    const formResponse = recoverableRequest(
      state, "GET", "/v2/challenge-form", null, null, "challenge-form"
    );
    assertCheck(formResponse, "challenge form loaded", (r) => r.status === 200);

    const form = challengeForm(formResponse.body || "");
    assertCheck(form, "challenge form parsed", (value) =>
      !!value && !!value.action && !!value.challenge
    );

    const claimResponse = rawRequest(
      state,
      "POST",
      form.action,
      { challenge: form.challenge },
      null,
      "challenge-claim",
      true,
      resolveUrl("/v2/challenge-form")
    );

    if (claimResponse.status === 401) {
      const error = classify401(state, claimResponse, "challenge claim");
      if (attempt === 0) {
        recoverSession(state, null, error);
        continue;
      }
      fail("Challenge claim authentication retry failed");
    }

    assertCheck(claimResponse, "challenge claim redirected", (r) => r.status === 302);
    const location = header(claimResponse, "Location");
    assertCheck(location, "challenge redirect has Location", (value) =>
      typeof value === "string" && value.length > 0
    );

    // The claim redirect is deliberately followed exactly once.
    const grantResponse = rawRequest(
      state,
      "GET",
      location,
      null,
      null,
      "challenge-grant",
      false,
      resolveUrl(form.action, resolveUrl("/v2/challenge-form"))
    );
    assertCheck(grantResponse, "challenge grant loaded", (r) => r.status === 200);

    const grantJson = safeJson(grantResponse);
    const grant = grantJson && (grantJson.grant_id ||
      (grantJson.data && grantJson.data.grant_id));
    assertCheck(grant, "challenge grant received", (value) =>
      typeof value === "string" && value.length > 0
    );
    return grant;
  }
  fail("Unable to acquire challenge grant");
}

function createCart(state, product) {
  let grant = acquireGrant(state);

  for (let attempt = 0; attempt < 2; attempt += 1) {
    const response = rawRequest(
      state,
      "POST",
      "/v2/carts",
      {
        product_id: product.product_id,
        variant_id: product.variant_id,
        grant_id: grant,
      },
      null,
      "cart-create",
      true
    );

    if (response.status === 401) {
      const error = classify401(state, response, "cart creation");
      if (attempt === 0) {
        // A 401 did not create a cart. Use a fresh claim for the single retry.
        recoverSession(state, null, error);
        grant = acquireGrant(state);
        continue;
      }
      fail("Cart creation authentication retry failed");
    }

    assertCheck(response, "cart created once", (r) => r.status === 201);
    const json = safeJson(response);
    assertCheck(json && json.id !== undefined, "cart ID received", (value) => !!value);

    state.cartId = json.id;
    state.cartCreates += 1;
    state.etag = header(response, "ETag");
    return;
  }
  fail("Cart creation failed");
}

function readCart(state) {
  const response = recoverableRequest(
    state,
    "GET",
    "/v2/carts/" + encodeURIComponent(String(state.cartId)),
    null,
    null,
    "cart-read"
  );
  assertCheck(response, "cart read succeeded", (r) => r.status === 200);
  const etag = header(response, "ETag");
  assertCheck(etag, "cart ETag received", (value) =>
    typeof value === "string" && value.length > 0
  );
  state.etag = etag;
  return etag;
}

function patchQuantity(state) {
  if (!state.etag) readCart(state);

  let conflictRetried = false;
  while (true) {
    const response = recoverableRequest(
      state,
      "PATCH",
      "/v2/carts/" + encodeURIComponent(String(state.cartId)),
      { quantity: 1 },
      { "If-Match": state.etag },
      "cart-quantity"
    );

    if (response.status === 412 && !conflictRetried) {
      conflictRetried = true;
      readCart(state);
      continue;
    }

    assertCheck(response, "cart quantity updated", (r) =>
      r.status === 200 || r.status === 204
    );
    const updatedEtag = header(response, "ETag");
    if (updatedEtag) state.etag = updatedEtag;
    else readCart(state);
    return;
  }
}

function reserveCart(state) {
  const response = recoverableRequest(
    state,
    "POST",
    "/v2/reservations",
    { cart_id: state.cartId },
    null,
    "reservation-create"
  );
  assertCheck(response, "reservation accepted", (r) => r.status === 202);

  const json = safeJson(response);
  const root = json && (json.data || json);
  const statusUrl = root && root.status_url;
  assertCheck(statusUrl, "reservation status URL received", (value) =>
    typeof value === "string" && value.length > 0
  );

  let reservationId = null;
  let previousPoll = false;

  for (let poll = 0; poll < 5; poll += 1) {
    if (previousPoll) sleep(0.05);

    const statusResponse = recoverableRequest(
      state,
      "GET",
      statusUrl,
      null,
      null,
      "reservation-status",
      resolveUrl("/v2/reservations")
    );
    assertCheck(statusResponse, "reservation status loaded", (r) => r.status === 200);

    const statusJson = safeJson(statusResponse);
    const statusRoot = statusJson && (statusJson.data || statusJson);
    assertCheck(statusRoot, "reservation status parsed", (value) => !!value);

    if (statusRoot.status === "ready") {
      reservationId = statusRoot.reservation_id;
      assertCheck(reservationId, "ready reservation has ID", (value) =>
        value !== undefined && value !== null && String(value).length > 0
      );
      break;
    }
    if (statusRoot.status === "failed") {
      assertCheck(statusRoot, "reservation is not failed", () => false);
      fail("Reservation failed");
    }
    assertCheck(statusRoot, "reservation remains pending", (value) =>
      value.status === "pending"
    );
    previousPoll = true;
  }

  assertCheck(reservationId, "reservation became ready within five polls", (value) =>
    value !== null
  );
  return reservationId;
}

function submitOrder(state, reservationId) {
  const key = "bench-order-" + String(state.cartId);
  let etag = readCart(state);

  for (let attempt = 0; attempt < 2; attempt += 1) {
    const response = recoverableRequest(
      state,
      "POST",
      "/v2/orders",
      { cart_id: state.cartId, reservation_id: reservationId },
      { "Idempotency-Key": key, "If-Match": etag },
      "order-submit"
    );

    if (response.status === 412 && attempt === 0) {
      etag = readCart(state);
      continue;
    }

    const json = safeJson(response);
    assertCheck(
      { status: response.status, accepted: json && json.accepted },
      "exactly one order accepted",
      (value) => value.status === 201 && value.accepted === true
    );
    state.committedOrders += 1;
    return;
  }

  fail("Order precondition retry failed");
}

export default function () {
  const state = {
    username: "bench-" + __VU,
    csrf: null,
    cartId: null,
    etag: null,
    expiryRecognized: 0,
    revocationRecognized: 0,
    recoveryCount: 0,
    loginCount: 0,
    cartCreates: 0,
    committedOrders: 0,
  };

  const product = selectProduct();
  login(state);
  createCart(state, product);
  patchQuantity(state);
  const reservationId = reserveCart(state);
  submitOrder(state, reservationId);

  assertCheck(state, "session expiry recognized", (s) => s.expiryRecognized > 0);
  assertCheck(state, "one cart and one committed order", (s) =>
    s.cartCreates === 1 && s.committedOrders === 1
  );
  assertCheck(state, "session recovery is bounded", (s) =>
    s.recoveryCount <= MAX_RECOVERIES
  );
}

from __future__ import annotations

import os
import uuid
import gevent
from collections.abc import Callable
from html.parser import HTMLParser
from itertools import count
from urllib.parse import urljoin, urlsplit, urlunsplit

from locust import HttpUser, LoadTestShape, StopUser, constant, task


BASE_URL = os.environ["BASE_URL"]
USER_COUNT = 2
ITERATIONS_PER_USER = 2
PASSWORD = "bench"
_user_sequence = count(1)
_NO_BODY = object()


class JourneyFailure(Exception):
    pass


class FormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self.inputs = []
        self._current_form = None

    @staticmethod
    def _attrs(attrs):
        return {str(key).lower(): value for key, value in attrs}

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        values = self._attrs(attrs)
        if tag == "form":
            self._current_form = {"attrs": values, "inputs": []}
            self.forms.append(self._current_form)
        elif tag == "input":
            self.inputs.append(values)
            if self._current_form is not None:
                self._current_form["inputs"].append(values)

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self._current_form = None


def _json_object(response):
    try:
        value = response.json()
    except Exception:
        return None
    return value if isinstance(value, dict) else None


def _data_object(value):
    if not isinstance(value, dict):
        return {}
    data = value.get("data")
    return data if isinstance(data, dict) else value


def _csrf_from_json(response):
    value = _json_object(response)
    if value is None:
        return None
    token = value.get("csrf")
    if token is None:
        token = _data_object(value).get("csrf")
    return str(token) if token not in (None, "") else None


def _error_code(response):
    value = _json_object(response)
    if value is None:
        return None
    error = value.get("error")
    if isinstance(error, dict):
        error = error.get("code")
    return str(error) if error is not None else None


def _check_json_keys(*keys):
    def check(response):
        value = _json_object(response)
        if value is None:
            return False, "Expected a JSON object"
        for key in keys:
            if value.get(key) in (None, ""):
                return False, "Missing JSON field: " + key
        return True, ""
    return check


def _check_csrf_json(response):
    if _csrf_from_json(response):
        return True, ""
    return False, "Expected a JSON csrf token"


def _safe_path(location):
    if not isinstance(location, str) or not location.strip():
        raise JourneyFailure("Missing dynamic URL")
    base = BASE_URL.rstrip("/") + "/"
    target = urljoin(base, location.strip())
    parsed_target = urlsplit(target)
    parsed_base = urlsplit(BASE_URL)
    if (
        parsed_target.scheme not in ("http", "https")
        or parsed_target.netloc != parsed_base.netloc
    ):
        raise JourneyFailure("Dynamic URL is outside the configured target")
    return urlunsplit(("", "", parsed_target.path or "/", parsed_target.query, ""))


def _csrf_from_form(html):
    parser = FormParser()
    parser.feed(html or "")
    for item in parser.inputs:
        if item.get("name") == "csrf" and item.get("value") not in (None, ""):
            return str(item["value"])
    return None


def _check_login_form(response):
    if _csrf_from_form(response.text):
        return True, ""
    return False, "Login form did not contain input[name=csrf]"


def _challenge_details(html):
    parser = FormParser()
    parser.feed(html or "")
    for form in parser.forms:
        challenge = next(
            (
                item.get("value")
                for item in form["inputs"]
                if item.get("name") == "challenge"
                and item.get("value") not in (None, "")
            ),
            None,
        )
        action = form["attrs"].get("action")
        if action and challenge:
            return action, str(challenge)
    return None


def _check_challenge_form(response):
    details = _challenge_details(response.text)
    if details is None:
        return False, "Challenge form is missing its action or challenge input"
    try:
        _safe_path(details[0])
    except JourneyFailure as exc:
        return False, str(exc)
    return True, ""


def _check_location(response):
    location = response.headers.get("Location")
    if not location:
        return False, "Expected a Location header"
    try:
        _safe_path(location)
    except JourneyFailure as exc:
        return False, str(exc)
    return True, ""


def _check_grant(response):
    value = _json_object(response)
    if value is None or value.get("grant_id") in (None, ""):
        return False, "Expected a grant_id JSON field"
    return True, ""


def _check_status_url(response):
    value = _json_object(response)
    if value is None or value.get("status_url") in (None, ""):
        return False, "Expected a status_url JSON field"
    try:
        _safe_path(str(value["status_url"]))
    except JourneyFailure as exc:
        return False, str(exc)
    return True, ""


def _check_order(response):
    value = _json_object(response)
    if value is None:
        return False, "Expected an order JSON object"
    if value.get("accepted") is not True:
        return False, "Order was not accepted"
