        allow_auth_expiry=False,
        allow_412=False,
        check: Callable | None = None,
    ):
        request_kwargs = {
            "headers": headers or {},
            "allow_redirects": False,
            "catch_response": True,
            "name": name or path,
        }
        if body is not _NO_BODY:
            request_kwargs["json"] = body

        failure = None
        with self.client.request(method, path, **request_kwargs) as response:
            status = response.status_code
            accepted = status in expected

            if status == 401 and allow_auth_expiry:
