    def _auth_call(
        self,
        method,
        path,
        *,
        body=_NO_BODY,
        headers=None,
        name=None,
        expected=(200,),
        check=None,
        cart_id=None,
        allow_412=False,
    ):
        method = method.upper()

        def make_headers():
            result = dict(headers or {})
            if method != "GET":
                result["X-CSRF-Token"] = self.csrf or ""
            return result

        response = self._send(
            method,
            path,
            body=body,
            headers=make_headers(),
            name=name,
            expected=expected,
            allow_auth_expiry=True,
            allow_412=allow_412,
            check=check,
        )

        if response.status_code == 401 and _error_code(response) in (
            "expired",
            "session",
        ):
            self._recover_session(cart_id, _error_code(response))
