                    (True, "")
                    if _json_object(r) is not None
                    else (False, "Expected catalog JSON")
                ),
            )
            payload = _json_object(response)
            item = self._available_item(self._catalog_products(payload))
            if item:
                return item
            next_value = self._catalog_next(payload)
            if not next_value:
                break
            next_url = str(next_value)
        return None

    def _select_item(self):
        response = self._send(
            "GET",
            "/v2/catalog",
            name="/v2/catalog",
            expected=(200,),
            check=lambda r: (
