            "GET",
            "/v2/carts/" + str(cart_id),
            name="/v2/carts/[id]",
            expected=(200,),
            check=lambda r: (
                (True, "")
                if r.headers.get("ETag")
                else (False, "Cart response did not include an ETag")
            ),
            cart_id=cart_id,
        )
