            raise JourneyFailure("Cart ETag was missing")

    def _set_quantity(self, cart_id):
        if not self.cart_etag:
            self._refresh_cart_etag(cart_id)

        def patch(etag, retry_412):
            return self._auth_call(
                "PATCH",
                "/v2/carts/" + str(cart_id),
                body={"quantity": 1},
                headers={"If-Match": etag},
                name="/v2/carts/[id]",
                expected=(200, 204),
                cart_id=cart_id,
                allow_412=retry_412,
            )

        response = patch(self.cart_etag, True)
        if response.status_code == 412:
            self._refresh_cart_etag(cart_id)
            response = patch(self.cart_etag, False)

        new_etag = response.headers.get("ETag")
        if new_etag:
            self.cart_etag = new_etag

