        response = self._auth_call(
            "POST",
            "/v2/reservations",
            body={"cart_id": cart_id},
            name="/v2/reservations",
            expected=(202,),
            check=_check_status_url,
            cart_id=cart_id,
        )
        value = _json_object(response)
        status_url = _safe_path(str(value["status_url"]))

        for poll_number in range(5):
            if poll_number:
                gevent.sleep(0.05)
            poll = self._auth_call(
                "GET",
                status_url,
                name="/v2/reservations/status",
                expected=(200,),
                check=lambda r: (
                    (True, "")
                    if _json_object(r) is not None
                    else (False, "Expected reservation status JSON")
                ),
                cart_id=cart_id,
            )
            status_value = _json_object(poll)
            status_data = _data_object(status_value)
            status = status_data.get("status")

            if status == "ready":
                reservation_id = status_data.get("reservation_id")
                if reservation_id in (None, ""):
                    raise JourneyFailure("Ready reservation did not include an id")
                return str(reservation_id)
            if status == "failed":
                raise JourneyFailure("Reservation failed")
            if status != "pending":
                raise JourneyFailure("Unexpected reservation status")

        raise JourneyFailure("Reservation did not become ready after five polls")

    def _place_order(self, cart_id, reservation_id):
        self._refresh_cart_etag(cart_id)
        idempotency_key = "order-" + str(cart_id) + "-" + uuid.uuid4().hex
        self._auth_call(
            "POST",
            "/v2/orders",
            body={
                "cart_id": cart_id,
                "reservation_id": reservation_id,
            },
            headers={
                "Idempotency-Key": idempotency_key,
                "If-Match": self.cart_etag,
            },
            name="/v2/orders",
            expected=(201,),
            check=_check_order,
            cart_id=cart_id,
        )

    def _journey(self):
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None

        self._login()
        product_id, variant_id = self._select_item()
        grant_id = self._claim_grant()

        cart_response = self._auth_call(
            "POST",
            "/v2/carts",
            body={
                "product_id": product_id,
                "variant_id": variant_id,
                "grant_id": grant_id,
            },
            name="/v2/carts",
