from __future__ import annotations

import os
import uuid
from collections.abc import Callable
from html.parser import HTMLParser
from itertools import count
from urllib.parse import urljoin, urlsplit, urlunsplit

import gevent
from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


BASE_URL = os.environ["BASE_URL"]
USER_COUNT = 2
ITERATIONS_PER_USER = 2
PASSWORD = "bench"
_user_sequence = count(1)
_NO_BODY = object()


class JourneyFailure(Exception):
    pass


class FormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self.inputs = []
        self._current_form = None

    @staticmethod
    def _attrs(attrs):
        return {str(key).lower(): value for key, value in attrs}

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        values = self._attrs(attrs)
        if tag == "form":
            self._current_form = {"attrs": values, "inputs": []}
            self.forms.append(self._current_form)
        elif tag == "input":
            self.inputs.append(values)
            if self._current_form is not None:
                self._current_form["inputs"].append(values)

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self._current_form = None


def _json_object(response):
    try:
        value = response.json()
    except Exception:
        return None
    return value if isinstance(value, dict) else None


def _data_object(value):
    if not isinstance(value, dict):
        return {}
    data = value.get("data")
    return data if isinstance(data, dict) else value


def _csrf_from_json(response):
    value = _json_object(response)
    if value is None:
        return None
    token = value.get("csrf")
    if token is None:
        token = _data_object(value).get("csrf")
    return str(token) if token not in (None, "") else None


def _error_code(response):
    value = _json_object(response)
    if value is None:
        return None
    error = value.get("error")
    if isinstance(error, dict):
        error = error.get("code")
    return str(error) if error is not None else None


def _check_json_keys(*keys):
    def check(response):
        value = _json_object(response)
        if value is None:
            return False, "Expected a JSON object"
        for key in keys:
            if value.get(key) in (None, ""):
                return False, "Missing JSON field: " + key
        return True, ""

    return check


def _check_csrf_json(response):
    if _csrf_from_json(response):
        return True, ""
    return False, "Expected a JSON csrf token"


def _safe_path(location):
    if not isinstance(location, str) or not location.strip():
        raise JourneyFailure("Missing dynamic URL")
    base = BASE_URL.rstrip("/") + "/"
    target = urljoin(base, location.strip())
    parsed_target = urlsplit(target)
    parsed_base = urlsplit(BASE_URL)
    if (
        parsed_target.scheme not in ("http", "https")
        or parsed_target.netloc != parsed_base.netloc
    ):
        raise JourneyFailure("Dynamic URL is outside the configured target")
    return urlunsplit(("", "", parsed_target.path or "/", parsed_target.query, ""))


def _csrf_from_form(html):
    parser = FormParser()
    parser.feed(html or "")
    for item in parser.inputs:
        if item.get("name") == "csrf" and item.get("value") not in (None, ""):
            return str(item["value"])
    return None


def _check_login_form(response):
    if _csrf_from_form(response.text):
        return True, ""
    return False, "Login form did not contain input[name=csrf]"


def _challenge_details(html):
    parser = FormParser()
    parser.feed(html or "")
    for form in parser.forms:
        challenge = next(
            (
                item.get("value")
                for item in form["inputs"]
                if item.get("name") == "challenge"
                and item.get("value") not in (None, "")
            ),
            None,
        )
        action = form["attrs"].get("action")
        if action and challenge:
            return action, str(challenge)
    return None


def _check_challenge_form(response):
    details = _challenge_details(response.text)
    if details is None:
        return False, "Challenge form is missing its action or challenge input"
    try:
        _safe_path(details[0])
    except JourneyFailure as exc:
        return False, str(exc)
    return True, ""


def _check_location(response):
    location = response.headers.get("Location")
    if not location:
        return False, "Expected a Location header"
    try:
        _safe_path(location)
    except JourneyFailure as exc:
        return False, str(exc)
    return True, ""


def _check_grant(response):
    value = _json_object(response)
    if value is None or value.get("grant_id") in (None, ""):
        return False, "Expected a grant_id JSON field"
    return True, ""


def _check_status_url(response):
    value = _json_object(response)
    if value is None or value.get("status_url") in (None, ""):
        return False, "Expected a status_url JSON field"
    try:
        _safe_path(str(value["status_url"]))
    except JourneyFailure as exc:
        return False, str(exc)
    return True, ""


def _check_order(response):
    value = _json_object(response)
    if value is None:
        return False, "Expected an order JSON object"
    if value.get("accepted") is not True:
        return False, "Order was not accepted"
    if value.get("id") in (None, ""):
        return False, "Accepted order did not include an id"
    return True, ""


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.instance_number = next(_user_sequence)
        self.username = "bench-" + str(((self.instance_number - 1) % 16) + 1)
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None

    def _send(
        self,
        method,
        path,
        *,
        body=_NO_BODY,
        headers=None,
        name=None,
        expected=(200,),
        allow_auth_expiry=False,
        allow_412=False,
        check: Callable | None = None,
    ):
        request_kwargs = {
            "headers": headers or {},
            "allow_redirects": False,
            "catch_response": True,
            "name": name or path,
        }
        if body is not _NO_BODY:
            request_kwargs["json"] = body

        failure = None
        with self.client.request(method, path, **request_kwargs) as response:
            status = response.status_code
            accepted = status in expected

            if status == 401 and allow_auth_expiry:
                accepted = _error_code(response) in ("expired", "session")
            if status == 412 and allow_412:
                accepted = True

            if accepted and status in expected and check is not None:
                try:
                    valid, message = check(response)
                except Exception as exc:
                    valid, message = False, "Response validation failed: " + str(exc)
                if not valid:
                    accepted = False
                    failure = message or "Response validation failed"

            if not accepted:
                if failure is None:
                    failure = "Unexpected HTTP status " + str(status)
                response.failure(failure)
            else:
                response.success()

        if failure is not None:
            raise JourneyFailure(failure)
        return response

    def _update_csrf(self, response):
        token = _csrf_from_json(response)
        if token:
            self.csrf = token

    def _login(self):
        form_response = self._send(
            "GET",
            "/v2/login-form",
            name="/v2/login-form",
            expected=(200,),
            check=_check_login_form,
        )
        form_csrf = _csrf_from_form(form_response.text)
        if not form_csrf:
            raise JourneyFailure("Login CSRF token was missing")

        login_response = self._send(
            "POST",
            "/v2/login",
            body={
                "username": self.username,
                "password": PASSWORD,
                "csrf": form_csrf,
            },
            name="/v2/login",
            expected=(200, 302),
            check=lambda response: (
                _check_location(response)
                if response.status_code == 302
                else _check_csrf_json(response)
            ),
        )

        if login_response.status_code == 302:
            destination = _safe_path(login_response.headers["Location"])
            final_response = self._send(
                "GET",
                destination,
                name="/v2/login-redirect",
                expected=(200,),
                check=_check_csrf_json,
            )
            self._update_csrf(final_response)
        else:
            self._update_csrf(login_response)

        if not self.csrf:
            raise JourneyFailure("Login did not provide a CSRF token")

    def _fresh_login(self):
        self.csrf = None
        self._login()

    def _recover_session(self, cart_id, original_error):
        if original_error == "expired":
            renew = self._send(
                "POST",
                "/v2/session/renew",
                body={},
                headers={"X-CSRF-Token": self.csrf or ""},
                name="/v2/session/renew",
                expected=(200,),
                allow_auth_expiry=True,
                check=_check_csrf_json,
            )
            if renew.status_code == 200:
                self._update_csrf(renew)
            else:
                self._fresh_login()
        else:
            self._fresh_login()

        if not cart_id:
            return

        recovery = self._send(
            "POST",
            "/v2/carts/" + str(cart_id) + "/recover",
            body={},
            headers={"X-CSRF-Token": self.csrf or ""},
            name="/v2/carts/[id]/recover",
            expected=(200, 204),
            allow_auth_expiry=True,
        )
        if recovery.status_code == 401:
            self._fresh_login()
            recovery = self._send(
                "POST",
                "/v2/carts/" + str(cart_id) + "/recover",
                body={},
                headers={"X-CSRF-Token": self.csrf or ""},
                name="/v2/carts/[id]/recover",
                expected=(200, 204),
            )
        self._update_csrf(recovery)

    def _auth_call(
        self,
        method,
        path,
        *,
        body=_NO_BODY,
        headers=None,
        name=None,
        expected=(200,),
        check=None,
        cart_id=None,
        allow_412=False,
    ):
        method = method.upper()

        def make_headers():
            result = dict(headers or {})
            if method != "GET":
                result["X-CSRF-Token"] = self.csrf or ""
            return result

        response = self._send(
            method,
            path,
            body=body,
            headers=make_headers(),
            name=name,
            expected=expected,
            allow_auth_expiry=True,
            allow_412=allow_412,
            check=check,
        )

        if response.status_code == 401 and _error_code(response) in (
            "expired",
            "session",
        ):
            self._recover_session(cart_id, _error_code(response))
            response = self._send(
                method,
                path,
                body=body,
                headers=make_headers(),
                name=name,
                expected=expected,
                allow_412=allow_412,
                check=check,
            )

        if method != "GET" and response.status_code in expected:
            self._update_csrf(response)
        return response

    @staticmethod
    def _catalog_products(payload):
        data = _data_object(payload)
        products = data.get("products")
        if isinstance(products, list):
            return products
        product = data.get("product")
        if isinstance(product, dict):
            return [product]
        if isinstance(payload.get("product"), dict):
            return [payload["product"]]
        return []

    @staticmethod
    def _catalog_next(payload):
        if "next" in payload:
            return payload.get("next")
        return _data_object(payload).get("next")

    @staticmethod
    def _available_item(products):
        for product in products:
            if not isinstance(product, dict) or product.get("id") in (None, ""):
                continue
            variants = product.get("variants")
            if not isinstance(variants, list):
                continue
            for variant in variants:
                if (
                    isinstance(variant, dict)
                    and variant.get("id") not in (None, "")
                    and variant.get("in_stock") is True
                ):
                    return str(product["id"]), str(variant["id"])
        return None

    def _catalog_page(self, first_url, max_pages=3):
        next_url = first_url
        for _ in range(max_pages):
            path = _safe_path(next_url)
            response = self._send(
                "GET",
                path,
                name="/v2/catalog/page",
                expected=(200,),
                check=lambda r: (
                    (True, "")
                    if _json_object(r) is not None
                    else (False, "Expected catalog JSON")
                ),
            )
            payload = _json_object(response)
            item = self._available_item(self._catalog_products(payload))
            if item:
                return item
            next_value = self._catalog_next(payload)
            if not next_value:
                break
            next_url = str(next_value)
        return None

    def _select_item(self):
        response = self._send(
            "GET",
            "/v2/catalog",
            name="/v2/catalog",
            expected=(200,),
            check=lambda r: (
                (True, "")
                if _json_object(r) is not None
                else (False, "Expected catalog JSON")
            ),
        )
        payload = _json_object(response)
        item = self._available_item(self._catalog_products(payload))
        if item:
            return item

        next_value = self._catalog_next(payload)
        if next_value:
            item = self._catalog_page(str(next_value), max_pages=3)
        else:
            item = self._catalog_page("/v2/catalog/page", max_pages=3)

        if item:
            return item
        raise JourneyFailure("No in-stock catalog variant was found")

    def _claim_grant(self):
        form_response = self._send(
            "GET",
            "/v2/challenge-form",
            name="/v2/challenge-form",
            expected=(200,),
            check=_check_challenge_form,
        )
        details = _challenge_details(form_response.text)
        if details is None:
            raise JourneyFailure("Challenge form was incomplete")
        action, challenge = details

        claim_response = self._auth_call(
            "POST",
            _safe_path(action),
            body={"challenge": challenge},
            name="/v2/challenges/[id]",
            expected=(302,),
            check=_check_location,
        )
        destination = _safe_path(claim_response.headers["Location"])
        grant_response = self._send(
            "GET",
            destination,
            name="/v2/challenge-redirect",
            expected=(200,),
            check=_check_grant,
        )
        self._update_csrf(grant_response)
        value = _json_object(grant_response)
        return str(value["grant_id"])

    def _refresh_cart_etag(self, cart_id):
        response = self._auth_call(
            "GET",
            "/v2/carts/" + str(cart_id),
            name="/v2/carts/[id]",
            expected=(200,),
            check=lambda r: (
                (True, "")
                if r.headers.get("ETag")
                else (False, "Cart response did not include an ETag")
            ),
            cart_id=cart_id,
        )
        self.cart_etag = response.headers.get("ETag")
        if not self.cart_etag:
            raise JourneyFailure("Cart ETag was missing")

    def _set_quantity(self, cart_id):
        if not self.cart_etag:
            self._refresh_cart_etag(cart_id)

        def patch(etag, retry_412):
            return self._auth_call(
                "PATCH",
                "/v2/carts/" + str(cart_id),
                body={"quantity": 1},
                headers={"If-Match": etag},
                name="/v2/carts/[id]",
                expected=(200, 204),
                cart_id=cart_id,
                allow_412=retry_412,
            )

        response = patch(self.cart_etag, True)
        if response.status_code == 412:
            self._refresh_cart_etag(cart_id)
            response = patch(self.cart_etag, False)

        new_etag = response.headers.get("ETag")
        if new_etag:
            self.cart_etag = new_etag

    def _reserve(self, cart_id):
        response = self._auth_call(
            "POST",
            "/v2/reservations",
            body={"cart_id": cart_id},
            name="/v2/reservations",
            expected=(202,),
            check=_check_status_url,
            cart_id=cart_id,
        )
        value = _json_object(response)
        status_url = _safe_path(str(value["status_url"]))

        for poll_number in range(5):
            if poll_number:
                gevent.sleep(0.05)
            poll = self._auth_call(
                "GET",
                status_url,
                name="/v2/reservations/status",
                expected=(200,),
                check=lambda r: (
                    (True, "")
                    if _json_object(r) is not None
                    else (False, "Expected reservation status JSON")
                ),
                cart_id=cart_id,
            )
            status_value = _json_object(poll)
            status_data = _data_object(status_value)
            status = status_data.get("status")

            if status == "ready":
                reservation_id = status_data.get("reservation_id")
                if reservation_id in (None, ""):
                    raise JourneyFailure("Ready reservation did not include an id")
                return str(reservation_id)
            if status == "failed":
                raise JourneyFailure("Reservation failed")
            if status != "pending":
                raise JourneyFailure("Unexpected reservation status")

        raise JourneyFailure("Reservation did not become ready after five polls")

    def _place_order(self, cart_id, reservation_id):
        self._refresh_cart_etag(cart_id)
        idempotency_key = "order-" + str(cart_id) + "-" + uuid.uuid4().hex
        self._auth_call(
            "POST",
            "/v2/orders",
            body={
                "cart_id": cart_id,
                "reservation_id": reservation_id,
            },
            headers={
                "Idempotency-Key": idempotency_key,
                "If-Match": self.cart_etag,
            },
            name="/v2/orders",
            expected=(201,),
            check=_check_order,
            cart_id=cart_id,
        )

    def _journey(self):
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None

        self._login()
        product_id, variant_id = self._select_item()
        grant_id = self._claim_grant()

        cart_response = self._auth_call(
            "POST",
            "/v2/carts",
            body={
                "product_id": product_id,
                "variant_id": variant_id,
                "grant_id": grant_id,
            },
            name="/v2/carts",
            expected=(201,),
            check=_check_json_keys("id"),
        )
        cart_value = _json_object(cart_response)
        self.cart_id = str(cart_value["id"])
        self.cart_etag = cart_response.headers.get("ETag")

        self._set_quantity(self.cart_id)
        reservation_id = self._reserve(self.cart_id)
        self._place_order(self.cart_id, reservation_id)

    @task
    def run_journeys(self):
        if self.instance_number > USER_COUNT:
            raise StopUser()

        try:
            for _ in range(ITERATIONS_PER_USER):
                self._journey()
        except JourneyFailure:
            raise StopUser()
        raise StopUser()


class FixedShape(LoadTestShape):
    def tick(self):
        if self.get_run_time() >= 5:
            return None
        return USER_COUNT, USER_COUNT

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.HttpProtocolBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;

import java.net.URI;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.function.Supplier;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
  private static final String BASE_URL =
      Optional.ofNullable(System.getenv("BASE_URL"))
          .filter(value -> !value.isBlank())
          .orElse("http://127.0.0.1:8000");

  private final HttpProtocolBuilder httpProtocol =
      http.baseUrl(BASE_URL)
          .acceptHeader("*/*")
          .disableFollowRedirect();

  public ModelSimulation() {
    ScenarioBuilder journey =
        scenario("reservation journey")
            .repeat(2)
            .on(
                exec(ModelSimulation::initializeJourney)
                    .exec(login())
                    .exec(catalogFlow())
                    .exec(challengeAndCreateCart())
                    .exec(
                        session -> {
                          if (empty(session, "cartId")) {
                            throw new AssertionError("Cart creation returned no cart ID");
                          }
                          return session.set("idempotencyKey", session.getString("cartId") + "-order");
                        })
                    .exec(readCart())
                    .exec(guarded("patchStatus", 200, ModelSimulation::patchWithOne412Retry))
                    .exec(reservation())
                    .exec(initializePolling())
                    .exec(
                        asLongAs(
                                session ->
                                    intValue(session, "pollCount") < 5
                                        && !"ready".equals(value(session, "jobStatus"))
                                        && !"failed".equals(value(session, "jobStatus")))
                            .on(pollReservation()))
                    .exec(assertReservationReady())
                    .exec(guarded("orderStatus", 201, ModelSimulation::placeOrder)));

    setUp(journey.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
  }

  private static Session initializeJourney(Session session) {
    return session
        .set("username", "bench")
        .set("csrf", "")
        .set("formCsrf", "")
        .set("loginLocation", "")
        .set("challengeAction", "")
        .set("challenge", "")
        .set("challengeLocation", "")
        .set("grantId", "")
        .set("cartId", "")
        .set("cartEtag", "")
        .set("patchEtag", "")
        .set("idempotencyKey", "")
        .set("productId", "")
        .set("variantId", "")
        .set("catalogProducts", new ArrayList<>())
        .set("pageProducts", new ArrayList<>())
        .set("nextUrl", "")
        .set("requestUrl", "")
        .set("reservationStatusUrl", "")
        .set("jobId", "")
        .set("jobStatus", "")
        .set("reservationId", "")
        .set("pollCount", 0)
        .set("lastError", "");
  }

  private static ChainBuilder login() {
    return exec(
            session ->
                session
                    .set("loginLocation", "")
                    .set("csrf", "")
                    .set("formCsrf", ""))
        .exec(
            http("login form")
                .get("/v2/login-form")
                .check(
                    status().is(200),
                    css("form input[name='csrf'][value]", "value")
                        .find()
                        .saveAs("formCsrf")))
        .exec(session -> session.set("csrf", session.getString("formCsrf")))
        .exec(
            http("login")
                .post("/v2/login")
                .header("Content-Type", "application/json")
                .body(
                    StringBody(
                        "{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{formCsrf}\"}"))
                .check(
                    status().in(200, 302),
                    header("Location").optional().saveAs("loginLocation"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
        .doIf(session -> !empty(session, "loginLocation"))
        .then(
            exec(
                http("login redirect")
                    .get("#{loginLocation}")
                    .check(status().is(200), jsonPath("$.csrf").optional().saveAs("csrf"))));
  }

  private static ChainBuilder catalogFlow() {
    return exec(
            http("catalog")
                .get("/v2/catalog")
                .check(
                    status().is(200),
                    jsonPath("$.data.products[*]").ofMap().findAll().saveAs("pageProducts"),
                    jsonPath("$.next").optional().saveAs("nextUrl")))
        .exec(ModelSimulation::mergeCatalogPage)
        .doIf(session -> !hasSelection(session) && !empty(session, "nextUrl"))
        .then(catalogNextPage())
        .doIf(session -> !hasSelection(session) && !empty(session, "nextUrl"))
        .then(catalogNextPage())
        .exec(
            session -> {
              if (!hasSelection(session)) {
                throw new AssertionError("No in-stock catalog variant found in the first three pages");
              }
              return session;
            });
  }

  private static ChainBuilder catalogNextPage() {
    return exec(
            session ->
                session
                    .set("requestUrl", session.getString("nextUrl"))
                    .set("nextUrl", ""))
        .exec(
            http("catalog page")
                .get("#{requestUrl}")
                .check(
                    status().is(200),
                    jsonPath("$.data.products[*]").ofMap().findAll().saveAs("pageProducts"),
                    jsonPath("$.next").optional().saveAs("nextUrl")))
        .exec(ModelSimulation::mergeCatalogPage);
  }

  private static Session mergeCatalogPage(Session session) {
    List<Object> products = new ArrayList<>();
    Object existing = session.get("catalogProducts");
    if (existing instanceof List<?>) {
      products.addAll((List<?>) existing);
    }

    Object page = session.get("pageProducts");
    if (page instanceof List<?>) {
      products.addAll((List<?>) page);
    }
    session = session.set("catalogProducts", products);

    if (!hasSelection(session)) {
      for (Object productObject : products) {
        if (!(productObject instanceof Map<?, ?>)) {
          continue;
        }
        Map<?, ?> product = (Map<?, ?>) productObject;
        Object productId = product.get("id");
        Object variantsObject = product.get("variants");
        if (productId == null || !(variantsObject instanceof List<?>)) {
          continue;
        }
        for (Object variantObject : (List<?>) variantsObject) {
          if (!(variantObject instanceof Map<?, ?>)) {
            continue;
          }
          Map<?, ?> variant = (Map<?, ?>) variantObject;
          Object inStock = variant.get("in_stock");
          boolean stocked =
              Boolean.TRUE.equals(inStock) || "true".equalsIgnoreCase(String.valueOf(inStock));
          Object variantId = variant.get("id");
          if (stocked && variantId != null) {
            return session
                .set("productId", String.valueOf(productId))
                .set("variantId", String.valueOf(variantId));
          }
        }
      }
    }
    return session;
  }

  private static ChainBuilder challengeAndCreateCart() {
    return guarded("cartStatus", 201, ModelSimulation::createCartAttempt);
  }

  private static ChainBuilder createCartAttempt() {
    return exec(
            http("challenge form")
                .get("/v2/challenge-form")
                .check(
                    status().is(200),
                    css("form[action^='/v2/challenges/']", "action")
                        .find()
                        .saveAs("challengeAction"),
                    css(
                            "form[action^='/v2/challenges/'] input[name='challenge']",
                            "value")
                        .find()
                        .saveAs("challenge")))
        .exec(
            http("claim challenge")
                .post("#{challengeAction}")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{\"challenge\":\"#{challenge}\"}"))
                .check(
                    status().is(302),
                    header("Location").saveAs("challengeLocation"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
        .exec(
            http("challenge grant")
                .get("#{challengeLocation}")
                .check(
                    status().is(200),
                    jsonPath("$.grant_id").saveAs("grantId"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
        .exec(
            session ->
                session
                    .set("lastError", "")
                    .set("cartId", "")
                    .set("cartEtag", ""))
        .exec(
            http("create cart")
                .post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(
                    StringBody(
                        "{\"product_id\":\"#{productId}\",\"variant_id\":\"#{variantId}\",\"grant_id\":\"#{grantId}\"}"))
                .check(
                    status().in(201, 401).saveAs("cartStatus"),
                    jsonPath("$.id").optional().saveAs("cartId"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.error").optional().saveAs("lastError"),
                    header("ETag").optional().saveAs("cartEtag")));
  }

  private static ChainBuilder readCart() {
    return exec(
        http("read cart")
            .get("/v2/carts/#{cartId}")
            .check(status().is(200), header("ETag").saveAs("cartEtag")));
  }

  private static ChainBuilder patchWithOne412Retry() {
    return exec(patchCartOnce())
        .doIf(session -> intValue(session, "patchStatus") == 412)
        .then(
            exec(
                    http("reread cart after 412")
                        .get("/v2/carts/#{cartId}")
                        .check(status().is(200), header("ETag").saveAs("cartEtag")))
                .exec(patchCartOnce()))
        .exec(
            session -> {
              int status = intValue(session, "patchStatus");
              if (status != 200 && status != 401) {
                throw new AssertionError("Cart PATCH failed after its single 412 retry");
              }
              return session;
            });
  }

  private static ChainBuilder patchCartOnce() {
    return exec(session -> session.set("patchEtag", ""))
        .exec(
            http("patch cart quantity")
                .patch("/v2/carts/#{cartId}")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("If-Match", "#{cartEtag}")
                .body(StringBody("{\"quantity\":1}"))
                .check(
                    status().in(200, 412, 401).saveAs("patchStatus"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.error").optional().saveAs("lastError"),
                    header("ETag").optional().saveAs("patchEtag")))
        .exec(
            session -> {
              if (!empty(session, "patchEtag")) {
                session = session.set("cartEtag", session.getString("patchEtag"));
              }
              return session;
            });
  }

  private static ChainBuilder reservation() {
    return guarded("reservationPostStatus", 202, ModelSimulation::postReservation);
  }

  private static ChainBuilder postReservation() {
    return exec(
            session ->
                session
                    .set("reservationStatusUrl", "")
                    .set("jobId", "")
                    .set("jobStatus", "")
                    .set("reservationId", "")
                    .set("lastError", ""))
        .exec(
            http("start reservation")
                .post("/v2/reservations")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{\"cart_id\":\"#{cartId}\"}"))
                .check(
                    status().in(202, 401).saveAs("reservationPostStatus"),
                    jsonPath("$.status_url").optional().saveAs("reservationStatusUrl"),
                    jsonPath("$.job_id").optional().saveAs("jobId"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.error").optional().saveAs("lastError")))
        .exec(ModelSimulation::extractJobId);
  }

  private static Session extractJobId(Session session) {
    if (!empty(session, "jobId") || empty(session, "reservationStatusUrl")) {
      return session;
    }
    try {
      String path = URI.create(session.getString("reservationStatusUrl")).getPath();
      String[] segments = path.split("/");
      int last = segments.length - 1;
      while (last >= 0 && segments[last].isEmpty()) {
        last--;
      }
      if (last >= 0 && "status".equals(segments[last])) {
        last--;
      }
      if (last >= 0) {
        session = session.set("jobId", segments[last]);
      }
      return session;
    } catch (RuntimeException exception) {
      throw new AssertionError("Could not extract the reservation job ID from status_url", exception);
    }
  }

  private static Session initializePolling(Session session) {
    return session.set("pollCount", 0).set("jobStatus", "pending");
  }

  private static ChainBuilder pollReservation() {
    return doIf(session -> intValue(session, "pollCount") > 0)
        .then(pause(Duration.ofMillis(50)))
        .exec(
            http("reservation status poll")
                .get("#{reservationStatusUrl}")
                .check(
                    status().is(200),
                    jsonPath("$.status").saveAs("jobStatus"),
                    jsonPath("$.reservation_id").optional().saveAs("reservationId"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
        .exec(session -> session.set("pollCount", intValue(session, "pollCount") + 1));
  }

  private static Session assertReservationReady(Session session) {
    if (!"ready".equals(value(session, "jobStatus"))) {
      throw new AssertionError(
          "Reservation job did not become ready; checkout is forbidden (status="
              + value(session, "jobStatus")
              + ")");
    }
    if (empty(session, "reservationId")) {
      throw new AssertionError("Ready reservation response had no reservation_id");
    }
    return session;
  }

  private static ChainBuilder placeOrder() {
    return exec(session -> session.set("lastError", ""))
        .exec(
            http("commit order")
                .post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "#{idempotencyKey}")
                .header("If-Match", "#{cartEtag}")
                .body(
                    StringBody(
                        "{\"cart_id\":\"#{cartId}\",\"reservation_id\":\"#{reservationId}\"}"))
                .check(
                    status().in(201, 401).saveAs("orderStatus"),
                    jsonPath("$.accepted").ofBoolean().optional().is(true),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.error").optional().saveAs("lastError")));
  }

  private static ChainBuilder guarded(
      String statusKey, int expectedStatus, Supplier<ChainBuilder> operation) {
    return exec(session -> session.set("lastError", ""))
        .exec(operation.get())
        .doIf(
                session ->
                    intValue(session, statusKey) == 401
                        && ("expired".equals(value(session, "lastError"))
                            || "session".equals(value(session, "lastError"))))
            .then(recoverAuthentication().exec(operation.get()))
        .exec(
            session -> {
              int actualStatus = intValue(session, statusKey);
              if (actualStatus != expectedStatus) {
                throw new AssertionError(
                    "Unexpected status for " + statusKey + ": " + actualStatus);
              }
              return session;
            });
  }

  private static ChainBuilder recoverAuthentication() {
    return exec(
            session ->
                session
                    .set("renewStatus", 0)
                    .set("renewError", "")
                    .set("lastError", ""))
        .exec(
            http("renew session")
                .post("/v2/session/renew")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(
                    status().in(200, 401).saveAs("renewStatus"),
                    jsonPath("$.error").optional().saveAs("renewError"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
        .doIf(
                session ->
                    intValue(session, "renewStatus") == 401
                        && "session".equals(value(session, "renewError")))
            .then(login())
        .exec(
            session -> {
              int status = intValue(session, "renewStatus");
              boolean renewed = status == 200;
              boolean relogged = status == 401 && "session".equals(value(session, "renewError"));
              if (!renewed && !relogged) {
                throw new AssertionError("Session renewal failed for a non-recoverable 401");
              }
              return session;
            })
        .doIf(session -> !empty(session, "cartId"))
        .then(recoverCart());
  }

  private static ChainBuilder recoverCart() {
    return exec(
        http("recover cart")
            .post("/v2/carts/#{cartId}/recover")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().is(200), jsonPath("$.csrf").optional().saveAs("csrf")));
  }

  private static boolean hasSelection(Session session) {
    return !empty(session, "productId") && !empty(session, "variantId");
  }

  private static boolean empty(Session session, String key) {
    Object value = session.get(key);
    return value == null || String.valueOf(value).isBlank();
  }

  private static String value(Session session, String key) {
    Object value = session.get(key);
    return value == null ? "" : String.valueOf(value);
  }

  private static int intValue(Session session, String key) {
    Object value = session.get(key);
    return value instanceof Number ? ((Number) value).intValue() : 0;
  }
}

