import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.net.URI;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Optional;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
  private static final String BASE_URL =
      Optional.ofNullable(System.getenv("BASE_URL"))
          .filter(value -> !value.isBlank())
          .orElse("http://127.0.0.1:8000");

  private final HttpProtocolBuilder httpProtocol =
      http.baseUrl(BASE_URL)
          .acceptHeader("*/*")
          .disableFollowRedirect();

  public ModelSimulation() {
    ScenarioBuilder journey =
        scenario("reservation journey")
            .repeat(2)
            .on(
                exec(ModelSimulation::initializeJourney)
                    .exec(login())
                    .exec(catalogFlow())
                    .exec(challengeAndCreateCart())
                    .exec(readCart())
                    .exec(patchCartWithOne412Retry())
                    .exec(startReservation())
                    .exec(ModelSimulation::initializePolling)
                    .asLongAs(
                            session ->
                                intValue(session, "pollCount") < 5
                                    && !"ready".equals(value(session, "jobStatus"))
                                    && !"failed".equals(value(session, "jobStatus")))
                        .on(pollReservation())
                    .exec(ModelSimulation::assertReservationReady)
                    .doIf(session -> "ready".equals(value(session, "jobStatus")))
                    .then(placeOrder()));

    setUp(journey.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
  }

  private static Session initializeJourney(Session session) {
    return session
        .set("username", "bench")
        .set("csrf", "")
        .set("formCsrf", "")
        .set("loginLocation", "")
        .set("challengeAction", "")
        .set("challenge", "")
        .set("challengeLocation", "")
        .set("grantId", "")
        .set("cartId", "")
        .set("cartEtag", "")
        .set("patchEtag", "")
        .set("idempotencyKey", "")
        .set("productId", "")
        .set("variantId", "")
        .set("catalogProducts", new ArrayList<>())
        .set("pageProducts", new ArrayList<>())
        .set("nextUrl", "")
        .set("requestUrl", "")
        .set("reservationStatusUrl", "")
        .set("jobId", "")
        .set("jobStatus", "")
        .set("reservationId", "")
        .set("pollCount", 0);
  }

  private static ChainBuilder login() {
    return exec(
            http("login form")
                .get("/v2/login-form")
                .check(
                    status().is(200),
                    css("input[name='csrf']", "value").find().saveAs("formCsrf")))
        .exec(session -> session.set("csrf", session.getString("formCsrf")))
        .exec(
            http("login")
                .post("/v2/login")
                .header("Content-Type", "application/json")
                .body(
                    StringBody(
                        "{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{formCsrf}\"}"))
                .check(
                    status().in(200, 302),
                    header("Location").optional().saveAs("loginLocation"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
        .doIf(session -> !empty(session, "loginLocation"))
        .then(
            exec(
                http("login redirect")
                    .get("#{loginLocation}")
                    .check(status().is(200), jsonPath("$.csrf").optional().saveAs("csrf"))));
  }

  private static ChainBuilder catalogFlow() {
    return exec(
            http("catalog")
                .get("/v2/catalog")
                .check(
                    status().is(200),
                    jsonPath("$.data.products[*]").ofMap().findAll().saveAs("pageProducts"),
                    jsonPath("$.next").optional().saveAs("nextUrl")))
        .exec(ModelSimulation::mergeCatalogPage)
        .doIf(session -> !hasSelection(session) && !empty(session, "nextUrl"))
        .then(catalogNextPage())
        .doIf(session -> !hasSelection(session) && !empty(session, "nextUrl"))
        .then(catalogNextPage())
        .exec(
            session -> {
              if (!hasSelection(session)) {
                throw new AssertionError(
                    "No in-stock catalog variant found in the first three pages");
              }
              return session;
            });
  }

  private static ChainBuilder catalogNextPage() {
    return exec(
            session ->
                session
                    .set("requestUrl", session.getString("nextUrl"))
                    .set("nextUrl", ""))
        .exec(
            http("catalog page")
                .get("#{requestUrl}")
                .check(
                    status().is(200),
                    jsonPath("$.data.products[*]").ofMap().findAll().saveAs("pageProducts"),
                    jsonPath("$.next").optional().saveAs("nextUrl")))
        .exec(ModelSimulation::mergeCatalogPage);
  }

  private static Session mergeCatalogPage(Session session) {
    List<Object> products = new ArrayList<>();
    Object existing = session.get("catalogProducts");
    if (existing instanceof List<?>) {
      products.addAll((List<?>) existing);
    }

    Object page = session.get("pageProducts");
    if (page instanceof List<?>) {
      products.addAll((List<?>) page);
    }
    session = session.set("catalogProducts", products);

    if (!hasSelection(session)) {
      for (Object productObject : products) {
        if (!(productObject instanceof Map<?, ?>)) {
          continue;
        }

        Map<?, ?> product = (Map<?, ?>) productObject;
        Object productId = product.get("id");
        Object variantsObject = product.get("variants");
        if (productId == null || !(variantsObject instanceof List<?>)) {
          continue;
        }

        for (Object variantObject : (List<?>) variantsObject) {
          if (!(variantObject instanceof Map<?, ?>)) {
            continue;
          }

          Map<?, ?> variant = (Map<?, ?>) variantObject;
          Object inStock = variant.get("in_stock");
          boolean stocked =
              Boolean.TRUE.equals(inStock)
                  || "true".equalsIgnoreCase(String.valueOf(inStock));
          Object variantId = variant.get("id");

          if (stocked && variantId != null) {
            return session
                .set("productId", String.valueOf(productId))
                .set("variantId", String.valueOf(variantId));
          }
        }
      }
    }
    return session;
  }

  private static ChainBuilder challengeAndCreateCart() {
    return exec(
            http("challenge form")
                .get("/v2/challenge-form")
                .check(
                    status().is(200),
                    css("form[action^='/v2/challenges/']", "action")
                        .find()
                        .saveAs("challengeAction"),
                    css(
                            "form[action^='/v2/challenges/'] input[name='challenge']",
                            "value")
                        .find()
                        .saveAs("challenge")))
        .exec(
            http("claim challenge")
                .post("#{challengeAction}")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{\"challenge\":\"#{challenge}\"}"))
                .check(
                    status().is(302),
                    header("Location").saveAs("challengeLocation"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
        .exec(
            http("challenge grant")
                .get("#{challengeLocation}")
                .check(
                    status().is(200),
                    jsonPath("$.grant_id").saveAs("grantId"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
        .exec(session -> session.set("cartId", "").set("cartEtag", ""))
        .exec(
            http("create cart")
                .post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(
                    StringBody(
                        "{\"product_id\":\"#{productId}\",\"variant_id\":\"#{variantId}\",\"grant_id\":\"#{grantId}\"}"))
                .check(
                    status().is(201),
                    jsonPath("$.id").saveAs("cartId"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    header("ETag").saveAs("cartEtag")))
        .exec(
            session ->
                session.set(
                    "idempotencyKey", session.getString("cartId") + "-order"));
  }

  private static ChainBuilder readCart() {
    return exec(
        http("read cart")
            .get("/v2/carts/#{cartId}")
            .check(status().is(200), header("ETag").saveAs("cartEtag")));
  }

  private static ChainBuilder patchCartWithOne412Retry() {
    return exec(patchCartOnce())
        .doIf(session -> intValue(session, "patchStatus") == 412)
        .then(
            exec(
                    http("reread cart after 412")
                        .get("/v2/carts/#{cartId}")
                        .check(status().is(200), header("ETag").saveAs("cartEtag")))
                .exec(patchCartOnce()))
        .exec(
            session -> {
              if (intValue(session, "patchStatus") != 200) {
                throw new AssertionError("Cart PATCH failed after its single 412 retry");
              }
              return session;
            });
  }

  private static ChainBuilder patchCartOnce() {
    return exec(session -> session.set("patchEtag", ""))
        .exec(
            http("patch cart quantity")
                .patch("/v2/carts/#{cartId}")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("If-Match", "#{cartEtag}")
                .body(StringBody("{\"quantity\":1}"))
                .check(
                    status().in(200, 412).saveAs("patchStatus"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    header("ETag").optional().saveAs("patchEtag")))
        .exec(
            session -> {
              if (!empty(session, "patchEtag")) {
                session = session.set("cartEtag", session.getString("patchEtag"));
              }
              return session;
            });
  }

  private static ChainBuilder startReservation() {
    return exec(
            session ->
                session
                    .set("reservationStatusUrl", "")
                    .set("jobId", "")
                    .set("jobStatus", "")
                    .set("reservationId", ""))
        .exec(
            http("start reservation")
                .post("/v2/reservations")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{\"cart_id\":\"#{cartId}\"}"))
                .check(
                    status().is(202),
                    jsonPath("$.status_url").saveAs("reservationStatusUrl"),
                    jsonPath("$.job_id").optional().saveAs("jobId"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
        .exec(ModelSimulation::extractJobId);
  }

  private static Session extractJobId(Session session) {
    if (!empty(session, "jobId")) {
      return session;
    }
    if (empty(session, "reservationStatusUrl")) {
      throw new AssertionError("202 reservation response had no status URL");
    }

    try {
      String path = URI.create(session.getString("reservationStatusUrl")).getPath();
      String[] segments = path.split("/");
      int last = segments.length - 1;
      while (last >= 0 && segments[last].isEmpty()) {
        last--;
      }
      if (last >= 0 && "status".equals(segments[last])) {
        last--;
      }
      if (last < 0) {
        throw new AssertionError("Could not extract a job ID from the status URL");
      }
      return session.set("jobId", segments[last]);
    } catch (IllegalArgumentException exception) {
      throw new AssertionError("Invalid reservation status URL", exception);
    }
  }

  private static Session initializePolling(Session session) {
    return session.set("pollCount", 0).set("jobStatus", "pending");
  }

  private static ChainBuilder pollReservation() {
    return pause(Duration.ofMillis(50))
        .exec(
            http("reservation status poll")
                .get("#{reservationStatusUrl}")
                .check(
                    status().is(200),
                    jsonPath("$.status").saveAs("jobStatus"),
                    jsonPath("$.reservation_id").optional().saveAs("reservationId"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
        .exec(session -> session.set("pollCount", intValue(session, "pollCount") + 1));
  }

  private static Session assertReservationReady(Session session) {
    if (!"ready".equals(value(session, "jobStatus"))) {
      throw new AssertionError(
          "Reservation is not ready; checkout is forbidden (status="
              + value(session, "jobStatus")
              + ")");
    }
    if (empty(session, "reservationId")) {
      throw new AssertionError("Ready reservation response had no reservation_id");
    }
    return session;
  }

  private static ChainBuilder placeOrder() {
    return exec(
        http("commit order")
            .post("/v2/orders")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .header("Idempotency-Key", "#{idempotencyKey}")
            .header("If-Match", "#{cartEtag}")
            .body(
                StringBody(
                    "{\"cart_id\":\"#{cartId}\",\"reservation_id\":\"#{reservationId}\"}"))
            .check(
                status().is(201),
                jsonPath("$.accepted").ofString().is("true"),
                jsonPath("$.csrf").optional().saveAs("csrf")));
  }

  private static boolean hasSelection(Session session) {
    return !empty(session, "productId") && !empty(session, "variantId");
  }

  private static boolean empty(Session session, String key) {
    Object value = session.get(key);
    return value == null || String.valueOf(value).isBlank();
  }

  private static String value(Session session, String key) {
    Object value = session.get(key);
    return value == null ? "" : String.valueOf(value);
  }

  private static int intValue(Session session, String key) {
    Object value = session.get(key);
    return value instanceof Number ? ((Number) value).intValue() : 0;
  }
}

import http from 'k6/http';
import { check, fail, sleep } from 'k6';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const MIN_POLL_INTERVAL = Math.max(0.05, Number(__ENV.POLL_INTERVAL || 0.05));

export const options = {
  scenarios: {
    reservation_journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
    },
  },
};

function requestParams(headers) {
  return { redirects: 0, headers: headers || {} };
}

function expectStatus(res, allowed, label) {
  const ok = check(res, {
    [label]: (r) => allowed.indexOf(r.status) !== -1,
  });
  if (!ok) {
    fail(`${label}: unexpected HTTP status ${res.status}`);
  }
}

function parseJson(res, label) {
  try {
    return res.json();
  } catch (_) {
    check(res, { [`${label}: valid JSON`]: () => false });
    fail(`${label}: response was not valid JSON`);
  }
}

function maybeJson(res) {
  try {
    return res.json();
  } catch (_) {
    return null;
  }
}

function headerValue(res, name) {
  const wanted = name.toLowerCase();
  const keys = Object.keys(res.headers || {});
  for (let i = 0; i < keys.length; i += 1) {
    if (keys[i].toLowerCase() === wanted) {
      const value = res.headers[keys[i]];
      return Array.isArray(value) ? value[0] : value;
    }
  }
  return null;
}

function resolveUrl(reference, relativeTo) {
  const resolved = new URL(reference, relativeTo || `${BASE_URL}/`);
  const base = new URL(`${BASE_URL}/`);
  if (resolved.protocol !== base.protocol || resolved.host !== base.host) {
    fail(`Refusing URL outside the configured target: ${resolved.toString()}`);
  }
  return resolved.toString();
}

function decodeHtml(value) {
  return String(value)
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');
}

function attributes(tag) {
  const result = Object.create(null);
  const text = tag.replace(/^<[^\s/>]+/i, '').replace(/\/?>$/, '');
  const re = /([^\s=/>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/g;
  let match;
  while ((match = re.exec(text)) !== null) {
    const key = match[1].toLowerCase();
    let value = match[2];
    if (value === undefined) value = match[3];
    if (value === undefined) value = match[4];
    if (value === undefined) value = '';
    result[key] = decodeHtml(value.replace(/\/$/, ''));
  }
  return result;
}

function inputValue(html, wantedName, label) {
  const tags = String(html).match(/<input\b[^>]*>/gi) || [];
  for (let i = 0; i < tags.length; i += 1) {
    const attrs = attributes(tags[i]);
    if (attrs.name === wantedName && attrs.value !== undefined && attrs.value !== '') {
      return attrs.value;
    }
  }
  fail(`${label}: input[name="${wantedName}"] not found`);
}

function getLoginCsrf(html) {
  return inputValue(html, 'csrf', 'login form');
}

function captureCsrf(ctx, res) {
  if (res.status < 400) {
    const body = maybeJson(res);
    if (body && body.csrf !== undefined && body.csrf !== null && body.csrf !== '') {
      ctx.csrf = body.csrf;
    }
  }
}

function login(ctx) {
  const formRes = http.get(`${BASE_URL}/v2/login-form`, requestParams());
  expectStatus(formRes, [200], 'load login form');
  const loginCsrf = getLoginCsrf(formRes.body);

  const loginRes = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({
      username: ctx.username,
      password: 'bench',
      csrf: loginCsrf,
    }),
    requestParams({ 'Content-Type': 'application/json' })
  );

  if (loginRes.status === 302) {
    const location = headerValue(loginRes, 'Location');
    if (!location) fail('login redirect did not include Location');
    const target = resolveUrl(location, `${BASE_URL}/v2/login`);
    const landing = http.get(target, requestParams());
    expectStatus(landing, [200], 'follow login redirect');
    const body = parseJson(landing, 'login redirect response');
    if (!body.csrf) fail('login redirect response did not include csrf');
    ctx.csrf = body.csrf;
  } else {
    expectStatus(loginRes, [200], 'login');
    const body = parseJson(loginRes, 'login response');
    if (!body.csrf) fail('login response did not include csrf');
    ctx.csrf = body.csrf;
  }
}

function recoverExistingCart(ctx) {
  if (!ctx.cartId) return;

  const res = http.post(
    `${BASE_URL}/v2/carts/${encodeURIComponent(ctx.cartId)}/recover`,
    JSON.stringify({}),
    requestParams({
      'Content-Type': 'application/json',
      'X-CSRF-Token': String(ctx.csrf),
    })
  );
  expectStatus(res, [200, 204], 'recover cart');
  captureCsrf(ctx, res);
}

function renewOrRelogin(ctx, originalError) {
  const renewRes = http.post(
    `${BASE_URL}/v2/session/renew`,
    JSON.stringify({}),
    requestParams({
      'Content-Type': 'application/json',
      'X-CSRF-Token': String(ctx.csrf),
    })
  );

  if (renewRes.status >= 200 && renewRes.status < 300) {
    const body = parseJson(renewRes, 'session renewal');
    if (body.csrf) ctx.csrf = body.csrf;
    if (!ctx.csrf) fail('session renewal did not provide a csrf token');
    recoverExistingCart(ctx);
    return;
  }

  const renewError = maybeJson(renewRes);
  if (originalError === 'session' || (renewError && renewError.error === 'session')) {
    login(ctx);
    recoverExistingCart(ctx);
    return;
  }

  fail(`session renewal failed with HTTP ${renewRes.status}`);
}

function authMutation(ctx, method, url, payload, extraHeaders, label, state) {
  const retryState = state || { authRetried: false };

  function send() {
    const headers = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': String(ctx.csrf),
    };
    const extra = extraHeaders || {};
    Object.keys(extra).forEach((key) => {
      if (extra[key] !== undefined && extra[key] !== null) {
        headers[key] = String(extra[key]);
      }
    });
    return http.request(
      method,
      url,
      JSON.stringify(payload),
      requestParams(headers)
    );
  }

  let res = send();
  if (res.status === 401) {
    const errorBody = maybeJson(res);
    const error = errorBody && errorBody.error;
    if (error === 'denied') {
      check(res, { [`${label}: denied is rejected`]: () => false });
      fail(`${label}: authorization denied`);
    }
    if (error !== 'expired' && error !== 'session') {
      check(res, { [`${label}: recognized authentication failure`]: () => false });
      fail(`${label}: unexpected 401 response`);
    }
    if (retryState.authRetried) {
      check(res, { [`${label}: authentication retry succeeds`]: () => false });
      fail(`${label}: authentication retry was already used`);
    }

    retryState.authRetried = true;
    renewOrRelogin(ctx, error);
    res = send();
  }

  captureCsrf(ctx, res);
  return res;
}

function extractCatalogProducts(body) {
  const data = body && body.data;
  if (data && Array.isArray(data.products)) return data.products;
  if (data && data.product) return [data.product];
  if (Array.isArray(body && body.products)) return body.products;
  if (data && Array.isArray(data)) return data;
  return [];
}

function nextCatalogUrl(body) {
  if (body && body.next !== undefined) return body.next;
  if (body && body.data && body.data.next !== undefined) return body.data.next;
  return null;
}

function chooseAvailableProduct() {
  let url = `${BASE_URL}/v2/catalog`;
  let products = [];

  for (let page = 0; page < 3 && url; page += 1) {
    const res = http.get(url, requestParams());
    expectStatus(res, [200], `load catalog page ${page + 1}`);
    const body = parseJson(res, `catalog page ${page + 1}`);
    products = products.concat(extractCatalogProducts(body));

    const next = nextCatalogUrl(body);
    if (next === null || next === undefined || next === '') {
      url = null;
    } else if (typeof next === 'string') {
      url = resolveUrl(next, url);
    } else {
      fail('catalog next value was not a relative URL or null');
    }
  }

  for (let i = 0; i < products.length; i += 1) {
    const product = products[i];
    if (!product || product.id === undefined || !Array.isArray(product.variants)) continue;
    for (let j = 0; j < product.variants.length; j += 1) {
      const variant = product.variants[j];
      if (variant && variant.id !== undefined && variant.in_stock === true) {
        return { productId: product.id, variantId: variant.id };
      }
    }
  }

  check(products, { 'catalog contains an in-stock product variant': () => false });
  fail('catalog contains no in-stock product variant');
}

function getChallengeDetails(html) {
  const forms = String(html).match(/<form\b[^>]*>/gi) || [];
  let action = null;
  for (let i = 0; i < forms.length; i += 1) {
    const attrs = attributes(forms[i]);
    if (attrs.action && /\/v2\/challenges\//i.test(attrs.action)) {
      action = attrs.action;
      break;
    }
  }
  if (!action) fail('challenge form action not found');
  return {
    action,
    challenge: inputValue(html, 'challenge', 'challenge form'),
  };
}

function obtainGrant(ctx) {
  const formRes = http.get(`${BASE_URL}/v2/challenge-form`, requestParams());
  expectStatus(formRes, [200], 'load challenge form');
  const details = getChallengeDetails(formRes.body);
  const actionUrl = resolveUrl(details.action, `${BASE_URL}/v2/challenge-form`);

  const challengeRes = authMutation(
    ctx,
    'POST',
    actionUrl,
    { challenge: details.challenge },
    {},
    'submit challenge',
    { authRetried: false }
  );
  expectStatus(challengeRes, [302], 'challenge redirect');
  const location = headerValue(challengeRes, 'Location');
  if (!location) fail('challenge redirect did not include Location');

  const grantUrl = resolveUrl(location, actionUrl);
  const grantRes = http.get(grantUrl, requestParams());
  expectStatus(grantRes, [200], 'load challenge grant');
  const grant = parseJson(grantRes, 'challenge grant');
  if (!grant.grant_id) fail('challenge grant response did not include grant_id');
  if (grant.csrf) ctx.csrf = grant.csrf;
  return grant.grant_id;
}

function getCartEtag(ctx) {
  const res = http.get(
    `${BASE_URL}/v2/carts/${encodeURIComponent(ctx.cartId)}`,
    requestParams()
  );
  expectStatus(res, [200], 'read cart');
  const etag = headerValue(res, 'ETag');
  if (etag) ctx.cartEtag = etag;
  if (!ctx.cartEtag) fail('cart response did not include an ETag');
}

function createAndUpdateCart(ctx, product, grantId) {
  const cartRes = authMutation(
    ctx,
    'POST',
    `${BASE_URL}/v2/carts`,
    {
      product_id: product.productId,
      variant_id: product.variantId,
      grant_id: grantId,
    },
    {},
    'create cart',
    { authRetried: false }
  );
  expectStatus(cartRes, [201], 'create cart');
  const cart = parseJson(cartRes, 'cart creation response');
  if (cart.id === undefined || cart.id === null) fail('cart response did not include id');
  ctx.cartId = cart.id;
  ctx.cartEtag = headerValue(cartRes, 'ETag');

  getCartEtag(ctx);
  const patchState = { authRetried: false };
  const patchHeaders = () => ({ 'If-Match': ctx.cartEtag });

  let patchRes = authMutation(
    ctx,
    'PATCH',
    `${BASE_URL}/v2/carts/${encodeURIComponent(ctx.cartId)}`,
    { quantity: 1 },
    patchHeaders(),
    'update cart quantity',
    patchState
  );

  if (patchRes.status === 412) {
    getCartEtag(ctx);
    patchRes = authMutation(
      ctx,
      'PATCH',
      `${BASE_URL}/v2/carts/${encodeURIComponent(ctx.cartId)}`,
      { quantity: 1 },
      patchHeaders(),
      'retry cart quantity update',
      patchState
    );
  }

  expectStatus(patchRes, [200, 204], 'update cart quantity');
  const updatedEtag = headerValue(patchRes, 'ETag');
  if (updatedEtag) ctx.cartEtag = updatedEtag;
  getCartEtag(ctx);
}

function identifyJob(job, statusUrl) {
  if (job.job_id !== undefined && job.job_id !== null) return String(job.job_id);
  if (job.id !== undefined && job.id !== null) return String(job.id);

  const match = String(statusUrl).match(/\/jobs?\/([^/?#]+)/i);
  if (match) return decodeURIComponent(match[1]);

  const queryMatch = String(statusUrl).match(/[?&](?:job_id|id)=([^&#]+)/i);
  if (queryMatch) return decodeURIComponent(queryMatch[1]);

  return null;
}

function obtainReservation(ctx) {
  const submitRes = authMutation(
    ctx,
    'POST',
    `${BASE_URL}/v2/reservations`,
    { cart_id: ctx.cartId },
    {},
    'submit reservation job',
    { authRetried: false }
  );
  expectStatus(submitRes, [202], 'submit reservation job');
  const job = parseJson(submitRes, 'reservation job response');
  if (!job.status_url) fail('202 reservation response did not include status_url');

  const statusUrl = resolveUrl(job.status_url, `${BASE_URL}/v2/reservations`);
  const jobId = identifyJob(job, statusUrl);
  check(job, {
    '202 reservation job and dynamic status URL identified': () =>
      Boolean(statusUrl) && (jobId !== null || Boolean(job.status_url)),
  });

  let latest = null;
  for (let poll = 0; poll < 5; poll += 1) {
    if (poll > 0) sleep(MIN_POLL_INTERVAL);
    const statusRes = http.get(statusUrl, requestParams());
    expectStatus(statusRes, [200], `poll reservation job ${poll + 1}`);
    latest = parseJson(statusRes, `reservation job status ${poll + 1}`);

    if (latest.status === 'ready') break;
    if (latest.status === 'failed') break;
    if (latest.status !== 'pending') {
      check(latest, { 'reservation job has a recognized status': () => false });
      fail(`reservation job returned unexpected status: ${latest.status}`);
    }
  }

  const ready = Boolean(
    latest &&
      latest.status === 'ready' &&
      latest.reservation_id !== undefined &&
      latest.reservation_id !== null &&
      latest.reservation_id !== ''
  );
  check(latest || {}, {
    'reservation job becomes ready with reservation_id': () => ready,
  });
  if (!ready) {
    fail('reservation job did not become ready; checkout will not be attempted');
  }
  return latest.reservation_id;
}

function commitOrder(ctx, reservationId) {
  const headers = {
    'Idempotency-Key': `order-cart-${ctx.cartId}`,
  };
  if (ctx.cartEtag) headers['If-Match'] = ctx.cartEtag;

  const orderRes = authMutation(
    ctx,
    'POST',
    `${BASE_URL}/v2/orders`,
    {
      cart_id: ctx.cartId,
      reservation_id: reservationId,
    },
    headers,
    'commit order',
    { authRetried: false }
  );

  if (orderRes.status === 200) {
    const rejected = parseJson(orderRes, 'order response');
    if (rejected.accepted === false) {
      check(rejected, { 'order is accepted': (body) => body.accepted === true });
      fail('order was not accepted');
    }
  }

  expectStatus(orderRes, [201], 'commit order');
  const order = parseJson(orderRes, 'committed order response');
  if (order.accepted !== true) {
    check(order, { 'committed order is accepted': (body) => body.accepted === true });
    fail('order response did not confirm acceptance');
  }
  check(order, { 'one order committed for this journey': (body) => body.accepted === true });
}

export default function () {
  const ctx = {
    username: `bench-${__VU}`,
    csrf: null,
    cartId: null,
    cartEtag: null,
  };

  login(ctx);
  const product = chooseAvailableProduct();
  const grantId = obtainGrant(ctx);
  createAndUpdateCart(ctx, product, grantId);

  const reservationId = obtainReservation(ctx);
  commitOrder(ctx, reservationId);
}

from html.parser import HTMLParser
import itertools
import os
from urllib.parse import parse_qs, unquote, urljoin, urlparse

from gevent import sleep
from locust import HttpUser, LoadTestShape, StopUser, task


BASE_URL = os.environ["BASE_URL"]
USER_COUNT = 2
ITERATIONS_PER_USER = 2
MAX_JOB_POLLS = 5
POLL_INTERVAL = 0.05


class FormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self._current_form = None
        self.inputs = []

    def handle_starttag(self, tag, attrs):
        attrs = {str(key).lower(): value for key, value in attrs}
        if tag.lower() == "form":
            self._current_form = {"attrs": attrs, "inputs": []}
            self.forms.append(self._current_form)
        elif tag.lower() == "input":
            item = {
                "attrs": attrs,
                "form": self._current_form,
            }
            self.inputs.append(item)
            if self._current_form is not None:
                self._current_form["inputs"].append(item)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self._current_form = None

    def input_value(self, name):
        for item in self.inputs:
            attrs = item["attrs"]
            if attrs.get("name") == name and attrs.get("value") is not None:
                return attrs["value"]
        return None

    def challenge_form(self):
        for form in self.forms:
            action = form["attrs"].get("action")
            if not action:
                continue
            challenge = None
            for item in form["inputs"]:
                attrs = item["attrs"]
                if attrs.get("name") == "challenge":
                    challenge = attrs.get("value")
                    break
            if challenge is not None:
                return action, challenge
        return None, None


class ReservationUser(HttpUser):
    host = BASE_URL
    network_timeout = 15
    connection_timeout = 5

    finished_users = 0
    account_sequence = itertools.count(1)

    def on_start(self):
        account_number = (next(type(self).account_sequence) - 1) % 16 + 1
        self.username = f"bench-{account_number}"
        self.csrf = None

    @staticmethod
    def _json(response):
        try:
            value = response.json()
            return value if isinstance(value, dict) else None
        except Exception:
            return None

    def _local_path(self, url):
        base = self.host.rstrip("/") + "/"
        base_parts = urlparse(base)
        absolute = urljoin(base, str(url))
        parts = urlparse(absolute)
        if parts.scheme != base_parts.scheme or parts.netloc != base_parts.netloc:
            raise ValueError("Refusing to request a URL outside BASE_URL")
        return parts.path or "/", parts.query

    def _request_url(self, url):
        path, query = self._local_path(url)
        return f"{path}?{query}" if query else path

    def _update_csrf(self, data):
        if isinstance(data, dict) and isinstance(data.get("csrf"), str) and data["csrf"]:
            self.csrf = data["csrf"]

    def _public_json(self, method, url, name, body=None, validator=None):
        kwargs = {
            "name": name,
            "catch_response": True,
            "allow_redirects": False,
        }
        if body is not None:
            kwargs["json"] = body

        with self.client.request(method, self._request_url(url), **kwargs) as response:
            data = self._json(response)
            issue = None
            if response.status_code != 200:
                issue = f"Expected HTTP 200, got {response.status_code}"
            elif data is None:
                issue = "Expected a JSON object"
            elif validator is not None:
                issue = validator(response, data)

            if issue:
                response.failure(issue)
            else:
                response.success()

        return response, data, issue is None

    def _login(self):
        with self.client.get(
            "/v2/login-form",
            name="/v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as response:
            issue = None
            parser = FormParser()
            if response.status_code != 200:
                issue = f"Login form returned HTTP {response.status_code}"
            else:
                parser.feed(response.text)
                if not parser.input_value("csrf"):
                    issue = "Login form did not contain input[name=csrf]"
            if issue:
                response.failure(issue)
            else:
                response.success()

        if issue:
            return False

        login_csrf = parser.input_value("csrf")
        with self.client.post(
            "/v2/login",
            name="/v2/login",
            json={
                "username": self.username,
                "password": "bench",
                "csrf": login_csrf,
            },
            catch_response=True,
            allow_redirects=False,
        ) as response:
            data = self._json(response)
            location = response.headers.get("Location")
            if response.status_code == 302 and location:
                response.success()
                redirect_location = location
                direct_csrf = None
            elif response.status_code == 200 and data and data.get("csrf"):
                response.success()
                redirect_location = None
                direct_csrf = data["csrf"]
            else:
                response.failure("Login did not return a CSRF token or a valid redirect")
                return False

        if redirect_location:
            _, data, ok = self._public_json(
                "GET", redirect_location, "/v2/login-redirect"
            )
            if not ok or not data.get("csrf"):
                return False
            self.csrf = data["csrf"]
        else:
            self.csrf = direct_csrf

        return bool(self.csrf)

    def _simple_auth_post(self, path, name, body):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf

        with self.client.post(
            self._request_url(path),
            name=name,
            json=body,
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as response:
            data = self._json(response)
            if 200 <= response.status_code < 300:
                self._update_csrf(data)
                response.success()
                return True
            if response.status_code == 401:
                # A renewal can legitimately be rejected for a revoked session.
                response.success()
                return False
            response.failure(f"Unexpected HTTP {response.status_code}")
            return False

    def _recover_session(self, cart_id=None):
        renewed = self._simple_auth_post("/v2/session/renew", "/v2/session/renew", {})
        if not renewed:
            if not self._login():
                return False

        if cart_id is not None:
            return self._simple_auth_post(
                f"/v2/carts/{cart_id}/recover",
                "/v2/carts/[cart_id]/recover",
                {},
            )
        return True

    def _auth_request(
        self,
        method,
        path,
        name,
        body=None,
        headers=None,
        expected=(200,),
        validator=None,
        cart_id=None,
        request_counter=None,
        retry_wait=0.0,
    ):
        auth_retries = 0

        while True:
            if request_counter is not None:
                if request_counter[0] >= MAX_JOB_POLLS:
                    return None, None, False
                request_counter[0] += 1

            request_headers = dict(headers or {})
            if method.upper() != "GET" and self.csrf:
                request_headers["X-CSRF-Token"] = self.csrf

            kwargs = {
                "name": name,
                "headers": request_headers,
                "catch_response": True,
                "allow_redirects": False,
            }
            if body is not None:
                kwargs["json"] = body

            retry_after_auth = False
            response_data = None

            with self.client.request(
                method,
                self._request_url(path),
                **kwargs,
            ) as response:
                response_data = self._json(response)

                if response.status_code == 401:
                    error = response_data.get("error") if response_data else None
                    is_recoverable = error in ("expired", "session")
                    budget_available = (
                        request_counter is None
                        or request_counter[0] < MAX_JOB_POLLS
                    )
                    if is_recoverable and auth_retries == 0 and budget_available:
                        response.success()
                        retry_after_auth = True
                    elif is_recoverable and auth_retries == 0:
                        response.success()
                    else:
                        response.failure(
                            f"Authentication assertion failed (error={error!r})"
                        )
                elif response.status_code in expected:
                    self._update_csrf(response_data)
                    issue = validator(response, response_data) if validator else None
                    if issue:
                        response.failure(issue)
                    else:
                        response.success()
                else:
                    response.failure(f"Unexpected HTTP {response.status_code}")

            if retry_after_auth:
                if not self._recover_session(cart_id):
                    return response, response_data, False
                auth_retries += 1
                if retry_wait:
                    sleep(retry_wait)
                continue

            if response.status_code == 401:
                error = response_data.get("error") if response_data else None
                if error in ("expired", "session") and auth_retries == 0:
                    return response, response_data, False

            return response, response_data, (
                response.status_code in expected
                and (validator(response, response_data) if validator else None) is None
            )

    def _catalog_choice(self):
        page_url = "/v2/catalog"
        for _ in range(3):
            response, data, ok = self._public_json(
                "GET", page_url, "/v2/catalog"
            )
            if not ok:
                return None

            products = []
            container = data.get("data")
            if isinstance(container, dict):
                listed = container.get("products")
                if isinstance(listed, list):
                    products.extend(listed)
                elif isinstance(container.get("product"), dict):
                    products.append(container["product"])

            if isinstance(data.get("products"), list):
                products.extend(data["products"])
            elif isinstance(data.get("product"), dict):
                products.append(data["product"])

            for product in products:
                if not isinstance(product, dict) or product.get("id") is None:
                    continue
                variants = product.get("variants")
                if not isinstance(variants, list):
                    continue
                for variant in variants:
                    if (
                        isinstance(variant, dict)
                        and variant.get("id") is not None
                        and variant.get("in_stock") is True
                    ):
                        return product["id"], variant["id"]

            next_url = data.get("next")
            if not next_url:
                return None
            page_url = self._request_url(next_url)

        return None

    def _challenge_grant(self):
        parsed_form = {}

        def check_form(response, _data):
            parser = FormParser()
            parser.feed(response.text)
            action, challenge = parser.challenge_form()
            if not action or challenge is None:
                return "Challenge form/action/input was not found"
            try:
                action_path = self._request_url(action)
            except ValueError:
                return "Challenge action is outside BASE_URL"
            if not action_path.startswith("/v2/challenges/"):
                return "Unexpected challenge form action"
            parsed_form["action"] = action_path
            parsed_form["challenge"] = challenge
            return None

        _, _, ok = self._auth_request(
            "GET",
            "/v2/challenge-form",
            "/v2/challenge-form",
            expected=(200,),
            validator=check_form,
        )
        if not ok:
            return None

        def check_redirect(response, _data):
            return None if response.headers.get("Location") else "Challenge response lacked Location"

        _, _, ok = self._auth_request(
            "POST",
            parsed_form["action"],
            "/v2/challenges/[id]",
            body={"challenge": parsed_form["challenge"]},
            expected=(302,),
            validator=check_redirect,
        )
        if not ok:
            return None

        location = response.headers.get("Location")
        if not location:
            return None

        def check_grant(_response, data):
            return None if data.get("grant_id") is not None else "Grant response lacked grant_id"

        _, data, ok = self._auth_request(
            "GET",
            location,
            "/v2/challenge-claim",
            expected=(200,),
            validator=check_grant,
        )
        if not ok or not data:
            return None
        return data["grant_id"]

    def _create_cart(self, product_id, variant_id, grant_id):
        body = {
            "product_id": product_id,
            "variant_id": variant_id,
            "grant_id": grant_id,
        }

        def check_cart(_response, data):
            return None if data.get("id") is not None else "Cart response lacked id"

        _, data, ok = self._auth_request(
            "POST",
            "/v2/carts",
            "/v2/carts",
            body=body,
            expected=(201,),
            validator=check_cart,
        )
        return data.get("id") if ok and data else None

    def _cart_etag(self, cart_id):
        _, _, ok = self._auth_request(
            "GET",
            f"/v2/carts/{cart_id}",
            "/v2/carts/[cart_id]",
            expected=(200,),
        )
        # The response is returned by the helper; fetch it directly here so the
        # ETag is captured from the same authenticated GET.
        if not ok:
            return None
        response, _, ok = self._auth_request(
            "GET",
            f"/v2/carts/{cart_id}",
            "/v2/carts/[cart_id]",
            expected=(200,),
        )
        if not ok or response is None:
            return None
        return response.headers.get("ETag")

    def _set_cart_quantity(self, cart_id):
        for attempt in range(2):
            etag = self._cart_etag(cart_id)
            if not etag:
                return None

            response, _, ok = self._auth_request(
                "PATCH",
                f"/v2/carts/{cart_id}",
                "/v2/carts/[cart_id]",
                body={"quantity": 1},
                headers={"If-Match": etag},
                expected=(200, 412),
            )
            if not ok:
                return None
            if response.status_code == 412:
                if attempt == 0:
                    continue
                return None

            return self._cart_etag(cart_id)

        return None

    def _job_id_from_response(self, data, status_url):
        job = data.get("job")
        job_id = data.get("job_id") or data.get("id")
        if job_id is None and isinstance(job, dict):
            job_id = job.get("id") or job.get("job_id")
        if job_id is not None:
            return str(job_id)

        parts = urlparse(urljoin(self.host.rstrip("/") + "/", str(status_url)))
        query = parse_qs(parts.query)
        for key in ("job_id", "id"):
            if query.get(key):
                return query[key][0]

        segments = [unquote(piece) for piece in parts.path.strip("/").split("/") if piece]
        for marker in ("jobs", "reservation-jobs", "reservation_jobs"):
            if marker in segments:
                index = segments.index(marker)
                if index + 1 < len(segments):
                    return segments[index + 1]
        if segments and segments[-1].lower() != "status":
            return segments[-1]
        if len(segments) > 1 and segments[-1].lower() == "status":
            return segments[-2]
        return None

    def _reservation(self, cart_id):
        def check_job(_response, data):
            status_url = data.get("status_url")
            if not status_url:
                return "202 reservation response lacked status_url"
            try:
                self._request_url(status_url)
            except ValueError:
                return "Reservation status URL is outside BASE_URL"
            if not self._job_id_from_response(data, status_url):
                return "202 reservation response lacked an extractable job ID"
            return None

        _, data, ok = self._auth_request(
            "POST",
            "/v2/reservations",
            "/v2/reservations",
            body={"cart_id": cart_id},
            expected=(202,),
            validator=check_job,
            cart_id=cart_id,
        )
        if not ok or not data:
            return None

        status_url = data["status_url"]
        job_id = self._job_id_from_response(data, status_url)
        poll_counter = [0]

        while poll_counter[0] < MAX_JOB_POLLS:
            if poll_counter[0]:
                sleep(max(POLL_INTERVAL, 0.05))

            def check_status(_response, result):
                reported_job = result.get("job_id")
                if reported_job is None and isinstance(result.get("job"), dict):
                    reported_job = result["job"].get("id")
                if reported_job is not None and str(reported_job) != job_id:
                    return "Polled status did not belong to the submitted job"

                state = result.get("status")
                if state == "ready":
                    if result.get("reservation_id") is None:
                        return "Ready job lacked reservation_id"
                    return None
                if state == "pending":
                    if poll_counter[0] >= MAX_JOB_POLLS:
                        return "Reservation job remained pending after five polls"
                    return None
                if state == "failed":
                    return "Reservation job failed"
                return f"Unexpected reservation job status: {state!r}"

            response, result, ok = self._auth_request(
                "GET",
                status_url,
                "/v2/reservations/status",
                expected=(200,),
                validator=check_status,
                cart_id=cart_id,
                request_counter=poll_counter,
                retry_wait=max(POLL_INTERVAL, 0.05),
            )
            if not ok or not result:
                return None
            if result.get("status") == "ready":
                return result.get("reservation_id")

        return None

    def _work(self):
        scheduled_retries = 0
        auth_retries = 0

        while True:
            response, data, ok = self._auth_request(
                "POST",
                "/v2/work",
                "/v2/work",
                body={},
                expected=(200, 429),
                validator=lambda r, d: (
                    None
                    if (
                        r.status_code == 429
                        and self._retry_after_is_one(r)
                    )
                    or (
                        r.status_code == 200
                        and d.get("ok") is True
                    )
                    else "Unexpected /v2/work response"
                ),
            )

            if response is None:
                return False

            if response.status_code == 401:
                if auth_retries == 0:
                    auth_retries += 1
                    continue
                return False

            if response.status_code == 200:
                return ok

            if response.status_code != 429 or not ok:
                return False
            if scheduled_retries >= 4:
                return False

            scheduled_retries += 1
            sleep(1.0)

    @staticmethod
    def _retry_after_is_one(response):
        value = response.headers.get("Retry-After", "").strip()
        try:
            return float(value) == 1.0
        except (TypeError, ValueError):
            return False

    def _journey(self):
        self.csrf = None
        if not self._login():
            return

        # Work failures are recorded on their own samples; checkout remains independent.
        self._work()

        choice = self._catalog_choice()
        if not choice:
            return
        product_id, variant_id = choice

        grant_id = self._challenge_grant()
        if grant_id is None:
            return

        cart_id = self._create_cart(product_id, variant_id, grant_id)
        if cart_id is None:
            return

        etag = self._set_cart_quantity(cart_id)
        if not etag:
            return

        reservation_id = self._reservation(cart_id)
        if reservation_id is None:
            return

        def check_order(_response, data):
            if data.get("accepted") is not True:
                return "Order was not accepted"
            if data.get("id") is None:
                return "Accepted order response lacked id"
            return None

        self._auth_request(
            "POST",
            "/v2/orders",
            "/v2/orders",
            body={
                "cart_id": cart_id,
                "reservation_id": reservation_id,
            },
            headers={
                "If-Match": etag,
                "Idempotency-Key": f"order-{cart_id}",
            },
            expected=(200, 201),
            validator=check_order,
            cart_id=cart_id,
        )

    @task
    def execute_iterations(self):
        try:
            for _ in range(ITERATIONS_PER_USER):
                try:
                    self._journey()
                except Exception:
                    # Request assertions are reported on their native samples.
                    # Keep the user lifecycle bounded even if a journey aborts.
                    pass
        finally:
            type(self).finished_users += 1
        raise StopUser()


class ReservationShape(LoadTestShape):
    def tick(self):
        finished = ReservationUser.finished_users
        if finished >= USER_COUNT:
            return None
        return USER_COUNT - finished, USER_COUNT

