from html.parser import HTMLParser
import itertools
import os
from urllib.parse import parse_qs, unquote, urljoin, urlparse

from gevent import sleep
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


USER_COUNT = 2
ITERATIONS_PER_USER = 2
MAX_JOB_POLLS = 5
MIN_POLL_INTERVAL = 0.05


class FormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self.inputs = []
        self.current_form = None

    def handle_starttag(self, tag, attrs):
        attrs = {str(key).lower(): value for key, value in attrs}
        if tag.lower() == "form":
            self.current_form = {"attrs": attrs, "inputs": []}
            self.forms.append(self.current_form)
        elif tag.lower() == "input":
            item = {"attrs": attrs}
            self.inputs.append(item)
            if self.current_form is not None:
                self.current_form["inputs"].append(item)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self.current_form = None

    def input_value(self, name):
        for item in self.inputs:
            attrs = item["attrs"]
            if attrs.get("name") == name and attrs.get("value") is not None:
                return attrs["value"]
        return None

    def challenge_form(self):
        for form in self.forms:
            action = form["attrs"].get("action")
            if not action:
                continue
            for item in form["inputs"]:
                attrs = item["attrs"]
                if attrs.get("name") == "challenge":
                    return action, attrs.get("value")
        return None, None


class ReservationUser(HttpUser):
    host = os.environ["BASE_URL"]
    network_timeout = 15
    connection_timeout = 5

    finished_users = 0
    account_sequence = itertools.count(1)

    def on_start(self):
        account_number = (next(type(self).account_sequence) - 1) % 16 + 1
        self.username = f"bench-{account_number}"
        self.csrf = None

    def _request_url(self, url):
        base = self.host.rstrip("/") + "/"
        base_parts = urlparse(base)
        absolute = urljoin(base, str(url))
        parts = urlparse(absolute)
        if parts.scheme != base_parts.scheme or parts.netloc != base_parts.netloc:
            raise ValueError("Refusing to request a URL outside BASE_URL")
        path = parts.path or "/"
        return f"{path}?{parts.query}" if parts.query else path

    @staticmethod
    def _json(response):
        try:
            result = response.json()
            return result if isinstance(result, dict) else None
        except Exception:
            return None

    def _update_csrf(self, data):
        if isinstance(data, dict) and isinstance(data.get("csrf"), str) and data["csrf"]:
            self.csrf = data["csrf"]

    def _public_json(self, method, url, name, body=None, validator=None):
        kwargs = {
            "name": name,
            "catch_response": True,
            "allow_redirects": False,
        }
        if body is not None:
            kwargs["json"] = body

        with self.client.request(method, self._request_url(url), **kwargs) as response:
            data = self._json(response)
            issue = None
            if response.status_code != 200:
                issue = f"Expected HTTP 200, got {response.status_code}"
            elif data is None:
                issue = "Expected a JSON object"
            elif validator is not None:
                issue = validator(response, data)

            if issue:
                response.failure(issue)
            else:
                response.success()

        return response, data, issue is None

    def _login(self):
        with self.client.get(
            "/v2/login-form",
            name="/v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as response:
            parser = FormParser()
            issue = None
            if response.status_code != 200:
                issue = f"Login form returned HTTP {response.status_code}"
            else:
                parser.feed(response.text)
                if not parser.input_value("csrf"):
                    issue = "Login form did not contain input[name=csrf]"

            if issue:
                response.failure(issue)
            else:
                response.success()

        if issue:
            return False

        with self.client.post(
            "/v2/login",
            name="/v2/login",
            json={
                "username": self.username,
                "password": "bench",
                "csrf": parser.input_value("csrf"),
            },
            catch_response=True,
            allow_redirects=False,
        ) as response:
            data = self._json(response)
            location = response.headers.get("Location")

            if response.status_code == 302 and location:
                response.success()
                redirect_location = location
                direct_csrf = None
            elif response.status_code == 200 and data and data.get("csrf"):
                response.success()
                redirect_location = None
                direct_csrf = data["csrf"]
            else:
                response.failure("Login did not return a CSRF token or valid redirect")
                return False

        if redirect_location:
            _, data, ok = self._public_json(
                "GET", redirect_location, "/v2/login-redirect"
            )
            if not ok or not data.get("csrf"):
                return False
            self.csrf = data["csrf"]
        else:
            self.csrf = direct_csrf

        return bool(self.csrf)

    def _recovery_post(self, path, name, body):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf

        with self.client.post(
            self._request_url(path),
            name=name,
            json=body,
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as response:
            data = self._json(response)
            if 200 <= response.status_code < 300:
                self._update_csrf(data)
                response.success()
                return True

            if response.status_code == 401:
                error = data.get("error") if data else None
                if error in ("expired", "session"):
                    response.success()
                    return False

            response.failure(f"Unexpected recovery response HTTP {response.status_code}")
            return False

    def _recover_session(self, cart_id=None):
        renewed = self._recovery_post(
            "/v2/session/renew", "/v2/session/renew", {}
        )
        if not renewed and not self._login():
            return False

        if cart_id is not None:
            return self._recovery_post(
                f"/v2/carts/{cart_id}/recover",
                "/v2/carts/[cart_id]/recover",
                {},
            )
        return True

    def _auth_request(
        self,
        method,
        url,
        name,
        body=None,
        headers=None,
        expected=(200,),
        validator=None,
        cart_id=None,
        request_counter=None,
        retry_wait=0.0,
    ):
        auth_retries = 0

        while True:
            if request_counter is not None:
                if request_counter[0] >= MAX_JOB_POLLS:
                    return None, None, False
                request_counter[0] += 1

            request_headers = dict(headers or {})
            if method.upper() != "GET" and self.csrf:
                request_headers["X-CSRF-Token"] = self.csrf

            kwargs = {
                "name": name,
                "headers": request_headers,
                "catch_response": True,
                "allow_redirects": False,
            }
            if body is not None:
                kwargs["json"] = body

            retry_after_recovery = False
            attempt_ok = False

            with self.client.request(
                method, self._request_url(url), **kwargs
            ) as response:
                data = self._json(response)

                if response.status_code == 401:
                    error = data.get("error") if data else None
                    recoverable = error in ("expired", "session")
                    budget_available = (
                        request_counter is None
                        or request_counter[0] < MAX_JOB_POLLS
                    )

                    if recoverable and auth_retries == 0 and budget_available:
                        response.success()
                        retry_after_recovery = True
                    elif recoverable and auth_retries == 0:
                        response.success()
                    else:
                        response.failure(
                            f"Authentication assertion failed (error={error!r})"
                        )
                elif response.status_code in expected:
                    self._update_csrf(data)
                    issue = validator(response, data) if validator else None
                    if issue:
                        response.failure(issue)
                    else:
                        response.success()
                        attempt_ok = True
                else:
                    response.failure(f"Unexpected HTTP {response.status_code}")

            if retry_after_recovery:
                if not self._recover_session(cart_id):
                    return response, data, False
                auth_retries += 1
                if retry_wait:
                    sleep(retry_wait)
                continue

            return response, data, attempt_ok

    def _catalog_choice(self):
        page_url = "/v2/catalog"

        for _ in range(3):
            _, data, ok = self._public_json("GET", page_url, "/v2/catalog")
            if not ok:
                return None

            products = []
            container = data.get("data")
            if isinstance(container, dict):
                if isinstance(container.get("products"), list):
                    products.extend(container["products"])
                elif isinstance(container.get("product"), dict):
                    products.append(container["product"])

            if isinstance(data.get("products"), list):
                products.extend(data["products"])
            elif isinstance(data.get("product"), dict):
                products.append(data["product"])

            for product in products:
                if not isinstance(product, dict) or product.get("id") is None:
                    continue
                variants = product.get("variants")
                if not isinstance(variants, list):
                    continue
                for variant in variants:
                    if (
                        isinstance(variant, dict)
                        and variant.get("id") is not None
                        and variant.get("in_stock") is True
                    ):
                        return product["id"], variant["id"]

            next_url = data.get("next")
            if not next_url and isinstance(container, dict):
                next_url = container.get("next")
            if not next_url:
                return None
            page_url = self._request_url(next_url)

        return None

    def _challenge_grant(self):
        parsed_form = {}

        def validate_form(response, _data):
            parser = FormParser()
            parser.feed(response.text)
            action, challenge = parser.challenge_form()
            if not action or challenge is None:
                return "Challenge form/action/input was not found"
            try:
                action_path = self._request_url(action)
            except ValueError:
                return "Challenge action is outside BASE_URL"
            if not action_path.startswith("/v2/challenges/"):
                return "Unexpected challenge form action"
            parsed_form["action"] = action_path
            parsed_form["challenge"] = challenge
            return None

        _, _, ok = self._auth_request(
            "GET",
            "/v2/challenge-form",
            "/v2/challenge-form",
            expected=(200,),
            validator=validate_form,
        )
        if not ok:
            return None

        def validate_redirect(response, _data):
            return (
                None
                if response.headers.get("Location")
                else "Challenge response lacked Location"
            )

        response, _, ok = self._auth_request(
            "POST",
            parsed_form["action"],
            "/v2/challenges/[id]",
            body={"challenge": parsed_form["challenge"]},
            expected=(302,),
            validator=validate_redirect,
        )
        if not ok:
            return None

        location = response.headers.get("Location")
        if not location:
            return None

        def validate_grant(_response, data):
            return None if data.get("grant_id") is not None else "Grant response lacked grant_id"

        _, data, ok = self._auth_request(
            "GET",
            location,
            "/v2/challenge-claim",
            expected=(200,),
            validator=validate_grant,
        )
        if not ok or not data:
            return None
        return data["grant_id"]

    def _create_cart(self, product_id, variant_id, grant_id):
        def validate_cart(_response, data):
            return None if data.get("id") is not None else "Cart response lacked id"

        _, data, ok = self._auth_request(
            "POST",
            "/v2/carts",
            "/v2/carts",
            body={
                "product_id": product_id,
                "variant_id": variant_id,
                "grant_id": grant_id,
            },
            expected=(201,),
            validator=validate_cart,
        )
        return data.get("id") if ok and data else None

    def _cart_etag(self, cart_id):
        response, _, ok = self._auth_request(
            "GET",
            f"/v2/carts/{cart_id}",
            "/v2/carts/[cart_id]",
            expected=(200,),
        )
        if not ok or response is None:
            return None
        return response.headers.get("ETag")

    def _set_cart_quantity(self, cart_id):
        for attempt in range(2):
            etag = self._cart_etag(cart_id)
            if not etag:
                return None

            def validate_patch(response, _data):
                if response.status_code == 412 and attempt == 1:
                    return "Cart PATCH still returned 412 after one retry"
                return None

            response, _, ok = self._auth_request(
                "PATCH",
                f"/v2/carts/{cart_id}",
                "/v2/carts/[cart_id]",
                body={"quantity": 1},
                headers={"If-Match": etag},
                expected=(200, 412),
                validator=validate_patch,
                cart_id=cart_id,
            )
            if not ok:
                return None

            if response.status_code == 412:
                continue
            return self._cart_etag(cart_id)

        return None

    def _job_id_from_response(self, data, status_url):
        job_id = data.get("job_id")
        if job_id is None:
            job = data.get("job")
            if isinstance(job, dict):
                job_id = job.get("id") or job.get("job_id")
        if job_id is None:
            job_id = data.get("id")
        if job_id is not None:
            return str(job_id)

        absolute = urljoin(self.host.rstrip("/") + "/", str(status_url))
        parts = urlparse(absolute)
        query = parse_qs(parts.query)
        for key in ("job_id", "job", "id"):
            if query.get(key):
                return query[key][0]

        segments = [
            unquote(segment)
            for segment in parts.path.strip("/").split("/")
            if segment
        ]
        for marker in ("jobs", "reservation-jobs", "reservation_jobs"):
            if marker in segments:
                index = segments.index(marker)
                if index + 1 < len(segments):
                    candidate = segments[index + 1]
                    if candidate.lower() != "status":
                        return candidate

        if segments and segments[-1].lower() == "status":
            return segments[-2] if len(segments) > 1 else None
        return segments[-1] if segments else None

    def _reservation(self, cart_id):
        job_info = {}

        def validate_submission(_response, data):
            status_url = data.get("status_url")
            if not status_url:
                return "202 reservation response lacked status_url"
            try:
                self._request_url(status_url)
            except ValueError:
                return "Reservation status URL is outside BASE_URL"

            job_id = self._job_id_from_response(data, status_url)
            if not job_id:
                return "202 reservation response lacked an extractable job ID"

            job_info["status_url"] = status_url
            job_info["job_id"] = job_id
            return None

        _, _, ok = self._auth_request(
            "POST",
            "/v2/reservations",
            "/v2/reservations",
            body={"cart_id": cart_id},
            expected=(202,),
            validator=validate_submission,
            cart_id=cart_id,
        )
        if not ok:
            return None

        poll_counter = [0]
        status_url = job_info["status_url"]
        job_id = job_info["job_id"]

        while poll_counter[0] < MAX_JOB_POLLS:
            if poll_counter[0]:
                sleep(MIN_POLL_INTERVAL)

            def validate_status(_response, data):
                reported_job_id = data.get("job_id")
                if reported_job_id is None and isinstance(data.get("job"), dict):
                    reported_job_id = data["job"].get("id") or data["job"].get("job_id")
                if reported_job_id is not None and str(reported_job_id) != job_id:
                    return "Polled status did not belong to the submitted job"

                status = data.get("status")
                if status == "ready":
                    if data.get("reservation_id") is None:
                        return "Ready job lacked reservation_id"
                    return None
                if status == "pending":
                    if poll_counter[0] >= MAX_JOB_POLLS:
                        return "Reservation job remained pending after five polls"
                    return None
                if status == "failed":
                    return "Reservation job failed"
                return f"Unexpected reservation job status: {status!r}"

            response, data, ok = self._auth_request(
                "GET",
                status_url,
                "/v2/reservations/status",
                expected=(200,),
                validator=validate_status,
                cart_id=cart_id,
                request_counter=poll_counter,
                retry_wait=MIN_POLL_INTERVAL,
            )
            if not ok or not data:
                return None
            if data.get("status") == "ready":
                return data["reservation_id"]

        return None

    @staticmethod
    def _retry_after_is_one(response):
        try:
            return float(response.headers.get("Retry-After", "").strip()) == 1.0
        except (TypeError, ValueError):
            return False

    def _work(self):
        scheduled_retries = 0

        while True:
            def validate_work(response, data):
                if response.status_code == 429:
                    return (
                        None
                        if self._retry_after_is_one(response)
                        else "Scheduled 429 lacked Retry-After: 1"
                    )
                return None if data.get("ok") is True else "/v2/work returned ok != true"

            response, _, ok = self._auth_request(
                "POST",
                "/v2/work",
                "/v2/work",
                body={},
                expected=(200, 429),
                validator=validate_work,
            )

            if response is None:
                return False
            if response.status_code == 200:
                return ok
            if response.status_code != 429 or not ok:
                return False
            if scheduled_retries >= 4:
                return False

            scheduled_retries += 1
            sleep(1.0)

    def _journey(self):
        self.csrf = None
        if not self._login():
            return

        self._work()

        choice = self._catalog_choice()
        if not choice:
            return
        product_id, variant_id = choice

        grant_id = self._challenge_grant()
        if grant_id is None:
            return

        cart_id = self._create_cart(product_id, variant_id, grant_id)
        if cart_id is None:
            return

        etag = self._set_cart_quantity(cart_id)
        if not etag:
            return

        reservation_id = self._reservation(cart_id)
        if reservation_id is None:
            return

        def validate_order(_response, data):
            if data.get("accepted") is not True:
                return "Order was not accepted"
            if data.get("id") is None:
                return "Accepted order response lacked id"
            return None

        self._auth_request(
            "POST",
            "/v2/orders",
            "/v2/orders",
            body={
                "cart_id": cart_id,
                "reservation_id": reservation_id,
            },
            headers={
                "If-Match": etag,
                "Idempotency-Key": f"order-{cart_id}",
            },
            expected=(200, 201),
            validator=validate_order,
            cart_id=cart_id,
        )

    @task
    def execute_iterations(self):
        try:
            for _ in range(ITERATIONS_PER_USER):
                self._journey()
        finally:
            type(self).finished_users += 1
        raise StopUser()


class ReservationShape(LoadTestShape):
    def tick(self):
        if ReservationUser.finished_users >= USER_COUNT:
            return None
        return USER_COUNT, USER_COUNT

