import http from 'k6/http';
import { check, sleep } from 'k6';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const BASE_ORIGIN_MATCH = BASE_URL.match(/^(https?:\/\/[^/]+)/i);
if (!BASE_ORIGIN_MATCH) {
  throw new Error('BASE_URL must be an absolute HTTP URL');
}
const BASE_ORIGIN = BASE_ORIGIN_MATCH[1];

export const options = {
  scenarios: {
    shop: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
    },
  },
};

let csrfToken = '';
let activeCartId = null;

function endpoint(path) {
  return BASE_URL + (path.charAt(0) === '/' ? path : '/' + path);
}

function resolveTarget(location) {
  const value = String(location || '').trim();
  if (!value || value.indexOf('//') === 0) {
    throw new Error('Invalid dynamic URL');
  }

  const absolute = value.match(/^([a-z][a-z0-9+.-]*:\/\/[^/?#]+)(.*)$/i);
  if (absolute) {
    if (absolute[1].toLowerCase() !== BASE_ORIGIN.toLowerCase()) {
      throw new Error('Dynamic URL is outside BASE_URL');
    }
    return value;
  }

  if (value.charAt(0) === '?') {
    return BASE_URL + value;
  }
  return BASE_URL + (value.charAt(0) === '/' ? value : '/' + value);
}

function responseJson(res) {
  try {
    return JSON.parse(res.body || '');
  } catch (_) {
    return null;
  }
}

function headerValue(res, wanted) {
  const headers = (res && res.headers) || {};
  const key = Object.keys(headers).find((name) => name.toLowerCase() === wanted.toLowerCase());
  if (!key) {
    return '';
  }
  const value = headers[key];
  return Array.isArray(value) ? String(value[0] || '') : String(value || '');
}

function captureCsrf(res) {
  if (!res || res.status < 200 || res.status >= 400) {
    return;
  }
  const data = responseJson(res);
  if (data && typeof data.csrf === 'string' && data.csrf.length > 0) {
    csrfToken = data.csrf;
  }
}

function assertThat(res, name, condition) {
  const passed = check(res, { [name]: () => Boolean(condition) });
  if (!passed) {
    throw new Error(name);
  }
}

function requestRaw(method, url, body, headers, name) {
  const params = {
    headers: headers || {},
    redirects: 0,
    timeout: '3s',
    tags: { name: name || method + ' request' },
  };
  const payload = method === 'GET' ? null : JSON.stringify(body === undefined ? {} : body);
  const res = http.request(method, url, payload, params);
  captureCsrf(res);
  return res;
}

function authRequestRaw(method, url, body, extraHeaders, name) {
  const headers = {};
  if (method !== 'GET') {
    if (!csrfToken) {
      throw new Error('Missing CSRF token for authenticated mutation');
    }
    headers['Content-Type'] = 'application/json';
    headers['X-CSRF-Token'] = csrfToken;
  }
  Object.keys(extraHeaders || {}).forEach((key) => {
    headers[key] = extraHeaders[key];
  });
  return requestRaw(method, url, body, headers, name);
}

function authError(res) {
  if (!res || res.status !== 401) {
    return '';
  }
  const data = responseJson(res);
  return data && typeof data.error === 'string' ? data.error : '';
}

function htmlDecode(value) {
  return String(value)
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&#(\d+);/g, (_, number) => String.fromCharCode(Number(number)))
    .replace(/&#x([0-9a-f]+);/gi, (_, number) => String.fromCharCode(parseInt(number, 16)));
}

function attributes(tag) {
  const result = {};
  const start = tag.indexOf(' ');
  const end = tag.lastIndexOf('>');
  const text = start >= 0 ? tag.slice(start + 1, end >= 0 ? end : undefined) : '';
  const pattern = /([^\s=/>]+)\s*(?:=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g;
  let match;
  while ((match = pattern.exec(text)) !== null) {
    const name = match[1].toLowerCase();
    const value = match[2] !== undefined
      ? match[2]
      : (match[3] !== undefined ? match[3] : match[4]);
    result[name] = value === undefined ? '' : htmlDecode(value);
  }
  return result;
}

function loginFormCsrf(html) {
  const tags = String(html || '').match(/<input\b[^>]*>/gi) || [];
  for (const tag of tags) {
    const attrs = attributes(tag);
    if (String(attrs.name || '').toLowerCase() === 'csrf' && attrs.value) {
      return attrs.value;
    }
  }
  return '';
}

function challengeForm(html) {
  const forms = String(html || '').match(/<form\b[^>]*>[\s\S]*?<\/form\s*>/gi) || [];
  for (const form of forms) {
    const opening = form.match(/^<form\b[^>]*>/i);
    if (!opening) {
      continue;
    }
    const formAttrs = attributes(opening[0]);
    const inputs = form.match(/<input\b[^>]*>/gi) || [];
    for (const input of inputs) {
      const inputAttrs = attributes(input);
      if (String(inputAttrs.name || '').toLowerCase() === 'challenge' && inputAttrs.value) {
        if (formAttrs.action) {
          return { action: formAttrs.action, challenge: inputAttrs.value };
        }
      }
    }
  }
  return null;
}

function performLogin(username) {
  const formRes = requestRaw(
    'GET',
    endpoint('/v2/login-form'),
    null,
    {},
    'GET /v2/login-form'
  );
  assertThat(formRes, 'login form returned HTTP 200', formRes.status === 200);

  const formToken = loginFormCsrf(formRes.body);
  assertThat(formRes, 'login form contains csrf input', Boolean(formToken));
  csrfToken = formToken;

  const loginRes = requestRaw(
    'POST',
    endpoint('/v2/login'),
    { username: username, password: 'bench', csrf: formToken },
    { 'Content-Type': 'application/json' },
    'POST /v2/login'
  );
  assertThat(
    loginRes,
    'login returned HTTP 200 or 302',
    loginRes.status === 200 || loginRes.status === 302
  );

  const location = headerValue(loginRes, 'Location');
  if (loginRes.status === 302 && !location) {
    assertThat(loginRes, 'login redirect has Location', false);
  }
  if (location) {
    const redirectRes = requestRaw(
      'GET',
      resolveTarget(location),
      null,
      {},
      'GET login redirect'
    );
    assertThat(redirectRes, 'login redirect returned HTTP 200', redirectRes.status === 200);
  }

  assertThat(loginRes, 'login leaves a CSRF token', Boolean(csrfToken));
}

function recoverSession(originalError) {
  const renewRes = authRequestRaw(
    'POST',
    endpoint('/v2/session/renew'),
    {},
    {},
    'POST /v2/session/renew'
  );

  const renewData = responseJson(renewRes);
  const renewed = renewRes.status >= 200 &&
    renewRes.status < 300 &&
    renewData &&
    typeof renewData.csrf === 'string' &&
    renewData.csrf.length > 0;

  if (!renewed) {
    if (renewRes.status >= 500) {
      assertThat(renewRes, 'session renewal did not return HTTP 5xx', false);
    }
    const renewalError = authError(renewRes);
    if (originalError === 'session' || renewalError === 'session') {
      performLogin('bench-' + (((__VU - 1) % 16) + 1));
    } else {
      assertThat(renewRes, 'expired session was renewed', renewed);
    }
  }

  if (activeCartId !== null) {
    const recoverRes = authRequestRaw(
      'POST',
      endpoint('/v2/carts/' + encodeURIComponent(String(activeCartId)) + '/recover'),
      {},
      {},
      'POST /v2/carts/{id}/recover'
    );
    assertThat(
      recoverRes,
      'cart recovery returned a successful response',
      recoverRes.status >= 200 && recoverRes.status < 300
    );
  }
}

function requestWithRecovery(method, url, body, extraHeaders, name) {
  let res = authRequestRaw(method, url, body, extraHeaders, name);
  const error = authError(res);

  if (error === 'expired' || error === 'session') {
    recoverSession(error);
    res = authRequestRaw(method, url, body, extraHeaders, name);
  }
  return res;
}

function findAvailableProduct() {
  let next = '/v2/catalog';
  let pages = 0;

  while (next !== null && pages < 3) {
    const pageRes = requestRaw('GET', resolveTarget(next), null, {}, 'GET catalog page');
    assertThat(pageRes, 'catalog page returned HTTP 200', pageRes.status === 200);

    const data = responseJson(pageRes);
    assertThat(
      pageRes,
      'catalog response contains products',
      Boolean(data && data.data && Array.isArray(data.data.products))
    );

    for (const product of data.data.products) {
      const variants = Array.isArray(product.variants) ? product.variants : [];
      for (const variant of variants) {
        if (variant && variant.in_stock === true &&
            product.id !== undefined && variant.id !== undefined) {
          return { productId: product.id, variantId: variant.id };
        }
      }
    }

    next = data.next === null || data.next === undefined ? null : String(data.next);
    pages += 1;
  }

  throw new Error('No in-stock product variant found within three catalog pages');
}

function createChallengeGrant() {
  const formRes = requestWithRecovery(
    'GET',
    endpoint('/v2/challenge-form'),
    null,
    {},
    'GET /v2/challenge-form'
  );
  assertThat(formRes, 'challenge form returned HTTP 200', formRes.status === 200);

  const form = challengeForm(formRes.body);
  assertThat(formRes, 'challenge form has action and challenge input', Boolean(form));
  const actionUrl = resolveTarget(form.action);

  const postRes = requestWithRecovery(
    'POST',
    actionUrl,
    { challenge: form.challenge },
    {},
    'POST challenge'
  );
  const location = headerValue(postRes, 'Location');
  assertThat(
    postRes,
    'challenge submission returned HTTP 302 with Location',
    postRes.status === 302 && Boolean(location)
  );

  const claimRes = requestWithRecovery(
    'GET',
    resolveTarget(location),
    null,
    {},
    'GET challenge claim'
  );
  assertThat(claimRes, 'challenge claim returned HTTP 200', claimRes.status === 200);

  const claim = responseJson(claimRes);
  assertThat(
    claimRes,
    'challenge claim contains grant_id',
    Boolean(claim && typeof claim.grant_id === 'string' && claim.grant_id.length > 0)
  );
  return claim.grant_id;
}

function catalogAndCart(username) {
  const selected = findAvailableProduct();
  const grantId = createChallengeGrant();

  const cartRes = requestWithRecovery(
    'POST',
    endpoint('/v2/carts'),
    {
      product_id: selected.productId,
      variant_id: selected.variantId,
      grant_id: grantId,
    },
    {},
    'POST /v2/carts'
  );

  assertThat(cartRes, 'cart creation returned HTTP 201', cartRes.status === 201);
  const cart = responseJson(cartRes);
  assertThat(
    cartRes,
    'cart response contains an id',
    Boolean(cart && cart.id !== undefined && cart.id !== null && String(cart.id).length > 0)
  );

  activeCartId = cart.id;
  assertThat(
    cartRes,
    'cart response contains a CSRF token',
    Boolean(cart.csrf || csrfToken)
  );

  const etag = headerValue(cartRes, 'ETag');
  assertThat(cartRes, 'cart response contains ETag', Boolean(etag));

  return { cartId: cart.id, etag: etag };
}

function obtainReservation(cartId) {
  const reservationRes = requestWithRecovery(
    'POST',
    endpoint('/v2/reservations'),
    { cart_id: cartId },
    {},
    'POST /v2/reservations'
  );
  assertThat(
    reservationRes,
    'reservation request returned HTTP 202',
    reservationRes.status === 202
  );

  const reservation = responseJson(reservationRes);
  assertThat(
    reservationRes,
    'reservation response contains status_url',
    Boolean(reservation && typeof reservation.status_url === 'string' && reservation.status_url)
  );

  const statusUrl = resolveTarget(reservation.status_url);
  for (let attempt = 0; attempt < 5; attempt += 1) {
    sleep(0.05);
    const statusRes = requestWithRecovery(
      'GET',
      statusUrl,
      null,
      {},
      'GET reservation status'
    );
    assertThat(
      statusRes,
      'reservation status returned HTTP 200 or 202',
      statusRes.status === 200 || statusRes.status === 202
    );

    const status = responseJson(statusRes);
    assertThat(
      statusRes,
      'reservation status is ready, pending, or failed',
      Boolean(status && (status.status === 'ready' ||
        status.status === 'pending' || status.status === 'failed'))
    );

    if (status.status === 'ready') {
      assertThat(
        statusRes,
        'ready reservation contains reservation_id',
        Boolean(status.reservation_id)
      );
      return status.reservation_id;
    }
    assertThat(statusRes, 'reservation did not fail', status.status !== 'failed');
  }

  throw new Error('Reservation did not become ready within five polls');
}

function checkout(cartId, etag, reservationId) {
  const idempotencyKey = String(cartId);
  const orderRes = requestWithRecovery(
    'POST',
    endpoint('/v2/orders'),
    { cart_id: cartId, reservation_id: reservationId },
    {
      'If-Match': etag,
      'Idempotency-Key': idempotencyKey,
    },
    'POST /v2/orders'
  );

  assertThat(orderRes, 'order returned HTTP 201', orderRes.status === 201);
  const order = responseJson(orderRes);
  assertThat(
    orderRes,
    'order was accepted',
    Boolean(order && order.accepted === true && order.id !== undefined)
  );
}

export default function () {
  http.cookieJar().clearAll();
  csrfToken = '';
  activeCartId = null;

  const username = 'bench-' + (((__VU - 1) % 16) + 1);
  performLogin(username);

  const cart = catalogAndCart(username);
  const reservationId = obtainReservation(cart.cartId);
  checkout(cart.cartId, cart.etag, reservationId);
}

import itertools
import os
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


ITERATIONS_PER_USER = 2
_account_numbers = itertools.count(1)


class JourneyAbort(Exception):
    pass


class InputParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.inputs = []
        self.current_action = None
        self.fields = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag.lower() == "form":
            self.current_action = attrs.get("action")
        elif tag.lower() == "input":
            field = {
                "name": attrs.get("name"),
                "value": attrs.get("value"),
            }
            self.inputs.append(field)
            self.fields.append((self.current_action, field))

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self.current_action = None

    def csrf_value(self):
        for field in self.inputs:
            if field.get("name") == "csrf" and field.get("value"):
                return field["value"]
        return None

    def challenge(self):
        for action, field in self.fields:
            if (
                field.get("name") == "challenge"
                and field.get("value")
                and action
                and "/v2/challenges/" in action
            ):
                return action, field["value"]
        return None, None


def json_object(response):
    try:
        value = response.json()
        return value if isinstance(value, dict) else {}
    except (ValueError, TypeError):
        return {}


def has_csrf(response):
    value = json_object(response).get("csrf")
    return isinstance(value, str) and bool(value)


def selected_product(response):
    data = json_object(response).get("data", {})
    products = data.get("products", []) if isinstance(data, dict) else []
    if not isinstance(products, list):
        return None

    # Match the JMX selector: the first product whose first variant is in stock.
    for product in products:
        if not isinstance(product, dict):
            continue
        variants = product.get("variants")
        if not isinstance(variants, list) or not variants:
            continue
        variant = variants[0]
        if (
            isinstance(variant, dict)
            and variant.get("in_stock") is True
            and product.get("id") is not None
            and variant.get("id") is not None
        ):
            return product["id"], variant["id"]
    return None


def auth_error(response):
    return json_object(response).get("error")


class ShopUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")

    def on_start(self):
        self.username = f"bench-{((next(_account_numbers) - 1) % 16) + 1}"
        self.iterations_done = 0
        self._reset_journey()

    def _reset_journey(self):
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.reservation_id = None
        self.product_id = None
        self.variant_id = None

    def _safe_local_url(self, location):
        base = urlsplit(self.host)
        resolved = urljoin(self.host.rstrip("/") + "/", location)
        target = urlsplit(resolved)
        if (target.scheme, target.netloc) != (base.scheme, base.netloc):
            raise JourneyAbort("dynamic URL is outside the configured target")
        return resolved

    def _send(
        self,
        method,
        path,
        *,
        name,
        body=None,
        headers=None,
        valid,
        auth_expected=True,
    ):
        with self.client.request(
            method,
            path,
            name=name,
            json=body,
            headers=headers or {},
            allow_redirects=False,
            timeout=(2, 3),
            catch_response=True,
        ) as response:
            try:
                is_valid = bool(valid(response))
            except Exception:
                is_valid = False

            expected_auth_error = (
                auth_expected
                and response.status_code == 401
                and auth_error(response) in ("expired", "session")
            )
            if is_valid or expected_auth_error:
                response.success()
            else:
                response.failure(f"{name}: unexpected response")
        return response, is_valid

    def _auth_headers(self, extra=None):
        if not self.csrf:
            raise JourneyAbort("no current CSRF token")
        headers = {"X-CSRF-Token": self.csrf}
        if extra:
            headers.update(extra)
        return headers

    def _capture_csrf(self, response):
        token = json_object(response).get("csrf")
        if isinstance(token, str) and token:
            self.csrf = token

    def _operation(self, method, path, *, name, body, headers, valid):
        response, is_valid = self._send(
            method,
            path,
            name=name,
            body=body,
            headers=headers,
            valid=valid,
        )

        error = auth_error(response)
        if response.status_code == 401 and error in ("expired", "session"):
            if not self._recover_auth(error):
                raise JourneyAbort("authentication recovery failed")
            response, is_valid = self._send(
                method,
                path,
                name=name,
                body=body,
                headers=headers if "X-CSRF-Token" not in (headers or {}) else self._auth_headers(
                    {
                        key: value
                        for key, value in (headers or {}).items()
                        if key != "X-CSRF-Token"
                    }
                ),
                valid=valid,
                auth_expected=False,
            )

        if not is_valid:
            raise JourneyAbort(f"{name} did not satisfy its response assertion")
        return response

    def _login(self):
        form_response, form_ok = self._send(
            "GET",
            "/v2/login-form",
            name="login form",
            valid=lambda r: r.status_code == 200
            and bool(self._parse_login_csrf(r.text)),
        )
        if not form_ok:
            raise JourneyAbort("login form did not contain a CSRF input")

        parser = InputParser()
        parser.feed(form_response.text)
        form_csrf = parser.csrf_value()
        if not form_csrf:
            raise JourneyAbort("login form CSRF token is missing")
        self.csrf = form_csrf

        login_response, login_ok = self._send(
            "POST",
            "/v2/login",
            name="login",
            body={
                "username": self.username,
                "password": "bench",
                "csrf": form_csrf,
            },
            valid=lambda r: (
                r.status_code == 200 and has_csrf(r)
            )
            or (
                r.status_code == 302
                and bool(r.headers.get("Location"))
            ),
        )
        if not login_ok:
            raise JourneyAbort("login failed")
        self._capture_csrf(login_response)

        if login_response.status_code == 302:
            location = self._safe_local_url(login_response.headers["Location"])
            landing, landing_ok = self._send(
                "GET",
                location,
                name="login redirect landing",
                valid=lambda r: 200 <= r.status_code < 300,
            )
            if not landing_ok:
                raise JourneyAbort("login redirect landing failed")
            self._capture_csrf(landing)

    @staticmethod
    def _parse_login_csrf(html):
        parser = InputParser()
        parser.feed(html)
        return parser.csrf_value()

    def _recover_auth(self, error):
        # A revoked session may reject renewal; in that case, log in afresh.
        renew, renew_ok = self._send(
            "POST",
            "/v2/session/renew",
            name="session renew",
            body={},
            headers=self._auth_headers(),
            valid=lambda r: (
                r.status_code == 200 and has_csrf(r)
            )
            or (
                error == "session"
                and r.status_code == 401
                and auth_error(r) == "session"
            ),
            auth_expected=False,
        )

        if renew_ok and renew.status_code == 200:
            self._capture_csrf(renew)
        elif error == "expired":
            return False

        if error == "session":
            try:
                self._login()
            except Exception:
                return False

        if self.cart_id:
            try:
                recovered = self._send(
                    "POST",
                    f"/v2/carts/{self.cart_id}/recover",
                    name="cart recovery",
                    body={},
                    headers=self._auth_headers(),
                    valid=lambda r: 200 <= r.status_code < 300,
                    auth_expected=False,
                )
            except Exception:
                return False
            response, recovered_ok = recovered
            if not recovered_ok:
                return False
            self._capture_csrf(response)

        return True

    def _get_catalog_selection(self):
        response = self._operation(
            "GET",
            "/v2/catalog",
            name="catalog",
            body=None,
            headers={},
            valid=lambda r: r.status_code == 200
            and selected_product(r) is not None,
        )
        self.product_id, self.variant_id = selected_product(response)

    def _get_grant(self):
        form, form_ok = self._send(
            "GET",
            "/v2/challenge-form",
            name="challenge form",
            valid=lambda r: r.status_code == 200
            and bool(self._parse_challenge(r.text)),
        )
        if not form_ok:
            raise JourneyAbort("challenge form is invalid")

        parser = InputParser()
        parser.feed(form.text)
        action, challenge = parser.challenge()
        if not action or not challenge:
            raise JourneyAbort("challenge fields are missing")
        action_url = self._safe_local_url(action)

        posted = self._operation(
            "POST",
            action_url,
            name="challenge submission",
            body={"challenge": challenge},
            headers=self._auth_headers(),
            valid=lambda r: r.status_code == 302
            and bool(r.headers.get("Location")),
        )
        self._capture_csrf(posted)

        claim_url = self._safe_local_url(posted.headers["Location"])
        claim, claim_ok = self._send(
            "GET",
            claim_url,
            name="challenge claim",
            valid=lambda r: r.status_code == 200
            and isinstance(json_object(r).get("grant_id"), str)
            and bool(json_object(r).get("grant_id"))
            and has_csrf(r),
        )
        if not claim_ok:
            raise JourneyAbort("challenge claim failed")
        payload = json_object(claim)
        self.grant_id = payload["grant_id"]
        self._capture_csrf(claim)

    @staticmethod
    def _parse_challenge(html):
        parser = InputParser()
        parser.feed(html)
        action, challenge = parser.challenge()
        return (action, challenge) if action and challenge else None

    def _create_cart(self):
        response = self._operation(
            "POST",
            "/v2/carts",
            name="cart creation",
            body={
                "product_id": self.product_id,
                "variant_id": self.variant_id,
                "grant_id": self.grant_id,
            },
            headers=self._auth_headers(),
            valid=lambda r: r.status_code == 201
            and isinstance(json_object(r).get("id"), str)
            and json_object(r)["id"].startswith("cart-")
            and has_csrf(r)
            and bool(r.headers.get("ETag")),
        )
        payload = json_object(response)
        self.cart_id = payload["id"]
        self.etag = response.headers["ETag"]
        self._capture_csrf(response)

    def _reserve(self):
        response = self._operation(
            "POST",
            "/v2/reservations",
            name="reservation creation",
            body={"cart_id": self.cart_id},
            headers=self._auth_headers(),
            valid=lambda r: r.status_code == 202
            and isinstance(json_object(r).get("status_url"), str)
            and bool(json_object(r).get("status_url")),
        )
        self._capture_csrf(response)
        status_url = self._safe_local_url(json_object(response)["status_url"])

        for poll_number in range(1, 6):
            self.wait(0.05)
            final_poll = poll_number == 5

            def valid_status(r):
                if r.status_code != 200:
                    return False
                state = json_object(r).get("status")
                if state == "ready":
                    return json_object(r).get("reservation_id") is not None
                if state == "pending":
                    return not final_poll
                return False

            status, status_ok = self._operation(
                "GET",
                status_url,
                name=f"reservation poll {poll_number}",
                body=None,
                headers={},
                valid=valid_status,
            )
            if not status_ok:
                raise JourneyAbort("reservation status failed")
            payload = json_object(status)
            if payload.get("status") == "ready":
                self.reservation_id = payload["reservation_id"]
                return

        raise JourneyAbort("reservation did not become ready")

    def _place_order(self):
        headers = self._auth_headers({"Idempotency-Key": self.cart_id})
        if self.etag:
            headers["If-Match"] = self.etag

        response = self._operation(
            "POST",
            "/v2/orders",
            name="order",
            body={
                "cart_id": self.cart_id,
                "reservation_id": self.reservation_id,
            },
            headers=headers,
            valid=lambda r: r.status_code == 201
            and json_object(r).get("accepted") is True
            and json_object(r).get("id") is not None
            and has_csrf(r),
        )
        self._capture_csrf(response)

    def _journey(self):
        self._login()
        self._get_catalog_selection()
        self._get_grant()
        self._create_cart()
        self._reserve()
        self._place_order()

    @task
    def run_journey(self):
        if self.iterations_done >= ITERATIONS_PER_USER:
            raise StopUser()

        self.iterations_done += 1
        self._reset_journey()
        try:
            self._journey()
        except Exception:
            # Failed samples remain visible; continue like the JMeter
            # ThreadGroup's "continue" sample-error policy.
            pass

        if self.iterations_done >= ITERATIONS_PER_USER:
            raise StopUser()


class FixedUsersShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.started = False

    def tick(self):
        if not self.started:
            self.started = True
            return (2, 2)

        if self.get_current_user_count() == 0:
            return None

        return (2, 2)

