import http from 'k6/http';
import { check, fail, sleep } from 'k6';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const accounts = JSON.parse(open('/fixtures/accounts.json'));

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
    },
  },
};

function requireCheck(condition, name) {
  if (!check(null, { [name]: condition })) {
    fail(name);
  }
}

function jsonBody(response) {
  try {
    return JSON.parse(response.body);
  } catch (_) {
    return null;
  }
}

function header(response, name) {
  const wanted = name.toLowerCase();
  for (const key in response.headers) {
    if (key.toLowerCase() === wanted) {
      return response.headers[key];
    }
  }
  return null;
}

function csrfFrom(response) {
  const body = jsonBody(response);
  return body && typeof body.csrf === 'string' && body.csrf.length > 0
    ? body.csrf
    : null;
}

function updateCsrf(state, response) {
  const fresh = csrfFrom(response);
  if (fresh) {
    state.csrf = fresh;
  }
}

function responseError(response) {
  const body = jsonBody(response);
  return body && typeof body.error === 'string' ? body.error : null;
}

function requestUrl(pathOrUrl) {
  if (/^https?:\/\//i.test(pathOrUrl)) {
    requireCheck(pathOrUrl.indexOf(BASE_URL + '/') === 0 || pathOrUrl === BASE_URL,
      'request remains on configured target');
    return pathOrUrl;
  }
  return BASE_URL + (pathOrUrl.charAt(0) === '/' ? pathOrUrl : '/' + pathOrUrl);
}

function resolveLocal(location, currentPath) {
  requireCheck(typeof location === 'string' && location.length > 0, 'dynamic Location exists');

  if (/^https?:\/\//i.test(location)) {
    return requestUrl(location);
  }
  requireCheck(location.indexOf('//') !== 0, 'redirect is not protocol-relative');

  if (location.charAt(0) === '/') {
    return BASE_URL + location;
  }
  const path = currentPath.split('?')[0];
  if (location.charAt(0) === '?') {
    return BASE_URL + path + location;
  }
  const directory = path.slice(0, path.lastIndexOf('/') + 1);
  return BASE_URL + directory + location;
}

function rawRequest(method, pathOrUrl, body, headers, name) {
  const data = body === undefined ? null : JSON.stringify(body);
  return http.request(method, requestUrl(pathOrUrl), data, {
    headers: headers || {},
    redirects: 0,
    timeout: '3s',
    tags: { name: name || method + ' ' + pathOrUrl },
  });
}

function htmlDecode(value) {
  return value
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&#x27;/gi, "'");
}

function attributes(tag) {
  const text = tag
    .replace(/^<\s*[^\s/>]+/i, '')
    .replace(/\/?>\s*$/i, '');
  const result = {};
  const pattern = /([^\s=/>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/g;
  let match;
  while ((match = pattern.exec(text)) !== null) {
    const key = match[1].toLowerCase();
    const value = match[2] !== undefined
      ? match[2]
      : match[3] !== undefined
        ? match[3]
        : match[4] !== undefined
          ? match[4]
          : '';
    result[key] = htmlDecode(value);
  }
  return result;
}

function inputValue(html, wantedName) {
  const pattern = /<input\b[^>]*>/gi;
  let match;
  while ((match = pattern.exec(html)) !== null) {
    const attrs = attributes(match[0]);
    if (attrs.name === wantedName && attrs.value !== undefined && attrs.value !== '') {
      return attrs.value;
    }
  }
  return null;
}

function parseLoginCsrf(html) {
  return inputValue(html, 'csrf');
}

function challengeTicket(html) {
  const forms = /<form\b[^>]*>[\s\S]*?<\/form\s*>/gi;
  let match;
  while ((match = forms.exec(html)) !== null) {
    const opening = match[0].match(/^<form\b[^>]*>/i);
    if (!opening) {
      continue;
    }
    const attrs = attributes(opening[0]);
    const challenge = inputValue(match[0], 'challenge');
    if (attrs.action && challenge) {
      return { path: attrs.action, challenge: challenge };
    }
  }
  return null;
}

function login(state) {
  const formResponse = rawRequest('GET', '/v2/login-form', undefined, {}, 'login form');
  requireCheck(formResponse.status === 200, 'login form returned 200');
  const formCsrf = parseLoginCsrf(formResponse.body);
  requireCheck(!!formCsrf, 'login form csrf input found');

  const loginResponse = rawRequest(
    'POST',
    '/v2/login',
    {
      username: state.account.username,
      password: state.account.password,
      csrf: formCsrf,
    },
    { 'Content-Type': 'application/json' },
    'login'
  );
  requireCheck(
    loginResponse.status === 200 || loginResponse.status === 201 || loginResponse.status === 302,
    'login succeeded or redirected'
  );

  let finalResponse = loginResponse;
  const location = header(loginResponse, 'Location');
  if (location) {
    finalResponse = rawRequest(
      'GET',
      resolveLocal(location, '/v2/login'),
      undefined,
      {},
      'login redirect destination'
    );
    updateCsrf(state, finalResponse);
  }
  updateCsrf(state, loginResponse);
  updateCsrf(state, finalResponse);

  const finalBody = jsonBody(finalResponse);
  const loginBody = jsonBody(loginResponse);
  const userPresent =
    (finalBody && finalBody.user !== undefined) ||
    (loginBody && loginBody.user !== undefined);
  requireCheck(!!userPresent, 'login returned user');
  requireCheck(!!state.csrf, 'login returned authenticated csrf');
}

function renew(state) {
  const response = rawRequest(
    'POST',
    '/v2/session/renew',
    {},
    {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf || '',
    },
    'renew session'
  );
  if (response.status >= 200 && response.status < 300) {
    updateCsrf(state, response);
    return !!state.csrf;
  }
  return false;
}

function recoverCart(state) {
  if (!state.cart) {
    return true;
  }
  const response = rawRequest(
    'POST',
    '/v2/carts/' + encodeURIComponent(state.cart) + '/recover',
    {},
    {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf || '',
    },
    'recover cart'
  );
  if (response.status >= 200 && response.status < 300) {
    updateCsrf(state, response);
    return true;
  }
  return false;
}

function restoreSession(state, error) {
  if (error === 'expired') {
    requireCheck(renew(state), 'expired session renewed');
    requireCheck(recoverCart(state), 'cart recovered after expiry');
    return;
  }

  requireCheck(error === 'session', '401 was an expiry or revoked session');
  if (renew(state) && recoverCart(state)) {
    return;
  }

  state.csrf = null;
  login(state);
  requireCheck(recoverCart(state), 'cart recovered after fresh login');
}

function authenticatedGet(state, pathOrUrl, name) {
  let response = rawRequest('GET', pathOrUrl, undefined, {}, name);
  if (response.status !== 401) {
    updateCsrf(state, response);
    return response;
  }

  const error = responseError(response);
  requireCheck(error === 'expired' || error === 'session', 'GET 401 is recoverable');
  restoreSession(state, error);

  response = rawRequest('GET', pathOrUrl, undefined, {}, name + ' retry');
  requireCheck(response.status !== 401, 'GET succeeded after one recovery');
  updateCsrf(state, response);
  return response;
}

function authenticatedMutation(state, method, path, body, extraHeaders, retryFactory, name) {
  function send(targetPath, targetBody) {
    const headers = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf || '',
    };
    const extras = extraHeaders || {};
    for (const key in extras) {
      headers[key] = extras[key];
    }
    return rawRequest(method, targetPath, targetBody, headers, name);
  }

  let response = send(path, body);
  if (response.status !== 401) {
    updateCsrf(state, response);
    return response;
  }

  const error = responseError(response);
  requireCheck(error === 'expired' || error === 'session', method + ' 401 is recoverable');
  restoreSession(state, error);

  const retry = retryFactory ? retryFactory() : { path: path, body: body };
  response = send(retry.path || path, retry.body === undefined ? body : retry.body);
  requireCheck(response.status !== 401, method + ' succeeded after one recovery');
  updateCsrf(state, response);
  return response;
}

function startJourney(state) {
  state.csrf = null;
  state.cart = null;
  state.etag = null;
  state.orderKey = null;
  login(state);
}

function selectProduct() {
  let path = '/v2/catalog';
  let pageCount = 0;

  while (pageCount < 3) {
    const response = authenticatedGet(nullSafeState, path, 'catalog page');
    requireCheck(response.status === 200, 'catalog page returned 200');

    const body = jsonBody(response);
    requireCheck(!!(body && body.data && Array.isArray(body.data.products)),
      'catalog products are present');

    for (const product of body.data.products) {
      if (!product || !Array.isArray(product.variants)) {
        continue;
      }
      for (const variant of product.variants) {
        if (variant && variant.in_stock === true) {
          return { product_id: product.id, variant_id: variant.id };
        }
      }
    }

    pageCount += 1;
    if (pageCount >= 3 || !body.next) {
      break;
    }
    path = resolveLocal(body.next, path);
  }

  requireCheck(false, 'an in-stock catalog variant was found within three pages');
  return null;
}

let nullSafeState = null;

function getChallengeTicket(state) {
  const response = authenticatedGet(state, '/v2/challenge-form', 'challenge form');
  requireCheck(response.status === 200, 'challenge form returned 200');
  const ticket = challengeTicket(response.body);
  requireCheck(!!ticket, 'challenge form and input found');
  return ticket;
}

function obtainGrant(state) {
  let ticket = getChallengeTicket(state);
  const postChallenge = (currentTicket) => authenticatedMutation(
    state,
    'POST',
    currentTicket.path,
    { challenge: currentTicket.challenge },
    {},
    () => {
      ticket = getChallengeTicket(state);
      return {
        path: ticket.path,
        body: { challenge: ticket.challenge },
      };
    },
    'submit challenge'
  );

  const challengeResponse = postChallenge(ticket);
  requireCheck(challengeResponse.status === 302, 'challenge returned 302');
  const location = header(challengeResponse, 'Location');
  requireCheck(!!location, 'challenge redirect Location exists');

  const grantResponse = authenticatedGet(
    state,
    resolveLocal(location, ticket.path),
    'challenge redirect destination'
  );
  requireCheck(grantResponse.status === 200, 'challenge redirect returned 200');
  const grantBody = jsonBody(grantResponse);
  requireCheck(!!(grantBody && grantBody.grant_id), 'challenge grant returned');
  updateCsrf(state, grantResponse);
  return grantBody.grant_id;
}

function catalogProduct(state) {
  let path = '/v2/catalog';
  let pageCount = 0;

  while (pageCount < 3) {
    const response = authenticatedGet(state, path, 'catalog page');
    requireCheck(response.status === 200, 'catalog page returned 200');

    const body = jsonBody(response);
    requireCheck(!!(body && body.data && Array.isArray(body.data.products)),
      'catalog products are present');

    for (const product of body.data.products) {
      if (!product || !Array.isArray(product.variants)) {
        continue;
      }
      for (const variant of product.variants) {
        if (variant && variant.in_stock === true) {
          return { product_id: product.id, variant_id: variant.id };
        }
      }
    }

    pageCount += 1;
    if (pageCount >= 3 || !body.next) {
      break;
    }
    path = resolveLocal(body.next, path);
  }

  requireCheck(false, 'in-stock product found within three catalog pages');
  return null;
}

function ensureEtag(state) {
  if (state.etag) {
    return;
  }
  const response = authenticatedGet(
    state,
    '/v2/carts/' + encodeURIComponent(state.cart),
    'read cart etag'
  );
  requireCheck(response.status === 200, 'cart read returned 200');
  state.etag = header(response, 'ETag');
  requireCheck(!!state.etag, 'cart ETag is present');
}

function updateCartQuantity(state, quantity) {
  ensureEtag(state);
  let response = authenticatedMutation(
    state,
    'PATCH',
    '/v2/carts/' + encodeURIComponent(state.cart),
    { quantity: quantity },
    { 'If-Match': state.etag },
    null,
    'set cart quantity'
  );

  if (response.status === 412) {
    const reread = authenticatedGet(
      state,
      '/v2/carts/' + encodeURIComponent(state.cart),
      'reread cart after 412'
    );
    requireCheck(reread.status === 200, 'cart reread after 412 returned 200');
    state.etag = header(reread, 'ETag');
    requireCheck(!!state.etag, 'fresh ETag found after 412');

    response = authenticatedMutation(
      state,
      'PATCH',
      '/v2/carts/' + encodeURIComponent(state.cart),
      { quantity: quantity },
      { 'If-Match': state.etag },
      null,
      'retry cart quantity after 412'
    );
  }

  requireCheck(response.status === 200 || response.status === 204,
    'cart quantity mutation succeeded');
  const responseEtag = header(response, 'ETag');
  if (responseEtag) {
    state.etag = responseEtag;
  } else {
    state.etag = null;
    ensureEtag(state);
  }
}

function reserveCart(state) {
  const response = authenticatedMutation(
    state,
    'POST',
    '/v2/reservations',
    { cart_id: state.cart },
    {},
    null,
    'create reservation'
  );
  requireCheck(response.status === 202, 'reservation returned 202');

  const body = jsonBody(response);
  requireCheck(!!(body && body.status_url), 'reservation status URL returned');
  updateCsrf(state, response);

  let statusUrl = resolveLocal(body.status_url, '/v2/reservations');
  for (let poll = 0; poll < 5; poll += 1) {
    if (poll > 0) {
      sleep(0.05);
    }
    const statusResponse = authenticatedGet(state, statusUrl, 'poll reservation');
    requireCheck(statusResponse.status === 200, 'reservation poll returned 200');

    const statusBody = jsonBody(statusResponse);
    requireCheck(!!statusBody && typeof statusBody.status === 'string',
      'reservation status returned');

    if (statusBody.status === 'ready') {
      requireCheck(!!statusBody.reservation_id, 'ready reservation has an id');
      return statusBody.reservation_id;
    }
    requireCheck(statusBody.status === 'pending', 'reservation did not fail');
  }

  requireCheck(false, 'reservation became ready within five polls');
  return null;
}

export default function () {
  requireCheck(Array.isArray(accounts) && accounts.length === 2, 'two account fixture rows loaded');
  const account = accounts[__VU - 1];
  requireCheck(!!account, 'account row assigned to VU');
  requireCheck(
    typeof account.username === 'string' &&
    typeof account.password === 'string' &&
    typeof account.quantity === 'number' &&
    Number.isInteger(account.quantity) &&
    typeof account.delay === 'number',
    'account fixture field types retained'
  );
  requireCheck(account.quantity >= 1 && account.quantity <= 20, 'fixture quantity is valid');

  http.cookieJar().clear(BASE_URL);

  const state = {
    account: account,
    csrf: null,
    cart: null,
    etag: null,
    orderKey: null,
  };
  startJourney(state);

  const product = catalogProduct(state);
  const grantId = obtainGrant(state);

  const cartResponse = authenticatedMutation(
    state,
    'POST',
    '/v2/carts',
    {
      product_id: product.product_id,
      variant_id: product.variant_id,
      grant_id: grantId,
    },
    {},
    () => {
      const freshGrant = obtainGrant(state);
      return {
        path: '/v2/carts',
        body: {
          product_id: product.product_id,
          variant_id: product.variant_id,
          grant_id: freshGrant,
        },
      };
    },
    'create cart'
  );
  requireCheck(cartResponse.status === 201, 'cart creation returned 201');

  const cartBody = jsonBody(cartResponse);
  requireCheck(!!(cartBody && typeof cartBody.id === 'string' && cartBody.id.length > 0),
    'cart id returned');
  requireCheck(cartBody.id.indexOf('cart-') === 0, 'cart id has expected prefix');
  state.cart = cartBody.id;
  state.etag = header(cartResponse, 'ETag');
  updateCsrf(state, cartResponse);

  updateCartQuantity(state, account.quantity);
  const reservationId = reserveCart(state);

  ensureEtag(state);
  state.orderKey = state.cart;
  const orderResponse = authenticatedMutation(
    state,
    'POST',
    '/v2/orders',
    {
      cart_id: state.cart,
      reservation_id: reservationId,
    },
    {
      'If-Match': state.etag,
      'Idempotency-Key': state.orderKey,
    },
    null,
    'commit order'
  );

  requireCheck(orderResponse.status === 201, 'order returned 201');
  const orderBody = jsonBody(orderResponse);
  requireCheck(!!(orderBody && orderBody.accepted === true && orderBody.id),
    'order was accepted');
}

import json
import os
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit, urlunsplit

import gevent
from locust import HttpUser, LoadTestShape, StopUser, constant, task


ITERATIONS_PER_USER = 2
COMPLETED_ACCOUNTS = set()


class FlowFailure(Exception):
    pass


class ShopFormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self.csrf_values = []
        self._current_form = None

    def handle_starttag(self, tag, attrs):
        attrs = {key.lower(): value for key, value in attrs if key}
        tag = tag.lower()

        if tag == "form":
            self._current_form = {
                "action": attrs.get("action"),
                "csrf": [],
                "challenge": [],
            }
            self.forms.append(self._current_form)
        elif tag == "input":
            name = (attrs.get("name") or "").lower()
            value = attrs.get("value")
            if name == "csrf" and value:
                self.csrf_values.append(value)
                if self._current_form is not None:
                    self._current_form["csrf"].append(value)
            elif name == "challenge" and value and self._current_form is not None:
                self._current_form["challenge"].append(value)

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self._current_form = None

    def csrf_token(self):
        for form in self.forms:
            action = (form.get("action") or "").lower()
            if form["csrf"] and "login" in action:
                return form["csrf"][0]
        for form in self.forms:
            if form["csrf"]:
                return form["csrf"][0]
        return self.csrf_values[0] if self.csrf_values else None

    def challenge_form(self):
        for form in self.forms:
            if form["challenge"] and form.get("action"):
                return form["action"], form["challenge"][0]
        return None, None


class TwoUserShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.initialized = False

    def tick(self):
        active_classes = [
            user_class
            for user_class in USER_CLASSES
            if user_class.account_index not in COMPLETED_ACCOUNTS
        ]
        if not active_classes:
            return None

        if not self.initialized:
            self.initialized = True
        return (len(active_classes), 2, active_classes)


class ShopUser(HttpUser):
    abstract = True
    host = os.environ["BASE_URL"]
    wait_time = constant(0)

    account_index = None

    def on_start(self):
        self._done_marked = False
        self.account = None
        self.csrf = None
        self.cart_id = None
        self.etag = None

        try:
            self._load_account()
        except FlowFailure:
            self._mark_done()
            raise StopUser()

    def on_stop(self):
        self._mark_done()

    def _mark_done(self):
        if not getattr(self, "_done_marked", True):
            self._done_marked = True
            COMPLETED_ACCOUNTS.add(self.account_index)

    def _request(
        self,
        method,
        path,
        name,
        *,
        json_body=None,
        headers=None,
        expected_statuses=None,
        parse_json=False,
        optional_json_statuses=(),
        validator=None,
    ):
        request_headers = dict(headers or {})
        kwargs = {
            "name": name,
            "catch_response": True,
            "allow_redirects": False,
            "timeout": 3,
            "headers": request_headers,
        }
        if json_body is not None:
            kwargs["json"] = json_body

        failure = None
        data = None
        with self.client.request(method, path, **kwargs) as response:
            if (
                expected_statuses is not None
                and response.status_code not in expected_statuses
            ):
                failure = (
                    f"{method} {path}: unexpected HTTP "
                    f"{response.status_code}; expected {expected_statuses}"
                )

            if failure is None and parse_json:
                try:
                    data = response.json()
                except Exception as exc:
                    if response.status_code not in optional_json_statuses:
                        failure = f"{method} {path}: invalid JSON response ({exc})"

            if failure is None and validator is not None:
                try:
                    failure = validator(response, data)
                except Exception as exc:
                    failure = f"{method} {path}: response validation error ({exc})"

            if failure:
                response.failure(failure)

        if failure:
            raise FlowFailure(failure)
        return response, data

    def _local_path(self, location):
        if not isinstance(location, str) or not location.strip():
            raise FlowFailure("Missing dynamic URL")

        base = urlsplit(self.host)
        target = urlsplit(urljoin(self.host.rstrip("/") + "/", location.strip()))

        base_port = base.port or (443 if base.scheme.lower() == "https" else 80)
        target_port = target.port or (
            443 if target.scheme.lower() == "https" else 80
        )
        if (
            target.scheme.lower() != base.scheme.lower()
            or (target.hostname or "").lower() != (base.hostname or "").lower()
            or target_port != base_port
        ):
            raise FlowFailure("Dynamic URL points outside the configured target")

        return urlunsplit(("", "", target.path or "/", target.query, ""))

    @staticmethod
    def _response_error(response, data=None):
        if isinstance(data, dict):
            return data.get("error")
        try:
            payload = json.loads(response.text)
            if isinstance(payload, dict):
                return payload.get("error")
        except Exception:
            pass
        return None

    @staticmethod
    def _capture_csrf(data, current):
        if isinstance(data, dict):
            token = data.get("csrf")
            if isinstance(token, str) and token:
                return token
        return current

    def _load_account(self):
        expected_usernames = {"bench-1", "bench-2"}

        def validate_fixture(response, data):
            if not isinstance(data, list) or len(data) != 2:
                return "accounts fixture must contain exactly two records"

            usernames = set()
            for row in data:
                if not isinstance(row, dict):
                    return "accounts fixture contains a non-object record"
                if not isinstance(row.get("username"), str):
                    return "account username must remain a string"
                if not isinstance(row.get("password"), str):
                    return "account password must remain a string"
                if type(row.get("quantity")) is not int:
                    return "account quantity must remain an integer"
                if type(row.get("delay")) is not int:
                    return "account delay must remain an integer"
                usernames.add(row["username"])

            if usernames != expected_usernames:
                return "accounts fixture does not contain the expected users"
            return None

        _, rows = self._request(
            "GET",
            "/fixtures/accounts.json",
            "/fixtures/accounts.json",
            expected_statuses=(200,),
            parse_json=True,
            validator=validate_fixture,
        )

        expected_username = f"bench-{self.account_index + 1}"
        row = next(
            (item for item in rows if item["username"] == expected_username),
            None,
        )
        if row is None:
            raise FlowFailure(f"No fixture record for {expected_username}")

        # Keep the fixture values and their JSON types unchanged.
        self.account = dict(row)

    def _login(self):
        token_box = {}

        def validate_form(response, data):
            parser = ShopFormParser()
            parser.feed(response.text)
            token = parser.csrf_token()
            if not token:
                return "Login form has no input[name=csrf]"
            token_box["csrf"] = token
            return None

        self._request(
            "GET",
            "/v2/login-form",
            "GET /v2/login-form",
            expected_statuses=(200,),
            validator=validate_form,
        )
        form_csrf = token_box["csrf"]
        self.csrf = form_csrf

        def validate_login(response, data):
            if response.status_code == 302:
                if not response.headers.get("Location"):
                    return "Login redirect has no Location header"
                return None
            if not isinstance(data, dict) or not data.get("csrf") or "user" not in data:
                return "Login response must contain csrf and user"
            return None

        response, data = self._request(
            "POST",
            "/v2/login",
            "POST /v2/login",
            json_body={
                "username": self.account["username"],
                "password": self.account["password"],
                "csrf": form_csrf,
            },
            headers={
                "Content-Type": "application/json",
                "X-CSRF-Token": form_csrf,
            },
            expected_statuses=(200, 302),
            parse_json=True,
            optional_json_statuses=(302,),
            validator=validate_login,
        )

        if response.status_code == 302:
            location = self._local_path(response.headers["Location"])

            def validate_redirect(response, data):
                if not isinstance(data, dict) or not data.get("csrf") or "user" not in data:
                    return "Login redirect response must contain csrf and user"
                return None

            _, data = self._request(
                "GET",
                location,
                "GET login Location",
                expected_statuses=(200,),
                parse_json=True,
                validator=validate_redirect,
            )

        self.csrf = self._capture_csrf(data, form_csrf)

    def _authenticated_request(
        self,
        method,
        path,
        name,
        *,
        json_body=None,
        expected_statuses=(200,),
        parse_json=False,
        optional_json_statuses=(),
        extra_headers=None,
        success_validator=None,
    ):
        for attempt in range(2):
            headers = dict(extra_headers or {})
            if method.upper() != "GET":
                if not self.csrf:
                    raise FlowFailure("Missing CSRF token for authenticated mutation")
                headers["X-CSRF-Token"] = self.csrf
                headers.setdefault("Content-Type", "application/json")

            def validate(response, data):
                if response.status_code == 401:
                    error = self._response_error(response, data)
                    if attempt == 0 and error in ("expired", "session"):
                        return None
                    return f"Authenticated request failed with 401 error={error!r}"

                if success_validator is not None:
                    return success_validator(response, data)
                return None

            response, data = self._request(
                method,
                path,
                name,
                json_body=json_body,
                headers=headers,
                expected_statuses=tuple(expected_statuses) + (401,),
                parse_json=parse_json,
                optional_json_statuses=tuple(optional_json_statuses) + (401,),
                validator=validate,
            )

            if response.status_code != 401:
                self.csrf = self._capture_csrf(data, self.csrf)
                return response, data

            error = self._response_error(response, data)
            self._recover_session(error)

        raise FlowFailure("Authenticated operation exceeded its single retry")

    def _recover_session(self, interrupted_error):
        def validate_renew(response, data):
            if response.status_code == 401:
                error = self._response_error(response, data)
                if interrupted_error == "session" and error == "session":
                    return None
                return f"Session renewal failed with error={error!r}"
            if not isinstance(data, dict) or not data.get("csrf"):
                return "Session renewal did not return a fresh csrf token"
            return None

        renew_response, renew_data = self._request(
            "POST",
            "/v2/session/renew",
            "POST /v2/session/renew",
            json_body={},
            headers={
                "Content-Type": "application/json",
                "X-CSRF-Token": self.csrf or "",
            },
            expected_statuses=(200, 401),
            parse_json=True,
            optional_json_statuses=(401,),
            validator=validate_renew,
        )

        if renew_response.status_code == 200:
            self.csrf = self._capture_csrf(renew_data, self.csrf)
        else:
            self._login()

        if self.cart_id:
            def validate_recover(response, data):
                if response.status_code == 401:
                    return (
                        "Cart recovery was rejected with "
                        f"error={self._response_error(response, data)!r}"
                    )
                return None

            recover_headers = {
                "Content-Type": "application/json",
                "X-CSRF-Token": self.csrf or "",
            }
            response, _ = self._request(
                "POST",
                f"/v2/carts/{self.cart_id}/recover",
                "POST cart recover",
                json_body={},
                headers=recover_headers,
                expected_statuses=(200, 401),
                parse_json=True,
                optional_json_statuses=(200, 401),
                validator=validate_recover,
            )
            try:
                recovered_data = response.json()
            except Exception:
                recovered_data = None
            self.csrf = self._capture_csrf(recovered_data, self.csrf)

    def _catalog_choice(self):
        choice = {}

        def validate_catalog(response, data):
            if not isinstance(data, dict):
                return "Catalog response is not an object"
            catalog_data = data.get("data")
            products = catalog_data.get("products") if isinstance(catalog_data, dict) else None
            if not isinstance(products, list):
                return "Catalog response has no data.products list"

            for product in products:
                if not isinstance(product, dict) or product.get("id") is None:
                    continue
                variants = product.get("variants")
                if not isinstance(variants, list):
                    continue
                for variant in variants:
                    if (
                        isinstance(variant, dict)
                        and variant.get("in_stock") is True
                        and variant.get("id") is not None
                    ):
                        choice["product_id"] = product["id"]
                        choice["variant_id"] = variant["id"]
                        return None

            return "Catalog contains no in-stock product variant"

        self._request(
            "GET",
            "/v2/catalog",
            "GET /v2/catalog",
            expected_statuses=(200,),
            parse_json=True,
            validator=validate_catalog,
        )
        return choice["product_id"], choice["variant_id"]

    def _challenge_grant(self):
        form_box = {}

        def validate_challenge_form(response, data):
            parser = ShopFormParser()
            parser.feed(response.text)
            action, challenge = parser.challenge_form()
            if not action or not challenge:
                return "Challenge form is missing its action or input[name=challenge]"
            try:
                form_box["action"] = self._local_path(action)
            except FlowFailure as exc:
                return str(exc)
            form_box["challenge"] = challenge
            return None

        self._request(
            "GET",
            "/v2/challenge-form",
            "GET /v2/challenge-form",
            expected_statuses=(200,),
            validator=validate_challenge_form,
        )

        def validate_challenge_post(response, data):
            if not response.headers.get("Location"):
                return "Challenge redirect has no Location header"
            try:
                self._local_path(response.headers["Location"])
            except FlowFailure as exc:
                return str(exc)
            return None

        response, _ = self._authenticated_request(
            "POST",
            form_box["action"],
            "POST challenge",
            json_body={"challenge": form_box["challenge"]},
            expected_statuses=(302,),
            parse_json=False,
            success_validator=validate_challenge_post,
        )
        grant_location = self._local_path(response.headers["Location"])

        grant_box = {}

        def validate_grant(response, data):
            if not isinstance(data, dict):
                return "Challenge redirect did not return a JSON object"
            if not data.get("grant_id") or not data.get("csrf"):
                return "Challenge redirect response is missing grant_id or csrf"
            grant_box["grant_id"] = data["grant_id"]
            return None

        _, data = self._request(
            "GET",
            grant_location,
            "GET challenge Location",
            expected_statuses=(200,),
            parse_json=True,
            validator=validate_grant,
        )
        self.csrf = self._capture_csrf(data, self.csrf)
        return grant_box["grant_id"]

    def _read_cart_etag(self):
        def validate_etag(response, data):
            if not response.headers.get("ETag"):
                return "Cart response has no ETag"
            return None

        response, _ = self._authenticated_request(
            "GET",
            f"/v2/carts/{self.cart_id}",
            "GET cart",
            expected_statuses=(200,),
            parse_json=False,
            success_validator=validate_etag,
        )
        self.etag = response.headers["ETag"]
        return self.etag

    def _create_cart(self, product_id, variant_id, grant_id):
        def validate_cart(response, data):
            if not isinstance(data, dict) or not isinstance(data.get("id"), str):
                return "Cart creation response has no string id"
            if not data["id"].startswith("cart-"):
                return "Cart creation returned an unexpected id"
            if not data.get("csrf"):
                return "Cart creation response has no csrf"
            if not response.headers.get("ETag"):
                return "Cart creation response has no ETag"
            return None

        response, data = self._authenticated_request(
            "POST",
            "/v2/carts",
            "POST /v2/carts",
            json_body={
                "product_id": product_id,
                "variant_id": variant_id,
                "grant_id": grant_id,
            },
            expected_statuses=(201,),
            parse_json=True,
            success_validator=validate_cart,
        )
        self.cart_id = data["id"]
        self.etag = response.headers["ETag"]
        self.csrf = self._capture_csrf(data, self.csrf)

    def _set_quantity(self):
        payload = {"quantity": self.account["quantity"]}

        for patch_attempt in range(2):
            def validate_patch(response, data):
                if response.status_code == 412:
                    if patch_attempt == 0:
                        return None
                    return "Cart quantity update still failed after one 412 retry"
                return None

            response, data = self._authenticated_request(
                "PATCH",
                f"/v2/carts/{self.cart_id}",
                "PATCH cart quantity",
                json_body=payload,
                expected_statuses=(200, 204, 412),
                parse_json=True,
                optional_json_statuses=(204, 412),
                extra_headers={"If-Match": self.etag},
                success_validator=validate_patch,
            )

            if response.status_code == 412:
                self._read_cart_etag()
                continue

            self.csrf = self._capture_csrf(data, self.csrf)
            updated_etag = response.headers.get("ETag")
            self.etag = updated_etag or self._read_cart_etag()
            return

        raise FlowFailure("Cart quantity update exceeded its single 412 retry")

    def _reserve(self):
        def validate_reservation(response, data):
            if not isinstance(data, dict) or not data.get("status_url"):
                return "Reservation response has no status_url"
            try:
                self._local_path(data["status_url"])
            except FlowFailure as exc:
                return str(exc)
            return None

        response, data = self._authenticated_request(
            "POST",
            "/v2/reservations",
            "POST /v2/reservations",
            json_body={"cart_id": self.cart_id},
            expected_statuses=(202,),
            parse_json=True,
            success_validator=validate_reservation,
        )
        self.csrf = self._capture_csrf(data, self.csrf)
        status_path = self._local_path(data["status_url"])

        for poll_index in range(5):
            if poll_index:
                gevent.sleep(0.05)

            result = {}

            def validate_status(response, payload):
                if not isinstance(payload, dict):
                    return "Reservation status is not a JSON object"
                status = payload.get("status")
                if status == "failed":
                    return "Reservation failed"
                if status == "ready":
                    if not payload.get("reservation_id"):
                        return "Ready reservation has no reservation_id"
                    result["reservation_id"] = payload["reservation_id"]
                    return None
                if status != "pending":
                    return f"Unexpected reservation status {status!r}"
                if poll_index == 4:
                    return "Reservation did not become ready within five polls"
                return None

            _, payload = self._authenticated_request(
                "GET",
                status_path,
                "GET reservation status",
                expected_statuses=(200,),
                parse_json=True,
                success_validator=validate_status,
            )
            if isinstance(payload, dict) and payload.get("status") == "ready":
                return result["reservation_id"]

        raise FlowFailure("Reservation was not ready")

    def _place_order(self, reservation_id):
        def validate_order(response, data):
            if response.status_code != 201:
                return "Order was not created with HTTP 201"
            if not isinstance(data, dict) or data.get("accepted") is not True:
                return "Order response did not confirm accepted=true"
            return None

        self._authenticated_request(
            "POST",
            "/v2/orders",
            "POST /v2/orders",
            json_body={
                "cart_id": self.cart_id,
                "reservation_id": reservation_id,
            },
            expected_statuses=(200, 201),
            parse_json=True,
            extra_headers={
                "If-Match": self.etag,
                "Idempotency-Key": self.cart_id,
            },
            success_validator=validate_order,
        )

    def _journey(self):
        self.csrf = None
        self.cart_id = None
        self.etag = None

        self._login()
        product_id, variant_id = self._catalog_choice()
        grant_id = self._challenge_grant()
        self._create_cart(product_id, variant_id, grant_id)
        self._set_quantity()
        reservation_id = self._reserve()
        self._place_order(reservation_id)

    @task
    def execute_iterations(self):
        try:
            for _ in range(ITERATIONS_PER_USER):
                self._journey()
        except FlowFailure:
            self._mark_done()
            raise StopUser()
        self._mark_done()
        raise StopUser()


class BenchOneUser(ShopUser):
    account_index = 0
    fixed_count = 1


class BenchTwoUser(ShopUser):
    account_index = 1
    fixed_count = 1


USER_CLASSES = [BenchOneUser, BenchTwoUser]

