import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.time.Duration;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
  private static final String BASE_URL = baseUrl();

  private static String baseUrl() {
    String value = System.getenv("BASE_URL");
    return value == null || value.isBlank() ? "http://127.0.0.1:8000" : value;
  }

  private static ChainBuilder clearJourneyState() {
    return exec(session ->
      session.remove("csrf")
        .remove("formCsrf")
        .remove("loginLocation")
        .remove("productId")
        .remove("variantId")
        .remove("catalogNext")
        .remove("pageUrl")
        .remove("cartId")
        .remove("cartEtag")
        .remove("orderId")
    );
  }

  private static ChainBuilder catalogPage(String requestName) {
    return doIf(session ->
        !session.contains("productId")
          && session.contains("catalogNext")
          && session.getString("catalogNext") != null
          && !"null".equals(session.getString("catalogNext"))
      )
      .then(
        exec(session ->
          session.set("pageUrl", session.getString("catalogNext"))
            .remove("catalogNext")
        )
        .exec(
          http(requestName)
            .get("#{pageUrl}")
            .check(
              status().is(200),
              jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id")
                .find().optional().saveAs("productId"),
              jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id")
                .find().optional().saveAs("variantId"),
              jsonPath("$.next").optional().saveAs("catalogNext")
            )
        )
      );
  }

  private static ChainBuilder checkout() {
    return doIf(session -> session.contains("productId") && session.contains("variantId"))
      .then(
        exec(
          http("create cart")
            .post("/v2/carts")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{\"product_id\":\"#{productId}\",\"variant_id\":\"#{variantId}\"}"))
            .check(
              status().is(201),
              jsonPath("$.id").saveAs("cartId"),
              jsonPath("$.csrf").optional().saveAs("csrf"),
              header("ETag").optional().saveAs("cartEtag")
            )
        )
        .exec(
          doIf(session -> session.contains("cartEtag"))
            .then(
              exec(
                http("commit order")
                  .post("/v2/orders")
                  .header("Content-Type", "application/json")
                  .header("X-CSRF-Token", "#{csrf}")
                  .header("Idempotency-Key", "#{cartId}")
                  .header("If-Match", "#{cartEtag}")
                  .body(StringBody("{\"cart_id\":\"#{cartId}\"}"))
                  .check(
                    status().is(201),
                    jsonPath("$.accepted").is("true"),
                    jsonPath("$.id").saveAs("orderId"),
                    jsonPath("$.csrf").optional().saveAs("csrf")
                  )
              )
            )
        )
        .exec(
          doIf(session -> !session.contains("cartEtag"))
            .then(
              exec(
                http("commit order")
                  .post("/v2/orders")
                  .header("Content-Type", "application/json")
                  .header("X-CSRF-Token", "#{csrf}")
                  .header("Idempotency-Key", "#{cartId}")
                  .body(StringBody("{\"cart_id\":\"#{cartId}\"}"))
                  .check(
                    status().is(201),
                    jsonPath("$.accepted").is("true"),
                    jsonPath("$.id").saveAs("orderId"),
                    jsonPath("$.csrf").optional().saveAs("csrf")
                  )
              )
            )
        )
      );
  }

  private final HttpProtocolBuilder httpProtocol =
    http.baseUrl(BASE_URL)
      .acceptHeader("application/json")
      .disableFollowRedirect();

  private final ScenarioBuilder journey =
    scenario("owned checkout journey")
      .exec(session ->
        session.set("username", "bench-" + ((session.userId() % 16) + 1))
      )
      .during(Duration.ofSeconds(38)).on(
        exec(pace(Duration.ofSeconds(2)))
          .exec(clearJourneyState())
          .exec(
            http("login form")
              .get("/v2/login-form")
              .check(
                status().is(200),
                css("input[name='csrf']", "value").saveAs("formCsrf")
              )
          )
          .exec(session -> session.set("csrf", session.getString("formCsrf")))
          .exec(
            http("login")
              .post("/v2/login")
              .header("Content-Type", "application/json")
              .body(StringBody(
                "{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{formCsrf}\"}"
              ))
              .check(
                status().in(200, 302),
                jsonPath("$.csrf").optional().saveAs("csrf"),
                header("Location").optional().saveAs("loginLocation")
              )
          )
          .exec(
            doIf(session -> session.contains("loginLocation"))
              .then(
                exec(
                  http("login redirect")
                    .get("#{loginLocation}")
                    .check(
                      status().is(200),
                      jsonPath("$.csrf").optional().saveAs("csrf")
                    )
                )
              )
          )
          .exec(
            http("catalog")
              .get("/v2/catalog")
              .check(
                status().is(200),
                jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id")
                  .find().optional().saveAs("productId"),
                jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id")
                  .find().optional().saveAs("variantId"),
                jsonPath("$.next").optional().saveAs("catalogNext")
              )
          )
          .exec(catalogPage("catalog page 2"))
          .exec(catalogPage("catalog page 3"))
          .exec(checkout())
      );

  {
    setUp(
      journey.injectOpen(rampUsers(4).during(Duration.ofMillis(1500)))
    )
      .protocols(httpProtocol)
      .maxDuration(Duration.ofSeconds(42));
  }
}

