import http from 'k6/http';
import { check } from 'k6';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const ORIGIN = (BASE.match(/^https?:\/\/[^/]+/i) || [BASE])[0];

export const options = {
  scenarios: {
    checkout_journey: {
      executor: 'constant-arrival-rate',
      rate: 2,
      timeUnit: '1s',
      duration: '38s',
      preAllocatedVUs: 4,
      maxVUs: 4,
      gracefulStop: '5s',
    },
  },
};

function json(res) {
  try {
    return JSON.parse(res.body || '{}');
  } catch (_) {
    return {};
  }
}

function responseHeader(res, name) {
  const wanted = name.toLowerCase();
  for (const key in res.headers) {
    if (key.toLowerCase() === wanted) return res.headers[key];
  }
  return '';
}

function decodeHtml(value) {
  return value
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');
}

function csrfFromForm(body) {
  const inputs = (body || '').match(/<input\b[^>]*>/gi) || [];
  for (const tag of inputs) {
    const attrs = {};
    const attrText = tag.replace(/^<input\b/i, '').replace(/\/?>$/, '');
    const pattern = /([^\s=/>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g;
    let match;
    while ((match = pattern.exec(attrText)) !== null) {
      attrs[match[1].toLowerCase()] = decodeHtml(match[2] || match[3] || match[4] || '');
    }
    if ((attrs.name || '').toLowerCase() === 'csrf' && attrs.value) return attrs.value;
  }
  return '';
}

function locationUrl(location) {
  if (!location) return '';
  if (/^https?:\/\//i.test(location)) {
