import json
import os
import re
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit, urlunsplit

from locust import HttpUser, LoadTestShape, constant_pacing, task
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
ITERATIONS_PER_USER = 19
COMPLETED_USERS = 0


class JourneyAbort(Exception):
    pass


class FormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self.inputs = []
        self.current_form = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag.lower() == "form":
            self.forms.append(attrs)
            self.current_form = len(self.forms) - 1
        elif tag.lower() == "input":
            self.inputs.append((attrs, self.current_form))

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self.current_form = None

    def csrf_token(self):
        for attrs, _ in self.inputs:
            if (attrs.get("name") or "").lower() == "csrf" and attrs.get("value"):
                return attrs["value"]
        return None

    def challenge_form(self):
        for attrs, form_index in self.inputs:
            if (attrs.get("name") or "").lower() != "challenge" or not attrs.get("value"):
                continue
            if form_index is None or form_index >= len(self.forms):
                continue
            action = self.forms[form_index].get("action")
            if action:
                return action, attrs["value"]
        return None, None


def json_object(response):
    try:
        value = response.json()
    except (ValueError, json.JSONDecodeError):
        return None
    return value if isinstance(value, dict) else None


def catalog_products(payload):
    data = payload.get("data")
    if isinstance(data, dict) and isinstance(data.get("products"), list):
        return data["products"]
    if isinstance(data, dict) and isinstance(data.get("product"), dict):
        return [data["product"]]
    if isinstance(payload.get("product"), dict):
        return [payload["product"]]
    return None


def available_product(payload):
    products = catalog_products(payload) or []
    for product in products:
        if not isinstance(product, dict) or not product.get("id"):
            continue
        variants = product.get("variants")
        if not isinstance(variants, list):
            continue
        for variant in variants:
            if (
                isinstance(variant, dict)
                and variant.get("in_stock") is True
                and variant.get("id")
            ):
                return product["id"], variant["id"]
    return None


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant_pacing(2.0)
    account_number = 0

    def on_start(self):
        type(self).account_number += 1
        self.username = f"bench-{((type(self).account_number - 1) % 16) + 1}"
        self.iterations = 0
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant_id = None

    def _response_json(self, response):
        return json_object(response)

    def _capture_csrf(self, response):
        payload = self._response_json(response)
        if payload and isinstance(payload.get("csrf"), str) and payload["csrf"]:
            self.csrf = payload["csrf"]

    def _internal_location(self, location, current_path):
        if not location:
            raise JourneyAbort("Missing redirect Location")
        base = urlsplit(self.host)
        resolved = urlsplit(urljoin(self.host.rstrip("/") + current_path, location))
        if (
            resolved.scheme != base.scheme
            or resolved.netloc != base.netloc
            or not resolved.path.startswith("/")
        ):
            raise JourneyAbort("Redirect is not on the configured host")
        return urlunsplit(("", "", resolved.path, resolved.query, ""))

    def _one_request(
        self,
        method,
        path,
        *,
        body=None,
        headers=None,
        expected=(200,),
        check=None,
        name=None,
        recoverable_401=False,
    ):
        with self.client.request(
            method,
            path,
            json=body,
            headers=dict(headers or {}),
            name=name or path,
            allow_redirects=False,
            timeout=(2, 3),
            catch_response=True,
        ) as response:
            payload = self._response_json(response)
            error = payload.get("error") if payload else None
            is_recoverable = (
                recoverable_401
                and response.status_code == 401
                and error in ("expired", "session")
            )
            if is_recoverable:
                valid = True
                response.success()
            elif response.status_code in expected:
                try:
                    valid = check is None or bool(check(response))
                except Exception:
                    valid = False
                if valid:
                    response.success()
                else:
                    response.failure("Response assertion failed")
            else:
                valid = False
                response.failure(f"Unexpected HTTP status {response.status_code}")
            self._capture_csrf(response)
        return response, valid

    def _request(
        self,
        method,
        path,
        *,
        body=None,
        headers=None,
        expected=(200,),
        check=None,
        name=None,
        auth=True,
    ):
        for attempt in range(2):
            request_headers = dict(headers or {})
            if auth and method.upper() != "GET" and self.csrf:
                request_headers["X-CSRF-Token"] = self.csrf

            response, valid = self._one_request(
                method,
                path,
                body=body,
                headers=request_headers,
                expected=expected,
                check=check,
                name=name,
                recoverable_401=auth,
            )
            payload = self._response_json(response)
            error = payload.get("error") if payload else None

            if (
                auth
                and response.status_code == 401
                and error in ("expired", "session")
                and attempt == 0
            ):
                if not self._recover_session(error):
                    raise JourneyAbort("Session recovery failed")
                continue

            if response.status_code not in expected or not valid:
                raise JourneyAbort(f"{method} {path} failed")
            return response

        raise JourneyAbort(f"{method} {path} recovery exhausted")

    def _perform_login(self):
        self.csrf = None

        def valid_login_form(response):
            parser = FormParser()
            parser.feed(response.text)
            return parser.csrf_token() is not None

        form_response = self._request(
            "GET",
            "/v2/login-form",
            expected=(200,),
            check=valid_login_form,
            auth=False,
        )
        parser = FormParser()
        parser.feed(form_response.text)
        form_token = parser.csrf_token()
        if not form_token:
            raise JourneyAbort("Login form has no CSRF token")

        def valid_login_response(response):
            if response.status_code == 302:
                try:
                    self._internal_location(response.headers.get("Location"), "/v2/login")
                    return True
                except JourneyAbort:
                    return False
            payload = self._response_json(response)
            return bool(payload and isinstance(payload.get("csrf"), str) and payload.get("csrf"))

        login_response = self._request(
            "POST",
            "/v2/login",
            body={"username": self.username, "password": "bench", "csrf": form_token},
            headers={"X-CSRF-Token": form_token},
            expected=(200, 302),
            check=valid_login_response,
            auth=False,
        )

        if login_response.status_code == 302:
            location = self._internal_location(
                login_response.headers.get("Location"), "/v2/login"
            )
            self._request(
                "GET",
                location,
                expected=(200,),
                check=lambda response: self._response_json(response) is not None,
                name="/v2/login redirect target",
                auth=False,
            )

    def _recover_session(self, error):
        renew_headers = {"X-CSRF-Token": self.csrf} if self.csrf else {}
        renew_response, renew_valid = self._one_request(
            "POST",
            "/v2/session/renew",
            body={},
            headers=renew_headers,
            expected=(200, 401),
            check=lambda response: (
                response.status_code == 401
                or bool((self._response_json(response) or {}).get("csrf"))
            ),
            name="/v2/session/renew",
        )
        renewed = renew_response.status_code == 200 and renew_valid

        if error == "expired" and not renewed:
            return False

        if error == "session" and not renewed:
            try:
                self._perform_login()
            except JourneyAbort:
                return False

        if self.cart_id:
            recover_headers = {"X-CSRF-Token": self.csrf} if self.csrf else {}
            recover_response, recover_valid = self._one_request(
                "POST",
                f"/v2/carts/{self.cart_id}/recover",
                body={},
                headers=recover_headers,
                expected=(200,),
                name="/v2/carts/[id]/recover",
            )
            if recover_response.status_code != 200 or not recover_valid:
                return False

        return True

    def _catalog_check(self, response):
        payload = self._response_json(response)
        return bool(
            payload
            and catalog_products(payload) is not None
            and "next" in payload
            and (payload["next"] is None or isinstance(payload["next"], str))
        )

    def _select_product(self):
        path = "/v2/catalog"
        seen = set()

        for page_number in range(4):
            response = self._request(
                "GET",
                path,
                expected=(200,),
                check=self._catalog_check,
                name="/v2/catalog" if page_number == 0 else "/v2/catalog/page",
            )
            payload = self._response_json(response)
            selected = available_product(payload)
            if selected:
                return selected

            next_url = payload.get("next")
            if not next_url or page_number == 3:
                break
            path = self._internal_location(next_url, path)
            if urlsplit(path).path != "/v2/catalog/page" or path in seen:
                raise JourneyAbort("Invalid catalog pagination link")
            seen.add(path)

        raise JourneyAbort("No in-stock catalog variant found")

    def _get_challenge_grant(self):
        def valid_challenge_form(response):
            parser = FormParser()
            parser.feed(response.text)
            action, challenge = parser.challenge_form()
            if not action or not challenge:
                return False
            try:
                resolved = self._internal_location(action, "/v2/challenge-form")
            except JourneyAbort:
                return False
            return bool(
                re.fullmatch(r"/v2/challenges/[^/?#]+", urlsplit(resolved).path)
            )

        form_response = self._request(
            "GET",
            "/v2/challenge-form",
            expected=(200,),
            check=valid_challenge_form,
        )
        parser = FormParser()
        parser.feed(form_response.text)
        action, challenge = parser.challenge_form()
        challenge_path = self._internal_location(action, "/v2/challenge-form")
        if not challenge or not re.fullmatch(
            r"/v2/challenges/[^/?#]+", urlsplit(challenge_path).path
        ):
            raise JourneyAbort("Invalid challenge form")

        def valid_challenge_post(response):
            try:
                self._internal_location(response.headers.get("Location"), challenge_path)
                return response.status_code == 302
            except JourneyAbort:
                return False

        challenge_response = self._request(
            "POST",
            challenge_path,
            body={"challenge": challenge},
            expected=(302,),
            check=valid_challenge_post,
            name="/v2/challenges/[id]",
        )
        grant_location = self._internal_location(
            challenge_response.headers.get("Location"), challenge_path
        )

        grant_response = self._request(
            "GET",
            grant_location,
            expected=(200,),
            check=lambda response: bool(
                (self._response_json(response) or {}).get("grant_id")
            ),
            name="/v2/challenge redirect target",
        )
        payload = self._response_json(grant_response)
        self.grant_id = payload.get("grant_id") if payload else None
        if not self.grant_id:
            raise JourneyAbort("Challenge did not return a grant")

    def _checkout(self):
        product_id, variant_id = self._select_product()
        self._get_challenge_grant()

        cart_body = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            cart_body["grant_id"] = self.grant_id

        cart_response = self._request(
            "POST",
            "/v2/carts",
            body=cart_body,
            expected=(201,),
            check=lambda response: bool((self._response_json(response) or {}).get("id")),
        )
        cart_payload = self._response_json(cart_response)
        self.cart_id = cart_payload.get("id") if cart_payload else None
        self.etag = cart_response.headers.get("ETag")
        self.grant_id = None
        if not self.cart_id:
            raise JourneyAbort("Cart creation returned no ID")

        order_headers = {"Idempotency-Key": str(self.cart_id)}
        if self.etag:
            order_headers["If-Match"] = self.etag

        self._request(
            "POST",
            "/v2/orders",
            body={"cart_id": self.cart_id},
            headers=order_headers,
            expected=(201,),
            check=lambda response: bool(
                (self._response_json(response) or {}).get("accepted") is True
                and (self._response_json(response) or {}).get("id")
            ),
        )

    @task
    def checkout_iteration(self):
        global COMPLETED_USERS

        if self.iterations >= ITERATIONS_PER_USER:
            raise StopUser()

        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant_id = None

        try:
            self._perform_login()
            self._checkout()
        except Exception:
            pass

        self.iterations += 1
        if self.iterations >= ITERATIONS_PER_USER:
            COMPLETED_USERS += 1
            raise StopUser()


