import http from 'k6/http';
import { check, group } from 'k6';
import { Rate } from 'k6/metrics';

const BASE_URL = String(__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const BASE_ORIGIN = new URL(BASE_URL).origin;
const TRANSACTION = 'shopping_journey';

const loginAssertion = new Rate('jmeter_login_csrf_assertion');
const cartAssertion = new Rate('jmeter_cart_id_assertion');
const orderAssertion = new Rate('jmeter_order_accepted_assertion');

export const options = {
  scenarios: {
    journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '10m',
    },
  },
  thresholds: {
    jmeter_login_csrf_assertion: ['rate==1'],
    jmeter_cart_id_assertion: ['rate==1'],
    jmeter_order_accepted_assertion: ['rate==1'],
  },
};

function targetUrl(ref) {
  const url = new URL(ref, `${BASE_URL}/`);
  if (url.origin !== BASE_ORIGIN) {
    throw new Error(`Refusing URL outside configured target: ${url.origin}`);
  }
  return url.toString();
}

function requestParams(name, headers) {
  return {
    headers: headers || {},
    tags: { name, transaction: TRANSACTION },
    redirects: 0,
    timeout: '3s',
  };
}

function headerValue(response, name) {
  if (!response || !response.headers) return '';
  const wanted = name.toLowerCase();
  const key = Object.keys(response.headers).find((k) => k.toLowerCase() === wanted);
  if (!key) return '';
  const value = response.headers[key];
  return Array.isArray(value) ? String(value[0] || '') : String(value || '');
}

function parseJson(response) {
  if (!response || !response.body) return null;
  try {
    return JSON.parse(response.body);
  } catch (_) {
    return null;
  }
}

function updateCsrf(ctx, response) {
  const data = parseJson(response);
  if (data && data.csrf !== undefined && data.csrf !== null && String(data.csrf) !== '') {
    ctx.csrf = String(data.csrf);
  }
}

function decodeHtml(value) {
  return value.replace(/&(#x[0-9a-f]+|#\d+|amp|quot|apos|lt|gt);/gi, (entity, code) => {
    const lower = code.toLowerCase();
    if (lower === 'amp') return '&';
    if (lower === 'quot') return '"';
    if (lower === 'apos') return "'";
    if (lower === 'lt') return '<';
    if (lower === 'gt') return '>';
    if (lower.startsWith('#x')) return String.fromCharCode(parseInt(lower.slice(2), 16));
    if (lower.startsWith('#')) return String.fromCharCode(parseInt(lower.slice(1), 10));
    return entity;
  });
}

function inputAttributes(tag) {
  const inner = tag.replace(/^<input\b/i, '').replace(/\/?>$/, '');
  const attrs = {};
  const attrPattern = /([^\s=/>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/g;
  let match;
  while ((match = attrPattern.exec(inner)) !== null) {
    attrs[match[1].toLowerCase()] = decodeHtml(match[2] !== undefined
      ? match[2]
      : match[3] !== undefined
        ? match[3]
        : match[4] !== undefined
          ? match[4]
          : '');
  }
  return attrs;
}

function extractInputValue(html, wantedName) {
  const tags = String(html || '').match(/<input\b[^>]*>/gi) || [];
  for (const tag of tags) {
    const attrs = inputAttributes(tag);
    if (String(attrs.name || '').toLowerCase() === wantedName.toLowerCase() && attrs.value) {
      return attrs.value;
    }
  }
  return '';
}

function recordAssertion(response, label, metric, matcher) {
  const passed = check(response || {}, {
    [label]: (res) => matcher(String((res && res.body) || '')),
  });
  metric.add(passed, { transaction: TRANSACTION });
  return passed;
}

function getLoginForm(ctx) {
  const response = http.get(
    targetUrl('/v2/login-form'),
    requestParams('GET /v2/login-form'),
  );
  const csrf = extractInputValue(response.body, 'csrf');
  if (!csrf) throw new Error('Login form did not contain input[name=csrf]');
  ctx.csrf = csrf;
}

function login(ctx, assertSourceSampler) {
  getLoginForm(ctx);

  const response = http.post(
    targetUrl('/v2/login'),
    JSON.stringify({
      username: ctx.username,
      password: 'bench',
      csrf: ctx.csrf,
    }),
    requestParams('POST /v2/login', { 'Content-Type': 'application/json' }),
  );

  if (assertSourceSampler) {
    recordAssertion(
      response,
      'JMeter assertion: login response contains csrf',
      loginAssertion,
      (body) => /"csrf"\s*:/.test(body),
    );
  }
  updateCsrf(ctx, response);

  const location = headerValue(response, 'Location');
  if (location) {
    const redirected = http.get(
      targetUrl(location),
      requestParams('GET login redirect'),
    );
    updateCsrf(ctx, redirected);
    const data = parseJson(redirected);
    if (data && data.grant_id !== undefined && data.grant_id !== null) {
      ctx.grantId = String(data.grant_id);
    }
  }

  if (!ctx.csrf) throw new Error('Login did not provide a CSRF token');
}

function rawAuthenticatedPost(ctx, path, body, name, extraHeaders) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': ctx.csrf,
    ...(extraHeaders || {}),
  };
  return http.post(
    targetUrl(path),
    JSON.stringify(body),
    requestParams(name, headers),
  );
}

function authError(response) {
  const data = parseJson(response);
  return data && typeof data.error === 'string' ? data.error : '';
}

function authenticatedPost(ctx, path, body, name, extraHeaders) {
  const first = rawAuthenticatedPost(ctx, path, body, name, extraHeaders);
  updateCsrf(ctx, first);

  if (first.status !== 401) return first;
  const error = authError(first);
  if (error !== 'expired' && error !== 'session') return first;

  const renew = rawAuthenticatedPost(
    ctx,
    '/v2/session/renew',
    {},
    'POST /v2/session/renew',
  );
  updateCsrf(ctx, renew);

  let recoveryReady = renew.status >= 200 && renew.status < 300;
  if (!recoveryReady && error === 'session') {
    login(ctx, false);
    recoveryReady = true;
  }
  if (!recoveryReady) return first;

  if (ctx.cartId) {
    const recovered = rawAuthenticatedPost(
      ctx,
      `/v2/carts/${encodeURIComponent(ctx.cartId)}/recover`,
      {},
      'POST /v2/carts/{id}/recover',
    );
    updateCsrf(ctx, recovered);
    if (recovered.status < 200 || recovered.status >= 300) return first;
  }

  // Retry only the interrupted operation, once, with its original payload and headers.
  const retry = rawAuthenticatedPost(ctx, path, body, name, extraHeaders);
  updateCsrf(ctx, retry);
  return retry;
}

function findAvailableProduct() {
  let pageUrl = targetUrl('/v2/catalog');

  for (let page = 0; page < 3; page += 1) {
    const name = page === 0 ? 'GET /v2/catalog' : 'GET /v2/catalog/page';
    const response = http.get(pageUrl, requestParams(name));
    const data = parseJson(response);
    const products = data && data.data && Array.isArray(data.data.products)
      ? data.data.products
      : [];

    for (const product of products) {
      const variants = Array.isArray(product.variants) ? product.variants : [];
      const variant = variants.find((item) => item && item.in_stock === true);
      if (product.id !== undefined && variant && variant.id !== undefined) {
        return { productId: product.id, variantId: variant.id };
      }
    }

    if (!data || !data.next) break;
    pageUrl = targetUrl(String(data.next));
  }

  throw new Error('No in-stock product variant found in the first three catalog pages');
}

export default function () {
  const jar = http.cookieJar();
  jar.clear(BASE_URL);

  const ctx = {
    username: `bench-${__VU}`,
    csrf: '',
    grantId: '',
    cartId: '',
    etag: '',
  };

  group(TRANSACTION, () => {
    login(ctx, true);

    const selection = findAvailableProduct();
    const cartPayload = {
      product_id: selection.productId,
      variant_id: selection.variantId,
    };
    if (ctx.grantId) cartPayload.grant_id = ctx.grantId;

    const cartResponse = authenticatedPost(
      ctx,
      '/v2/carts',
      cartPayload,
      'POST /v2/carts',
    );

    recordAssertion(
      cartResponse,
      'JMeter assertion: cart response id begins with cart-',
      cartAssertion,
      (body) => /"id"\s*:\s*"cart-/.test(body),
    );

    const cartData = parseJson(cartResponse);
    if (cartData && cartData.id !== undefined && cartData.id !== null) {
      ctx.cartId = String(cartData.id);
    }
    const cartEtag = headerValue(cartResponse, 'ETag');
    if (cartEtag) ctx.etag = cartEtag;
    if (!ctx.cartId) throw new Error('Cart response did not provide a cart id');

    const orderHeaders = { 'Idempotency-Key': ctx.cartId };
    if (ctx.etag) orderHeaders['If-Match'] = ctx.etag;

    const orderResponse = authenticatedPost(
      ctx,
      '/v2/orders',
      { cart_id: ctx.cartId },
      'POST /v2/orders',
      orderHeaders,
    );

    recordAssertion(
      orderResponse,
      'JMeter assertion: order response is accepted',
      orderAssertion,
      (body) => /"accepted"\s*:\s*true\b/.test(body),
    );
  });
}

