import http from 'k6/http';
import { check, group } from 'k6';
import { Rate } from 'k6/metrics';

const BASE_URL = String(__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const BASE_ORIGIN = new URL(BASE_URL).origin;
const TRANSACTION = 'shopping_journey';

const loginAssertion = new Rate('jmeter_login_csrf_assertion');
const cartAssertion = new Rate('jmeter_cart_id_assertion');
const orderAssertion = new Rate('jmeter_order_accepted_assertion');

export const options = {
  scenarios: {
    journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '10m',
    },
  },
  thresholds: {
    jmeter_login_csrf_assertion: ['rate==1'],
    jmeter_cart_id_assertion: ['rate==1'],
    jmeter_order_accepted_assertion: ['rate==1'],
  },
};

function targetUrl(ref) {
  const url = new URL(ref, `${BASE_URL}/`);
  if (url.origin !== BASE_ORIGIN) {
    throw new Error(`Refusing URL outside configured target: ${url.origin}`);
  }
  return url.toString();
}

function params(name, headers) {
  return {
    headers: headers || {},
    tags: { name, transaction: TRANSACTION },
    redirects: 0,
    timeout: '3s',
  };
}

function getHeader(response, wanted) {
  const headers = response && response.headers ? response.headers : {};
  const key = Object.keys(headers).find((candidate) => candidate.toLowerCase() === wanted.toLowerCase());
  if (!key) return '';
  const value = headers[key];
  return Array.isArray(value) ? String(value[0] || '') : String(value || '');
}

function parseJson(response) {
  if (!response || !response.body) return null;
  try {
    return JSON.parse(response.body);
  } catch (_) {
    return null;
  }
}

function updateCsrf(ctx, response) {
  const data = parseJson(response);
  if (data && data.csrf !== undefined && data.csrf !== null && String(data.csrf) !== '') {
    ctx.csrf = String(data.csrf);
  }
}

function decodeHtml(value) {
  return String(value).replace(/&(#x[0-9a-f]+|#\d+|amp|quot|apos|lt|gt);/gi, (entity, code) => {
    const lower = code.toLowerCase();
    if (lower === 'amp') return '&';
    if (lower === 'quot') return '"';
    if (lower === 'apos') return "'";
    if (lower === 'lt') return '<';
    if (lower === 'gt') return '>';
    if (lower.startsWith('#x')) return String.fromCharCode(parseInt(lower.slice(2), 16));
    if (lower.startsWith('#')) return String.fromCharCode(parseInt(lower.slice(1), 10));
    return entity;
  });
}

function parseAttributes(tag) {
  const attrs = {};
  const inner = tag.replace(/^<[a-z][^>\s]*/i, '').replace(/\/?>$/, '');
  const pattern = /([^\s=/>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/g;
  let match;
  while ((match = pattern.exec(inner)) !== null) {
    attrs[match[1].toLowerCase()] = decodeHtml(
      match[2] !== undefined ? match[2] :
        match[3] !== undefined ? match[3] :
          match[4] !== undefined ? match[4] : '',
    );
  }
  return attrs;
}

function extractInputValue(html, wantedName) {
  const inputs = String(html || '').match(/<input\b[^>]*>/gi) || [];
  for (const input of inputs) {
    const attrs = parseAttributes(input);
    if (String(attrs.name || '').toLowerCase() === wantedName.toLowerCase() && attrs.value) {
      return attrs.value;
    }
  }
  return '';
}

function recordAssertion(response, label, metric, matcher) {
  const passed = check(response || {}, {
    [label]: (res) => matcher(String((res && res.body) || '')),
  });
  metric.add(passed, { transaction: TRANSACTION });
  return passed;
}

function getLoginForm(ctx) {
  const response = http.get(targetUrl('/v2/login-form'), params('GET /v2/login-form'));
  ctx.csrf = extractInputValue(response.body, 'csrf');
  if (!ctx.csrf) throw new Error('Login form did not contain input[name=csrf]');
}

function login(ctx, assertSourceSampler) {
  getLoginForm(ctx);

  const response = http.post(
    targetUrl('/v2/login'),
    JSON.stringify({ username: ctx.username, password: 'bench', csrf: ctx.csrf }),
    params('POST /v2/login', { 'Content-Type': 'application/json' }),
  );

  if (assertSourceSampler) {
    recordAssertion(
      response,
      'JMeter assertion: login response contains csrf',
      loginAssertion,
      (body) => /"csrf"\s*:/.test(body),
    );
  }
  updateCsrf(ctx, response);

  const location = getHeader(response, 'Location');
  if (location) {
    const redirected = http.get(targetUrl(location), params('GET login redirect'));
    updateCsrf(ctx, redirected);
    const data = parseJson(redirected);
    if (data && data.grant_id !== undefined && data.grant_id !== null) {
      ctx.grantId = String(data.grant_id);
    }
  }

  if (!ctx.csrf) throw new Error('Login did not provide a CSRF token');
}

function rawAuthenticatedPost(ctx, path, body, name, extraHeaders) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': ctx.csrf,
    ...(extraHeaders || {}),
  };
  return http.post(targetUrl(path), JSON.stringify(body), params(name, headers));
}

function errorCode(response) {
  const data = parseJson(response);
  return data && typeof data.error === 'string' ? data.error : '';
}

function authenticatedPost(ctx, path, body, name, extraHeaders) {
  const first = rawAuthenticatedPost(ctx, path, body, name, extraHeaders);
  updateCsrf(ctx, first);

  if (first.status !== 401) return first;
  const error = errorCode(first);
  if (error !== 'expired' && error !== 'session') return first;

  const renew = rawAuthenticatedPost(ctx, '/v2/session/renew', {}, 'POST /v2/session/renew');
  updateCsrf(ctx, renew);

  if (error === 'expired' && (renew.status < 200 || renew.status >= 300)) {
    return first;
  }

  if (error === 'session') {
    login(ctx, false);
  }

  if (ctx.cartId) {
    const recovered = rawAuthenticatedPost(
      ctx,
      `/v2/carts/${encodeURIComponent(ctx.cartId)}/recover`,
      {},
      'POST /v2/carts/{id}/recover',
    );
    updateCsrf(ctx, recovered);
    if (recovered.status < 200 || recovered.status >= 300) return first;
  }

  // Retry only the interrupted operation, once, with its original payload and headers.
  const retry = rawAuthenticatedPost(ctx, path, body, name, extraHeaders);
  updateCsrf(ctx, retry);
  return retry;
}

function findAvailableProduct() {
  let pageUrl = targetUrl('/v2/catalog');

  for (let page = 0; page < 3; page += 1) {
    const response = http.get(
      pageUrl,
      params(page === 0 ? 'GET /v2/catalog' : 'GET /v2/catalog/page'),
    );
    const data = parseJson(response);
    const products = data && data.data && Array.isArray(data.data.products)
      ? data.data.products
      : [];

    for (const product of products) {
      const variants = Array.isArray(product.variants) ? product.variants : [];
      const variant = variants.find((item) => item && item.in_stock === true);
      if (product.id !== undefined && variant && variant.id !== undefined) {
        return { productId: product.id, variantId: variant.id };
      }
    }

    if (!data || !data.next) break;
    pageUrl = targetUrl(String(data.next));
  }

  throw new Error('No in-stock product variant found in the first three catalog pages');
}

function getChallenge(ctx) {
  const response = http.get(
    targetUrl('/v2/challenge-form'),
    params('GET /v2/challenge-form'),
  );
  const forms = String(response.body || '').match(/<form\b[^>]*>[\s\S]*?<\/form>/gi) || [];

  for (const form of forms) {
    const openingTag = form.match(/^<form\b[^>]*>/i);
    const action = openingTag ? parseAttributes(openingTag[0]).action : '';
    const challenge = extractInputValue(form, 'challenge');
    if (action && challenge) return { action, challenge };
  }

  throw new Error('Challenge form did not provide an action and input[name=challenge]');
}

function obtainGrant(ctx) {
  const challenge = getChallenge(ctx);
  const response = authenticatedPost(
    ctx,
    challenge.action,
    { challenge: challenge.challenge },
    'POST challenge',
  );

  if (response.status !== 302) {
    throw new Error(`Challenge submission returned HTTP ${response.status}, expected 302`);
  }

  const location = getHeader(response, 'Location');
  if (!location) throw new Error('Challenge response did not provide a Location');

  const result = http.get(targetUrl(location), params('GET challenge redirect'));
  const data = parseJson(result);
  if (!data || data.grant_id === undefined || data.grant_id === null) {
    throw new Error('Challenge redirect did not provide grant_id');
  }
  ctx.grantId = String(data.grant_id);
  updateCsrf(ctx, result);
}

export default function () {
  http.cookieJar().clear(BASE_URL);

  const ctx = {
    username: `bench-${__VU}`,
    csrf: '',
    grantId: '',
    cartId: '',
  };

  group(TRANSACTION, () => {
    login(ctx, true);

    const selection = findAvailableProduct();
    obtainGrant(ctx);

    const cartResponse = authenticatedPost(
      ctx,
      '/v2/carts',
      {
        product_id: selection.productId,
        variant_id: selection.variantId,
        grant_id: ctx.grantId,
      },
      'POST /v2/carts',
    );

    recordAssertion(
      cartResponse,
      'JMeter assertion: cart response id begins with cart-',
      cartAssertion,
      (body) => /"id"\s*:\s*"cart-/.test(body),
    );

    const cartData = parseJson(cartResponse);
    if (cartData && cartData.id !== undefined && cartData.id !== null) {
      ctx.cartId = String(cartData.id);
    }
    const etag = getHeader(cartResponse, 'ETag');
    if (!ctx.cartId) throw new Error('Cart response did not provide a cart id');

    const orderHeaders = { 'Idempotency-Key': ctx.cartId };
    if (etag) orderHeaders['If-Match'] = etag;

    const orderResponse = authenticatedPost(
      ctx,
      '/v2/orders',
      { cart_id: ctx.cartId },
      'POST /v2/orders',
      orderHeaders,
    );

    recordAssertion(
      orderResponse,
      'JMeter assertion: order response is accepted',
      orderAssertion,
      (body) => /"accepted"\s*:\s*true\b/.test(body),
    );
  });
}

import itertools
import os
import re
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

from locust import HttpUser, LoadTestShape, StopUser, task


BASE_URL = os.environ["BASE_URL"]
_base = urlsplit(BASE_URL)
if (_base.scheme, _base.hostname, _base.port) != ("http", "127.0.0.1", 8000):
    raise RuntimeError("BASE_URL must be http://127.0.0.1:8000")

USERS = 2
ITERATIONS_PER_USER = 2
USER_IDS = itertools.count(1)


class FormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.csrf = None
        self.challenge = None
        self.action = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag.lower() == "form" and self.action is None:
            self.action = attrs.get("action")
        if tag.lower() == "input":
            name = attrs.get("name")
            value = attrs.get("value")
            if name == "csrf" and value is not None and self.csrf is None:
                self.csrf = value
            elif name == "challenge" and value is not None and self.challenge is None:
                self.challenge = value


class ShopUser(HttpUser):
    host = BASE_URL

    def on_start(self):
        self.username = f"bench-{((next(USER_IDS) - 1) % 16) + 1}"
        self.iterations = 0
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.reservation_id = None
        self._journey_active = False
        self._journey_failed = False

    def _mark_failure(self):
        if self._journey_active:
            self._journey_failed = True

    @staticmethod
    def _json_data(response):
        try:
            value = response.json()
            return value if isinstance(value, dict) else None
        except (ValueError, TypeError):
            return None

    @staticmethod
    def _header(headers, name):
        for key, value in headers.items():
            if key.lower() == name.lower():
                return value
        return None

    def _local_path(self, location):
        target = urlsplit(urljoin(BASE_URL.rstrip("/") + "/", location))
        if (
            target.scheme != _base.scheme
            or target.netloc.lower() != _base.netloc.lower()
            or not target.path.startswith("/")
        ):
            raise ValueError("redirect or action is outside the configured target")
        return target.path + (("?" + target.query) if target.query else "")

    def _send_once(
        self,
        method,
        path,
        *,
        name,
        json_body=None,
        authenticated=False,
        headers=None,
        allowed_status=(200,),
        check=None,
        retry_auth=True,
        expected_auth_401=False,
    ):
        request_headers = {}
        if method.upper() != "GET":
            request_headers["Content-Type"] = "application/json"
            if authenticated and self.csrf:
                request_headers["X-CSRF-Token"] = self.csrf
        if headers:
            request_headers.update(headers)

        result = {
            "status": None,
            "text": "",
            "headers": {},
            "data": None,
            "ok": False,
            "auth_error": None,
        }

        try:
            kwargs = {
                "headers": request_headers,
                "name": name,
                "catch_response": True,
                "allow_redirects": False,
                "timeout": (2, 3),
            }
            if method.upper() != "GET":
                kwargs["json"] = json_body

            with self.client.request(method, path, **kwargs) as response:
                result["status"] = response.status_code
                result["text"] = response.text
                result["headers"] = dict(response.headers)
                result["data"] = self._json_data(response)

                data = result["data"]
                if isinstance(data, dict):
                    token = data.get("csrf")
                    if isinstance(token, str) and token:
                        self.csrf = token

                error = data.get("error") if isinstance(data, dict) else None
                if response.status_code == 401 and error in ("expired", "session"):
                    result["auth_error"] = error
                    if retry_auth or expected_auth_401:
                        response.success()
                    else:
                        response.failure("authorization recovery/retry exhausted")
                        self._mark_failure()
                else:
                    failure = None
                    if response.status_code not in allowed_status:
                        failure = f"unexpected HTTP status {response.status_code}"
                    elif check is not None:
                        try:
                            failure = check(result)
                        except Exception as exc:
                            failure = f"response check raised: {exc}"

                    if failure:
                        response.failure(str(failure))
                        self._mark_failure()
                    else:
                        response.success()
                        result["ok"] = True
        except Exception:
            self._mark_failure()
            return result

        return result

    def _send(self, method, path, *, retry_auth=True, expected_auth_401=False, **kwargs):
        result = self._send_once(
            method,
            path,
            retry_auth=retry_auth,
            expected_auth_401=expected_auth_401,
            **kwargs,
        )
        if result["auth_error"] and retry_auth:
            if self._recover_session(result["auth_error"]):
                return self._send(
                    method,
                    path,
                    retry_auth=False,
                    expected_auth_401=False,
                    **kwargs,
                )
            self._mark_failure()
        return result

    def _parse_csrf_form(self, result):
        parser = FormParser()
        parser.feed(result["text"])
        if not parser.csrf:
            return "login form did not contain input[name=csrf]"
        self.csrf = parser.csrf
        return None

    def _login(self):
        form = self._send(
            "GET",
            "/v2/login-form",
            name="Journey - Login form",
            allowed_status=(200,),
            check=self._parse_csrf_form,
        )
        if not form["ok"]:
            return False

        login = self._send(
            "POST",
            "/v2/login",
            name="Journey - Login",
            json_body={
                "username": self.username,
                "password": "bench",
                "csrf": self.csrf,
            },
            authenticated=False,
            allowed_status=(200, 302),
            check=lambda result: (
                None
                if re.search(r'"csrf"\s*:', result["text"])
                else 'source assertion failed: response body lacks "csrf":'
            ),
        )

        location = self._header(login["headers"], "Location")
        if login["status"] == 302 and location:
            try:
                redirect_path = self._local_path(location)
            except ValueError:
                self._mark_failure()
                return False
            redirected = self._send_once(
                "GET",
                redirect_path,
                name="Journey - Login redirect",
                authenticated=False,
                allowed_status=(200,),
                retry_auth=False,
            )
            if not redirected["ok"]:
                return False

        return bool(self.csrf)

    def _challenge(self):
        def check_form(result):
            parser = FormParser()
            parser.feed(result["text"])
            if not parser.action or not parser.challenge:
                return "challenge form lacked its action or input[name=challenge]"
            try:
                self.challenge_action = self._local_path(parser.action)
            except ValueError:
                return "challenge form action is outside the configured target"
            self.challenge_value = parser.challenge
            return None

        form = self._send(
            "GET",
            "/v2/challenge-form",
            name="Journey - Challenge form",
            authenticated=True,
            allowed_status=(200,),
            check=check_form,
        )
        if not form["ok"]:
            return False

        submitted = self._send(
            "POST",
            self.challenge_action,
            name="Journey - Submit challenge",
            json_body={"challenge": self.challenge_value},
            authenticated=True,
            allowed_status=(302,),
            check=lambda result: (
                None
                if self._header(result["headers"], "Location")
                else "challenge response lacked Location"
            ),
        )
        location = self._header(submitted["headers"], "Location")
        if not location:
            return False

        try:
            grant_path = self._local_path(location)
        except ValueError:
            self._mark_failure()
            return False

        grant = self._send_once(
            "GET",
            grant_path,
            name="Journey - Claim challenge grant",
            authenticated=False,
            allowed_status=(200,),
            check=lambda result: (
                None
                if isinstance(result["data"], dict)
                and isinstance(result["data"].get("grant_id"), str)
                and result["data"].get("grant_id")
                else "challenge claim did not return grant_id"
            ),
            retry_auth=False,
        )
        if not grant["ok"]:
            return False

        self.grant_id = grant["data"]["grant_id"]
        return True

    def _select_catalog_item(self, result):
        data = result["data"]
        products = data.get("data", {}).get("products") if isinstance(data, dict) else None
        if not isinstance(products, list):
            return "catalog response lacked data.products"

        for product in products:
            if not isinstance(product, dict):
                continue
            variants = product.get("variants")
            if (
                isinstance(variants, list)
                and variants
                and isinstance(variants[0], dict)
                and variants[0].get("in_stock") is True
            ):
                self.product_id = product.get("id")
                self.variant_id = variants[0].get("id")
                if self.product_id is not None and self.variant_id is not None:
                    return None
        return "catalog contained no in-stock first variant"

    def _create_cart(self):
        cart = self._send(
            "POST",
            "/v2/carts",
            name="Journey - Create cart",
            json_body={
                "product_id": self.product_id,
                "variant_id": self.variant_id,
                "grant_id": self.grant_id,
            },
            authenticated=True,
            allowed_status=(201,),
            check=lambda result: (
                None
                if re.search(r'"id"\s*:\s*"cart-', result["text"])
                else 'source assertion failed: response body lacks an id beginning "cart-"'
            ),
        )

        data = cart["data"]
        cart_id = data.get("id") if isinstance(data, dict) else None
        if cart["status"] != 201 or not isinstance(cart_id, str) or not cart_id:
            return False

        self.cart_id = cart_id
        self.etag = self._header(cart["headers"], "ETag")
        return True

    def _read_cart_etag(self):
        def check_etag(result):
            if not self._header(result["headers"], "ETag"):
                return "cart response lacked ETag"
            return None

        current = self._send(
            "GET",
            f"/v2/carts/{self.cart_id}",
            name="Journey - Read cart",
            authenticated=True,
            allowed_status=(200,),
            check=check_etag,
        )
        if current["ok"]:
            self.etag = self._header(current["headers"], "ETag")
        return current["ok"]

    def _patch_quantity(self, final_attempt=False):
        def check_patch(result):
            if result["status"] == 412 and final_attempt:
                return "cart update still conflicted after its single retry"
            return None

        return self._send(
            "PATCH",
            f"/v2/carts/{self.cart_id}",
            name="Journey - Set cart quantity",
            json_body={"quantity": 2},
            authenticated=True,
            headers={"If-Match": self.etag} if self.etag else {},
            allowed_status=(200, 412),
            check=check_patch,
        )

    def _update_cart(self):
        if not self._read_cart_etag():
            return False

        patched = self._patch_quantity()
        if not patched["ok"]:
            return False
        if patched["status"] == 200:
            new_etag = self._header(patched["headers"], "ETag")
            if new_etag:
                self.etag = new_etag
            return True

        # A 412 is an expected conflict: re-read the ETag and retry the same payload once.
        if not self._read_cart_etag():
            return False
        retried = self._patch_quantity(final_attempt=True)
        if not retried["ok"] or retried["status"] != 200:
            return False
        new_etag = self._header(retried["headers"], "ETag")
        if new_etag:
            self.etag = new_etag
        return True

    def _reserve(self):
        reservation = self._send(
            "POST",
            "/v2/reservations",
            name="Journey - Create reservation",
            json_body={"cart_id": self.cart_id},
            authenticated=True,
            allowed_status=(202,),
