            self._journey_failed = True

    @staticmethod
    def _json_data(response):
        try:
            value = response.json()
            return value if isinstance(value, dict) else None
        except (ValueError, TypeError):
            return None

    @staticmethod
    def _header(headers, name):
        for key, value in headers.items():
            if key.lower() == name.lower():
                return value
        return None

    def _local_path(self, location):
        target = urlsplit(urljoin(BASE_URL.rstrip("/") + "/", location))
        if (
            target.scheme != _base.scheme
            or target.netloc.lower() != _base.netloc.lower()
            or not target.path.startswith("/")
        ):
            raise ValueError("URL is outside the configured target")
        return target.path + (("?" + target.query) if target.query else "")

    def _send_once(
        self,
        method,
        path,
        *,
        name,
        json_body=None,
        authenticated=False,
        headers=None,
        allowed_status=(200,),
        check=None,
        retry_auth=True,
        expected_auth_401=False,
    ):
        request_headers = {}
        if method.upper() != "GET":
            request_headers["Content-Type"] = "application/json"
            if authenticated and self.csrf:
                request_headers["X-CSRF-Token"] = self.csrf
        if headers:
            request_headers.update(headers)

        result = {
            "status": None,
            "text": "",
            "headers": {},
            "data": None,
            "ok": False,
            "auth_error": None,
        }

        try:
            kwargs = {
                "headers": request_headers,
                "name": name,
                "catch_response": True,
                "allow_redirects": False,
                "timeout": (2, 3),
            }
            if method.upper() != "GET":
                kwargs["json"] = json_body

            with self.client.request(method, path, **kwargs) as response:
                result["status"] = response.status_code
                result["text"] = response.text
                result["headers"] = dict(response.headers)
                result["data"] = self._json_data(response)

                data = result["data"]
                if isinstance(data, dict):
                    token = data.get("csrf")
                    if isinstance(token, str) and token:
                        self.csrf = token

                error = data.get("error") if isinstance(data, dict) else None
                if response.status_code == 401 and error in ("expired", "session"):
                    result["auth_error"] = error
                    if retry_auth or expected_auth_401:
                        response.success()
                    else:
                        response.failure("authorization recovery/retry exhausted")
                        self._mark_failure()
                else:
                    failure = None
                    if response.status_code not in allowed_status:
                        failure = f"unexpected HTTP status {response.status_code}"
                    elif check is not None:
                        try:
                            failure = check(result)
                        except Exception as exc:
                            failure = f"response check raised: {exc}"

                    if failure:
                        response.failure(str(failure))
                        self._mark_failure()
                    else:
                        response.success()
                        result["ok"] = True
        except Exception:
            self._mark_failure()

        return result

    def _send(self, method, path, *, retry_auth=True, expected_auth_401=False, **kwargs):
        result = self._send_once(
            method,
            path,
            retry_auth=retry_auth,
            expected_auth_401=expected_auth_401,
            **kwargs,
        )
        if result["auth_error"] and retry_auth:
            if self._recover_session(result["auth_error"]):
                return self._send(
                    method,
                    path,
                    retry_auth=False,
                    expected_auth_401=False,
                    **kwargs,
                )
            self._mark_failure()
        return result

    def _parse_csrf_form(self, result):
        parser = FormParser()
        parser.feed(result["text"])
        if not parser.csrf:
            return "login form did not contain input[name=csrf]"
        self.csrf = parser.csrf
        return None

    def _login(self):
        form = self._send(
            "GET",
            "/v2/login-form",
            name="Journey - Login form",
            allowed_status=(200,),
            check=self._parse_csrf_form,
        )
        if not form["ok"]:
            return False

        login = self._send(
            "POST",
            "/v2/login",
            name="Journey - Login",
            json_body={
                "username": self.username,
                "password": "bench",
                "csrf": self.csrf,
            },
            allowed_status=(200, 302),
            check=lambda result: (
                None
                if re.search(r'"csrf"\s*:', result["text"])
                else 'source assertion failed: response body lacks "csrf":'
            ),
        )

        location = self._header(login["headers"], "Location")
        if login["status"] == 302 and location:
            try:
                redirect_path = self._local_path(location)
            except ValueError:
                self._mark_failure()
                return False
            redirected = self._send_once(
                "GET",
                redirect_path,
                name="Journey - Login redirect",
                allowed_status=(200,),
                retry_auth=False,
            )
            if not redirected["ok"]:
                return False

        return bool(login["ok"] and self.csrf)

    def _challenge(self):
        def check_form(result):
            parser = FormParser()
            parser.feed(result["text"])
            if not parser.action or not parser.challenge:
                return "challenge form lacked its action or input[name=challenge]"
            try:
                self.challenge_action = self._local_path(parser.action)
            except ValueError:
                return "challenge form action is outside the configured target"
            self.challenge_value = parser.challenge
            return None

        form = self._send(
            "GET",
            "/v2/challenge-form",
            name="Journey - Challenge form",
            authenticated=True,
            allowed_status=(200,),
            check=check_form,
        )
        if not form["ok"]:
            return False

        submitted = self._send(
            "POST",
            self.challenge_action,
            name="Journey - Submit challenge",
            json_body={"challenge": self.challenge_value},
            authenticated=True,
            allowed_status=(302,),
            check=lambda result: (
                None
                if self._header(result["headers"], "Location")
                else "challenge response lacked Location"
            ),
        )
        location = self._header(submitted["headers"], "Location")
        if not submitted["ok"] or not location:
            return False

        try:
            grant_path = self._local_path(location)
        except ValueError:
            self._mark_failure()
            return False

        grant = self._send_once(
            "GET",
            grant_path,
            name="Journey - Claim challenge grant",
            allowed_status=(200,),
            check=lambda result: (
                None
                if isinstance(result["data"], dict)
                and isinstance(result["data"].get("grant_id"), str)
                and result["data"].get("grant_id")
                else "challenge claim did not return grant_id"
            ),
            retry_auth=False,
        )
        if not grant["ok"]:
            return False

        self.grant_id = grant["data"]["grant_id"]
        return True

    def _select_catalog_item(self, result):
        data = result["data"]
        products = data.get("data", {}).get("products") if isinstance(data, dict) else None
        if not isinstance(products, list):
            return "catalog response lacked data.products"

        for product in products:
            if not isinstance(product, dict):
                continue
            variants = product.get("variants")
            if (
                isinstance(variants, list)
                and variants
                and isinstance(variants[0], dict)
                and variants[0].get("in_stock") is True
            ):
                product_id = product.get("id")
                variant_id = variants[0].get("id")
                if product_id is not None and variant_id is not None:
                    self.product_id = product_id
                    self.variant_id = variant_id
                    return None
        return "catalog contained no in-stock first variant"

    def _create_cart(self):
        cart = self._send(
            "POST",
            "/v2/carts",
            name="Journey - Create cart",
            json_body={
                "product_id": self.product_id,
                "variant_id": self.variant_id,
                "grant_id": self.grant_id,
            },
            authenticated=True,
            allowed_status=(201,),
            check=lambda result: (
                None
                if re.search(r'"id"\s*:\s*"cart-', result["text"])
                else 'source assertion failed: response body lacks an id beginning "cart-"'
            ),
        )

        data = cart["data"]
        cart_id = data.get("id") if isinstance(data, dict) else None
        if not cart["ok"] or not isinstance(cart_id, str) or not cart_id:
            return False

        self.cart_id = cart_id
        self.etag = self._header(cart["headers"], "ETag")
        return True

    def _read_cart_etag(self):
        current = self._send(
            "GET",
            f"/v2/carts/{self.cart_id}",
            name="Journey - Read cart",
            authenticated=True,
            allowed_status=(200,),
            check=lambda result: (
                None
                if self._header(result["headers"], "ETag")
                else "cart response lacked ETag"
            ),
        )
        if current["ok"]:
            self.etag = self._header(current["headers"], "ETag")
        return current["ok"]

    def _patch_quantity(self, final_attempt=False):
        def check_patch(result):
            if result["status"] == 412 and final_attempt:
                return "cart update still conflicted after its single retry"
            return None

        return self._send(
            "PATCH",
            f"/v2/carts/{self.cart_id}",
            name="Journey - Set cart quantity",
            json_body={"quantity": 2},
            authenticated=True,
            headers={"If-Match": self.etag} if self.etag else {},
            allowed_status=(200, 412),
            check=check_patch,
        )

    def _update_cart(self):
        if not self._read_cart_etag():
            return False

        patched = self._patch_quantity()
        if not patched["ok"]:
            return False
        if patched["status"] == 200:
            new_etag = self._header(patched["headers"], "ETag")
            if new_etag:
                self.etag = new_etag
            return True

        # On 412, re-read ETag and retry the identical payload exactly once.
        if not self._read_cart_etag():
            return False
        retried = self._patch_quantity(final_attempt=True)
        if not retried["ok"] or retried["status"] != 200:
            return False
        new_etag = self._header(retried["headers"], "ETag")
        if new_etag:
            self.etag = new_etag
        return True

    def _reserve(self):
        reservation = self._send(
            "POST",
            "/v2/reservations",
            name="Journey - Create reservation",
            json_body={"cart_id": self.cart_id},
            authenticated=True,
            allowed_status=(202,),
            check=lambda result: (
                None
                if isinstance(result["data"], dict)
                and isinstance(result["data"].get("status_url"), str)
                and result["data"].get("status_url")
                else "reservation response lacked status_url"
            ),
        )
        if not reservation["ok"]:
            return False

        try:
            status_path = self._local_path(reservation["data"]["status_url"])
        except ValueError:
            self._mark_failure()
            return False

        for attempt in range(1, 6):
            if attempt > 1:
                self.wait(0.05)

            def check_status(result, poll_number=attempt):
                data = result["data"]
                if not isinstance(data, dict):
                    return "reservation status was not a JSON object"
                status = data.get("status")
                if status == "ready":
                    if not isinstance(data.get("reservation_id"), str):
                        return "ready reservation lacked reservation_id"
                    return None
                if status == "pending":
                    if poll_number == 5:
                        return "reservation remained pending after five polls"
                    return None
                if status == "failed":
                    return "reservation failed"
                return "reservation returned an unknown status"

            polled = self._send(
                "GET",
                status_path,
                name="Journey - Poll reservation",
                authenticated=True,
                allowed_status=(200,),
                check=check_status,
            )
            if not polled["ok"]:
                return False
            if polled["data"].get("status") == "ready":
                self.reservation_id = polled["data"]["reservation_id"]
                return True

        return False

    def _place_order(self):
        headers = {"Idempotency-Key": self.cart_id}
        if self.etag:
            headers["If-Match"] = self.etag

        def check_order(result):
            if not re.search(r'"accepted"\s*:\s*true', result["text"]):
                return 'source assertion failed: response body lacks "accepted": true'
            if result["status"] != 201:
                return "accepted order did not return HTTP 201"
            return None

        order = self._send(
            "POST",
            "/v2/orders",
            name="Journey - Place order",
            json_body={
                "cart_id": self.cart_id,
                "reservation_id": self.reservation_id,
            },
            authenticated=True,
            headers=headers,
            allowed_status=(200, 201),
            check=check_order,
        )
        return order["ok"]

    def _recover_session(self, error):
        renewed = self._send(
            "POST",
            "/v2/session/renew",
            name="Journey - Renew session",
            json_body={},
            authenticated=True,
            allowed_status=(200,),
            check=lambda result: (
                None
                if isinstance(result["data"], dict)
                and isinstance(result["data"].get("csrf"), str)
                and result["data"].get("csrf")
                else "session renewal did not return csrf"
            ),
            retry_auth=False,
            expected_auth_401=True,
        )

        if not renewed["ok"]:
            if error != "session" and not renewed["auth_error"]:
                return False
            if not self._login():
                return False

        if self.cart_id:
            recovered = self._send(
                "POST",
                f"/v2/carts/{self.cart_id}/recover",
                name="Journey - Recover cart",
                json_body={},
                authenticated=True,
                allowed_status=(200, 204),
                retry_auth=False,
            )
            if not recovered["ok"]:
                return False

        return True

    def _journey(self):
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.reservation_id = None
        self.product_id = None
        self.variant_id = None

        if not self._login():
            return
        if not self._challenge():
            return

        catalog = self._send(
            "GET",
            "/v2/catalog",
            name="Journey - Catalog",
            authenticated=True,
            allowed_status=(200,),
            check=self._select_catalog_item,
        )
        if not catalog["ok"]:
            return
        if not self._create_cart():
            return
        if not self._update_cart():
            return
        if not self._reserve():
            return
        self._place_order()

    def _record_transaction(self):
        environment = self.environment
        if not hasattr(environment, "_journey_transaction_total"):
            environment._journey_transaction_total = 0
            environment._journey_transaction_failed = 0
        environment._journey_transaction_total += 1
        if self._journey_failed:
            environment._journey_transaction_failed += 1

    def _run_iteration(self):
        self._journey_active = True
        self._journey_failed = False
        self.client.cookies.clear()
        try:
            self._journey()
        except Exception:
            self._mark_failure()
        finally:
            self._record_transaction()
            self._journey_active = False

    @task
    def run_journeys(self):
        for _ in range(ITERATIONS_PER_USER):
            self._run_iteration()
        raise StopUser()


class FixedIterationShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.started = False

    def tick(self):
        if not self.started:
            self.started = True
            return USERS, USERS

        if self.runner.user_count == 0:
            environment = self.runner.environment
            total = getattr(environment, "_journey_transaction_total", 0)
            failed = getattr(environment, "_journey_transaction_failed", 0)

            # The error limit is zero failed journeys out of the four planned journeys.
            if total != EXPECTED_JOURNEYS or failed > 0:
                environment.process_exit_code = max(
                    getattr(environment, "process_exit_code", 0) or 0,
                    1,
                )
            return None

        return USERS, USERS

