import http from 'k6/http';
import { check } from 'k6';

const cfg = { users: 2, iterations: 2, mode: 'flow' };
const rows = [
  { username: 'bench-1', password: 'bench', quantity: 2 },
  { username: 'bench-2', password: 'bench', quantity: 3 },
  { username: 'bench-3', password: 'bench', quantity: 4 },
  { username: 'bench-4', password: 'bench', quantity: 5 },
  { username: 'bench-5', password: 'bench', quantity: 6 },
  { username: 'bench-6', password: 'bench', quantity: 7 },
  { username: 'bench-7', password: 'bench', quantity: 8 },
  { username: 'bench-8', password: 'bench', quantity: 9 },
  { username: 'bench-9', password: 'bench', quantity: 10 },
  { username: 'bench-10', password: 'bench', quantity: 11 },
  { username: 'bench-11', password: 'bench', quantity: 12 },
  { username: 'bench-12', password: 'bench', quantity: 13 },
  { username: 'bench-13', password: 'bench', quantity: 14 },
  { username: 'bench-14', password: 'bench', quantity: 15 },
  { username: 'bench-15', password: 'bench', quantity: 16 },
  { username: 'bench-16', password: 'bench', quantity: 17 },
];

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: cfg.users,
      iterations: cfg.iterations,
      maxDuration: '30s',
    },
  },
  thresholds: { checks: ['rate==1'] },
};

const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
let csrf = '';
let cart = '';

function body(r) {
  try {
    return r.json();
  } catch (_) {
    return {};
  }
}

function header(r, name) {
  const wanted = name.toLowerCase();
  const headers = r && r.headers ? r.headers : {};
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() === wanted) return headers[key];
  }
  return '';
}

function locationURL(location) {
  if (!location) return '';
  if (/^https?:\/\//i.test(location)) {
    return location.indexOf(base) === 0 ? location : '';
  }
  return base + (location.charAt(0) === '/' ? location : '/' + location);
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const url = /^https?:\/\//i.test(path)
    ? path
    : base + (path.charAt(0) === '/' ? path : '/' + path);
  const r = http.request(
    method,
    url,
    data === null ? null : JSON.stringify(data),
    {
      headers: Object.assign(
        {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf,
        },
        extra
      ),
      redirects: 0,
      timeout: '3s',
    }
  );

  const result = body(r);
  if (typeof result.csrf === 'string' && result.csrf.length > 0) {
    csrf = result.csrf;
  }
  return r;
}

function login() {
  http.cookieJar().clear(base);

  const formResponse = raw('/v2/login-form');
  const formToken = formResponse
    .html()
    .find('input[name="csrf"]')
    .first()
    .attr('value');

  if (!formToken) {
    check(false, { 'login form has CSRF token': (v) => v });
    return false;
  }

  csrf = formToken;
  const row = rows[(__VU - 1) % rows.length];
  let response = raw('/v2/login', 'POST', {
    username: row.username,
    password: row.password,
    csrf: formToken,
  });

  if (response.status === 302) {
    const url = locationURL(header(response, 'Location'));
    if (url) response = raw(url);
  }

  const ok = response.status === 200;
  check(response, { 'login succeeds': (r) => r.status === 200 });
  return ok;
}

function request(path, method = 'GET', data = null, extra = {}) {
  let response = raw(path, method, data, extra);

  if (response.status === 401) {
    const error = body(response).error;
    if (error === 'expired' || error === 'session') {
      const renewed = raw('/v2/session/renew', 'POST', {});
      let recovered = renewed.status === 200;

      if (!recovered) recovered = login();

      if (recovered && cart) {
        const recovery = raw(
          '/v2/carts/' + encodeURIComponent(cart) + '/recover',
          'POST',
          {}
        );
        recovered = recovery.status < 400;
      }

      if (recovered) response = raw(path, method, data, extra);
    }
  }

  return response;
}

function readCartETag() {
  const response = request(
    '/v2/carts/' + encodeURIComponent(cart),
    'GET'
  );
  const etag = header(response, 'ETag');
  check(response, {
    'cart can be read with ETag': (r) => r.status === 200 && !!header(r, 'ETag'),
  });
  return response.status === 200 ? etag : '';
}

function flow() {
  csrf = '';
  cart = '';

  if (!login()) return;

  const catalogResponse = request('/v2/catalog');
  const catalog = body(catalogResponse);
  check(catalogResponse, {
    'catalog loads': (r) => r.status === 200,
  });
  if (catalogResponse.status !== 200) return;

  const products =
    catalog && catalog.data && Array.isArray(catalog.data.products)
      ? catalog.data.products
      : [];
  const product = products.find(
    (p) =>
      Array.isArray(p.variants) && p.variants.some((v) => v.in_stock)
  );

  if (!product) {
    check(false, { 'eligible product exists': (v) => v });
    return;
  }

  const variant = product.variants.find((v) => v.in_stock);
  const cartResponse = request('/v2/carts', 'POST', {
    product_id: product.id,
    variant_id: variant.id,
  });
  const cartData = body(cartResponse);
  check(cartResponse, {
    'cart is created': (r) =>
      r.status === 201 &&
      cartData.id !== undefined &&
      cartData.id !== null &&
      String(cartData.id).length > 0,
  });

  if (
    cartResponse.status !== 201 ||
    cartData.id === undefined ||
    cartData.id === null
  ) {
    return;
  }

  cart = String(cartData.id);
  let etag = readCartETag();
  if (!etag) return;

  const row = rows[(__VU - 1) % rows.length];
  const quantity = row.quantity;
  let update = request(
    '/v2/carts/' + encodeURIComponent(cart),
    'PATCH',
    { quantity: quantity },
    { 'If-Match': etag }
  );

  if (update.status === 412) {
    etag = readCartETag();
    if (!etag) return;
    update = request(
      '/v2/carts/' + encodeURIComponent(cart),
      'PATCH',
      { quantity: quantity },
      { 'If-Match': etag }
    );
  }

  check(update, { 'cart quantity is updated': (r) => r.status === 200 });
  if (update.status !== 200) return;

  etag = readCartETag();
  if (!etag) return;

  const order = request(
    '/v2/orders',
    'POST',
    { cart_id: cart },
    {
      'Idempotency-Key': cart,
      'If-Match': etag,
    }
  );

  check(order, {
    'order is accepted': (r) =>
      r.status === 201 && body(r).accepted === true,
  });
}

export default function () {
  flow();
}

