import http from 'k6/http';
import {check, sleep} from 'k6';
import {Rate} from 'k6/metrics';

const cfg = {"users": 2, "iterations": 2, "mode": "flow"};
const rows = [{"username": "bench-1", "password": "bench", "quantity": 2}, {"username": "bench-2", "password": "bench", "quantity": 3}, {"username": "bench-3", "password": "bench", "quantity": 4}, {"username": "bench-4", "password": "bench", "quantity": 5}, {"username": "bench-5", "password": "bench", "quantity": 6}, {"username": "bench-6", "password": "bench", "quantity": 7}, {"username": "bench-7", "password": "bench", "quantity": 8}, {"username": "bench-8", "password": "bench", "quantity": 9}, {"username": "bench-9", "password": "bench", "quantity": 10}, {"username": "bench-10", "password": "bench", "quantity": 11}, {"username": "bench-11", "password": "bench", "quantity": 12}, {"username": "bench-12", "password": "bench", "quantity": 13}, {"username": "bench-13", "password": "bench", "quantity": 14}, {"username": "bench-14", "password": "bench", "quantity": 15}, {"username": "bench-15", "password": "bench", "quantity": 16}, {"username": "bench-16", "password": "bench", "quantity": 17}];

const failure = new Rate('business_failure');
const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s'
    }
  },
  thresholds: {
    checks: ['rate==1']
  }
};

function newContext() {
  return {csrf: '', cart: '', etag: '', grant: ''};
}

function body(response) {
  try {
    return response.json();
  } catch (_) {
    return {};
  }
}

function header(response, name) {
  const headers = response && response.headers ? response.headers : {};
  const wanted = name.toLowerCase();
  const keys = Object.keys(headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === wanted) return headers[keys[i]];
  }
  return '';
}

function urlFor(path) {
  if (/^https?:\/\//i.test(path)) return path;
  return base + (path.charAt(0) === '/' ? path : '/' + path);
}

function raw(ctx, path, method, data, extraHeaders) {
  const headers = Object.assign({
    'Content-Type': 'application/json',
    'X-CSRF-Token': ctx.csrf
  }, extraHeaders || {});

  const response = http.request(
    method || 'GET',
    urlFor(path),
    data === null || data === undefined ? null : JSON.stringify(data),
    {headers: headers, redirects: 0, timeout: '3s'}
  );

  const result = body(response);
  if (response.status >= 200 && response.status < 400 &&
      typeof result.csrf === 'string' && result.csrf.length > 0) {
    ctx.csrf = result.csrf;
  }

  if (path === '/v2/work' || path === '/v2/browse') {
    const expectedExpiry = response.status === 401 && result.error === 'expired';
    const retryAfter = header(response, 'Retry-After');
    const expectedThrottle = response.status === 429 && retryAfter !== '';
    failure.add(response.status >= 400 && !expectedExpiry && !expectedThrottle);
  }

  return response;
}

function htmlInputValue(response, selector) {
  try {
    const selection = response.html().find(selector).first();
    return selection.attr('value') || '';
  } catch (_) {
    return '';
  }
}

function login(ctx) {
  let response = raw(ctx, '/v2/login-form', 'GET', null);
  const formOK = check(response, {
    'login form loaded': r => r.status === 200
  });
  if (!formOK) return false;

  let token = htmlInputValue(response, 'form input[name="csrf"]');
  if (!token) token = htmlInputValue(response, 'input[name="csrf"]');
  if (!check(token, {'login form has csrf': value => typeof value === 'string' && value.length > 0})) {
    return false;
  }

  ctx.csrf = token;
  const row = rows[(__VU - 1) % rows.length];
  response = raw(ctx, '/v2/login', 'POST', {
    username: row.username,
    password: row.password,
    csrf: token
  });

  if (response.status === 302) {
    const location = header(response, 'Location');
    if (!check(location, {'login redirect has location': value => value.length > 0})) return false;
    // Redirects are disabled; fetch the dynamic location exactly once.
    response = raw(ctx, location, 'GET', null);
  }

  if (!check(response, {'login succeeded': r => r.status === 200})) return false;
  return check(ctx.csrf, {
    'authenticated csrf available': value => typeof value === 'string' && value.length > 0
  });
}

function request(ctx, path, method, data, extraHeaders) {
  const verb = method || 'GET';
  let response = raw(ctx, path, verb, data, extraHeaders);
  const result = body(response);

  if (response.status !== 401 ||
      (result.error !== 'expired' && result.error !== 'session')) {
    return response;
  }

  let sessionReady = false;
  if (result.error === 'expired') {
    const renewed = raw(ctx, '/v2/session/renew', 'POST', {});
    sessionReady = renewed.status === 200;
  }

  if (!sessionReady) {
    if (!login(ctx)) return response;
  }

  if (ctx.cart) {
    const recovered = raw(ctx, '/v2/carts/' + ctx.cart + '/recover', 'POST', {});
    if (!check(recovered, {'cart recovered': r => r.status >= 200 && r.status < 300})) {
      return response;
    }
  }

  // Retry only the interrupted operation, once, with the same payload and headers.
  return raw(ctx, path, verb, data, extraHeaders);
}

function findEligibleProduct(catalog) {
  const products = catalog && catalog.data && catalog.data.products;
  if (!Array.isArray(products)) return null;

  for (let i = 0; i < products.length; i++) {
    const variants = products[i].variants || [];
    for (let j = 0; j < variants.length; j++) {
      if (variants[j].in_stock === true) {
        return {product: products[i], variant: variants[j]};
      }
    }
  }
  return null;
}

function selectProduct(ctx) {
  let page = cfg.mode === 'pagination' ? '/v2/catalog/page' : '/v2/catalog';

  for (let i = 0; i < 3 && page; i++) {
    const response = request(ctx, page, 'GET', null);
    if (!check(response, {'catalog loaded': r => r.status === 200})) return null;

    const catalog = body(response);
    const eligible = findEligibleProduct(catalog);
    if (eligible) return eligible;
    page = catalog.next || null;
  }

  check(false, {'eligible product found': value => value === true});
  return null;
}

function flow(ctx) {
  // Each invocation is a new journey: log in afresh and never reuse a prior cart.
  if (!login(ctx)) return;

  if (cfg.mode === 'challenge') {
    let response = request(ctx, '/v2/challenge-form', 'GET', null);
    if (!check(response, {'challenge form loaded': r => r.status === 200})) return;

    const challenge = htmlInputValue(response, 'form input[name="challenge"]');
    let action = '';
    try {
      action = response.html().find('form').first().attr('action') || '';
    } catch (_) {
      action = '';
    }
    if (!check(challenge, {'challenge token present': value => value.length > 0}) ||
        !check(action, {'challenge action present': value => value.length > 0})) return;

    response = request(ctx, action, 'POST', {challenge: challenge});
    if (!check(response, {'challenge accepted': r => r.status === 302})) return;

    const location = header(response, 'Location');
    if (!check(location, {'challenge redirect has location': value => value.length > 0})) return;

    // Fetch the dynamic grant location once; do not follow redirects automatically.
    response = raw(ctx, location, 'GET', null);
    if (!check(response, {'challenge grant loaded': r => r.status === 200})) return;
    ctx.grant = body(response).grant_id || '';
    if (!check(ctx.grant, {'challenge grant present': value => value.length > 0})) return;
  }

  const selected = selectProduct(ctx);
  if (!selected) return;

  const cartPayload = {
    product_id: selected.product.id,
    variant_id: selected.variant.id
  };
  if (ctx.grant) cartPayload.grant_id = ctx.grant;

  let response = request(ctx, '/v2/carts', 'POST', cartPayload);
  if (!check(response, {'cart created': r => r.status === 201 && !!body(r).id})) return;

  ctx.cart = String(body(response).id);
  ctx.etag = header(response, 'ETag');
  ctx.grant = '';

  if (cfg.mode === 'etag' || cfg.mode === 'data') {
    const row = rows[(__VU - 1) % rows.length];
    const quantity = cfg.mode === 'data' ? row.quantity : (cfg.quantity || 2);
    if (!check(ctx.etag, {'cart etag present': value => value.length > 0})) return;

    const patchHeaders = {'If-Match': ctx.etag};
    response = request(ctx, '/v2/carts/' + ctx.cart, 'PATCH', {quantity: quantity}, patchHeaders);

    if (response.status === 412) {
      const current = request(ctx, '/v2/carts/' + ctx.cart, 'GET', null);
      if (!check(current, {'cart reread after conflict': r => r.status === 200})) return;
      ctx.etag = header(current, 'ETag');
      if (!check(ctx.etag, {'fresh cart etag present': value => value.length > 0})) return;
      response = request(ctx, '/v2/carts/' + ctx.cart, 'PATCH', {quantity: quantity}, {
        'If-Match': ctx.etag
      });
    }

    if (!check(response, {'cart updated': r => r.status === 200})) return;
    ctx.etag = header(response, 'ETag') || ctx.etag;
  }

  let reservationId = '';
  if (cfg.mode === 'reservation') {
    response = request(ctx, '/v2/reservations', 'POST', {cart_id: ctx.cart});
    if (!check(response, {'reservation requested': r => r.status === 202 && !!body(r).status_url})) return;

