      sleep(0.05);
      response = request(ctx, statusUrl, 'GET', null);
      if (!check(response, {'reservation status loaded': r => r.status === 200})) return;

      const status = body(response);
      if (status.status === 'ready') {
        reservationId = status.reservation_id || '';
        break;
      }
      if (status.status === 'failed') {
        check(false, {'reservation ready': value => value === true});
        return;
      }
    }

    if (!check(reservationId, {'reservation ready': value => value.length > 0})) return;
  }

  const orderPayload = {cart_id: ctx.cart};
  if (reservationId) orderPayload.reservation_id = reservationId;

  const orderHeaders = {'Idempotency-Key': ctx.cart};
  if (ctx.etag) orderHeaders['If-Match'] = ctx.etag;

  response = request(ctx, '/v2/orders', 'POST', orderPayload, orderHeaders);
  check(response, {
    'order accepted': r => r.status === 201 && body(r).accepted === true
  });

  if (cfg.mode === 'threshold') raw(ctx, '/v2/health', 'GET', null);
}

function work(ctx, path) {
  if (!ctx.csrf && !login(ctx)) return;

  const endpoint = path || cfg.path || '/v2/work';
  let response = request(ctx, endpoint, 'POST', {});

  for (let retries = 0; retries < 4 && response.status === 429; retries++) {
    const delay = Number(header(response, 'Retry-After'));
    if (!check(delay, {'throttle has valid retry-after': value => isFinite(value) && value > 0})) return;
    sleep(delay);
    response = request(ctx, endpoint, 'POST', {});
  }

  check(response, {
    'operation succeeded': r => r.status === 200 && body(r).ok === true
  });
}

export default function() {
  const ctx = newContext();

  if (cfg.workload) {
    if (cfg.operation === 'journey') flow(ctx);
    else work(ctx);
  } else if (cfg.mode === 'errors') {
    if (!login(ctx)) return;
    for (let i = 0; i < 4; i++) work(ctx);
  } else {
    flow(ctx);
  }
}

export function browse() {
  const ctx = newContext();
  work(ctx, '/v2/browse');
}

export function checkout() {
  flow(newContext());
}

import os
import re
from html.parser import HTMLParser

from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

CFG = {"users": 2, "iterations": 2}
ACCOUNT_LOCK = Semaphore()
NEXT_ACCOUNT = 0


class FormParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.csrf = None

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input":
            return
        fields = {key.lower(): value for key, value in attrs}
        if fields.get("name", "").lower() == "csrf" and self.csrf is None:
            self.csrf = fields.get("value")


class ShopUser(HttpUser):
    host = os.environ["BASE_URL"]
    wait_time = lambda self: 0

    def on_start(self):
        global NEXT_ACCOUNT
        worker_id = getattr(self, "_p95_worker_id", None)
        try:
            account_number = int(worker_id.rsplit("-", 1)[1])
        except (AttributeError, IndexError, TypeError, ValueError):
            with ACCOUNT_LOCK:
                NEXT_ACCOUNT += 1
                account_number = NEXT_ACCOUNT
        self.username = "bench-{}".format((account_number - 1) % 16 + 1)
        self.password = "bench"
        self.csrf = ""
        self.cart_id = ""
        self.etag = ""
        self.iteration = 0

    def fail_run(self):
        self.environment.process_exit_code = 99

    def raw(self, path, method="GET", data=None, headers=None,
            allow_auth_error=True):
        method = method.upper()
        request_headers = {"Content-Type": "application/json"}
        if method != "GET" and path != "/v2/login" and self.csrf:
            request_headers["X-CSRF-Token"] = self.csrf
        request_headers.update(headers or {})

        with self.client.request(
            method,
            path,
            json=data,
            headers=request_headers,
            name=path,
            catch_response=True,
            allow_redirects=False,
            timeout=3,
        ) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}
            if not isinstance(body, dict):
                body = {}

            status = response.status_code
            error = body.get("error")
            allowed = status < 400
            if allow_auth_error and status == 401 and error in ("expired", "session"):
                allowed = True
            if status == 412 and error in ("etag", "etag_conflict"):
                allowed = True
            if method == "POST" and path == "/v2/login":
                allowed = (
                    status == 200 and bool(body.get("csrf"))
                ) or (
                    status == 302 and bool(response.headers.get("Location"))
                )
            if method == "POST" and path == "/v2/carts":
                allowed = status == 201 and bool(body.get("id"))
            if method == "POST" and path == "/v2/orders":
                allowed = status == 201 and body.get("accepted") is True and bool(body.get("id"))

            if allowed:
                response.success()
            else:
                response.failure("request assertion failed")

            if body.get("csrf"):
                self.csrf = body["csrf"]
            return response, body

    def login(self, fresh_session):
        if fresh_session:
            self.client.cookies.clear()
        self.csrf = ""

        form_response, _ = self.raw("/v2/login-form")
        if form_response.status_code != 200:
            return False

        parser = FormParser()
        parser.feed(form_response.text)
        if not parser.csrf:
            return False

        response, body = self.raw(
            "/v2/login",
            "POST",
            {"username": self.username, "password": self.password, "csrf": parser.csrf},
        )
        if response.status_code == 302:
            location = response.headers.get("Location")
            if not location:
                return False
            # Follow the server-provided login redirect exactly once.
            landing, body = self.raw(location)
            if landing.status_code >= 400:
                return False
            if body.get("csrf"):
                self.csrf = body["csrf"]

        return response.status_code in (200, 302) and bool(self.csrf)

    def recover(self, original_error):
        renewed, _ = self.raw("/v2/session/renew", "POST", {})
        if renewed.status_code != 200:
            if original_error != "session" or not self.login(fresh_session=False):
                return False

        if self.cart_id:
            recovered, _ = self.raw(
                "/v2/carts/{}/recover".format(self.cart_id), "POST", {}
            )
            if recovered.status_code >= 400:
                return False
            self.etag = recovered.headers.get("ETag", self.etag)
        return True

    def request(self, path, method="GET", data=None, headers=None):
        response, body = self.raw(path, method, data, headers)
        if response.status_code == 401 and body.get("error") in ("expired", "session"):
            if self.recover(body["error"]):
                # Retry only the interrupted operation, at most once.
                return self.raw(path, method, data, headers, allow_auth_error=False)
        return response, body

    def journey(self):
        # A new cookie jar, login session, and cart for every iteration.
        self.client.cookies.clear()
        self.csrf = ""
        self.cart_id = ""
        self.etag = ""

        if not self.login(fresh_session=False):
            self.fail_run()
            return

        page = "/v2/catalog"
        product = None
        for _ in range(3):
            response, body = self.request(page)
            if response.status_code != 200:
                self.fail_run()
                return
            products = body.get("data", {}).get("products", [])
            product = next(
                (
                    item for item in products
                    if any(variant.get("in_stock") for variant in item.get("variants", []))
                ),
                None,
            )
            if product:
                break
            page = body.get("next")
            if not page:
                break

        if not product:
            self.fail_run()
            return

        variant = next(
            item for item in product["variants"] if item.get("in_stock")
        )
        response, body = self.request(
            "/v2/carts",
            "POST",
            {"product_id": product["id"], "variant_id": variant["id"]},
        )
        self.cart_id = body.get("id", "")
        self.etag = response.headers.get("ETag", "")
        if response.status_code != 201 or not self.cart_id:
            self.fail_run()
            return

        if not self.etag:
            response, _ = self.request("/v2/carts/{}".format(self.cart_id))
            self.etag = response.headers.get("ETag", "")
            if response.status_code >= 400:
                self.fail_run()
                return

        headers = {"Idempotency-Key": self.cart_id}
        if self.etag:
            headers["If-Match"] = self.etag
        self.request(
            "/v2/orders",
            "POST",
            {"cart_id": self.cart_id},
            headers,
        )

    @task
    def run_journey(self):
        self.journey()
        self.iteration += 1
        if self.iteration >= CFG["iterations"]:
            raise StopUser()


class JourneyShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.launched = False

    def tick(self):
        if not self.launched:
            self.launched = True
            return CFG["users"], CFG["users"]
        if self.runner.user_count == 0:
            return None
        return CFG["users"], CFG["users"]

