import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.io.IOException;

public class ModelSimulation extends Simulation {
    private static final String MODE = "denial";
    private static final ObjectMapper JSON = new ObjectMapper();
    private static final String BASE_URL = System.getenv("BASE_URL") == null
        ? "http://127.0.0.1:8000" : System.getenv("BASE_URL");

    private static final HttpProtocolBuilder HTTP = http.baseUrl(BASE_URL)
        .disableWarmUp()
        .acceptHeader("application/json");

    private static String errorIn(String body) {
        try {
            JsonNode node = JSON.readTree(body);
            return node.hasNonNull("error") ? node.path("error").asText() : null;
        } catch (IOException | RuntimeException ignored) {
            return null;
        }
    }

    private static boolean recoverableOrSuccessfulResponse(String body) {
        String error = errorIn(body);
        return error == null || "expired".equals(error) || "session".equals(error);
    }

    private static boolean validCatalogResponse(String body) {
        String error = errorIn(body);
        if ("expired".equals(error) || "session".equals(error)) return true;
        try {
            return JSON.readTree(body).path("data").path("products").isArray();
        } catch (IOException | RuntimeException ignored) {
            return false;
        }
    }

    private static boolean validCartResponse(String body) {
        String error = errorIn(body);
        if ("expired".equals(error) || "session".equals(error)) return true;
        try {
            JsonNode node = JSON.readTree(body);
            return node.path("id").isValueNode() && !node.path("id").isNull()
                && node.path("csrf").isTextual();
        } catch (IOException | RuntimeException ignored) {
            return false;
        }
    }

    private static boolean validOrderResponse(String body) {
        String error = errorIn(body);
        if ("expired".equals(error) || "session".equals(error)) return true;
        if ("denied".equals(error)) return false;
        try {
            return JSON.readTree(body).path("accepted").asBoolean(false);
        } catch (IOException | RuntimeException ignored) {
            return false;
        }
    }

    private static boolean isRecoverable401(Session session, String statusKey) {
        if (!session.contains(statusKey) || session.getInt(statusKey) != 401
            || !session.contains("responseBody")) {
            return false;
        }
        String error = errorIn(session.getString("responseBody"));
        return "expired".equals(error) || "session".equals(error);
    }

    private static ChainBuilder login() {
        return exec(session -> session.remove("loginLocation").set("csrf", ""))
            .exec(http("login form").get("/v2/login-form")
                .check(regex("(?i)<input(?=[^>]*\\bname=[\\\"']csrf[\\\"'])"
                    + "(?=[^>]*\\bvalue=[\\\"']([^\\\"']+)[\\\"'])[^>]*>")
                    .saveAs("formCsrf")))
            .exec(http("login").post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> "{\"username\":\"bench-"
                    + (((session.userId() - 1) % 16) + 1)
                    + "\",\"password\":\"bench\",\"csrf\":\""
                    + session.getString("formCsrf") + "\"}"))
                .check(status().in(200, 302),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    header("Location").optional().saveAs("loginLocation")))
            .exec(doIf(session -> session.contains("loginLocation")).then(
                exec(http("login redirect").get("#{loginLocation}")
                    .check(status().is(200),
                        jsonPath("$.csrf").optional().saveAs("csrf")))));
    }

    private static ChainBuilder recoverSession() {
        return exec(http("session renew").post("/v2/session/renew")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(status().in(200, 401), status().saveAs("renewStatus"),
                    bodyString().transform(
                        ModelSimulation::recoverableOrSuccessfulResponse).is(true),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(doIf(session -> session.getInt("renewStatus") != 200).then(login()))
            .exec(doIf(Session::contains, "cart").then(
                exec(http("cart recovery").post("/v2/carts/#{cart}/recover")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
                    .check(status().is(200),
                        header("ETag").optional().saveAs("etag"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))));
    }

    private static Session selectProduct(Session session) {
        try {
            JsonNode products = JSON.readTree(session.getString("catalogBody"))
                .path("data").path("products");
            for (JsonNode product : products) {
                for (JsonNode variant : product.path("variants")) {
                    if (variant.path("in_stock").asBoolean(false)) {
                        return session.set("product", product.path("id").asText())
                            .set("variant", variant.path("id").asText());
                    }
                }
            }
        } catch (IOException | RuntimeException ignored) {
            return session;
        }
        return session;
    }

    private static ChainBuilder catalog() {
        return exec(http("catalog").get("/v2/catalog")
                .header("X-CSRF-Token", "#{csrf}")
                .check(status().in(200, 401), status().saveAs("catalogStatus"),
                    bodyString().transform(ModelSimulation::validCatalogResponse).is(true),
                    bodyString().saveAs("responseBody"),
                    bodyString().saveAs("catalogBody"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(doIf(session -> isRecoverable401(session, "catalogStatus")).then(
                recoverSession()
                    .exec(http("catalog retry").get("/v2/catalog")
                        .header("X-CSRF-Token", "#{csrf}")
                        .check(status().is(200), bodyString().transform(
                                ModelSimulation::validCatalogResponse).is(true),
                            bodyString().saveAs("catalogBody"),
                            jsonPath("$.csrf").optional().saveAs("csrf")))))
            .exec(doIf(session -> session.contains("catalogStatus")
                && session.getInt("catalogStatus") == 200
                || session.contains("catalogBody")).then(
                exec(session -> selectProduct(session))));
    }

    private static String cartBody(Session session) {
        String body = "{\"product_id\":\"" + session.getString("product")
            + "\",\"variant_id\":\"" + session.getString("variant") + "\"";
        if (session.contains("grant")) {
            body += ",\"grant_id\":\"" + session.getString("grant") + "\"";
        }
        return body + "}";
    }

    private static ChainBuilder cartRequest(boolean retry) {
        if (retry) {
            return exec(http("cart retry").post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(ModelSimulation::cartBody))
                .check(status().is(201),
                    bodyString().transform(ModelSimulation::validCartResponse).is(true),
                    jsonPath("$.id").saveAs("cart"),
                    header("ETag").optional().saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")));
        }
        return exec(http("cart").post("/v2/carts")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody(ModelSimulation::cartBody))
            .check(status().in(201, 401), status().saveAs("cartStatus"),
                bodyString().transform(ModelSimulation::validCartResponse).is(true),
                bodyString().saveAs("responseBody"),
                jsonPath("$.id").optional().saveAs("cart"),
                header("ETag").optional().saveAs("etag"),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static ChainBuilder createCart() {
        return cartRequest(false)
            .exec(doIf(session -> isRecoverable401(session, "cartStatus")).then(
                recoverSession().exec(cartRequest(true))));
    }

    private static ChainBuilder orderRequest(boolean retry) {
        if (retry) {
            return exec(http("order retry").post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "#{cart}")
                .header("If-Match", "#{etag}")
                .body(StringBody(session -> "{\"cart_id\":\""
                    + session.getString("cart") + "\"}"))
                .check(status().is(201),
                    bodyString().transform(ModelSimulation::validOrderResponse).is(true),
                    jsonPath("$.csrf").optional().saveAs("csrf")));
        }
        return exec(http("commit").post("/v2/orders")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .header("Idempotency-Key", "#{cart}")
            .header("If-Match", "#{etag}")
            .body(StringBody(session -> "{\"cart_id\":\""
                + session.getString("cart") + "\"}"))
            .check(status().in(201, 401), status().saveAs("orderStatus"),
                bodyString().transform(ModelSimulation::validOrderResponse).is(true),
                bodyString().saveAs("responseBody"),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static ChainBuilder order() {
        return orderRequest(false)
            .exec(doIf(session -> isRecoverable401(session, "orderStatus")).then(
                recoverSession().exec(orderRequest(true))));
    }

    private static ChainBuilder journey() {
        return exec(session -> session.remove("csrf").remove("formCsrf")
                .remove("loginLocation").remove("product").remove("variant")
                .remove("cart").remove("etag").remove("grant")
                .remove("catalogStatus").remove("cartStatus").remove("orderStatus")
                .remove("responseBody").remove("catalogBody").remove("renewStatus"))
            .exec(login())
            .exec(catalog())
            .exec(doIf(session -> session.contains("product")
                && session.contains("variant")).then(
                createCart()
                    .exec(doIf(Session::contains, "cart").then(order()))));
    }

    public ModelSimulation() {
        setUp(scenario("denial journey")
            .exec(repeat(2).on(journey()))
            .injectOpen(atOnceUsers(2)))
            .protocols(HTTP)
            .assertions(global().failedRequests().count().is(0L));
    }
}

