import java.io.IOException;

public class ModelSimulation extends Simulation {
    private static final ObjectMapper JSON = new ObjectMapper();
    private static final String BASE_URL = System.getenv("BASE_URL") == null
        ? "http://127.0.0.1:8000" : System.getenv("BASE_URL");

    private static final HttpProtocolBuilder HTTP = http.baseUrl(BASE_URL)
        .disableWarmUp()
        .acceptHeader("application/json");

    private static JsonNode parse(String body) {
        try {
            return JSON.readTree(body);
        } catch (IOException | RuntimeException ignored) {
            return null;
        }
    }

    private static boolean isRecoverableError(String body) {
        JsonNode node = parse(body);
        if (node == null || !node.hasNonNull("error")) return false;
        String error = node.path("error").asText();
        return "expired".equals(error) || "session".equals(error);
    }

    private static boolean isRecoverable401(Session session, String statusKey, String bodyKey) {
        return session.contains(statusKey)
            && session.getInt(statusKey) == 401
            && session.contains(bodyKey)
            && isRecoverableError(session.getString(bodyKey));
    }

    private static boolean validCatalogOrRecoverableError(String body) {
        JsonNode node = parse(body);
        if (node == null) return false;
        if (node.hasNonNull("error")) return isRecoverableError(body);
        return node.path("data").path("products").isArray();
    }

    private static boolean validCatalog(String body) {
        JsonNode node = parse(body);
        return node != null && node.path("data").path("products").isArray();
    }

    private static boolean validCartOrRecoverableError(String body) {
        JsonNode node = parse(body);
        if (node == null) return false;
        if (node.hasNonNull("error")) return isRecoverableError(body);
        return node.path("id").isValueNode()
            && !node.path("id").isNull()
            && node.path("csrf").isTextual();
    }

    private static boolean validCart(String body) {
        JsonNode node = parse(body);
        return node != null
            && node.path("id").isValueNode()
            && !node.path("id").isNull()
            && node.path("csrf").isTextual();
    }

    private static boolean validJsonOrRecoverableError(String body) {
        JsonNode node = parse(body);
        if (node == null) return false;
        return !node.hasNonNull("error") || isRecoverableError(body);
    }

    private static boolean validRenewResponse(String body) {
        JsonNode node = parse(body);
        if (node == null) return false;
        if ("session".equals(node.path("error").asText())) return true;
        return !node.hasNonNull("error") && node.path("csrf").isTextual();
    }

    private static boolean validOrderOrRecoverableError(String body) {
        JsonNode node = parse(body);
        if (node == null) return false;
        if (node.hasNonNull("error")) return isRecoverableError(body);
        return node.path("accepted").asBoolean(false);
    }

    private static boolean validOrder(String body) {
        JsonNode node = parse(body);
        return node != null && node.path("accepted").asBoolean(false);
    }

    private static ChainBuilder login() {
        return exec(session -> session
                .set("csrf", "")
                .remove("loginLocation"))
            .exec(http("login form").get("/v2/login-form")
                .check(regex("(?i)<input\\b(?=[^>]*\\bname\\s*=\\s*[\\\"']?csrf[\\\"']?(?:\\s|/?>))"
                    + "(?=[^>]*\\bvalue\\s*=\\s*[\\\"']?([^\\\"'\\s>]+)[\\\"']?)[^>]*>")
                    .saveAs("formCsrf")))
            .exec(http("login").post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> "{\"username\":\"bench-"
                    + (((session.userId() - 1) % 16) + 1)
                    + "\",\"password\":\"bench\",\"csrf\":\""
                    + session.getString("formCsrf") + "\"}"))
                .check(status().in(200, 302),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    header("Location").optional().saveAs("loginLocation")))
            .exec(doIf(session -> session.contains("loginLocation")).then(
                exec(http("login redirect").get("#{loginLocation}")
                    .check(status().is(200),
                        jsonPath("$.csrf").saveAs("csrf")))));
    }

    private static ChainBuilder recoverCart() {
        return exec(http("cart recovery").post("/v2/carts/#{cart}/recover")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().is(200),
                header("ETag").optional().saveAs("etag"),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static ChainBuilder renewAndRecover() {
        return exec(http("session renew").post("/v2/session/renew")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(status().in(200, 401),
                    status().saveAs("renewStatus"),
                    bodyString().saveAs("renewBody"),
                    bodyString().transform(ModelSimulation::validRenewResponse).is(true),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(doIf(session -> session.getInt("renewStatus") == 401).then(login()))
            .exec(doIf(session -> session.contains("cart")).then(recoverCart()));
    }

    private static ChainBuilder catalogRequest(boolean retry) {
        if (retry) {
            return exec(http("catalog retry").get("/v2/catalog")
                .header("X-CSRF-Token", "#{csrf}")
                .check(status().is(200),
                    bodyString().transform(ModelSimulation::validCatalog).is(true),
                    bodyString().saveAs("catalogResponse"),
                    jsonPath("$.csrf").optional().saveAs("csrf")));
        }
        return exec(http("catalog").get("/v2/catalog")
            .header("X-CSRF-Token", "#{csrf}")
            .check(status().in(200, 401),
                status().saveAs("catalogStatus"),
                bodyString().saveAs("catalogResponse"),
                bodyString().transform(
                    ModelSimulation::validCatalogOrRecoverableError).is(true),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static Session selectProduct(Session session) {
        JsonNode node = parse(session.getString("catalogResponse"));
        if (node == null) return session;

        JsonNode products = node.path("data").path("products");
        for (JsonNode product : products) {
            for (JsonNode variant : product.path("variants")) {
                if (variant.path("in_stock").asBoolean(false)) {
                    return session
                        .set("product", product.path("id").asText())
                        .set("variant", variant.path("id").asText());
                }
            }
        }
        return session;
    }

    private static ChainBuilder catalog() {
        return catalogRequest(false)
            .exec(doIf(session -> isRecoverable401(
                session, "catalogStatus", "catalogResponse")).then(
                renewAndRecover().exec(catalogRequest(true))))
            .exec(doIf(session -> session.contains("catalogStatus")
                && session.getInt("catalogStatus") == 200).then(
                exec(session -> selectProduct(session))));
    }

    private static String cartBody(Session session) {
        return "{\"product_id\":\"" + session.getString("product")
            + "\",\"variant_id\":\"" + session.getString("variant") + "\"}";
    }

    private static ChainBuilder cartRequest(boolean retry) {
        if (retry) {
            return exec(http("cart retry").post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(ModelSimulation::cartBody))
                .check(status().is(201),
                    bodyString().transform(ModelSimulation::validCart).is(true),
                    jsonPath("$.id").saveAs("cart"),
                    header("ETag").optional().saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")));
        }
        return exec(http("cart").post("/v2/carts")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody(ModelSimulation::cartBody))
            .check(status().in(201, 401),
                status().saveAs("cartStatus"),
                bodyString().saveAs("cartResponse"),
                bodyString().transform(
                    ModelSimulation::validCartOrRecoverableError).is(true),
                jsonPath("$.id").optional().saveAs("cart"),
                header("ETag").optional().saveAs("etag"),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static ChainBuilder createCart() {
        return cartRequest(false)
            .exec(doIf(session -> isRecoverable401(
                session, "cartStatus", "cartResponse")).then(
                renewAndRecover().exec(cartRequest(true))));
    }

    private static ChainBuilder cartReadRequest(boolean retry) {
        if (retry) {
            return exec(http("cart read retry").get("/v2/carts/#{cart}")
                .header("X-CSRF-Token", "#{csrf}")
                .check(status().is(200),
                    bodyString().transform(
                        ModelSimulation::validJsonOrRecoverableError).is(true),
                    header("ETag").saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf")));
        }
        return exec(http("cart read").get("/v2/carts/#{cart}")
            .header("X-CSRF-Token", "#{csrf}")
            .check(status().in(200, 401),
                status().saveAs("cartReadStatus"),
                bodyString().saveAs("cartReadResponse"),
                bodyString().transform(
                    ModelSimulation::validJsonOrRecoverableError).is(true),
                header("ETag").optional().saveAs("etag"),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static ChainBuilder readCart() {
        return cartReadRequest(false)
            .exec(doIf(session -> isRecoverable401(
                session, "cartReadStatus", "cartReadResponse")).then(
                renewAndRecover().exec(cartReadRequest(true))));
    }

    private static ChainBuilder orderRequest(boolean retry) {
        if (retry) {
            return exec(http("order retry").post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "#{cart}")
                .header("If-Match", "#{etag}")
                .body(StringBody(session -> "{\"cart_id\":\""
                    + session.getString("cart") + "\"}"))
                .check(status().is(201),
                    bodyString().transform(ModelSimulation::validOrder).is(true),
                    jsonPath("$.csrf").optional().saveAs("csrf")));
        }
        return exec(http("commit").post("/v2/orders")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .header("Idempotency-Key", "#{cart}")
            .header("If-Match", "#{etag}")
            .body(StringBody(session -> "{\"cart_id\":\""
                + session.getString("cart") + "\"}"))
            .check(status().in(201, 401),
                status().saveAs("orderStatus"),
                bodyString().saveAs("orderResponse"),
                bodyString().transform(
                    ModelSimulation::validOrderOrRecoverableError).is(true),
                jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static ChainBuilder order() {
        return orderRequest(false)
            .exec(doIf(session -> isRecoverable401(
                session, "orderStatus", "orderResponse")).then(
                renewAndRecover().exec(orderRequest(true))));
    }

    private static ChainBuilder journey() {
        return exec(session -> session
                .remove("csrf")
                .remove("formCsrf")
                .remove("loginLocation")
                .remove("product")
                .remove("variant")
                .remove("cart")
                .remove("etag")
                .remove("catalogStatus")
                .remove("catalogResponse")
                .remove("cartStatus")
                .remove("cartResponse")
                .remove("cartReadStatus")
                .remove("cartReadResponse")
                .remove("orderStatus")
                .remove("orderResponse")
                .remove("renewStatus")
                .remove("renewBody"))
            .exec(login())
            .exec(catalog())
            .exec(doIf(session -> session.contains("product")
                && session.contains("variant")).then(createCart()))
            .exec(doIf(session -> session.contains("cart")).then(readCart()))
            .exec(doIf(session -> session.contains("cart")
                && session.contains("etag")).then(order()));
    }

    public ModelSimulation() {
        setUp(scenario("denial journey")
            .exec(repeat(2).on(journey()))
            .injectOpen(atOnceUsers(2)))
            .protocols(HTTP)
            .assertions(global().failedRequests().count().is(0L));
    }
}

