import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const cfg = {"users": 2, "iterations": 2, "mode": "denial"};
const rows = [{"username": "bench-1", "password": "bench", "quantity": 2}, {"username": "bench-2", "password": "bench", "quantity": 3}, {"username": "bench-3", "password": "bench", "quantity": 4}, {"username": "bench-4", "password": "bench", "quantity": 5}, {"username": "bench-5", "password": "bench", "quantity": 6}, {"username": "bench-6", "password": "bench", "quantity": 7}, {"username": "bench-7", "password": "bench", "quantity": 8}, {"username": "bench-8", "password": "bench", "quantity": 9}, {"username": "bench-9", "password": "bench", "quantity": 10}, {"username": "bench-10", "password": "bench", "quantity": 11}, {"username": "bench-11", "password": "bench", "quantity": 12}, {"username": "bench-12", "password": "bench", "quantity": 13}, {"username": "bench-13", "password": "bench", "quantity": 14}, {"username": "bench-14", "password": "bench", "quantity": 15}, {"username": "bench-15", "password": "bench", "quantity": 16}, {"username": "bench-16", "password": "bench", "quantity": 17}];

const failure = new Rate('business_failure');
export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
let csrf = '';
let cart = '';
let grant = '';

function body(r) {
  try {
    return r.json();
  } catch (_) {
    return {};
  }
}

function header(r, name) {
  const wanted = name.toLowerCase();
  const keys = Object.keys(r.headers || {});
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === wanted) return r.headers[keys[i]];
  }
  return '';
}

function urlFor(path) {
  const value = String(path);
  if (/^https?:\/\//i.test(value)) return value;
  return base + (value.charAt(0) === '/' ? value : '/' + value);
}

function raw(path, method, data, extra) {
  const verb = method || 'GET';
  const headers = { 'Content-Type': 'application/json' };
  if (csrf) headers['X-CSRF-Token'] = csrf;

  const additional = extra || {};
  Object.keys(additional).forEach(function (key) {
    headers[key] = additional[key];
  });

  const r = http.request(
    verb,
    urlFor(path),
    data === null || data === undefined ? null : JSON.stringify(data),
    {
      headers: headers,
      redirects: 0,
      timeout: '3s',
    }
  );

  const result = body(r);
  if (typeof result.csrf === 'string' && result.csrf.length > 0) {
    csrf = result.csrf;
  }

  if (path === '/v2/work') {
    const expired = r.status === 401 && result.error === 'expired';
    const retryAfter = Number(header(r, 'Retry-After'));
    const scheduled429 = r.status === 429 && retryAfter >= 1;
    failure.add(r.status >= 400 && !expired && !scheduled429);
  }

  return r;
}

function accountForVU() {
  return rows[(__VU - 1) % rows.length];
}

function login() {
  csrf = '';

  const formResponse = raw('/v2/login-form', 'GET', null);
  let formToken = '';
  try {
    formToken = formResponse.html().find('input[name="csrf"]').first().attr('value') || '';
  } catch (_) {
    formToken = '';
  }

  if (!formToken) {
    check({ ok: false }, { 'login form CSRF token': function (x) { return x.ok; } });
    return false;
  }

  const account = accountForVU();
  let r = raw('/v2/login', 'POST', {
    username: account.username,
    password: account.password,
    csrf: formToken,
  });

  let loginSucceeded = r.status === 200;
  if (r.status === 302) {
    const location = header(r, 'Location');
    if (location) {
      r = raw(location, 'GET', null);
      loginSucceeded = r.status === 200;
    } else {
      loginSucceeded = false;
    }
  }

  const ok = loginSucceeded && !!csrf;
  check({ ok: ok }, { 'fresh login and CSRF token': function (x) { return x.ok; } });
  return ok;
}

function recoverAfter401(original, path, method, data, extra) {
  const error = body(original).error;
  if (error !== 'expired' && error !== 'session') return original;

  let sessionReady = false;

  if (error === 'expired') {
    const renewed = raw('/v2/session/renew', 'POST', {});
    const renewedBody = body(renewed);
    sessionReady = renewed.status === 200 &&
      typeof renewedBody.csrf === 'string' &&
      renewedBody.csrf.length > 0;

    check(
      { ok: sessionReady },
      { 'expired session renewed': function (x) { return x.ok; } }
    );
  }

  if (!sessionReady) {
    sessionReady = login();
  }
  if (!sessionReady) return original;

  if (cart) {
    const recovered = raw('/v2/carts/' + cart + '/recover', 'POST', {});
    const recoverySucceeded = recovered.status === 200;
    check(
      { ok: recoverySucceeded },
      { 'cart recovered after authentication': function (x) { return x.ok; } }
    );
    if (!recoverySucceeded) return original;
  }

  return raw(path, method, data, extra);
}

function request(path, method, data, extra) {
  const verb = method || 'GET';
  const r = raw(path, verb, data, extra);
  if (r.status === 401) {
    return recoverAfter401(r, path, verb, data, extra);
  }
  return r;
}

function work(override) {
  if (!csrf && !login()) return;

  const path = override || cfg.path || '/v2/work';
  let r = request(path, 'POST', {});

  for (let n = 0; n < 4 && r.status === 429; n++) {
    const delay = Number(header(r, 'Retry-After')) || 1;
    sleep(delay);
    r = request(path, 'POST', {});
  }

  check(r, {
    'work operation succeeded': function (response) {
      return response.status === 200 && body(response).ok === true;
    },
  });
}

function eligibleProduct(payload) {
  const products = payload && payload.data && payload.data.products;
  if (!products || !products.length) return null;

  for (let i = 0; i < products.length; i++) {
    const variants = products[i].variants || [];
    for (let j = 0; j < variants.length; j++) {
      if (variants[j].in_stock) return products[i];
    }
  }
  return null;
}

function etagOf(r) {
  return header(r, 'ETag');
}

function flow() {
  csrf = '';
  cart = '';
  grant = '';

  if (!login()) return;

  if (cfg.mode === 'challenge') {
    const challengeForm = request('/v2/challenge-form', 'GET', null);
    if (challengeForm.status !== 200) {
      check(challengeForm, { 'challenge form loaded': function (r) { return r.status === 200; } });
      return;
    }

    let action = '';
    let challengeToken = '';
    try {
      const doc = challengeForm.html();
      const form = doc.find('form').first();
      action = form.attr('action') || '';
      challengeToken = form.find('input[name="challenge"]').first().attr('value') || '';
    } catch (_) {
      action = '';
      challengeToken = '';
    }

    if (!action || !challengeToken) {
      check({ ok: false }, { 'challenge form fields found': function (x) { return x.ok; } });
      return;
    }

    const claim = request(action, 'POST', { challenge: challengeToken });
    const claimLocation = header(claim, 'Location');
    if (claim.status !== 302 || !claimLocation) {
      check(claim, {
        'challenge claim redirected': function (r) { return r.status === 302 && !!header(r, 'Location'); },
      });
      return;
    }

    const grantResponse = request(claimLocation, 'GET', null);
    grant = body(grantResponse).grant_id || '';
    if (grantResponse.status !== 200 || !grant) {
      check({ ok: false }, { 'challenge grant received': function (x) { return x.ok; } });
      return;
    }
  }

  let page = cfg.mode === 'pagination' ? '/v2/catalog/page' : '/v2/catalog';
  let product = null;

  for (let n = 0; n < 3 && page; n++) {
    const catalogResponse = request(page, 'GET', null);
    if (catalogResponse.status !== 200) {
      check(catalogResponse, {
        'catalog page loaded': function (r) { return r.status === 200; },
      });
      return;
    }

    const catalog = body(catalogResponse);
    product = eligibleProduct(catalog);
    if (product) break;
    page = catalog.next || null;
  }

  if (!product) {
    check({ ok: false }, { 'eligible product found': function (x) { return x.ok; } });
    return;
  }

  let variant = null;
  for (let i = 0; i < product.variants.length; i++) {
    if (product.variants[i].in_stock) {
      variant = product.variants[i];
      break;
    }
  }
  if (!variant) {
    check({ ok: false }, { 'in-stock variant found': function (x) { return x.ok; } });
    return;
  }

  const cartPayload = {
    product_id: product.id,
    variant_id: variant.id,
  };
  if (grant) cartPayload.grant_id = grant;

  let r = request('/v2/carts', 'POST', cartPayload);
  check(r, {
    'cart created': function (response) {
      return response.status === 201 && !!body(response).id;
    },
  });
  if (r.status !== 201 || !body(r).id) return;

  cart = body(r).id;
  let etag = etagOf(r);

  if (cfg.mode === 'etag' || cfg.mode === 'data') {
    const quantity = cfg.mode === 'data'
      ? accountForVU().quantity
      : (cfg.quantity || 2);
    const payload = { quantity: quantity };

    r = request('/v2/carts/' + cart, 'PATCH', payload, { 'If-Match': etag });
    if (r.status === 412) {
      const reread = request('/v2/carts/' + cart, 'GET', null);
      etag = etagOf(reread);
      r = request('/v2/carts/' + cart, 'PATCH', payload, { 'If-Match': etag });
    }

    check(r, {
      'cart quantity updated': function (response) { return response.status === 200; },
    });
    if (r.status !== 200) return;
    etag = etagOf(r) || etag;
  }

  let reservationId;
  if (cfg.mode === 'reservation') {
    r = request('/v2/reservations', 'POST', { cart_id: cart });
    if (r.status !== 202 || !body(r).status_url) {
      check(r, {
        'reservation accepted': function (response) { return response.status === 202; },
      });
      return;
    }

    const statusURL = body(r).status_url;
    let ready = false;
    for (let n = 0; n < 5; n++) {
      sleep(0.05);
      r = request(statusURL, 'GET', null);
      const status = body(r);
      if (r.status === 200 && status.status === 'ready' && status.reservation_id) {
        reservationId = status.reservation_id;
        ready = true;
        break;
      }
      if (r.status !== 200 || status.status === 'failed') break;
    }

    check(
      { ready: ready },
      { 'reservation ready': function (x) { return x.ready; } }
    );
    if (!ready) return;
  }

  const orderPayload = { cart_id: cart };
  if (reservationId) orderPayload.reservation_id = reservationId;

  const orderHeaders = { 'Idempotency-Key': 'order-' + cart };
  if (etag) orderHeaders['If-Match'] = etag;

  r = request('/v2/orders', 'POST', orderPayload, orderHeaders);
  check(r, {
    'order accepted': function (response) {
      return response.status === 201 && body(response).accepted === true;
    },
  });

  if (cfg.mode === 'threshold') raw('/v2/health', 'GET', null);
}

export default function () {
  if (cfg.workload) {
    if (cfg.operation === 'journey') flow();
    else work();
  } else if (cfg.mode === 'errors') {
    if (login()) {
      for (let n = 0; n < 4; n++) work();
    }
  } else {
    flow();
  }
}

export function browse() {
  work('/v2/browse');
}

export function checkout() {
  flow();
}

import os
import time
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

from gevent import sleep
from gevent.event import Event
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser


CFG = {"users": 2, "iterations": 2, "mode": "denial"}
MODE = CFG.get("mode", "flow")
ROWS = [
    {"username": "bench-1", "password": "bench", "quantity": 2},
    {"username": "bench-2", "password": "bench", "quantity": 3},
    {"username": "bench-3", "password": "bench", "quantity": 4},
    {"username": "bench-4", "password": "bench", "quantity": 5},
    {"username": "bench-5", "password": "bench", "quantity": 6},
    {"username": "bench-6", "password": "bench", "quantity": 7},
    {"username": "bench-7", "password": "bench", "quantity": 8},
    {"username": "bench-8", "password": "bench", "quantity": 9},
    {"username": "bench-9", "password": "bench", "quantity": 10},
    {"username": "bench-10", "password": "bench", "quantity": 11},
    {"username": "bench-11", "password": "bench", "quantity": 12},
    {"username": "bench-12", "password": "bench", "quantity": 13},
    {"username": "bench-13", "password": "bench", "quantity": 14},
    {"username": "bench-14", "password": "bench", "quantity": 15},
    {"username": "bench-15", "password": "bench", "quantity": 16},
    {"username": "bench-16", "password": "bench", "quantity": 17},
]
BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
DURATION = CFG.get("duration", 35)
POOLS = CFG.get("pools") or [
    {
        "name": "work",
        "path": CFG.get("path", "/v2/work"),
        "rate": CFG.get("rate", 5),
        "operation": CFG.get("operation", "work"),
    }
]
if isinstance(POOLS, dict):
    POOLS = [dict(pool, name=name) for name, pool in POOLS.items()]


def local_path(location):
    """Resolve a supplied URL while refusing to send traffic off the configured host."""
    if not location:
        return None

    base = urlsplit(BASE_URL)
    resolved = urlsplit(urljoin(BASE_URL + "/", location))
    if resolved.scheme != base.scheme or resolved.netloc.lower() != base.netloc.lower():
        return None
    if not resolved.path.startswith("/"):
        return None
    return resolved.path + (("?" + resolved.query) if resolved.query else "")


class FormFields(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.inputs = {}
        self.action = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        tag = tag.lower()
        if tag == "input":
            name = (attrs.get("name") or "").lower()
            if name and attrs.get("value") is not None:
                self.inputs.setdefault(name, []).append(attrs["value"])
        elif tag == "form" and self.action is None:
            self.action = attrs.get("action")


class ArrivalPlan:
    def __init__(self):
        self.started = None
        self.counts = {pool["name"]: 0 for pool in POOLS}
        self.lock = Semaphore()

    def slot(self, pool, number):
        rates = CFG.get("rates", [pool["rate"]]) if not CFG.get("pools") else [pool["rate"]]
        spans = [15, 10, 10] if len(rates) > 1 else [DURATION]
        offset = 0
        for rate, span in zip(rates, spans):
            count = int(rate * span)
            if number < count:
                return offset + number / rate + (
                    number * 0.002 if pool.get("operation") == "journey" else 0
                )
            number -= count
            offset += span
        return None

    def next(self):
        with self.lock:
            if self.started is None:
                self.started = time.monotonic()
            scheduled = [
                (self.slot(pool, self.counts[pool["name"]]), pool)
                for pool in POOLS
            ]
            scheduled = [(slot, pool) for slot, pool in scheduled if slot is not None]
            if not scheduled:
                return None
            slot, pool = min(scheduled, key=lambda item: item[0])
            self.counts[pool["name"]] += 1
            deadline = self.started + slot
        sleep(max(0, deadline - time.monotonic()))
        return pool


ARRIVALS = ArrivalPlan()
OWNER = {"logins": 0, "ready": Event(), "lock": Semaphore()}


class MatrixUser(HttpUser):
    host = BASE_URL
    wait_time = lambda self: 0

    def on_start(self):
        worker_id = str(getattr(self, "_p95_worker_id", "user-1"))
        try:
            number = int(worker_id.rsplit("-", 1)[1])
        except (IndexError, ValueError):
            number = 1

        self.row = ROWS[(number - 1) % len(ROWS)]
        self.username = (
            "bench"
            if MODE == "ownership"
            else self.row["username"]
            if MODE in ("data", "partition")
            else "bench-" + str((number - 1) % 16 + 1)
        )
        self.password = self.row.get("password", "bench")
        self.csrf = ""
        self.cart = ""
        self.etag = ""
        self.grant = ""
        self.iteration = 0

    def fail_run(self):
        self.environment.process_exit_code = 99

    def raw(
        self,
        path,
        method="GET",
        data=None,
        headers=None,
        name=None,
        auth_exhausted=False,
    ):
        safe_path = local_path(path)
        if safe_path is None:
            self.fail_run()
            safe_path = "/__invalid_location__"

        request_headers = {"Content-Type": "application/json"}
        if self.csrf:
            request_headers["X-CSRF-Token"] = self.csrf
        request_headers.update(headers or {})

        with self.client.request(
            method,
            safe_path,
            json=data,
            headers=request_headers,
            name=name,
            catch_response=True,
            allow_redirects=False,
            timeout=3,
        ) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}

            clean_path = safe_path.split("?", 1)[0]
            status = response.status_code
            error = body.get("error")
            allowed = status < 400

            # Expiry/revocation responses are expected control responses only when
            # the caller can still perform its one bounded recovery attempt.
            if status == 401:
                allowed = (
                    error in ("expired", "session")
                    and not auth_exhausted
                )

            # These responses are explicit protocol control-flow outcomes.
            if (
                status == 412
                and method.upper() == "PATCH"
                and clean_path.startswith("/v2/carts/")
            ):
                allowed = True

            if clean_path == "/v2/work" and status == 429:
                try:
                    retry_after = float(response.headers.get("Retry-After", ""))
                except (TypeError, ValueError):
                    retry_after = 0
                allowed = retry_after >= 1

            if (
                clean_path == "/v2/carts"
                and method.upper() == "POST"
                and status != 201
            ):
                allowed = False

            if (
                clean_path == "/v2/orders"
                and method.upper() == "POST"
                and (status != 201 or body.get("accepted") is not True)
            ):
                allowed = False

            if (
                clean_path == "/v2/reservations"
                and method.upper() == "POST"
                and status != 202
            ):
                allowed = False

            if (
                clean_path.startswith("/v2/reservations/")
                and body.get("status") == "failed"
            ):
                allowed = False

            if (
                name == "checkout"
                and response.elapsed.total_seconds() * 1000 >= 250
            ):
                allowed = False

            if allowed:
                response.success()
            else:
                response.failure("request assertion failed")
                self.fail_run()

            if body.get("csrf"):
                self.csrf = body["csrf"]

            return response, body

    def login(self):
        self.csrf = ""
        self.grant = ""

        form_response, _ = self.raw("/v2/login-form", name="login form")
        if form_response.status_code >= 400:
            self.fail_run()
            return False

        fields = FormFields()
        fields.feed(form_response.text)
        csrf_values = fields.inputs.get("csrf", [])
        if not csrf_values:
            self.fail_run()
            return False

        response, body = self.raw(
            "/v2/login",
            "POST",
            {
                "username": self.username,
                "password": self.password,
                "csrf": csrf_values[0],
            },
            name="login",
        )

        if response.status_code == 302:
            location = local_path(response.headers.get("Location"))
            if not location:
                self.fail_run()
                return False
            # Redirects are disabled; fetch the dynamic destination exactly once.
            redirect_response, redirect_body = self.raw(
                location, name="login redirect"
            )
            if redirect_response.status_code >= 400:
                return False
            body = redirect_body
        elif not 200 <= response.status_code < 300:
            self.fail_run()
            return False

        if body.get("grant_id"):
            self.grant = body["grant_id"]
        return bool(self.csrf)

    def recover_session(self, original_error):
        renewed, renew_body = self.raw(
            "/v2/session/renew",
            "POST",
            {},
            name="session renew",
        )

        if renewed.status_code != 200:
            renew_error = renew_body.get("error")
            if renew_error == "denied":
                return False
            if (
                original_error == "session"
                or renew_error in ("session", "expired")
            ):
                if not self.login():
                    return False
            else:
                return False

        if self.cart:
            recovered, _ = self.raw(
                "/v2/carts/" + self.cart + "/recover",
                "POST",
                {},
                name="cart recover",
                auth_exhausted=True,
            )
            if not 200 <= recovered.status_code < 300:
                return False
            self.etag = recovered.headers.get("ETag", self.etag)

        return bool(self.csrf)

    def request(self, path, method="GET", data=None, headers=None, name=None):
        safe_path = local_path(path)
        if safe_path is None:
            self.fail_run()
            safe_path = "/__invalid_location__"

        response, body = self.raw(safe_path, method, data, headers, name)
        if response.status_code != 401 or body.get("error") not in (
            "expired",
            "session",
        ):
            return response, body

        if not self.recover_session(body.get("error")):
            self.fail_run()
            return response, body

        retry_headers = dict(headers or {})
        if any(key.lower() == "if-match" for key in retry_headers):
            for key in list(retry_headers):
                if key.lower() == "if-match":
                    retry_headers[key] = self.etag

        # Retry the interrupted operation once, preserving its payload and
        # idempotency key. A second auth failure is an assertion failure.
        return self.raw(
            safe_path,
            method,
            data,
            retry_headers,
            name,
            auth_exhausted=True,
        )

    def work(self, path="/v2/work"):
        if not self.csrf and not self.login():
            return

        for attempt in range(5):
            response, _ = self.request(path, "POST", {}, name="work")
            if response.status_code != 429:
                return

            try:
                retry_after = float(response.headers.get("Retry-After", ""))
            except (TypeError, ValueError):
                self.fail_run()
                return
            if retry_after < 1:
                self.fail_run()
                return
            if attempt < 4:
                sleep(retry_after)

    def flow(self):
        self.client.cookies.clear()
        self.cart = ""
        self.etag = ""
        self.grant = ""

        if not self.login():
            return

        if MODE == "ownership":
            with OWNER["lock"]:
                OWNER["logins"] += 1
                if OWNER["logins"] >= CFG.get("users", 2):
                    OWNER["ready"].set()
            if not OWNER["ready"].wait(5):
                self.fail_run()
                return
            if str(getattr(self, "_p95_worker_id", "user-1")) != "user-1":
                sleep(0.5)

        if MODE == "challenge":
            page, _ = self.request("/v2/challenge-form", name="challenge form")
            if page.status_code >= 400:
                return
            fields = FormFields()
            fields.feed(page.text)
            actions = fields.action
            challenges = fields.inputs.get("challenge", [])
            action = local_path(actions)
            if not action or not challenges:
                self.fail_run()
                return

            response, _ = self.request(
                action,
                "POST",
                {"challenge": challenges[0]},
                name="challenge claim",
            )
            if response.status_code != 302:
                self.fail_run()
                return

            location = local_path(response.headers.get("Location"))
            if not location:
                self.fail_run()
                return
            grant_response, grant_body = self.request(
                location, name="challenge grant"
            )
            if grant_response.status_code >= 400:
                return
            self.grant = grant_body.get("grant_id", "")

        page = "/v2/catalog/page" if MODE == "pagination" else "/v2/catalog"
        product = None
        for _ in range(3):
            response, body = self.request(page, name="catalog")
            if response.status_code >= 400:
                return

            products = body.get("data", {}).get("products", [])
            product = next(
                (
                    item
                    for item in products
                    if any(
                        variant.get("in_stock")
                        for variant in item.get("variants", [])
                    )
                ),
                None,
            )
            if product:
                break

            next_page = body.get("next")
            if not next_page:
                break
            page = local_path(next_page)
            if not page:
                self.fail_run()
                return

        if not product:
            self.fail_run()
            return

        variant = next(
            item for item in product["variants"] if item.get("in_stock")
        )
        cart_data = {
            "product_id": product["id"],
            "variant_id": variant["id"],
        }
        if self.grant:
            cart_data["grant_id"] = self.grant

        response, body = self.request(
            "/v2/carts",
            "POST",
            cart_data,
            name="cart create",
        )
        self.cart = body.get("id", "")
        self.etag = response.headers.get("ETag", "")
        if response.status_code != 201 or not self.cart:
            self.fail_run()
            return

        if MODE in ("etag", "data"):
            quantity = (
                self.row.get("quantity", 2)
                if MODE == "data"
                else CFG.get("quantity", 2)
            )
            cart_path = "/v2/carts/" + self.cart
            response, _ = self.request(
                cart_path,
                "PATCH",
                {"quantity": quantity},
                {"If-Match": self.etag},
                name="cart update",
            )
            if response.status_code == 412:
                response, _ = self.request(cart_path, name="cart reread")
                if response.status_code >= 400:
                    return
                self.etag = response.headers.get("ETag", self.etag)
                response, _ = self.request(
                    cart_path,
                    "PATCH",
                    {"quantity": quantity},
                    {"If-Match": self.etag},
                    name="cart update retry",
                )
            self.etag = response.headers.get("ETag", self.etag)
            if response.status_code >= 400 or response.status_code == 412:
                self.fail_run()
                return

        reservation = None
        if MODE == "reservation":
            response, body = self.request(
                "/v2/reservations",
                "POST",
                {"cart_id": self.cart},
                name="reservation create",
            )
            if response.status_code != 202:
                return

            status_url = local_path(body.get("status_url"))
            if not status_url:
                self.fail_run()
                return

            for _ in range(5):
                sleep(0.05)
                response, state = self.request(status_url, name="reservation poll")
                if response.status_code >= 400:
                    return
                if state.get("status") == "ready":
                    reservation = state.get("reservation_id")
                    break
                if state.get("status") == "failed":
                    return
            if not reservation:
                self.fail_run()
                return

        order_data = {"cart_id": self.cart}
        if reservation:
            order_data["reservation_id"] = reservation

        response, body = self.request(
            "/v2/orders",
            "POST",
            order_data,
            {"Idempotency-Key": self.cart, "If-Match": self.etag},
            "checkout" if MODE == "threshold" else "checkout",
        )
        if response.status_code != 201 or body.get("accepted") is not True:
            self.fail_run()

    @task
    def run_scenario(self):
        if CFG.get("workload"):
            pool = ARRIVALS.next()
            if pool is None:
                raise StopUser()
            if pool.get("operation") == "journey":
                self.flow()
            else:
                self.work(pool["path"])
            return

        if MODE == "errors":
            self.login()
            for _ in range(4):
                self.work()
        else:
            self.flow()

        self.iteration += 1
        if self.iteration >= CFG.get("iterations", 2):
            raise StopUser()


class MatrixShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.first_tick = True

    def tick(self):
        users = (
            CFG.get(
                "max_vus",
                64 if CFG.get("capacity") or CFG.get("pools") else 32,
            )
            if CFG.get("workload")
            else CFG.get("users", 2)
        )
        elapsed = self.get_run_time()

        if CFG.get("workload"):
            return None if elapsed >= DURATION + 5 else (users, max(1, users))

        if self.first_tick:
            self.first_tick = False
            return users, max(1, users)

        return None if self.runner.user_count == 0 else (users, max(1, users))

