  { username: 'bench-15', password: 'bench', quantity: 16 },
  { username: 'bench-16', password: 'bench', quantity: 17 },
];

const businessFailure = new Rate('business_failure');
const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: cfg.users,
      iterations: cfg.iterations,
      maxDuration: '30s',
    },
  },
  thresholds: {
    checks: ['rate==1'],
  },
};

let csrf = '';
let cart = '';
let grant = '';

function endpoint(path) {
  let value = String(path || '/');
  if (/^https?:\/\//i.test(value)) {
    const schemeEnd = value.indexOf('://') + 3;
    const pathStart = value.indexOf('/', schemeEnd);
    value = pathStart < 0 ? '/' : value.slice(pathStart);
  }
  return base + (value.charAt(0) === '/' ? value : '/' + value);
}

function body(response) {
  try {
    const parsed = response.json();
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch (_) {
    return {};
  }
}

function header(response, name) {
  return response.headers[name] || response.headers[name.toLowerCase()] || '';
}

function raw(path, method, data, extraHeaders) {
  const headers = Object.assign(
    {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    extraHeaders || {}
  );

  const response = http.request(
    method || 'GET',
    endpoint(path),
    data === null || data === undefined ? null : JSON.stringify(data),
    { headers: headers, redirects: 0, timeout: '3s' }
  );

  const parsed = body(response);
  if (typeof parsed.csrf === 'string' && parsed.csrf) {
    csrf = parsed.csrf;
  }

  if (path === '/v2/work') {
    const retryAfter = Number(header(response, 'Retry-After'));
    const expectedExpiry = response.status === 401 && parsed.error === 'expired';
    const expectedThrottle = response.status === 429 && retryAfter === 1;
    businessFailure.add(
      response.status >= 400 && !expectedExpiry && !expectedThrottle
    );
  }

  return response;
}

function login() {
  csrf = '';

  const formResponse = raw('/v2/login-form', 'GET', null);
  let loginToken = '';
  try {
    loginToken = formResponse.html().find('input[name="csrf"]').first().attr('value') || '';
  } catch (_) {
    loginToken = '';
  }

  if (
    !check(formResponse, {
      'login form and CSRF token': (r) => r.status === 200 && loginToken.length > 0,
    })
  ) {
    return false;
  }

  const row = rows[(__VU - 1) % rows.length];
  let response = raw('/v2/login', 'POST', {
    username: row.username,
    password: row.password,
    csrf: loginToken,
  });

  if (response.status === 302) {
    const location = header(response, 'Location');
    if (!location) {
      check(false, { 'login redirect has Location': (value) => value });
      return false;
    }
    response = raw(location, 'GET', null);
  }

  return check(response, {
    'login succeeds': (r) => r.status === 200,
  });
}

function recoverCart() {
  if (!cart) {
    return true;
  }
  const response = raw('/v2/carts/' + cart + '/recover', 'POST', {});
  return check(response, {
    'cart recovery succeeds': (r) => r.status >= 200 && r.status < 300,
  });
}

function request(path, method, data, extraHeaders) {
  let response = raw(path, method || 'GET', data, extraHeaders);
  if (response.status !== 401) {
    return response;
  }

  const error = body(response).error;
  if (error !== 'expired' && error !== 'session') {
    return response;
  }

  if (error === 'expired') {
    const renewed = raw('/v2/session/renew', 'POST', {});
    if (renewed.status !== 200 && !login()) {
      return response;
    }
  } else if (!login()) {
    return response;
  }

  if (!recoverCart()) {
    return response;
  }

  // Retry only the interrupted operation, once.
  return raw(path, method || 'GET', data, extraHeaders);
}

function findEligibleProduct(catalog) {
  if (!catalog || !catalog.data || !Array.isArray(catalog.data.products)) {
    return null;
  }
  for (let i = 0; i < catalog.data.products.length; i++) {
    const product = catalog.data.products[i];
    if (!product || !Array.isArray(product.variants)) {
      continue;
    }
    for (let j = 0; j < product.variants.length; j++) {
      if (product.variants[j] && product.variants[j].in_stock) {
        return product;
      }
    }
  }
  return null;
}

function flow() {
  csrf = '';
  cart = '';
  grant = '';

  if (!login()) {
    return;
  }

  if (cfg.mode === 'challenge') {
    const formResponse = request('/v2/challenge-form', 'GET', null);
    if (!check(formResponse, { 'challenge form loads': (r) => r.status === 200 })) {
      return;
    }

    let form;
    let challengeToken = '';
    let action = '';
    try {
      form = formResponse.html().find('form').first();
      challengeToken = form.find('input[name="challenge"]').first().attr('value') || '';
      action = form.attr('action') || '';
    } catch (_) {
      challengeToken = '';
      action = '';
    }

    if (!challengeToken || !action) {
      check(false, { 'challenge form has action and token': (value) => value });
      return;
    }

    const claim = request(action, 'POST', { challenge: challengeToken });
    const claimLocation = header(claim, 'Location');
    if (
      !check(claim, {
        'challenge claim redirects': (r) => r.status === 302 && claimLocation.length > 0,
      })
    ) {
      return;
    }

    const grantResponse = request(claimLocation, 'GET', null);
    const grantBody = body(grantResponse);
    if (
      !check(grantResponse, {
        'challenge grant is returned': (r) =>
          r.status === 200 && typeof grantBody.grant_id === 'string',
      })
    ) {
      return;
    }
    grant = grantBody.grant_id;
  }

  let page = cfg.mode === 'pagination' ? '/v2/catalog/page' : '/v2/catalog';
  let product = null;

  for (let n = 0; n < 3 && page; n++) {
    const response = request(page, 'GET', null);
    if (!check(response, { 'catalog page loads': (r) => r.status === 200 })) {
      return;
    }

    const catalog = body(response);
    product = findEligibleProduct(catalog);
    if (product) {
      break;
    }
    page = catalog.next || null;
  }

  if (!product) {
    check(false, { 'eligible in-stock product exists': (value) => value });
    return;
  }

  let variant = null;
  for (let i = 0; i < product.variants.length; i++) {
    if (product.variants[i] && product.variants[i].in_stock) {
      variant = product.variants[i];
      break;
    }
  }
  if (!variant) {
    check(false, { 'in-stock variant exists': (value) => value });
    return;
  }

  const cartPayload = {
    product_id: product.id,
    variant_id: variant.id,
  };
  if (grant) {
    cartPayload.grant_id = grant;
  }

  const cartResponse = request('/v2/carts', 'POST', cartPayload);
  grant = '';
  const cartBody = body(cartResponse);
  if (
    !check(cartResponse, {
      'cart is created': (r) =>
        r.status === 201 && cartBody.id !== undefined && cartBody.id !== null,
    })
  ) {
    return;
  }

  cart = String(cartBody.id);
  let etag = header(cartResponse, 'ETag');

  if (!etag) {
    const cartRead = request('/v2/carts/' + cart, 'GET', null);
    if (!check(cartRead, { 'cart can be read': (r) => r.status === 200 })) {
      return;
    }
    etag = header(cartRead, 'ETag');
  }

  if (cfg.mode === 'etag' || cfg.mode === 'data') {
    const row = rows[(__VU - 1) % rows.length];
    const quantity = cfg.mode === 'data' ? row.quantity : (cfg.quantity || 2);

    if (!etag) {
      check(false, { 'cart has ETag for update': (value) => value });
      return;
    }

    const payload = { quantity: quantity };
    let updated = request('/v2/carts/' + cart, 'PATCH', payload, {
      'If-Match': etag,
    });

    if (updated.status === 412) {
      const reread = request('/v2/carts/' + cart, 'GET', null);
      if (!check(reread, { 'cart rereads after 412': (r) => r.status === 200 })) {
        return;
      }
      etag = header(reread, 'ETag');
      if (!etag) {
        check(false, { 'cart reread supplies ETag': (value) => value });
        return;
      }
      // Retry the same payload once with the refreshed ETag.
      updated = request('/v2/carts/' + cart, 'PATCH', payload, {
        'If-Match': etag,
      });
    }

    if (!check(updated, { 'cart quantity update succeeds': (r) => r.status === 200 })) {
      return;
    }
    etag = header(updated, 'ETag') || etag;
  }

  let reservationId = '';
  if (cfg.mode === 'reservation') {
    const reservationResponse = request('/v2/reservations', 'POST', {
      cart_id: cart,
    });
    const reservationBody = body(reservationResponse);
    if (
      !check(reservationResponse, {
        'reservation is submitted': (r) =>
          r.status === 202 && typeof reservationBody.status_url === 'string',
      })
    ) {
      return;
    }

    for (let n = 0; n < 5; n++) {
      sleep(0.05);
      const statusResponse = request(reservationBody.status_url, 'GET', null);
      const statusBody = body(statusResponse);
      if (statusResponse.status === 200 && statusBody.status === 'ready') {
        reservationId = statusBody.reservation_id || '';
        break;
      }
      if (statusBody.status === 'failed') {
        break;
      }
    }

    if (!reservationId) {
      check(false, { 'reservation becomes ready': (value) => value });
      return;
    }
  }

  const orderPayload = { cart_id: cart };
  if (reservationId) {
    orderPayload.reservation_id = reservationId;
  }

  const orderHeaders = { 'Idempotency-Key': 'order-' + cart };
  if (etag) {
    orderHeaders['If-Match'] = etag;
  }

  const orderResponse = request('/v2/orders', 'POST', orderPayload, orderHeaders);
  const orderBody = body(orderResponse);
  check(orderResponse, {
    'order accepted': (r) => r.status === 201 && orderBody.accepted === true,
  });
}

function work(pathOverride) {
  if (!csrf && !login()) {
    return;
  }

  const path = pathOverride || cfg.path || '/v2/work';
  let response = request(path, 'POST', {});

  for (let retry = 0; retry < 4 && response.status === 429; retry++) {
    const retryAfter = Number(header(response, 'Retry-After'));
    if (retryAfter !== 1) {
      break;
    }
    sleep(1);
    response = request(path, 'POST', {});
  }

  check(response, {
    'business operation succeeds': (r) =>
      r.status === 200 && body(r).ok === true,
  });
}

export default function () {
  if (cfg.workload) {
    if (cfg.operation === 'journey') {
      flow();
    } else {
      work();
    }
  } else if (cfg.mode === 'errors') {
    if (login()) {
      for (let i = 0; i < 4; i++) {
        work();
      }
    }
  } else {
    flow();
  }
}

export function browse() {
  work('/v2/browse');
}

export function checkout() {
  flow();
}

import os

from gevent.lock import Semaphore
from html.parser import HTMLParser
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

CFG = {"users": 2, "iterations": 2, "mode": "decline"}

_STATE_LOCK = Semaphore()
_NEXT_ACCOUNT = 0
_COMPLETED_JOURNEYS = 0


def allocate_account():
    global _NEXT_ACCOUNT
    with _STATE_LOCK:
        number = _NEXT_ACCOUNT
        _NEXT_ACCOUNT += 1
    return "bench-{}".format(number % 16 + 1)


def record_completion():
    global _COMPLETED_JOURNEYS
    with _STATE_LOCK:
        _COMPLETED_JOURNEYS += 1


def completed_journeys():
    with _STATE_LOCK:
        return _COMPLETED_JOURNEYS


class InputParser(HTMLParser):
    def __init__(self, wanted_name):
        super().__init__(convert_charrefs=True)
        self.wanted_name = wanted_name.lower()
        self.value = None

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input":
            return
        attributes = {}
        for key, value in attrs:
            if key:
                attributes[key.lower()] = value
        if (str(attributes.get("name", "")).lower() == self.wanted_name
                and attributes.get("value") is not None
                and self.value is None):
            self.value = attributes["value"]


class ShopUser(HttpUser):
    host = os.environ["BASE_URL"]
    wait_time = lambda self: 0

    def on_start(self):
        self.username = allocate_account()
        self.password = "bench"
        self.csrf = ""
        self.cart = ""
        self.etag = ""
        self.iteration = 0
        self._form_csrf = None

    def _parse_body(self, response):
        try:
            body = response.json()
        except (ValueError, TypeError):
            return {}
        return body if isinstance(body, dict) else {}

    def raw(self, path, method="GET", data=None, headers=None, name=None,
            expected=None, validator=None, checkout=False):
        request_headers = {"Content-Type": "application/json"}
        if self.csrf and method.upper() != "GET":
            request_headers["X-CSRF-Token"] = self.csrf
        request_headers.update(headers or {})

        with self.client.request(
            method,
            path,
            json=data,
            headers=request_headers,
            name=name,
            catch_response=True,
            allow_redirects=False,
            timeout=3,
        ) as response:
            body = self._parse_body(response)
            if body.get("csrf"):
                self.csrf = str(body["csrf"])

            error = body.get("error")
            recoverable_auth = (
                response.status_code == 401 and error in ("expired", "session")
            )
            etag_conflict = (
                method.upper() == "PATCH"
                and response.status_code == 412
                and error in ("etag", "etag_conflict")
            )
            scheduled_work_limit = (
                response.status_code == 429
                and path.split("?", 1)[0] in ("/v2/work", "/v2/browse")
            )

            message = "request assertion failed"
            if recoverable_auth or etag_conflict or scheduled_work_limit:
                ok = True
            elif checkout:
                if response.status_code == 200 and body.get("accepted") is False:
                    ok = False
                    message = "checkout declined: accepted=false"
                elif response.status_code == 201 and body.get("accepted") is True:
                    ok = True
                else:
                    ok = False
                    message = "checkout assertion failed: expected HTTP 201 accepted=true"
            elif expected is not None:
                ok = response.status_code in expected
            else:
                ok = response.status_code < 400

            if ok and validator is not None:
                try:
                    result = validator(response, body)
                    if isinstance(result, tuple):
                        ok, message = result
                    else:
                        ok = bool(result)
                        if not ok:
                            message = "response content assertion failed"
                except Exception:
                    ok = False
                    message = "response content assertion failed"

            if ok:
                response.success()
            else:
                response.failure(message)

            return response, body, ok

    def _csrf_form_validator(self, response, _body):
        parser = InputParser("csrf")
        parser.feed(response.text or "")
        self._form_csrf = parser.value
        return bool(self._form_csrf), "login form assertion failed: missing csrf input"

    def login(self):
        self.csrf = ""
        self._form_csrf = None

        _, _, ok = self.raw(
            "/v2/login-form",
            expected={200},
            validator=self._csrf_form_validator,
            name="login form",
        )
        if not ok or not self._form_csrf:
            return False

        def login_validator(response, body):
            if response.status_code == 302:
                return (
                    bool(response.headers.get("Location")),
                    "login assertion failed: missing redirect Location",
                )
            return (
                bool(body.get("csrf")),
                "login assertion failed: missing csrf",
            )

        response, _, ok = self.raw(
            "/v2/login",
            method="POST",
            data={
                "username": self.username,
                "password": self.password,
                "csrf": self._form_csrf,
            },
            expected={200, 302},
            validator=login_validator,
            name="login",
        )
        if not ok:
            return False

        if response.status_code == 302:
            location = response.headers.get("Location")
            if not location:
                return False

            _, _, ok = self.raw(
                location,
                method="GET",
                expected={200},
                validator=lambda _response, body: (
                    bool(body.get("csrf")),
                    "login redirect assertion failed: missing csrf",
                ),
                name="login redirect",
            )
            if not ok:
                return False

        return bool(self.csrf)

    def recover(self, auth_error):
        renewed, _, renew_ok = self.raw(
            "/v2/session/renew",
            method="POST",
            data={},
            expected={200},
            name="session renew",
        )
        if auth_error == "session" or renewed.status_code != 200 or not renew_ok:
            self.login()

        if self.cart and self.csrf:
            response, _, _ = self.raw(
                "/v2/carts/" + self.cart + "/recover",
                method="POST",
                data={},
                expected={200},
                name="cart recover",
            )
            self.etag = response.headers.get("ETag", self.etag)

    def request(self, path, method="GET", data=None, headers=None, name=None,
                expected=None, validator=None, checkout=False):
        request_headers = dict(headers or {})
        for attempt in range(2):
            response, body, ok = self.raw(
                path,
                method=method,
                data=data,
                headers=request_headers,
                name=name,
                expected=expected,
                validator=validator,
                checkout=checkout,
            )
            if (attempt == 0
                    and response.status_code == 401
                    and body.get("error") in ("expired", "session")):
                self.recover(body["error"])
                if path == "/v2/orders" and self.etag:
                    request_headers["If-Match"] = self.etag
                continue
            return response, body, ok
        return response, body, ok

    def _catalog_validator(self, _response, body):
        products = body.get("data", {}).get("products")
        return (
            isinstance(products, list),
            "catalog assertion failed: missing products list",
        )

    def _cart_validator(self, _response, body):
        return (
            body.get("id") is not None,
            "cart assertion failed: missing cart id",
        )

    def journey(self):
        # Each journey starts with its own fresh login and cart.
        self.client.cookies.clear()
        self.csrf = ""
        self.cart = ""
        self.etag = ""

        if not self.login():
            return

        path = "/v2/catalog"
        selected_product = None
        selected_variant = None

        for _ in range(3):
            _, body, ok = self.request(
                path,
                expected={200},
                validator=self._catalog_validator,
                name="catalog",
            )
            if not ok:
                return

            products = body.get("data", {}).get("products", [])
            for product in products:
                if not isinstance(product, dict):
                    continue
                variants = product.get("variants", [])
                if not isinstance(variants, list):
                    continue
                variant = next(
                    (
                        item for item in variants
                        if isinstance(item, dict) and item.get("in_stock") is True
                    ),
                    None,
                )
                if variant is not None:
                    selected_product = product
                    selected_variant = variant
                    break

            if selected_product is not None:
                break

            next_path = body.get("next")
            if not isinstance(next_path, str) or not next_path:
                break
            path = next_path

        if selected_product is None or selected_variant is None:
            return

        cart_response, cart_body, ok = self.request(
            "/v2/carts",
            method="POST",
            data={
                "product_id": selected_product["id"],
                "variant_id": selected_variant["id"],
            },
            expected={201},
            validator=self._cart_validator,
            name="create cart",
        )
        if not ok:
            return

        self.cart = str(cart_body["id"])
        self.etag = cart_response.headers.get("ETag", "")

        order_headers = {"Idempotency-Key": self.cart}
        if self.etag:
            order_headers["If-Match"] = self.etag

        # A declined HTTP 200 is an assertion failure, not a successful order.
        # Do not retry it or create another cart.
        self.request(
            "/v2/orders",
            method="POST",
            data={"cart_id": self.cart},
            headers=order_headers,
            name="checkout",
            checkout=True,
        )

    @task
    def run_journey(self):
        if self.iteration >= CFG["iterations"]:
            raise StopUser()

        self.journey()
        self.iteration += 1
        record_completion()

        if self.iteration >= CFG["iterations"]:
            raise StopUser()


class MatrixShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.first_tick = True

    def tick(self):
        users = CFG["users"]
        if self.first_tick:
            self.first_tick = False
            return users, users

        if completed_journeys() >= users * CFG["iterations"]:
            return None

        return users, users

