        try {
            double seconds = Double.parseDouble(session.getString("retryAfter"));
            return Duration.ofMillis((long) Math.ceil(Math.max(1.0, seconds) * 1000));
        } catch (RuntimeException error) {
            return Duration.ofSeconds(1);
        }
    }

    private static ChainBuilder rawWork() {
        return exec(http("work").post("/v2/work")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
