    private static JsonNode readAccounts() {
        if (USER_COUNT < 1 || ITERATION_COUNT < 1) {
            throw new IllegalStateException("users and iterations must be positive");
        }
        try {
            JsonNode rows = JSON.readTree(Files.readString(Path.of("/fixtures/accounts.json")));
            if (rows == null || !rows.isArray() || rows.size() < USER_COUNT) {
                throw new IllegalStateException("accounts.json does not contain an account for every user");
            }

            Set<String> usernames = new HashSet<>();
            for (int i = 0; i < USER_COUNT; i++) {
                String username = rows.get(i).path("username").asText("");
                String password = rows.get(i).path("password").asText("");
                if (username.isBlank() || password.isBlank() || !usernames.add(username)) {
                    throw new IllegalStateException("account rows must have credentials and distinct usernames");
                }
