    ROWS = json.load(accounts_file)

if not isinstance(ROWS, list) or len(ROWS) < CFG["users"]:
    raise ValueError("Not enough fixture accounts for the configured users")

_user_assignment_lock = Semaphore()
_user_assignment_next = 0

_barrier_lock = Semaphore()
_barrier_arrivals = 0
_barrier_event = Event()


class InputParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.inputs = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "input":
            self.inputs.append(dict(attrs))

    def value_for(self, name):
        for attrs in self.inputs:
            if attrs.get("name") == name and attrs.get("value"):
                return attrs["value"]
        return None


def user_index(user):
    global _user_assignment_next

    worker_id = str(getattr(user, "_p95_worker_id", ""))
    match = re.search(r"(\d+)$", worker_id)
    if match:
        index = int(match.group(1)) - 1
    else:
        with _user_assignment_lock:
            index = _user_assignment_next
            _user_assignment_next += 1

    if index < 0 or index >= len(ROWS):
        raise ValueError("No fixture account assigned to this user")
    return index


def journey_barrier():
    """Keep both logged-in sessions active before either journey proceeds."""
    global _barrier_arrivals, _barrier_event

    with _barrier_lock:
        event = _barrier_event
        _barrier_arrivals += 1
        if _barrier_arrivals >= CFG["users"]:
            _barrier_arrivals = 0
            _barrier_event = Event()
            event.set()

    return event.wait(timeout=5)


