    wait_time = lambda self: 0

    def on_start(self):
        try:
            self.row = ROWS[user_index(self)]
        except (IndexError, ValueError):
            self.environment.process_exit_code = 99
            raise StopUser()

        self.username = self.row["username"]
        self.password = self.row.get("password", "bench")
        self.csrf = ""
        self.cart = ""
        self.etag = ""
        self.iteration = 0

    def raw(self, path, method="GET", data=None, headers=None, name=None,
            expected_status=None, validator=None):
        request_headers = {"Content-Type": "application/json"}
        if self.csrf:
            request_headers["X-CSRF-Token"] = self.csrf
        request_headers.update(headers or {})

        with self.client.request(
            method,
            path,
            json=data,
            headers=request_headers,
            name=name,
            catch_response=True,
            allow_redirects=False,
            timeout=3,
        ) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}

            error = body.get("error")
            expected_interruption = (
                response.status_code == 401 and error in ("expired", "session")
            )
            expected_conflict = (
                response.status_code == 412
                and error in ("etag", "etag_conflict")
            )
            expected_work_throttle = (
                response.status_code == 429
                and path.split("?", 1)[0] == "/v2/work"
            )

            allowed = (
                response.status_code < 400
                or expected_interruption
                or expected_conflict
                or expected_work_throttle
            )

            if expected_status is not None and not expected_interruption:
                allowed = allowed and response.status_code == expected_status

            if (
                path.split("?", 1)[0] == "/v2/orders"
                and method == "POST"
                and response.status_code < 400
                and body.get("accepted") is not True
            ):
                allowed = False

            if validator is not None and not expected_interruption:
                try:
                    allowed = allowed and bool(validator(response, body))
                except Exception:
                    allowed = False

