        self.csrf = ""
        form, _ = self.raw("/v2/login-form")
        parser = InputParser()
        parser.feed(form.text or "")
        token = parser.value_for("csrf")
        if not token:
            self.environment.process_exit_code = 99
            return False

        response, body = self.raw(
            "/v2/login",
            "POST",
            {
                "username": self.username,
                "password": self.password,
                "csrf": token,
            },
        )

        if response.status_code == 302:
            location = response.headers.get("Location")
            if not location:
                self.environment.process_exit_code = 99
                return False
            _, body = self.raw(location)

