            response, _ = self.raw(
                "/v2/carts/" + self.cart + "/recover", "POST", {}
            )
            if response.status_code >= 400:
                return False
            self.etag = response.headers.get("ETag", self.etag)

        return True

    def request(self, path, method="GET", data=None, headers=None, name=None,
                expected_status=None, validator=None):
        request_headers = dict(headers or {})
        response, body = self.raw(
            path,
            method,
            data,
            request_headers,
            name,
            expected_status,
            validator,
        )

        if response.status_code == 401 and body.get("error") in (
            "expired",
            "session",
        ):
            if not self.recover(body["error"]):
                self.environment.process_exit_code = 99
                return response, body

            if "If-Match" in request_headers and self.etag:
                request_headers["If-Match"] = self.etag

            response, body = self.raw(
                path,
                method,
                data,
                request_headers,
                name,
                expected_status,
                validator,
            )
            if response.status_code == 401:
                self.environment.process_exit_code = 99

        return response, body

    def flow(self):
        self.client.cookies.clear()
        self.csrf = ""
        self.cart = ""
        self.etag = ""

        logged_in = self.login()
        if not journey_barrier():
            self.environment.process_exit_code = 99
            return
        if not logged_in:
            return

        page = "/v2/catalog"
        product = None
        for _ in range(3):
            _, body = self.request(page)
            products = body.get("data", {}).get("products", [])
            product = next(
                (
                    item
                    for item in products
                    if any(
                        variant.get("in_stock")
                        for variant in item.get("variants", [])
                    )
                ),
                None,
            )
            if product:
                break
            page = body.get("next")
            if not page:
                break

        if not product:
            self.environment.process_exit_code = 99
            return

        variant = next(
            item for item in product["variants"] if item.get("in_stock")
        )
        response, body = self.request(
            "/v2/carts",
            "POST",
            {
                "product_id": product["id"],
                "variant_id": variant["id"],
            },
            expected_status=201,
            validator=lambda response, body: bool(body.get("id")),
        )
        self.cart = body.get("id", "")
        self.etag = response.headers.get("ETag", "")
        if not self.cart:
            self.environment.process_exit_code = 99
            return

        order_headers = {"Idempotency-Key": self.cart}
        if self.etag:
            order_headers["If-Match"] = self.etag

        self.request(
            "/v2/orders",
            "POST",
            {"cart_id": self.cart},
            order_headers,
            expected_status=201,
            validator=lambda response, body: body.get("accepted") is True,
        )

    @task
    def run_scenario(self):
        self.flow()
        self.iteration += 1
        if self.iteration >= CFG["iterations"]:
            raise StopUser()


class MatrixShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.started = False

    def tick(self):
        users = CFG["users"]
        if not self.started:
            self.started = True
            return users, users
        if self.runner.user_count == 0:
            return None
        return users, users

