import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.io.IOException;
import java.time.Duration;

public class ModelSimulation extends Simulation {
    private static final int USERS = 2;
    private static final int ITERATIONS = 2;
    private static final int WORKS_PER_ITERATION = 4;
    private static final ObjectMapper JSON = new ObjectMapper();
    private static final String BASE_URL =
        System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final HttpProtocolBuilder HTTP = http.baseUrl(BASE_URL)
        .disableWarmUp()
        .acceptHeader("application/json");

    private static String username(Session session) {
        return "bench-" + ((session.userId() - 1) % 16 + 1);
    }

    private static String classifyWorkBody(String body) {
        if (body == null || body.isBlank()) {
            return "valid";
        }

        try {
            JsonNode node = JSON.readTree(body);
            if (node == null || !node.isObject()) {
                return "invalid";
            }

            String error = node.path("error").asText("");
            if ("denied".equals(error) || "session".equals(error)) {
                return "invalid";
            }
            if (!error.isEmpty()) {
                return "valid";
            }
            if (node.has("ok")) {
                return node.path("ok").asBoolean(false) ? "valid" : "invalid";
            }
            return "valid";
        } catch (IOException error) {
            return "invalid";
        }
    }

    private static Duration retryDelay(Session session) {
        try {
            long millis = (long) (Double.parseDouble(session.getString("retryAfter")) * 1000);
            return Duration.ofMillis(Math.max(1000, millis));
        } catch (RuntimeException error) {
            return Duration.ofSeconds(1);
        }
    }

    private static ChainBuilder login() {
        return exec(session -> session.set("csrf", "")
                .remove("location")
                .remove("workStatus")
                .remove("workError")
                .remove("retryAfter"))
            .exec(http("login form").get("/v2/login-form")
                .check(regex("(?is)<input\\b(?=[^>]*\\bname\\s*=\\s*['\"]csrf['\"])"
                    + "(?=[^>]*\\bvalue\\s*=\\s*['\"]([^'\"]+)['\"])[^>]*>")
                    .saveAs("formCsrf")))
            .exec(http("login").post("/v2/login")
                .disableFollowRedirect()
                .header("Content-Type", "application/json")
                .body(StringBody(session -> "{\"username\":\"" + username(session)
                    + "\",\"password\":\"bench\",\"csrf\":\""
                    + session.getString("formCsrf") + "\"}"))
                .check(status().in(200, 302),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    header("Location").optional().saveAs("location")))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("login redirect").get("#{location}")
                    .check(jsonPath("$.csrf").optional().saveAs("csrf")))));
    }

    private static ChainBuilder workAttempt(String path) {
        return exec(session -> session.remove("workError").remove("retryAfter"))
            .exec(http("work").post(path)
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(status().saveAs("workStatus"),
                    status().in(200, 401, 429),
                    header("Retry-After").optional().saveAs("retryAfter"),
                    jsonPath("$.error").optional().saveAs("workError"),
                    bodyString().transform(ModelSimulation::classifyWorkBody).is("valid"),
                    jsonPath("$.csrf").optional().saveAs("csrf")));
    }

    private static ChainBuilder renew() {
        return exec(http("renew").post("/v2/session/renew")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().is(200), jsonPath("$.csrf").saveAs("csrf")));
    }

    private static ChainBuilder workRequest(String path) {
        ChainBuilder chain = exec(session -> session.set("expiryRecovered", false)
                .set("throttleRetries", 0))
            .exec(workAttempt(path));

        // Recover an expired session at most once for this interrupted operation.
        // Four subsequent stages allow the original request and its retry to
        // receive scheduled 429 responses while limiting throttling retries to four.
        for (int stage = 0; stage < 5; stage++) {
            chain = chain.exec(doIf(session ->
                    session.getInt("workStatus") == 401
                        && "expired".equals(session.getString("workError"))
                        && !session.getBoolean("expiryRecovered"))
                .then(exec(session -> session.set("expiryRecovered", true))
                    .exec(renew())
                    .exec(workAttempt(path))));

            if (stage < 4) {
                chain = chain.exec(doIf(session ->
                        session.getInt("workStatus") == 429
                            && session.getInt("throttleRetries") < 4)
                    .then(pause(session -> retryDelay(session))
                        .exec(session -> session.set("throttleRetries",
                            session.getInt("throttleRetries") + 1))
                        .exec(workAttempt(path))));
            }
        }
        return chain;
    }

    public ModelSimulation() {
        setUp(
            scenario("work")
                .exec(repeat(ITERATIONS).on(
                    login().exec(repeat(WORKS_PER_ITERATION)
                        .on(workRequest("/v2/work")))))
                .injectOpen(atOnceUsers(USERS))
        ).protocols(HTTP);
    }
}

