  "thresholds": {"checks": ["rate==1"]}
};

let csrf = '', cart = '', grant = '';
let unexpectedWorkResponse = false;
const base = __ENV.BASE_URL;

function body(r) {
  try {
    return r.json();
  } catch (_) {
    return {};
  }
}

function retryAfterSeconds(r) {
  const value = r.headers['Retry-After'] || r.headers['retry-after'];
  return value === undefined || value === null || String(value).trim() === ''
    ? NaN
    : Number(value);
}

function isScheduledThrottle(r) {
  return r.status === 429 && retryAfterSeconds(r) === 1;
}

function raw(path, method='GET', data=null, extra={}) {
  const r = http.request(method, base + path, data === null ? null : JSON.stringify(data), {
    headers: Object.assign({'Content-Type': 'application/json', 'X-CSRF-Token': csrf}, extra),
    redirects: 0,
    timeout: '3s'
  });

  const b = body(r);
  if (b.csrf) csrf = b.csrf;

  if (path === '/v2/work') {
    const expectedExpiry = r.status === 401 && b.error === 'expired';
    const expectedThrottle = isScheduledThrottle(r);
    const successfulWork = r.status === 200 && b.ok === true;
    const unexpected = !successfulWork && !expectedExpiry && !expectedThrottle;

    // A Rate's denominator is the number of samples added: add one for every
    // raw work response, including expected expiry and scheduled-throttle responses.
    failure.add(unexpected);
    if (unexpected) unexpectedWorkResponse = true;
  }

  return r;
}

function login() {
  let r = raw('/v2/login-form');
  const token = r.html().find('input[name="csrf"]').first().attr('value');
  const row = rows[(__VU - 1) % rows.length];

  r = raw('/v2/login', 'POST', {
    username: row.username,
    password: row.password,
    csrf: token
  });

  if (r.status === 302) {
    r = raw(r.headers.Location);
    grant = body(r).grant_id;
  }

  check(r, {'login': response => response.status === 200});
}

function request(path, method='GET', data=null, extra={}) {
  let r = raw(path, method, data, extra);

  if (r.status === 401) {
    const error = body(r).error;

    if (error === 'expired' || error === 'session') {
      if (error === 'expired') {
        const renewed = raw('/v2/session/renew', 'POST', {});
        if (renewed.status !== 200) login();
      } else {
        login();
      }

      if (cart) raw('/v2/carts/' + cart + '/recover', 'POST', {});
      r = raw(path, method, data, extra);
    }
  }

  return r;
}

function work(override) {
  if (cfg.workload || !csrf) login();

  unexpectedWorkResponse = false;
  const path = override || cfg.path || '/v2/work';
  let r = request(path, 'POST', {});

  for (let n = 0; n < 4 && isScheduledThrottle(r); n++) {
    sleep(retryAfterSeconds(r) + 0.01);
    r = request(path, 'POST', {});
  }

  const sawUnexpectedResponse = unexpectedWorkResponse;
  check(r, {
    'operation or expected throttle': response =>
      !sawUnexpectedResponse &&
      ((response.status === 200 && body(response).ok === true) ||
       (cfg.completion && isScheduledThrottle(response)))
  });
}

function flow() {
  csrf = '';
  cart = '';
  grant = '';
  login();

  if (cfg.mode === 'challenge') {
    let r = request('/v2/challenge-form');
    const form = r.html().find('form');
    const token = form.find('input[name="challenge"]').first().attr('value');

    r = request(form.attr('action'), 'POST', {challenge: token});
    r = request(r.headers.Location);
    grant = body(r).grant_id;
  }

  let page = cfg.mode === 'pagination' ? '/v2/catalog/page' : '/v2/catalog';
  let product;

  for (let n = 0; n < 3 && page; n++) {
    const b = body(request(page));
    product = b.data.products.find(p => p.variants.some(v => v.in_stock));
    if (product) break;
    page = b.next;
  }

  if (!product) {
    check(false, {'eligible product': x => x});
    return;
  }

  const variant = product.variants.find(v => v.in_stock);
  let r = request('/v2/carts', 'POST', {
    product_id: product.id,
    variant_id: variant.id,
    grant_id: grant
  });

  cart = body(r).id;
  let etag = r.headers.Etag;
  check(r, {'cart': response => response.status === 201});

  if (cfg.mode === 'etag' || cfg.mode === 'data') {
    const quantity = cfg.mode === 'data'
      ? rows[(__VU - 1) % rows.length].quantity
      : (cfg.quantity || 2);

    r = request('/v2/carts/' + cart, 'PATCH', {quantity}, {'If-Match': etag});

    if (r.status === 412) {
      etag = request('/v2/carts/' + cart).headers.Etag;
      r = request('/v2/carts/' + cart, 'PATCH', {quantity}, {'If-Match': etag});
    }

    etag = r.headers.Etag;
    check(r, {'update': response => response.status === 200});
  }

  let reservation;
  if (cfg.mode === 'reservation') {
    r = request('/v2/reservations', 'POST', {cart_id: cart});
    const url = body(r).status_url;

    for (let n = 0; n < 5; n++) {
      sleep(0.05);
      r = request(url);
      const b = body(r);

      if (b.status === 'ready') {
        reservation = b.reservation_id;
        break;
      }
      if (b.status === 'failed') {
        check(false, {'reservation ready': x => x});
        return;
      }
    }

    if (!reservation) return;
  }

  r = request('/v2/orders', 'POST', {
    cart_id: cart,
    reservation_id: reservation
  }, {
    'Idempotency-Key': cart,
    'If-Match': etag
  });

  check(r, {'accepted': response => response.status === 201 && body(response).accepted === true});

  if (cfg.mode === 'threshold') raw('/v2/health');
}

export default function() {
  if (cfg.workload) {
    if (cfg.operation === 'journey') flow();
    else work();
  } else if (cfg.mode === 'errors') {
    login();
    for (let n = 0; n < 4; n++) work();
  } else {
    flow();
  }
}

export function browse() {
  work('/v2/browse');
}

