public class ModelSimulation extends Simulation {
  private static final String BASE_URL = configuredBaseUrl();

  private static String configuredBaseUrl() {
    String value = System.getenv("BASE_URL");
    return value == null || value.isBlank() ? "http://127.0.0.1:8000" : value;
  }

  private static ChainBuilder loginFlow() {
    return exec(session -> session.set("loginStatus", 0))
        .exec(
            http("GET login form")
                .get("/v2/login-form")
                .check(
                    status().is(200),
                    css("input[name='csrf']", "value").find().saveAs("csrf")))
        .exec(
            http("POST login")
                .post("/v2/login")
                .header("Content-Type", "application/json")
                .body(
                    StringBody(
                        "{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{csrf}\"}"))
                .check(
                    status().in(200, 302).saveAs("loginStatus"),
                    header("Location").optional().saveAs("loginLocation"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
        .doIf(session -> session.getInt("loginStatus") == 302)
        .then(
            exec(
                http("GET login redirect")
                    .get("#{loginLocation}")
                    .check(status().is(200), jsonPath("$.csrf").saveAs("csrf"))));
  }

  private static ChainBuilder renewSession() {
    return exec(
        http("POST session renew")
            .post("/v2/session/renew")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{}"))
            .check(status().is(200), jsonPath("$.csrf").saveAs("csrf")));
  }

  private static ChainBuilder workAttempt() {
    return exec(
            session ->
                session.set("workStatus", -1).set("workError", "").set("workRetryAfter", ""))
        .exec(
            http("POST /v2/work")
                .post("/v2/work")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(
                    status().in(200, 401, 429).saveAs("workStatus"),
                    jsonPath("$.ok").optional().is("true"),
                    jsonPath("$.error").optional().not("denied"),
                    jsonPath("$.error").optional().saveAs("workError"),
                    header("Retry-After").optional().saveAs("workRetryAfter")));
  }

  private static ChainBuilder retryScheduled429() {
    return asLongAs(
            session ->
                session.getInt("workStatus") == 429
                    && session.getInt("work429Retries") < 4)
        .on(
            pause(Duration.ofSeconds(1))
                .exec(
                    session ->
                        session.set(
                            "work429Retries", session.getInt("work429Retries") + 1))
                .exec(workAttempt()));
  }

  public ModelSimulation() {
    HttpProtocolBuilder httpProtocol =
        http.baseUrl(BASE_URL).disableFollowRedirect();

    List<Map<String, Object>> accounts = new ArrayList<>();
    for (int i = 1; i <= 16; i++) {
      Map<String, Object> account = new HashMap<>();
      account.put("username", "bench-" + i);
      accounts.add(account);
    }

    ScenarioBuilder work =
        scenario("Authenticated work")
            .feed(listFeeder(accounts).circular())
            .exec(loginFlow())
            .exec(session -> session.set("work429Retries", 0))
            .exec(workAttempt())
            .exec(retryScheduled429())
            .doIf(
                session ->
                    session.getInt("workStatus") == 401
                        && ("expired".equals(session.getString("workError"))
