import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';
import { parseHTML } from 'k6/html';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 5,
      timeUnit: '1s',
      duration: '40s',
      preAllocatedVUs: 16,
      maxVUs: 32,
      gracefulStop: '5s',
      exec: 'workIteration',
    },
  },
};

function headerValue(response, name) {
  if (!response || !response.headers) return '';
  const wanted = name.toLowerCase();
  for (const key in response.headers) {
    if (key.toLowerCase() === wanted) return String(response.headers[key]);
  }
  return '';
}

function absoluteURL(location) {
  if (/^https?:\/\//i.test(location)) return location;
  if (location.startsWith('//')) return 'http:' + location;
  if (location.startsWith('/')) return BASE_URL + location;
  return BASE_URL + '/' + location;
}

function jsonOrNull(response) {
  if (!response || !response.body) return null;
  try {
    return response.json();
  } catch (_) {
    return null;
  }
}

function csrfFromForm(body) {
  try {
    return parseHTML(body).find('input[name="csrf"]').attr('value') || '';
  } catch (_) {
    return '';
  }
}

function login(username) {
  const formResponse = http.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    timeout: '5s',
  });
  if (formResponse.status < 200 || formResponse.status >= 300) {
    return { ok: false, csrf: '' };
  }

  const formCsrf = csrfFromForm(formResponse.body || '');
  if (!formCsrf) return { ok: false, csrf: '' };

  let response = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf: formCsrf }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
      timeout: '5s',
    }
  );

  if (response.status === 302) {
    const location = headerValue(response, 'Location');
    if (!location) return { ok: false, csrf: '' };
    response = http.get(absoluteURL(location), {
      redirects: 0,
      timeout: '5s',
    });
  }

  const data = jsonOrNull(response);
  const csrf = data && typeof data.csrf === 'string' ? data.csrf : '';
  return {
    ok: response.status >= 200 && response.status < 300 && csrf.length > 0,
    csrf,
  };
}

function postAuthenticated(path, csrf) {
  return http.post(`${BASE_URL}${path}`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    redirects: 0,
    timeout: '5s',
  });
}

function renewSession(csrf) {
  const response = postAuthenticated('/v2/session/renew', csrf);
  const data = jsonOrNull(response);
  return {
    ok: response.status >= 200 && response.status < 400,
    csrf: data && typeof data.csrf === 'string' && data.csrf ? data.csrf : csrf,
    error: data && data.error ? data.error : '',
  };
}

function runWork(username, initialCsrf) {
  let csrf = initialCsrf;
  let authRecoveryUsed = false;
  let rateRetries = 0;

  while (true) {
    const response = postAuthenticated('/v2/work', csrf);
    const data = jsonOrNull(response);
    const status = response.status;
    const authError = data && data.error ? data.error : '';
    const retryAfter = Number(headerValue(response, 'Retry-After'));
    const scheduled429 = status === 429 && retryAfter === 1;
    const expectedAuthExpiry =
      status === 401 && (authError === 'expired' || authError === 'session');
    const accepted = status === 200 && data !== null && data.ok === true;

    businessFailure.add(
      !(accepted || scheduled429 || expectedAuthExpiry)
    );

    if (accepted) {
      if (typeof data.csrf === 'string' && data.csrf) csrf = data.csrf;
      return { accepted: true, response, data };
    }

    if (expectedAuthExpiry && !authRecoveryUsed) {
      authRecoveryUsed = true;

      if (authError === 'expired') {
        const renewed = renewSession(csrf);
        if (renewed.ok) {
          csrf = renewed.csrf;
        } else {
          const fresh = login(username);
          if (!fresh.ok) return { accepted: false, response, data };
          csrf = fresh.csrf;
        }
      } else {
        const fresh = login(username);
        if (!fresh.ok) return { accepted: false, response, data };
        csrf = fresh.csrf;
      }

      // Retry the interrupted work operation once after authentication recovery.
      continue;
    }

    if (scheduled429 && rateRetries < 4) {
      rateRetries += 1;
      sleep(1);
      continue;
    }

    return { accepted: false, response, data };
  }
}

export function workIteration() {
  const username = `bench-${((__VU - 1) % 16) + 1}`;
  const auth = login(username);

  check(auth, {
    'authenticated session established': (result) => result.ok,
  });

  if (!auth.ok) return;

  const result = runWork(username, auth.csrf);
  check(result, {
    'work accepted': (outcome) => outcome.accepted,
  });
}

import json
import os
import time
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit, urlunsplit

import gevent
from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser


class CsrfInputParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.values = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input":
            return
        attributes = {key.lower(): value for key, value in attrs}
        if (attributes.get("name") or "").lower() == "csrf":
            value = attributes.get("value")
            if value:
                self.values.append(value)


class WorkUser(HttpUser):
    host = os.environ["BASE_URL"]
    wait_time = constant(0)

    first_eligible_start = None
    startup_failed = False

    def on_start(self):
        self.csrf = None
        self.authenticated = False
        self.should_stop = False
        self.next_work_at = None
        if not self._login():
            type(self).startup_failed = True
            raise StopUser()

    def wait_time(self):
        if self.next_work_at is None:
            return 0
        return max(0.0, self.next_work_at - time.monotonic())

    @staticmethod
    def _json_body(response):
        try:
            value = response.json()
            return value if isinstance(value, dict) else {}
        except Exception:
            return {}

    def _location_path(self, location):
        if not location:
            return None

        base = self.host.rstrip("/") + "/"
        destination = urlsplit(urljoin(base, location))
        origin = urlsplit(base)
        if (
            destination.scheme.lower() != origin.scheme.lower()
            or destination.netloc.lower() != origin.netloc.lower()
        ):
            return None

        return urlunsplit(("", "", destination.path or "/", destination.query, ""))

    def _login(self):
        self.authenticated = False

        with self.client.get(
            "/v2/login-form",
            name="/v2/login-form",
            allow_redirects=False,
            catch_response=True,
        ) as response:
            if response.status_code != 200:
                response.failure("Login form did not return 200")
                return False

            parser = CsrfInputParser()
            parser.feed(response.text)
            form_csrf = parser.values[0] if parser.values else None
            if not form_csrf:
                response.failure("Login form did not contain input[name=csrf]")
                return False
            response.success()

        with self.client.post(
            "/v2/login",
            name="/v2/login",
            json={
                "username": "bench-1",
                "password": "bench",
                "csrf": form_csrf,
            },
            allow_redirects=False,
            catch_response=True,
        ) as response:
            status = response.status_code
            location = response.headers.get("Location")
            login_data = self._json_body(response)

            if status == 302:
                response.success()
            elif 200 <= status < 300:
                response.success()
            else:
                response.failure("Login request failed")
                return False

        login_csrf = login_data.get("csrf")
        if location:
            path = self._location_path(location)
            if not path:
                return False

            with self.client.get(
                path,
                name="/v2/login-redirect",
                allow_redirects=False,
                catch_response=True,
            ) as response:
                if not 200 <= response.status_code < 300:
                    response.failure("Login redirect target failed")
                    return False
                redirect_data = self._json_body(response)
                if not redirect_data:
                    parser = CsrfInputParser()
                    parser.feed(response.text)
                    if parser.values:
                        redirect_data = {"csrf": parser.values[0]}
                response.success()

            if not login_csrf:
                login_csrf = redirect_data.get("csrf")

        if not login_csrf:
            return False

        self.csrf = login_csrf
        self.authenticated = True
        return True

    def _renew(self):
        with self.client.post(
            "/v2/session/renew",
            name="/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf or ""},
            allow_redirects=False,
            catch_response=True,
        ) as response:
            data = self._json_body(response)
            status = response.status_code

            if 200 <= status < 400:
                self.csrf = data.get("csrf") or self.csrf
                response.success()
                return True

            if status == 401:
                response.success()
            else:
                response.failure("Session renewal failed")

        return False

    def _recover_authentication(self, error):
        if error == "expired" and self._renew():
            return True
        return self._login()

    def _send_work(self):
        auth_retries = 0
        rate_retries = 0
        last_start = time.monotonic()

        while True:
            started = time.monotonic()
            last_start = started
            auth_error = None
            scheduled_rate_limit = False
            succeeded = False

            with self.client.post(
                "/v2/work",
                name="/v2/work",
                json={},
                headers={"X-CSRF-Token": self.csrf or ""},
                allow_redirects=False,
                catch_response=True,
            ) as response:
                data = self._json_body(response)
                status = response.status_code

                if status == 200 and data.get("ok") is True:
                    self.csrf = data.get("csrf") or self.csrf
                    if type(self).first_eligible_start is None:
                        type(self).first_eligible_start = started
                    response.success()
                    succeeded = True

                elif status == 401 and data.get("error") in ("expired", "session"):
                    if auth_retries == 0:
                        auth_error = data["error"]
                        response.success()
                    else:
                        response.failure("Authentication recovery was exhausted")

                elif status == 429 and response.headers.get("Retry-After") == "1":
                    if rate_retries < 4:
                        scheduled_rate_limit = True
                        response.success()
                    else:
                        response.failure("Scheduled rate-limit retries were exhausted")

                else:
                    response.failure("Unexpected /v2/work response")

            if succeeded:
                return last_start

            if scheduled_rate_limit:
                rate_retries += 1
                gevent.sleep(1)
                continue

            if auth_error:
                auth_retries += 1
                if not self._recover_authentication(auth_error):
                    self.should_stop = True
                    return last_start
                continue

            return last_start

    @task
    def perform_work(self):
        anchor = type(self).first_eligible_start
        if anchor is not None and time.monotonic() >= anchor + 39.8:
            raise StopUser()
        if self.should_stop or not self.authenticated:
            raise StopUser()

        request_start = self._send_work()
        self.next_work_at = request_start + 0.2


class WorkShape(LoadTestShape):
    def tick(self):
        elapsed = self.get_run_time()
        anchor = WorkUser.first_eligible_start

        if WorkUser.startup_failed:
            return None
        if anchor is None:
            if elapsed >= 10:
                return None
        elif time.monotonic() >= anchor + 39.8:
            return None

        return (1, 1)

import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.core.Session;
import io.gatling.javaapi.http.HttpProtocolBuilder;

import java.time.Duration;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {
  private static final String BASE_URL =
      System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

  private final HttpProtocolBuilder httpProtocol =
      http.baseUrl(BASE_URL)
          .disableFollowRedirect()
          .acceptHeader("application/json, text/html");

  private ChainBuilder loginChain() {
    return exec(session ->
            session.remove("csrf")
                .remove("loginFormCsrf")
                .remove("loginResponseCsrf")
                .remove("loginLocation")
                .set("loginStatus", 0))
        .exec(
            http("login form")
                .get("/v2/login-form")
                .check(
                    status().is(200),
                    css("input[name='csrf']", "value").saveAs("loginFormCsrf")))
        .exec(
            http("login")
                .post("/v2/login")
                .body(
                    StringBody(
                        session -> {
                          String formCsrf =
                              session.contains("loginFormCsrf")
                                  ? session.getString("loginFormCsrf")
                                  : "";
                          return "{\"username\":\"bench\",\"password\":\"bench\",\"csrf\":\""
                              + formCsrf
                              + "\"}";
                        }))
                .asJson()
                .check(
                    status().in(200, 302).saveAs("loginStatus"),
                    jsonPath("$.csrf").optional().saveAs("loginResponseCsrf"),
                    header("Location").optional().saveAs("loginLocation")))
        .doIf(session -> session.getInt("loginStatus") == 200)
        .then(
            exec(
                session -> {
                  if (session.contains("loginResponseCsrf")) {
                    return session.set("csrf", session.getString("loginResponseCsrf"));
                  }
                  return session.set("workDone", 1).markAsFailed();
                }))
        .doIf(session -> session.getInt("loginStatus") == 302)
        .then(
            exec(
                http("login redirect")
                    .get("#{loginLocation}")
                    .check(status().is(200), jsonPath("$.csrf").saveAs("csrf"))))
        .exec(
            session -> {
              if (session.contains("csrf")) {
                return session;
              }
              return session.set("workDone", 1).markAsFailed();
            });
  }

  public ModelSimulation() {
    ChainBuilder login = loginChain();

    ChainBuilder renew =
        exec(session -> session.remove("renewCsrf").set("renewStatus", 0))
            .exec(
                http("renew session")
                    .post("/v2/session/renew")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{}"))
                    .asJson()
                    .check(
                        status().in(200, 401).saveAs("renewStatus"),
                        jsonPath("$.csrf").optional().saveAs("renewCsrf")))
            .exec(
                session -> {
                  int status = session.getInt("renewStatus");
                  if (status == 200 && session.contains("renewCsrf")) {
                    return session.set("csrf", session.getString("renewCsrf"));
                  }
                  if (status == 200) {
                    return session.set("workDone", 1).markAsFailed();
                  }
                  if (status == 401) {
                    return session;
                  }
                  return session.set("workDone", 1).markAsFailed();
                })
            .doIf(session -> session.getInt("renewStatus") == 401)
            .then(login);

    ChainBuilder workLoop =
        asLongAs(
                session ->
                    session.getInt("workDone") == 0 && session.getInt("workAttempts") < 5)
            .on(
                exec(
