import http from "k6/http";
import { check, sleep } from "k6";
import { Rate } from "k6/metrics";

const BASE_URL = (__ENV.BASE_URL || "http://127.0.0.1:8000").replace(/\/+$/, "");
const businessFailure = new Rate("business_failure");

export const options = {
  scenarios: {
    work: {
      executor: "constant-arrival-rate",
      rate: 5,
      timeUnit: "1s",
      duration: "40s",
      preAllocatedVUs: 16,
      maxVUs: 32,
      gracefulStop: "5s",
      exec: "workJourney",
    },
  },
  thresholds: {
    dropped_iterations: ["count<3"],
    business_failure: ["rate<0.0101"],
    checks: ["rate>0.989"],
  },
};

function headerValue(response, name) {
  if (!response || !response.headers) return null;
  if (response.headers[name] !== undefined) return String(response.headers[name]);

  const wanted = name.toLowerCase();
  for (const key in response.headers) {
    if (key.toLowerCase() === wanted) return String(response.headers[key]);
  }
  return null;
}

function safeJson(response) {
  if (!response || !response.body) return null;
  try {
    return response.json();
  } catch (_) {
    return null;
  }
}

function decodeHtml(value) {
  return String(value)
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&amp;/gi, "&");
}

function getAttribute(tag, name) {
  const escapedName = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const pattern = new RegExp(
    "(?:^|\\s)" +
      escapedName +
      "\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s/>]+))",
    "i"
  );
  const match = tag.match(pattern);
  if (!match) return null;
  return decodeHtml(match[1] !== undefined ? match[1] : match[2] !== undefined ? match[2] : match[3]);
}

function csrfFromLoginForm(html) {
  const inputs = String(html || "").match(/<input\b[^>]*>/gi) || [];
  for (let i = 0; i < inputs.length; i++) {
    if (getAttribute(inputs[i], "name") === "csrf") {
      const value = getAttribute(inputs[i], "value");
      if (value) return value;
    }
  }
  return null;
}

function resolveLocation(location) {
  if (!location) return null;
  const value = String(location).trim();

  if (/^https?:\/\//i.test(value)) {
    if (value === BASE_URL || value.indexOf(BASE_URL + "/") === 0 || value.indexOf(BASE_URL + "?") === 0) {
      return value;
    }
    return null;
  }
  if (value.charAt(0) === "/") return BASE_URL + value;
  return BASE_URL + "/" + value;
}

function accountForVU() {
  const accountNumber = ((__VU - 1) % 17) + 1;
  return accountNumber === 17 ? "bench" : "bench-" + accountNumber;
}

function loginForCurrentUser() {
  const formResponse = http.get(BASE_URL + "/v2/login-form", {
    redirects: 0,
    timeout: "10s",
    tags: { name: "GET /v2/login-form" },
  });
  if (!formResponse || formResponse.status < 200 || formResponse.status >= 300) return null;

  const csrf = csrfFromLoginForm(formResponse.body);
  if (!csrf) return null;

  const username = accountForVU();
  const loginResponse = http.post(
    BASE_URL + "/v2/login",
    JSON.stringify({ username: username, password: "bench", csrf: csrf }),
    {
      headers: { "Content-Type": "application/json" },
      redirects: 0,
      timeout: "10s",
      tags: { name: "POST /v2/login" },
    }
  );
  if (!loginResponse) return null;

  let resultResponse = loginResponse;
  if (loginResponse.status === 302) {
    const location = resolveLocation(headerValue(loginResponse, "Location"));
    if (!location) return null;

    // Follow the dynamic login redirect exactly once.
    resultResponse = http.get(location, {
      redirects: 0,
      timeout: "10s",
      tags: { name: "GET login redirect" },
    });
  }

  if (!resultResponse || resultResponse.status < 200 || resultResponse.status >= 300) return null;
  const result = safeJson(resultResponse);
  return result && typeof result.csrf === "string" && result.csrf ? result.csrf : null;
}

function renewSession(csrf) {
  const response = http.post(
    BASE_URL + "/v2/session/renew",
    JSON.stringify({}),
    {
      headers: {
        "Content-Type": "application/json",
        "X-CSRF-Token": csrf,
      },
      redirects: 0,
      timeout: "10s",
      tags: { name: "POST /v2/session/renew" },
    }
  );

  if (!response || response.status < 200 || response.status >= 300) {
    return { ok: false, csrf: csrf };
  }

  const body = safeJson(response);
  return {
    ok: true,
    csrf: body && typeof body.csrf === "string" && body.csrf ? body.csrf : csrf,
  };
}

function retryAfterSeconds(response) {
  const value = headerValue(response, "Retry-After");
  if (value === null) return null;

  const match = value.match(/^\s*(\d+(?:\.\d+)?)\s*$/);
  if (!match) return null;

  const seconds = Number(match[1]);
  return isFinite(seconds) && seconds > 0 ? seconds : null;
}

function postWork(csrf) {
  let authRetryUsed = false;
  let retries429 = 0;

  while (true) {
    let response;
    try {
      response = http.post(BASE_URL + "/v2/work", JSON.stringify({}), {
        headers: {
          "Content-Type": "application/json",
          "X-CSRF-Token": csrf,
        },
        redirects: 0,
        timeout: "10s",
        tags: { name: "POST /v2/work" },
      });
    } catch (_) {
      return { response: null, body: null, csrf: csrf };
    }

    if (!response) return { response: null, body: null, csrf: csrf };

    const body = safeJson(response);
    const expired = response.status === 401 && body && body.error === "expired";
    const delay = response.status === 429 ? retryAfterSeconds(response) : null;
    const expected429 =
      response.status === 429 && delay !== null && Math.abs(delay - 1) < 0.001;

    // Exactly one custom-metric sample for every raw /v2/work response.
    businessFailure.add(!(expired || expected429));

    if (
      response.status >= 200 &&
      response.status < 300 &&
      body &&
      typeof body.csrf === "string" &&
      body.csrf
    ) {
      csrf = body.csrf;
    }

    if (response.status === 200 && body && body.ok === true) {
      return { response: response, body: body, csrf: csrf };
    }

    if (
      response.status === 401 &&
      body &&
      (body.error === "expired" || body.error === "session") &&
      !authRetryUsed
    ) {
      authRetryUsed = true;
      const renewal = renewSession(csrf);

      if (renewal.ok) {
        csrf = renewal.csrf;
        continue;
      }

      if (body.error === "session") {
        const freshCsrf = loginForCurrentUser();
        if (freshCsrf) {
          csrf = freshCsrf;
          continue;
        }
      }

      return { response: response, body: body, csrf: csrf };
    }

    if (response.status === 429 && delay !== null && retries429 < 4) {
      retries429 += 1;
      sleep(Math.max(1, delay));
      continue;
    }

    return { response: response, body: body, csrf: csrf };
  }
}

export function workJourney() {
  // Each journey gets a fresh authenticated session; this pool needs no cart.
  const csrf = loginForCurrentUser();
  if (!csrf) {
    check(false, {
      "POST /v2/work returned 200 {ok:true}": (value) => value === true,
    });
    return;
  }

  const result = postWork(csrf);
  const succeeded =
    !!result &&
    !!result.response &&
    result.response.status === 200 &&
    !!result.body &&
    result.body.ok === true;

  check(succeeded, {
    "POST /v2/work returned 200 {ok:true}": (value) => value === true,
  });
}

import itertools
import math
import os
import time
from html.parser import HTMLParser

import gevent
from locust import HttpUser, LoadTestShape, StopUser, task


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
ACCOUNTS = tuple(f"bench-{i}" for i in range(1, 17))
PASSWORD = "bench"

TARGET_INTERVAL = 0.2
USER_COUNT = 16
MAX_ITERATIONS_PER_USER = 500

_user_numbers = itertools.count()
_next_start = None
_first_work_start = None
_module_loaded_at = time.monotonic()


class _CsrfInputParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.value = None

    def handle_starttag(self, tag, attrs):
        self._check(tag, attrs)

    def handle_startendtag(self, tag, attrs):
        self._check(tag, attrs)

    def _check(self, tag, attrs):
        if tag.lower() != "input":
            return
