import io.gatling.javaapi.core.ChainBuilder;
import io.gatling.javaapi.core.ScenarioBuilder;
import io.gatling.javaapi.http.HttpProtocolBuilder;
import io.gatling.javaapi.core.Session;

import java.time.Duration;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

  private static final String BASE_URL =
      System.getenv("BASE_URL") == null || System.getenv("BASE_URL").isBlank()
          ? "http://127.0.0.1:8000"
          : System.getenv("BASE_URL");

  private final HttpProtocolBuilder httpProtocol =
      http.baseUrl(BASE_URL)
          .disableFollowRedirect()
          .acceptHeader("application/json, text/html")
          .contentTypeHeader("application/json");

  private static boolean hasStatus(Session session, int status) {
    return session.contains("workStatus") && session.getInt("workStatus") == status;
  }

  private static String workError(Session session) {
    return session.contains("workError") ? session.getString("workError") : "";
  }

  private ChainBuilder loginFlow() {
    return exec(session ->
            session.remove("formCsrf")
                .remove("postLoginCsrf")
                .remove("loginLocation")
                .remove("landingCsrf"))
        .exec(
            http("GET /v2/login-form")
                .get("/v2/login-form")
                .check(
                    status().is(200),
                    css("input[name=csrf]", "value").saveAs("formCsrf")))
        .exec(
            http("POST /v2/login")
                .post("/v2/login")
                .body(
                    StringBody(
                        session ->
                            "{\"username\":\"bench\",\"password\":\"bench\",\"csrf\":\""
                                + session.getString("formCsrf")
                                + "\"}"))
                .check(
                    status().in(200, 302),
                    jsonPath("$.csrf").optional().saveAs("postLoginCsrf"),
                    header("Location").optional().saveAs("loginLocation")))
        .exec(
            session -> {
              Object token = session.get("postLoginCsrf");
              return session.set(
                  "csrf",
                  token == null ? session.getString("formCsrf") : token.toString());
            })
        .doIf(session -> session.contains("loginLocation"))
        .then(
            exec(
                    http("GET login redirect")
                        .get("#{loginLocation}")
                        .check(
                            status().is(200),
                            jsonPath("$.csrf").optional().saveAs("landingCsrf")))
                .exec(
                    session -> {
                      Object token = session.get("landingCsrf");
                      return token == null
                          ? session
                          : session.set("csrf", token.toString());
                    }));
  }

  private ChainBuilder workRequest() {
    return exec(
            session ->
                session.remove("workCsrf")
                    .remove("workError")
                    .remove("retryAfter")
                    .set("workStatus", 0))
        .exec(
            http("POST /v2/work")
                .post("/v2/work")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(
                    status().in(200, 401, 429).saveAs("workStatus"),
                    jsonPath("$.csrf").optional().saveAs("workCsrf"),
                    jsonPath("$.error").optional().saveAs("workError"),
                    header("Retry-After").optional().saveAs("retryAfter"))
                .checkIf(session -> session.getInt("authRetries") > 0)
                .then(status().in(200, 429))
                .checkIf(session -> session.getInt("rateRetries") >= 4)
                .then(status().in(200, 401))
                .checkIf(session -> hasStatus(session, 200))
                .then(jsonPath("$.ok").is("true"))
