import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PASSWORD = 'bench';
const businessFailure = new Rate('business_failure');

export const options = {
  discardResponseBodies: false,
  scenarios: {
    work: {
      executor: 'constant-arrival-rate',
      rate: 8,
      timeUnit: '1s',
      duration: '40s',
      preAllocatedVUs: 16,
      maxVUs: 32,
      gracefulStop: '5s',
      exec: 'journey',
    },
  },
};

function parseJson(response) {
  if (!response || !response.body) return null;
  try {
    return JSON.parse(response.body);
  } catch (_) {
    return null;
  }
}

function getHeader(response, name) {
  if (!response || !response.headers) return '';
  return response.headers[name] || response.headers[name.toLowerCase()] || '';
}

function decodeHtml(value) {
  return value
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)));
}

function attribute(tag, name) {
  const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp(
    '(?:^|\\s)' + escaped + '\\s*=\\s*(?:"([^"]*)"|\\x27([^\\x27]*)\\x27|([^\\s"\\x27=<>`]+))',
    'i'
  );
  const match = tag.match(re);
  if (!match) return null;
  return decodeHtml(match[1] !== undefined ? match[1] :
    (match[2] !== undefined ? match[2] : match[3]));
}

function csrfFromForm(html) {
  const tags = html.match(/<input\b(?:[^>"']|"[^"]*"|'[^']*')*>/gi) || [];
  for (const tag of tags) {
    if ((attribute(tag, 'name') || '').toLowerCase() === 'csrf') {
      return attribute(tag, 'value');
    }
  }
  return null;
}

function resolveLocation(location, currentPath) {
  if (/^https?:\/\//i.test(location)) return location;
  if (location.startsWith('//')) return 'http:' + location;
  if (location.startsWith('/')) return BASE_URL + location;

  const parent = currentPath.slice(0, currentPath.lastIndexOf('/') + 1);
  const parts = (parent + location).split('/');
  const normalized = [];
  for (const part of parts) {
    if (part === '..') normalized.pop();
    else if (part !== '.' && part !== '') normalized.push(part);
  }
  return BASE_URL + '/' + normalized.join('/');
}

function jsonPost(path, payload, csrf, name) {
  const headers = { 'Content-Type': 'application/json' };
  if (csrf) headers['X-CSRF-Token'] = csrf;
  return http.post(BASE_URL + path, JSON.stringify(payload), {
    headers,
    redirects: 0,
    tags: { name },
  });
}

function freshLogin(username) {
  const formResponse = http.get(BASE_URL + '/v2/login-form', {
    redirects: 0,
    tags: { name: 'GET /v2/login-form' },
  });
  const formCsrf = formResponse.status === 200
    ? csrfFromForm(formResponse.body || '')
    : null;

  check(formResponse, {
    'login form available': (r) => r.status === 200,
    'login form CSRF present': () => !!formCsrf,
  });
  if (!formCsrf) return null;

  const loginResponse = http.post(
    BASE_URL + '/v2/login',
    JSON.stringify({ username, password: PASSWORD, csrf: formCsrf }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
      tags: { name: 'POST /v2/login' },
    }
  );

  let result = loginResponse;
  if ([301, 302, 303, 307, 308].indexOf(loginResponse.status) !== -1) {
    const location = getHeader(loginResponse, 'Location');
    if (!location) {
      check(loginResponse, { 'login redirect has Location': () => false });
      return null;
    }
    result = http.get(resolveLocation(location, '/v2/login'), {
      redirects: 0,
      tags: { name: 'GET login redirect' },
    });
  }

  const body = parseJson(result);
  const csrf = body && typeof body.csrf === 'string' ? body.csrf : null;
  check(result, {
    'login completed': (r) => r.status >= 200 && r.status < 400,
    'login returned CSRF': () => !!csrf,
  });
  return csrf;
}

function renewSession(csrf) {
  const response = jsonPost('/v2/session/renew', {}, csrf, 'POST /v2/session/renew');
  const body = parseJson(response);
  const nextCsrf = body && typeof body.csrf === 'string' ? body.csrf : null;
  return response.status >= 200 && response.status < 400 && nextCsrf
    ? nextCsrf
    : null;
}

function recordWorkResponse(response) {
  const body = parseJson(response);
  const scheduled429 = response.status === 429 &&
    String(getHeader(response, 'Retry-After')).trim() === '1';
  const expectedAuthError = response.status === 401 && body &&
    (body.error === 'expired' || body.error === 'session');
  const accepted = response.status === 200 && body && body.ok === true;

  businessFailure.add(accepted || scheduled429 || expectedAuthError ? 0 : 1);
  return body;
}

export function journey() {
  const username = 'bench-' + (((__VU - 1) % 16) + 1);
  let csrf = freshLogin(username);
  if (!csrf) return;

  let authRecoveryUsed = false;
  let scheduledRetries = 0;
  let finalResponse = null;
  let finished = false;

  while (!finished) {
    const response = jsonPost('/v2/work', {}, csrf, 'POST /v2/work');
    const body = recordWorkResponse(response);
    finalResponse = response;

    if (body && typeof body.csrf === 'string') csrf = body.csrf;

    if (response.status === 401 && body && !authRecoveryUsed &&
        (body.error === 'expired' || body.error === 'session')) {
      authRecoveryUsed = true;
      const renewedCsrf = renewSession(csrf);

      if (renewedCsrf) {
        csrf = renewedCsrf;
        continue;
      }

      if (body.error === 'session') {
        const loggedInCsrf = freshLogin(username);
        if (loggedInCsrf) {
          csrf = loggedInCsrf;
          continue;
        }
      }
      finished = true;
      continue;
    }

    if (response.status === 429 &&
        String(getHeader(response, 'Retry-After')).trim() === '1' &&
        scheduledRetries < 4) {
      scheduledRetries += 1;
      sleep(1);
      continue;
    }

    finished = true;
  }

  const finalBody = parseJson(finalResponse);
  check(finalResponse, {
    'work accepted': (r) => r.status === 200 && finalBody && finalBody.ok === true,
  });
}

import os
import time
from html.parser import HTMLParser

import gevent
from locust import HttpUser, LoadTestShape, StopUser, constant, task


_PERIOD = 1.0 / 8.0
_next_work_start = None
_T0 = None
_user_sequence = 0


class _CsrfParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.token = None

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input":
            return
        attributes = dict(attrs)
        if attributes.get("name") == "csrf" and attributes.get("value"):
            self.token = attributes["value"]


def _json_body(response):
    try:
        value = response.json()
        return value if isinstance(value, dict) else {}
    except Exception:
        return {}


class WorkUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
    wait_time = constant(0)

    def on_start(self):
        global _user_sequence
        index = _user_sequence
        _user_sequence += 1
        self.username = f"bench-{index + 1}" if index < 16 else "bench"
        self.csrf = None
        if not self._login():
            raise StopUser()

    def _store_csrf(self, data):
        token = data.get("csrf") if isinstance(data, dict) else None
        if isinstance(token, str) and token:
            self.csrf = token

    def _login(self):
        try:
            form = self.client.get(
                "/v2/login-form",
                name="GET /v2/login-form",
                allow_redirects=False,
            )
            if form.status_code != 200:
                return False

            parser = _CsrfParser()
            parser.feed(form.text)
            if not parser.token:
                return False

            response = self.client.post(
                "/v2/login",
                json={
                    "username": self.username,
                    "password": "bench",
                    "csrf": parser.token,
                },
                name="POST /v2/login",
                allow_redirects=False,
            )

            if response.status_code == 302:
                location = response.headers.get("Location")
                if not location:
                    return False
                response = self.client.get(
                    location,
                    name="GET login redirect",
                    allow_redirects=False,
                )

            if response.status_code != 200:
                return False
            data = _json_body(response)
            self._store_csrf(data)
            return bool(self.csrf)
        except Exception:
            return False

    def _renew(self):
        try:
            with self.client.post(
                "/v2/session/renew",
